fn io_error(e: std::io::Error) -> windows::core::Error {
    windows::core::Error::new(E_FAIL, e.to_string())
}

fn scale(dip: i32, dpi: u32) -> i32 {
    dip * dpi as i32 / 96
}

fn padding(dpi: u32) -> i32 {
    scale(PADDING_DIP, dpi)
}

/// Pixels between split panes.
fn gap(dpi: u32) -> i32 {
    scale(1, dpi).max(1)
}

/// Outer window size for a grid of `cols` x `rows` cells.
fn window_size(m: &CellMetrics, cols: usize, rows: usize, dpi: u32, menu: bool) -> (i32, i32) {
    let pad = padding(dpi);
    client_to_window(
        cols as i32 * m.width as i32 + 2 * pad,
        rows as i32 * m.height as i32 + 2 * pad,
        dpi,
        menu,
    )
}

/// What full screen changed, put back when it ends.
struct FullScreen {
    /// Where the window was, maximized or not.
    placement: WINDOWPLACEMENT,
    /// Its style, with the caption and the sizing frame.
    style: isize,
    /// Whether the menu bar showed.
    menu: bool,
}

/// The whole monitor the window is on (taskbar included), in screen
/// coordinates.
fn monitor_rect(hwnd: HWND) -> Option<RECT> {
    let mut info = MONITORINFO {
        cbSize: size_of::<MONITORINFO>() as u32,
        ..Default::default()
    };
    // SAFETY: our window and a local out-pointer with its size set.
    unsafe {
        let monitor = MonitorFromWindow(hwnd, MONITOR_DEFAULTTONEAREST);
        GetMonitorInfoW(monitor, &mut info)
            .as_bool()
            .then_some(info.rcMonitor)
    }
}

/// Settings > Full screen and F11: the window loses its caption, frame and
/// menu bar and covers its monitor, taskbar too; the second time puts
/// back where it was, its size and whether it was maximized. Alt still
/// shows the menu bar, which hides again once a menu closes.
fn toggle_full_screen(hwnd: HWND) {
    let Some((back, menu)) = with_window(|w| (w.full_screen.take(), w.menu)) else {
        return;
    };
    // SAFETY: our own window and menu; locals for the out-pointers. No
    // window borrow is held across the calls, which send WM_SIZE.
    unsafe {
        if let Some(back) = back {
            with_window(|w| w.menu_visible = back.menu);
            SetWindowLongPtrW(hwnd, GWL_STYLE, back.style);
            let _ = SetMenu(hwnd, back.menu.then_some(menu));
            let _ = SetWindowPlacement(hwnd, &back.placement);
            let _ = SetWindowPos(
                hwnd,
                None,
                0,
                0,
                0,
                0,
                SWP_NOMOVE | SWP_NOSIZE | SWP_NOZORDER | SWP_NOOWNERZORDER | SWP_FRAMECHANGED,
            );
        } else {
            let mut placement = WINDOWPLACEMENT {
                length: size_of::<WINDOWPLACEMENT>() as u32,
                ..Default::default()
            };
            let Some(r) = monitor_rect(hwnd) else {
                return;
            };
            if GetWindowPlacement(hwnd, &mut placement).is_err() {
                return;
            }
            let style = GetWindowLongPtrW(hwnd, GWL_STYLE);
            with_window(|w| {
                w.full_screen = Some(FullScreen {
                    placement,
                    style,
                    menu: w.menu_visible,
                });
                w.menu_visible = false;
            });
            SetWindowLongPtrW(hwnd, GWL_STYLE, style & !(WS_OVERLAPPEDWINDOW.0 as isize));
            let _ = SetMenu(hwnd, None);
            let _ = SetWindowPos(
                hwnd,
                Some(HWND_TOP),
                r.left,
                r.top,
                r.right - r.left,
                r.bottom - r.top,
                SWP_NOOWNERZORDER | SWP_FRAMECHANGED,
            );
        }
    }
    with_window(Window::update_menu_checks);
}

fn client_to_window(w: i32, h: i32, dpi: u32, menu: bool) -> (i32, i32) {
    let mut r = RECT {
        left: 0,
        top: 0,
        right: w,
        bottom: h,
    };
    // SAFETY: valid pointer to a local rect. On failure the client size is
    // used as is, which only makes the window slightly small.
    let _ = unsafe { AdjustWindowRectExForDpi(&mut r, STYLE, menu, EX_STYLE, dpi) };
    (r.right - r.left, r.bottom - r.top)
}

fn win_rect(r: Rect) -> RECT {
    RECT {
        left: r.x,
        top: r.y,
        right: r.right(),
        bottom: r.bottom(),
    }
}

fn pixel(r: Rect) -> PixelRect {
    PixelRect {
        left: r.x,
        top: r.y,
        right: r.right(),
        bottom: r.bottom(),
    }
}

/// `r` grown by `by` pixels on every side.
fn mix(a: Rgb, b: Rgb, amount: f32) -> Rgb {
    let m = |x: u8, y: u8| (f32::from(x) * (1.0 - amount) + f32::from(y) * amount).round() as u8;
    Rgb::new(m(a.r, b.r), m(a.g, b.g), m(a.b, b.b))
}

/// The four thin rects that outline `r`, `t` pixels thick.
fn frame(r: Rect, t: i32, colour: Rgb, out: &mut Vec<(PixelRect, Rgb)>) {
    for e in [
        Rect::new(r.x, r.y, r.w, t),
        Rect::new(r.x, r.bottom() - t, r.w, t),
        Rect::new(r.x, r.y, t, r.h),
        Rect::new(r.right() - t, r.y, t, r.h),
    ] {
        out.push((pixel(e), colour));
    }
}

/// The modifier keys held now.
fn key_mods() -> Mods {
    // SAFETY: plain key-state queries.
    let down = |vk: VIRTUAL_KEY| unsafe { GetKeyState(i32::from(vk.0)) } < 0;
    Mods {
        shift: down(VK_SHIFT),
        alt: down(VK_MENU),
        ctrl: down(VK_CONTROL),
    }
}

/// Removes the WM_CHAR or WM_SYSCHAR that TranslateMessage queued for a
/// key this window already handled on key-down.
fn drop_pending_char(hwnd: HWND) {
    let mut msg = MSG::default();
    // SAFETY: our window and a local out-pointer.
    unsafe {
        let _ = PeekMessageW(&mut msg, Some(hwnd), WM_CHAR, WM_CHAR, PM_REMOVE);
        let _ = PeekMessageW(&mut msg, Some(hwnd), WM_SYSCHAR, WM_SYSCHAR, PM_REMOVE);
    }
}

/// The terminal key for a virtual key, if it is one that does not type
/// text.
fn terminal_key(vk: VIRTUAL_KEY) -> Option<Key> {
    Some(match vk {
        VK_UP => Key::Up,
        VK_DOWN => Key::Down,
        VK_LEFT => Key::Left,
        VK_RIGHT => Key::Right,
        VK_HOME => Key::Home,
        VK_END => Key::End,
        VK_INSERT => Key::Insert,
        VK_DELETE => Key::Delete,
        VK_PRIOR => Key::PageUp,
        VK_NEXT => Key::PageDown,
        VK_BACK => Key::Backspace,
        VK_TAB => Key::Tab,
        VK_RETURN => Key::Enter,
        VK_ESCAPE => Key::Escape,
        v if (VK_F1.0..=VK_F12.0).contains(&v.0) => Key::F((v.0 - VK_F1.0 + 1) as u8),
        _ => return None,
    })
}

/// The side pane key for a virtual key.
fn side_key(vk: VIRTUAL_KEY, mods: Mods) -> Option<SideKey> {
    Some(match vk {
        VK_UP => SideKey::Up,
        VK_DOWN => SideKey::Down,
        VK_PRIOR => SideKey::PageUp,
        VK_NEXT => SideKey::PageDown,
        VK_HOME => SideKey::Home,
        VK_END => SideKey::End,
        VK_LEFT => SideKey::Left,
        VK_RIGHT => SideKey::Right,
        VK_RETURN => SideKey::Enter { split: mods.shift },
        VK_ESCAPE => SideKey::Escape,
        VK_BACK => SideKey::Backspace,
        VK_DELETE => SideKey::Delete,
        VK_TAB if !mods.ctrl => SideKey::Tab,
        VK_F5 => SideKey::Refresh,
        VK_F2 => SideKey::Edit,
        VK_INSERT => SideKey::New,
        v if mods.ctrl && !mods.alt && v == VIRTUAL_KEY(u16::from(b'D')) => {
            SideKey::ToggleFavourite
        }
        _ => return None,
    })
}

fn lparam_point(lparam: LPARAM) -> (i32, i32) {
    let x = (lparam.0 & 0xFFFF) as u16 as i16;
    let y = ((lparam.0 >> 16) & 0xFFFF) as u16 as i16;
    (i32::from(x), i32::from(y))
}

/// What a key-down handler decided.
enum KeyOutcome {
    Handled,
    /// Not ours: let DefWindowProc and the queued WM_CHAR handle it.
    Default,
    Run(Command),
}

/// Where a point in the client falls.
enum Spot {
    /// Column and row in the side pane's grid.
    Side(usize, usize),
    SideEdge,
    Strip(usize),
    Divider(layout::Divider),
    Pane(PaneId),
    Nothing,
}

fn clamp16(v: usize) -> u16 {
    u16::try_from(v).unwrap_or(u16::MAX)
}

impl Window {
    /// Wakes the window from a background thread: one WM_SHELL_OUTPUT per
    /// batch.
    fn notifier(&self) -> impl Fn() + Send + Clone + 'static {
        let pending = self.output_pending.clone();
        let hwnd = self.hwnd.0 as isize;
        move || {
            if !pending.swap(true, Ordering::AcqRel) {
                // SAFETY: posting to our window; if it is gone the post
                // fails harmlessly.
                unsafe {
                    let _ = PostMessageW(
                        Some(HWND(hwnd as *mut c_void)),
                        WM_SHELL_OUTPUT,
                        WPARAM(0),
                        LPARAM(0),
                    );
                }
            }
        }
    }

    fn focused_id(&self) -> PaneId {
        self.ws.focused()
    }

    /// The panes of the active tab, in layout order.
    fn visible_ids(&self) -> Vec<PaneId> {
        self.ws.tab().map(|t| t.root.panes()).unwrap_or_default()
    }

    fn is_visible(&self, id: PaneId) -> bool {
        self.ws.tab().is_some_and(|t| t.root.contains(id))
    }

    /// Whether `id` shows a focused cursor.
    fn has_keyboard(&self, id: PaneId) -> bool {
        self.focused && !self.side.focused && id == self.focused_id()
    }

    /// An id for a new shell or SFTP channel, below the forwarding
    /// engine's range.
    fn new_channel(&mut self) -> ChannelId {
        let channel = self.next_channel;
        self.next_channel = ((self.next_channel + 1) % crate::remote_app::FIRST_ID).max(1);
        channel
    }

    /// The pane whose SSH session has `channel`: its shell, or a jump
    /// host's login or stream on the way.
    fn pane_of_channel(&self, channel: ChannelId) -> Option<PaneId> {
        self.panes.values().find_map(|p| match &p.host {
            Host::Ssh(s) if s.owns(channel) => Some(p.id),
            Host::Telnet(s) if s.channel == channel => Some(p.id),
            Host::Winrm(s) if s.channel == channel => Some(p.id),
            _ => None,
        })
    }

    /// The pane with the SSH session for pane `id`: the gateway of a tmux
    /// pane, else the pane itself.
    fn host_pane(&self, id: PaneId) -> PaneId {
        self.panes.get(&id).and_then(Pane::gateway).unwrap_or(id)
    }

    /// A tmux pane in tmux layout, whose place tmux decides: it does not
    /// move between tabs natively.
    fn locked(&self, id: PaneId) -> bool {
        self.panes
            .get(&id)
            .and_then(Pane::gateway)
            .and_then(|g| self.tmux.get(&g))
            .is_some_and(|t| t.mode() == TmuxMode::Tmux)
    }

    fn locked_tab(&self, i: usize) -> bool {
        self.ws
            .tabs
            .get(i)
            .is_some_and(|t| t.root.panes().iter().any(|id| self.locked(*id)))
    }

    /// Lines of scrollback for `target`'s panes.
    fn scrollback_for(&self, target: &Target) -> Option<usize> {
        self.settings
            .profile(&target.alias)
            .and_then(|p| p.scrollback)
            .or(self.settings.scrollback)
    }

    /// A tmux watcher for SSH pane `id`, with its host's preferences.
    fn new_tmux(&self, id: PaneId) -> Tmux {
        let (mode, history) = match self.panes.get(&id).map(|p| &p.host) {
            Some(Host::Ssh(s)) => (
                self.settings
                    .profile(&s.target.alias)
                    .and_then(|p| p.tmux_layout.as_deref())
                    .and_then(TmuxMode::parse)
                    .unwrap_or(TmuxMode::Ferossh),
                self.scrollback_for(&s.target),
            ),
            _ => (TmuxMode::Ferossh, None),
        };
        let mut t = Tmux::new(
            id,
            mode,
            history.unwrap_or(TermSettings::DEFAULT_SCROLLBACK),
        );
        // Not attached yet, so nothing to send.
        let _ = t.want_keys(self.settings.tmux_keys);
        t.start_dir = self.profile_start_dir(id);
        t
    }

    /// The start directory in the profile of SSH pane `id`'s host.
    fn profile_start_dir(&self, id: PaneId) -> Option<String> {
        match self.panes.get(&id).map(|p| &p.host) {
            Some(Host::Ssh(s)) => self
                .settings
                .profile(&s.target.alias)
                .and_then(|p| p.start_dir.clone()),
            _ => None,
        }
    }

    /// Session > Start new tabs and panes in this directory, from pane
    /// `pane`: tmux is asked for a tmux pane's directory (the answer
    /// comes back as an action); an SSH shell's is the one it reported.
    fn start_dir_here(&mut self, pane: PaneId) -> Option<Command> {
        let host = self.host_pane(pane);
        if host != pane {
            let actions = self
                .tmux
                .get_mut(&host)
                .filter(|t| t.active())
                .map(|t| t.ask_dir(pane))
                .unwrap_or_default();
            self.run_tmux(host, actions);
            return None;
        }
        let p = self.panes.get(&pane)?;
        if !matches!(p.host, Host::Ssh(_)) {
            return Some(Command::Notice(
                "Only a pane connected to an SSH host has a start directory to save.".into(),
            ));
        }
        let Some(dir) = p.cwd.clone() else {
            return Some(Command::Notice(
                "FeroSSH does not know this shell's directory: it reports none and has a \
                 prompt FeroSSH does not read. Type the directory in Settings > Connection \
                 manager, Edit connection, Start dir."
                    .into(),
            ));
        };
        self.save_start_dir(pane, &String::from_utf8_lossy(&dir))
    }

    /// Keeps `dir` as the start directory of SSH pane `gateway`'s host:
    /// in its profile, and for the tmux sessions on that host now.
    fn save_start_dir(&mut self, gateway: PaneId, dir: &str) -> Option<Command> {
        let Some(Host::Ssh(s)) = self.panes.get(&gateway).map(|p| &p.host) else {
            return None;
        };
        let alias = s.target.alias.clone();
        let Some(dir) = ferossh_config::settings::start_dir(dir) else {
            return Some(Command::Notice(
                "This directory's name cannot be typed safely at a shell, so it is not saved."
                    .into(),
            ));
        };
        self.settings.profile_mut(&alias).start_dir = Some(dir.clone());
        self.save_settings();
        let gateways: Vec<PaneId> = self.tmux.keys().copied().collect();
        for g in gateways {
            let same = matches!(
                self.panes.get(&g).map(|p| &p.host),
                Some(Host::Ssh(o)) if o.target.alias.eq_ignore_ascii_case(&alias)
            );
            if same && let Some(t) = self.tmux.get_mut(&g) {
                t.start_dir = Some(dir.clone());
            }
        }
        Some(Command::Notice(format!(
            "New tabs and panes on {alias} start in {dir} now, also after FeroSSH restarts. \
             New tabs and panes opened from a pane whose directory FeroSSH knows still \
             follow that pane. Change or clear it in Edit connection, Start dir."
        )))
    }

    /// Writes to the host of SSH pane `id`, past any local prompt: tmux
    /// commands, and the line that starts tmux.
    fn send_host(&mut self, id: PaneId, bytes: &[u8]) {
        let effects = match self.panes.get_mut(&id).map(|p| &mut p.host) {
            Some(Host::Ssh(s)) => s.input(bytes),
            _ => return,
        };
        self.apply(id, effects);
    }

    /// Output from SSH pane `id`'s host, which may be tmux in control
    /// mode.
    fn host_output(&mut self, id: PaneId, bytes: &[u8]) {
        if !self.tmux.contains_key(&id) {
            let t = self.new_tmux(id);
            self.tmux.insert(id, t);
        }
        let Some(t) = self.tmux.get_mut(&id) else {
            return;
        };
        let actions = t.feed(&mut self.ws, bytes);
        self.run_tmux(id, actions);
    }

    /// Carries out what gateway `gateway`'s tmux watcher decided.
    fn run_tmux(&mut self, gateway: PaneId, actions: Vec<tmux::Action>) {
        // tmux shows the session's panes now: a workspace's plan for it
        // has done its part.
        if actions
            .iter()
            .any(|a| matches!(a, tmux::Action::Create { .. }))
        {
            self.workspace_tmux.remove(&gateway);
        }
        let mut structure = false;
        for action in actions {
            match action {
                tmux::Action::Write(bytes) => self.send_host(gateway, &bytes),
                tmux::Action::GatewayOutput(bytes) => {
                    if let Some(p) = self.panes.get_mut(&gateway) {
                        p.term.feed(&bytes);
                    }
                    self.log(gateway, &bytes);
                    self.watch_output(gateway, &bytes);
                }
                tmux::Action::Create {
                    native,
                    look,
                    cols,
                    rows,
                    ..
                } => {
                    self.add_tmux_pane(gateway, native, &look, cols, rows);
                    self.watch_agent(gateway, native);
                }
                tmux::Action::Feed { native, bytes } => {
                    if let Some(p) = self.panes.get_mut(&native) {
                        p.term.feed(&bytes);
                    }
                    self.log(native, &bytes);
                    self.watch_output(native, &bytes);
                }
                tmux::Action::Resize { native, cols, rows } => {
                    if let Some(p) = self.panes.get_mut(&native) {
                        p.term.resize(usize::from(cols), usize::from(rows));
                        p.grid.mark_all_dirty();
                        p.record_resize();
                    }
                }
                tmux::Action::Remove { native } => {
                    self.stop_log(native);
                    self.panes.remove(&native);
                    if self.mouse.pane == Some(native) {
                        self.mouse.pane = None;
                    }
                    structure = true;
                }
                tmux::Action::Focus { .. }
                | tmux::Action::ShowGateway
                | tmux::Action::Structure => structure = true,
                tmux::Action::Picker(names) => {
                    self.queued.push(Command::TmuxPicker { gateway, names });
                }
                tmux::Action::Crowded {
                    session,
                    have,
                    want,
                    others,
                } => {
                    let name = self
                        .tmux
                        .get(&gateway)
                        .and_then(|t| t.session_name())
                        .unwrap_or_default()
                        .to_owned();
                    self.queued.push(Command::TmuxCrowded(CrowdedOffer {
                        gateway,
                        host: self.key_host(gateway).unwrap_or_default(),
                        name,
                        session,
                        have,
                        want,
                        others,
                    }));
                }
                tmux::Action::AgentMarked(natives) => {
                    for native in natives {
                        self.watch_agent(gateway, native);
                    }
                }
                tmux::Action::Tell(text) => {
                    self.queued
                        .push(Command::Notice(crate::ssh::sanitize(&text)));
                }
                tmux::Action::Notice(text) => {
                    let text = crate::ssh::sanitize(&text);
                    self.show(gateway, &format!("\x1b[0;90m{text}\x1b[0m\r\n"));
                }
                tmux::Action::StartDir(dir) => {
                    if let Some(command) = self.save_start_dir(gateway, &dir) {
                        self.queued.push(command);
                    }
                }
                tmux::Action::DiffDir { native, dir } => {
                    if let Some(command) = self.open_diff(native, dir.into_bytes()) {
                        self.queued.push(command);
                    }
                }
            }
        }
        if structure {
            self.after_structure_change();
        }
    }

    /// A native pane for a tmux pane: the gateway's look, with the font,
    /// size and theme the session saved for its window.
    fn add_tmux_pane(
        &mut self,
        gateway: PaneId,
        native: PaneId,
        look: &tmux_saved::Look,
        cols: u16,
        rows: u16,
    ) {
        // The gateway's theme as picked, not a menu preview of another.
        let Some(g_theme) = self.committed_theme(gateway) else {
            return;
        };
        let Some(g) = self.panes.get(&gateway) else {
            return;
        };
        let (label, scrollback) = match &g.host {
            Host::Ssh(s) => (s.target.label(), self.scrollback_for(&s.target)),
            _ => (String::new(), None),
        };
        let mut font = g.font.clone();
        let mut metrics = g.metrics;
        // The connection's enforced look holds for each of its windows.
        let lock = g.lock.clone();
        // A saved look never overrides a Production or Staging colour.
        let theme = lock.theme(
            look.theme
                .as_deref()
                .and_then(Theme::by_name)
                .filter(|t| {
                    g_theme.group() != ThemeGroup::Warning && t.group() != ThemeGroup::Warning
                })
                .unwrap_or(g_theme),
        );
        if look.font.is_some() || look.size.is_some() {
            let wanted = lock.font(FontSpec::new(
                look.font.as_deref().unwrap_or(&font.family),
                look.size.unwrap_or(font.size_pt),
            ));
            if let Ok(m) = self.renderer.metrics(&wanted, self.dpi) {
                font = wanted;
                metrics = m;
            }
        }
        let mut pane = new_pane(native, font, theme, metrics, scrollback);
        pane.lock = lock;
        pane.term.resize(usize::from(cols), usize::from(rows));
        pane.host = Host::Tmux { gateway, label };
        pane.hl_host = self.panes.get(&gateway).and_then(|g| g.hl_host.clone());
        pane.name = look.name.as_deref().and_then(live::clean_name);
        pane.log.enabled = self.panes.get(&gateway).is_some_and(|g| g.log.enabled);
        pane.log.raw = self.panes.get(&gateway).is_some_and(|g| g.log.raw);
        // The connection's security rules hold for each of its windows.
        pane.policy = self
            .panes
            .get(&gateway)
            .map(|g| g.policy)
            .unwrap_or_default();
        self.panes.insert(native, pane);
        self.apply_highlight(native, false);
        // With the audit trail on, an agent pane's first log is already
        // named after its agent.
        let agent = self
            .settings
            .agent_audit
            .then(|| self.tmux.get(&gateway).and_then(|t| t.agent_of(native)))
            .flatten()
            .map(str::to_owned);
        self.start_log_as(native, agent.as_deref());
    }

    /// Tells each tmux session its panes' sizes, and saves its layout and
    /// looks when they changed.
    fn sync_tmux(&mut self) {
        let pad = padding(self.dpi);
        let gateways: Vec<PaneId> = self
            .tmux
            .iter()
            .filter(|(_, t)| t.active())
            .map(|(g, _)| *g)
            .collect();
        // A theme only previewed in the menu is not saved.
        let previewed = self
            .look_preview
            .as_ref()
            .filter(|p| p.theme_by.is_some())
            .map(|p| (p.pane, p.theme.name));
        for g in gateways {
            let panes = &self.panes;
            let cells = |n: PaneId| {
                // A hidden pane never shown here has no size to give.
                let p = panes.get(&n).filter(|p| p.rect.w > 0 && p.rect.h > 0)?;
                let m = p.metrics;
                let cols = (p.rect.w - 2 * pad).max(0) / m.width.max(1) as i32;
                let rows = (p.rect.h - 2 * pad).max(0) / m.height.max(1) as i32;
                Some((
                    u16::try_from(cols.max(1)).unwrap_or(u16::MAX),
                    u16::try_from(rows.max(1)).unwrap_or(u16::MAX),
                ))
            };
            let look_of = |n: PaneId| {
                panes
                    .get(&n)
                    .map(|p| tmux_saved::Look {
                        font: Some(p.font.family.clone()),
                        size: Some(p.font.size_pt),
                        theme: Some(
                            previewed
                                .filter(|(id, _)| *id == n)
                                .map_or(p.theme.name, |(_, name)| name)
                                .to_owned(),
                        ),
                        name: p.name.clone(),
                    })
                    .unwrap_or_default()
            };
            let Some(t) = self.tmux.get_mut(&g) else {
                continue;
            };
            let mut actions = t.sync_sizes(&self.ws, &cells);
            actions.extend(t.sync_saved(&self.ws, &look_of));
            self.run_tmux(g, actions);
        }
    }

    /// Session > tmux > Detach other clients, as answered in the dialog.
    /// Skipped when another session is attached by now.
    /// Keeps a question about other tmux clients for when no dialog is
    /// open, replacing an earlier one about the same gateway and session.
    fn wait_crowded(&mut self, offer: CrowdedOffer) {
        match self
            .crowded_waiting
            .iter_mut()
            .find(|o| o.gateway == offer.gateway && o.session == offer.session)
        {
            Some(o) => *o = offer,
            None => self.crowded_waiting.push(offer),
        }
    }

    fn detach_other_tmux(&mut self, gateway: PaneId, session: ferossh_tmuxcc::SessionId) {
        let Some(t) = self.tmux.get_mut(&gateway).filter(|t| t.active()) else {
            return;
        };
        let actions = t.detach_others(Some(session));
        self.run_tmux(gateway, actions);
    }

    /// SSH pane `id` lost its connection: if it ran tmux, its panes go
    /// and the session is attached again after the next login.
    fn tmux_lost(&mut self, id: PaneId) {
        let key = self.pane_sftp_key(id);
        let Some(t) = self.tmux.get_mut(&id) else {
            return;
        };
        let actions = t.connection_lost(&mut self.ws);
        if let Some(key) = key {
            if let Some(name) = t.reattach.take() {
                // The pane's tmux watcher may be made anew before the
                // login: whether the session was on the shared server
                // goes along.
                let shared = t.take_reattach_shared(&name);
                self.reattach.insert(id, (key, Some((name, shared))));
            } else if t.take_stay_at_shell() {
                // Not attached again: the login stays at the shell.
                self.reattach.insert(id, (key, None));
            }
        }
        self.run_tmux(id, actions);
    }

    /// After a login on SSH pane `id`: attach tmux again after a dropped
    /// connection, or when the host's profile asks for it. Only one pane
    /// per host runs tmux, so a second tab on the host stays a shell.
    /// Returns whether it attaches tmux.
    fn tmux_after_login(&mut self, id: PaneId) -> bool {
        let Some(Host::Ssh(s)) = self.panes.get(&id).map(|p| &p.host) else {
            return false;
        };
        let key = sftp_key(&s.target);
        let profile = self
            .settings
            .profile(&s.target.alias)
            .and_then(|p| p.tmux.clone());
        // A workspace's tmux session, on the host it was saved on: made
        // again first if gone.
        let workspace = self
            .workspace_tmux
            .get(&id)
            .is_some_and(|w| w.key.as_deref() == Some(key.as_str()));
        if !workspace {
            self.workspace_tmux.remove(&id);
        }
        let mut shared = false;
        let (name, rebuild) = match self.reattach.remove(&id) {
            Some((k, Some((name, on_shared)))) if k == key => {
                shared = on_shared;
                (name, None)
            }
            Some((k, None)) if k == key => return false,
            _ => match self.workspace_tmux.get(&id) {
                Some(w) => (w.name.clone(), w.rebuild.clone()),
                None => match profile {
                    Some(name) => (name, None),
                    None => return false,
                },
            },
        };
        let busy = self.tmux.iter().any(|(g, t)| {
            *g != id && t.active() && self.pane_sftp_key(*g).as_deref() == Some(key.as_str())
        });
        if busy {
            // Only one pane per host shows tmux. A workspace's session
            // stays wanted, and kept when saving, until this pane closes.
            if workspace {
                self.show(
                    id,
                    &format!(
                        "\x1b[0;90mAnother pane already shows tmux on this host, so the \
                         workspace's tmux session {} is not attached here.\x1b[0m\r\n",
                        crate::ssh::sanitize(&name)
                    ),
                );
            }
            return false;
        }
        // The plan stays (saving keeps its panes) until tmux shows them.
        if let Some(line) = rebuild {
            self.send_host(id, line.as_bytes());
        }
        if shared {
            if !self.tmux.contains_key(&id) {
                let t = self.new_tmux(id);
                self.tmux.insert(id, t);
            }
            if let Some(t) = self.tmux.get_mut(&id) {
                t.reattach_on_shared(&name);
            }
        }
        self.attach_tmux(id, &name, false)
    }

    /// Types the `cd` to the directory of the pane a new tab or pane was
    /// opened from at pane `id`'s freshly logged-in shell. Once: a
    /// reconnect starts where the server starts it. Otherwise (the
    /// directory was not known, or later logins) the host's start
    /// directory, after every login.
    fn cd_after_login(&mut self, id: PaneId) {
        let split_dir = self.panes.get_mut(&id).and_then(|p| p.start_dir.take());
        let Some(dir) = split_dir.or_else(|| self.profile_start_dir(id).map(String::into_bytes))
        else {
            return;
        };
        if let Some(line) = same_dir::cd_line(&dir) {
            self.send_host(id, &line);
        }
    }

    /// Types the line that starts tmux in control mode at pane `id`'s
    /// shell.
    /// Whether tmux was started: not over Mosh.
    fn attach_tmux(&mut self, id: PaneId, name: &str, pick: bool) -> bool {
        // Mosh sends screens, not the byte stream tmux control mode needs.
        if let Some(Host::Ssh(s)) = self.panes.get(&id).map(|p| &p.host)
            && s.target.mosh.is_some()
        {
            self.show(
                id,
                "\x1b[0;90mtmux integration needs an SSH shell: it does not work over Mosh. \
                 Run tmux in the pane as usual.\x1b[0m\r\n",
            );
            return false;
        }
        if !self.tmux.contains_key(&id) {
            let t = self.new_tmux(id);
            self.tmux.insert(id, t);
        }
        let Some(t) = self.tmux.get_mut(&id) else {
            return false;
        };
        let line = t.attach(name, pick);
        self.send_host(id, &line);
        true
    }

    /// Whether gateway pane `id` can start or join a tmux session: in
    /// one already, or at a logged-in SSH shell (not over Mosh).
    fn tmux_ready(&self, id: PaneId) -> std::result::Result<(), String> {
        if self.tmux.get(&id).is_some_and(Tmux::active) {
            return Ok(());
        }
        match self.panes.get(&id).map(|p| &p.host) {
            Some(Host::Ssh(s)) if s.target.mosh.is_some() => {
                Err("tmux integration needs an SSH shell: it does not work over Mosh.".into())
            }
            // tmux is typed at a shell: not into a login without one, or
            // into the program a RemoteCommand runs.
            Some(Host::Ssh(s)) if s.target.no_shell() || s.target.command.is_some() => Err(
                "Sharing and joining tmux type a command at the host's shell, and this \
                 connection has none (file transfer or tunnel only, or a RemoteCommand)."
                    .into(),
            ),
            // A login script would type its next line into tmux.
            Some(Host::Ssh(_)) if self.scripts.contains_key(&id) => Err(
                "A script is still running in this pane. Let it finish, or stop it, then try \
                 again."
                    .into(),
            ),
            Some(Host::Ssh(s)) if s.state() == State::Connected && !s.prompt_active() => Ok(()),
            _ => Err(NOT_IN_SHELL.into()),
        }
    }

    /// The account gateway `id` logged in as and the session to offer
    /// sharing: the one attached, or the host's tmux session.
    fn tmux_share_defaults(&self, id: PaneId) -> Option<(String, String)> {
        let Some(Host::Ssh(s)) = self.panes.get(&id).map(|p| &p.host) else {
            return None;
        };
        let session = self
            .tmux
            .get(&id)
            .filter(|t| t.active())
            .and_then(|t| t.session_name().map(str::to_owned))
            .or_else(|| {
                self.settings
                    .profile(&s.target.alias)
                    .and_then(|p| p.tmux.clone())
            })
            .unwrap_or_else(|| "main".to_owned());
        Some((crate::ssh::sanitize(&s.target.user), session))
    }

    /// Session > tmux > Share this session, as answered: fields Session
    /// and Accounts. Returns a problem to show, if any.
    fn share_tmux(
        &mut self,
        gateway: PaneId,
        answer: &crate::fields_view::Answer,
    ) -> Option<String> {
        if let Err(why) = self.tmux_ready(gateway) {
            return Some(why);
        }
        let field = |i: usize| answer.fields.get(i).map_or("", |f| f.trim());
        let session = ferossh_tmuxcc::command::session_name(field(0));
        let accounts = match ferossh_tmuxcc::command::account_names(field(1)) {
            Ok(a) => a,
            Err(bad) => {
                return Some(format!(
                    "\"{}\" is not an account name.",
                    crate::ssh::sanitize(&bad)
                ));
            }
        };
        let user = self.tmux_share_defaults(gateway).map(|(u, _)| u)?;
        if accounts.is_empty() {
            // Attached already: that session is the one shared, on the
            // server it runs on.
            let attached = self
                .tmux
                .get(&gateway)
                .filter(|t| t.active())
                .map(|t| (t.session_name().map(str::to_owned), t.on_shared_server()));
            let is_attached = attached.is_some();
            let (session, shared_server) = match attached {
                Some((name, shared)) => (name.unwrap_or(session), shared),
                None => (session, false),
            };
            let text = if shared_server {
                format!(
                    "Anyone logged in to this host as {user} can watch tmux session {session}: \
                     in FeroSSH with Session > tmux > Join a shared session (Shared by account \
                     {user}, Session {session}), or with: tmux -S \
                     {}{user}/default attach -E -r -t {session}\n\n\
                     Session > tmux > Stop sharing detaches those watching.",
                    ferossh_tmuxcc::command::SHARE_DIR_PREFIX
                )
            } else {
                format!(
                    "Anyone logged in to this host as {user} can watch tmux session {session}: \
                     in FeroSSH with Session > tmux > Join a shared session (Session \
                     {session}), or with: tmux attach -E -r -t {session}\n\n\
                     Session > tmux > Stop sharing detaches those watching."
                )
            };
            if is_attached {
                return Some(text);
            }
            if !self.attach_tmux(gateway, &session, false) {
                return None;
            }
            let actions = self
                .tmux
                .get_mut(&gateway)
                .map(|t| t.share_same_account(text))
                .unwrap_or_default();
            self.run_tmux(gateway, actions);
            return None;
        }
        if !self.tmux.contains_key(&gateway) {
            let t = self.new_tmux(gateway);
            self.tmux.insert(gateway, t);
        }
        let share = tmux::Share {
            accounts,
            can_type: answer.option,
        };
        let actions = self
            .tmux
            .get_mut(&gateway)
            .map(|t| t.share(&session, share))
            .unwrap_or_default();
        self.run_tmux(gateway, actions);
        None
    }

    /// Session > tmux > Join a shared session, as answered: fields Shared
    /// by account and Session. Returns a problem to show, if any.
    fn join_tmux(
        &mut self,
        gateway: PaneId,
        answer: &crate::fields_view::Answer,
    ) -> Option<String> {
        if let Err(why) = self.tmux_ready(gateway) {
            return Some(why);
        }
        let field = |i: usize| answer.fields.get(i).map_or("", |f| f.trim());
        let owner = match field(0) {
            "" => None,
            text => match ferossh_tmuxcc::command::account_name(text) {
                Some(a) => Some(a),
                None => {
                    return Some(format!(
                        "\"{}\" is not an account name.",
                        crate::ssh::sanitize(text)
                    ));
                }
            },
        };
        // A name is joined exactly as typed (spaces too, which tmux
        // allows), never cleaned into another session's name.
        let raw = answer.fields.get(1).map_or("", String::as_str);
        let session = Some(raw).filter(|s| !s.trim().is_empty());
        if let Some(s) = session
            && ferossh_tmuxcc::command::session_name(s) != s
        {
            return Some(format!(
                "\"{}\" has characters FeroSSH does not type into a command line. Leave \
                 Session empty to pick the session from the list instead.",
                crate::ssh::sanitize(s)
            ));
        }
        if !self.tmux.contains_key(&gateway) {
            let t = self.new_tmux(gateway);
            self.tmux.insert(gateway, t);
        }
        let actions = self
            .tmux
            .get_mut(&gateway)
            .map(|t| t.join(owner.as_deref(), session, answer.option))
            .unwrap_or_default();
        self.run_tmux(gateway, actions);
        None
    }

    /// Feeds local text (not from the host) to a pane's terminal.
    fn show(&mut self, id: PaneId, text: &str) {
        if self.run_login.contains(&id)
            && let Some(line) = batch::last_line(text)
        {
            self.run_notes.insert(id, line);
        }
        if let Some(p) = self.panes.get_mut(&id) {
            p.term.feed(text.as_bytes());
        }
    }

    /// Ends whatever the pane is connected to.
    fn end_host(&mut self, id: PaneId) {
        // Another connection takes the pane: an answer still to come is
        // for one no longer wanted.
        self.connect_pending.remove(&id);
        self.drop_rules(id);
        self.forget_preview_scans(id);
        self.scripts.remove(&id);
        self.zmodem.remove(&id);
        self.retries.remove(&id);
        // tmux on it is over too; a reattach after a dropped connection
        // stays wanted.
        if let Some(mut t) = self.tmux.remove(&id) {
            let actions = t.connection_lost(&mut self.ws);
            self.run_tmux(id, actions);
        }
        self.stop_diff(id);
        let effects = match self.panes.get_mut(&id).map(|p| &mut p.host) {
            Some(Host::Ssh(session)) => session.close(),
            Some(Host::Telnet(session)) => session.close(),
            Some(Host::Winrm(session)) => session.close(),
            _ => Vec::new(),
        };
        self.apply(id, effects);
        self.stop_log(id);
        if let Some(p) = self.panes.get_mut(&id) {
            p.host = Host::Ask(String::new());
            // The connection's enforced look goes with it; the next one
            // brings its own.
            p.lock = look::Lock::default();
            p.desktop = None;
            p.title = None;
            p.cwd = None;
            p.cwd_host = None;
            p.cwd_reported = false;
            p.prompt_host = None;
            p.start_dir = None;
            p.local_cwd = None;
            p.hl_host = None;
        }
        // A host's rules leave with it; the pane's own stop pattern stays.
        self.apply_highlight(id, false);
        self.prune_sftp();
        self.prune_forwards();
    }

    fn start_shell(&mut self, id: PaneId) {
        self.start_shell_in(id, None);
    }

    /// Starts the local shell in folder `dir`, or in the profile folder.
    fn start_shell_in(&mut self, id: PaneId, dir: Option<&str>) {
        self.end_host(id);
        let notify = self.notifier();
        let Some(p) = self.panes.get_mut(&id) else {
            return;
        };
        let (cols, rows) = (p.term.cols(), p.term.rows());
        match Shell::spawn(&self.command, cols, rows, dir, notify) {
            Ok(shell) => {
                p.host = Host::Local {
                    shell: Some(shell),
                    exited: false,
                };
                self.start_log(id);
                // A workspace's local pane runs its script once its shell
                // runs (also when it starts only on a retry).
                self.workspace_start(id, true);
            }
            Err(e) => {
                let text = format!(
                    "\x1b[0;31mCould not start {}: {}\x1b[0m\r\nPress Enter to try again.\r\n",
                    self.command,
                    e.message()
                );
                p.host = Host::Local {
                    shell: None,
                    exited: true,
                };
                self.show(id, &text);
            }
        }
        self.update_title();
        self.refresh(id);
    }

    /// Shows the connect prompt.
    fn ask_destination(&mut self, id: PaneId) {
        self.end_host(id);
        if let Some(p) = self.panes.get_mut(&id) {
            p.term.scroll_to_bottom();
        }
        self.show(id, &format!("\r\n{CONNECT_PROMPT}"));
        self.update_title();
        self.refresh_chrome();
        self.refresh(id);
    }

    fn set_title_text(&self, text: &str) {
        // SAFETY: our window and a valid string.
        let _ = unsafe { SetWindowTextW(self.hwnd, &HSTRING::from(text)) };
    }

    /// The window title follows the focused pane.
    fn update_title(&self) {
        if self.standby.capture == Capture::Waiting {
            self.set_title_text(&format!(
                "Press the new standby hotkey, or Esc to cancel - {APP_NAME}"
            ));
            return;
        }
        let focused = self.focused_id();
        let label = self.panes.get(&focused).map(Pane::label);
        let badge = self.forwarding(&self.forward_view(), focused).badge();
        let legacy = if self.unencrypted(focused) {
            " ⚠ (Telnet, unencrypted)"
        } else if self.legacy_in_use(focused) {
            tabstrip::LEGACY_BADGE
        } else {
            ""
        };
        let broadcast = match self.broadcast {
            broadcast::Scope::Off => "",
            broadcast::Scope::Tab => " (broadcast to tab)",
            broadcast::Scope::All => " (broadcast to all tabs)",
        };
        match label {
            Some(l) if l != "new tab" => {
                self.set_title_text(&format!("{l}{legacy}{badge}{broadcast} - {APP_NAME}"));
            }
            _ => self.set_title_text(APP_NAME),
        }
    }

    /// Every connection's forwards, from the forwarding engine.
    fn forward_view(&self) -> Vec<ConnView> {
        let mut views: Vec<ConnView> = self
            .workers
            .values()
            .flat_map(|w| w.forwarder.view())
            .collect();
        views.sort_by_key(|v| v.connection);
        views
    }

    /// What the badge of pane `id`'s tab shows.
    fn forwarding(&self, views: &[ConnView], id: PaneId) -> Forwarding {
        let Some(connection) = self.pane_connection(id) else {
            return Forwarding::None;
        };
        match views.iter().find(|v| v.connection == connection) {
            Some(v) if v.inbound() => Forwarding::Inbound,
            Some(v) if !v.forwards.is_empty() => Forwarding::Outbound,
            _ => Forwarding::None,
        }
    }

    /// What the session manager lists: each tab's sessions in tab order,
    /// then a snippet run's sessions that no tab shows. Empty connect
    /// prompts are left out.
    fn open_sessions(&self) -> Vec<LiveSession> {
        let views = self.forward_view();
        let focused = self.focused_id();
        let mut hidden: Vec<PaneId> = self
            .run_hidden
            .iter()
            .chain(&self.launch_hidden)
            .copied()
            .collect();
        hidden.sort_unstable();
        // Panes the user hid, in the order they were hidden.
        hidden.extend(self.ws.hidden());
        let panes = self
            .ws
            .tabs
            .iter()
            .enumerate()
            .flat_map(|(i, t)| t.root.panes().into_iter().map(move |id| (Some(i), id)))
            .chain(hidden.into_iter().map(|id| (None, id)));
        let state = |s: State| match s {
            State::Connected => LiveState::Connected,
            State::Connecting => LiveState::Connecting,
            State::Blocked | State::Ended => LiveState::Ended,
        };
        let mut out = Vec::new();
        let now = Instant::now();
        for (tab, id) in panes {
            let Some(p) = self.panes.get(&id) else {
                continue;
            };
            let mut notes = Vec::new();
            let (kind, target, mut st) = match &p.host {
                Host::Ask(_) | Host::Replay(_) | Host::Diff(_) => continue,
                Host::Ssh(s) => {
                    if self.via.get(&s.connection).is_some_and(|v| !v.is_empty())
                        || self.proxies.contains_key(&s.connection)
                    {
                        notes.push("via jump host");
                    }
                    let kind = if s.target.mosh.is_some() {
                        live::Kind::Mosh
                    } else if s.target.sftp_only {
                        live::Kind::Sftp
                    } else if s.target.tunnel_only {
                        live::Kind::Tunnel
                    } else {
                        live::Kind::Ssh
                    };
                    (kind, s.target.label(), state(s.state()))
                }
                Host::Telnet(s) => {
                    notes.push("unencrypted");
                    (live::Kind::Telnet, s.target.label(), state(s.state()))
                }
                Host::Winrm(s) => (live::Kind::WinRm, s.target.label(), state(s.state())),
                Host::Serial { port, target, .. } => (
                    live::Kind::Serial,
                    target.label(),
                    if port.is_some() {
                        LiveState::Connected
                    } else {
                        LiveState::Ended
                    },
                ),
                Host::Tmux { label, .. } => (live::Kind::Tmux, label.clone(), LiveState::Connected),
                Host::Desktop { label, .. } => {
                    (live::Kind::Desktop, label.clone(), LiveState::Connected)
                }
                Host::Local { exited, .. } => (
                    live::Kind::Local,
                    "local shell".to_owned(),
                    if *exited {
                        LiveState::Ended
                    } else {
                        LiveState::Connected
                    },
                ),
            };
            if self.retries.contains_key(&id) {
                st = LiveState::Reconnecting;
            }
            if self.tmux.get(&id).is_some_and(|t| t.active()) {
                notes.push("tmux");
            }
            if self.forwarding(&views, id) != Forwarding::None {
                notes.push("forwards");
            }
            if self.legacy_in_use(id) {
                notes.push("older crypto");
            }
            if p.log.enabled {
                notes.push("logging");
            }
            let user_hid = self.ws.is_hidden(id);
            if tab.is_none() && !user_hid {
                notes.push("script run");
            }
            let agent = self.agent_of(id).map(|name| {
                let state = p
                    .quiet
                    .as_ref()
                    .map_or(crate::attention::State::Idle, |w| w.state(now));
                let asked = p.attention_since.filter(|_| p.attention);
                let (what, since) = crate::agents::status(asked, state, now);
                live::Agent {
                    name: name.to_owned(),
                    state: what,
                    since: since.map(crate::attention::spoken),
                    waited: asked.map(|_| since.unwrap_or_default()),
                    last: crate::agents::last_line(&p.term.screen_text()),
                }
            });
            out.push(LiveSession {
                pane: id,
                tab,
                hidden: user_hid,
                kind,
                agent,
                target,
                name: p.name.clone(),
                title: p.title.clone().filter(|t| !t.is_empty()),
                state: st,
                notes,
                focused: tab.is_some() && id == focused,
            });
        }
        out
    }

    fn live_action(&mut self, action: Option<LiveAction>) -> Option<Command> {
        match action? {
            LiveAction::Show(id) => {
                if self.run_hidden.contains(&id) {
                    return self.show_run_pane(id);
                }
                if self.launch_hidden.contains(&id) {
                    self.reveal_launch(id);
                    return None;
                }
                if self.ws.is_hidden(id) {
                    self.show_hidden(id);
                    return None;
                }
                self.focus_pane(id);
                self.focus_terminal();
                None
            }
            LiveAction::Hide(id) => self.hide_pane(id),
            LiveAction::Close(id) => {
                let s = self.open_sessions().into_iter().find(|s| s.pane == id)?;
                let in_tabs: usize = self.ws.tabs.iter().map(|t| t.root.panes().len()).sum();
                Some(Command::CloseSession {
                    pane: id,
                    label: s.target,
                    live: s.state != LiveState::Ended,
                    last: s.tab.is_some() && in_tabs == 1,
                })
            }
            LiveAction::Rename(id, name) => {
                self.rename_session(id, name);
                self.end_rename();
                None
            }
            LiveAction::Leave => {
                self.focus_terminal();
                None
            }
        }
    }

    /// Window > Rename session, a double-click on a tab, or its right-click
    /// menu: the session manager opens with pane `id`'s name to type.
    fn start_rename(&mut self, id: PaneId) {
        if !self.open_sessions().iter().any(|s| s.pane == id) {
            return;
        }
        let back = self.rename_return.take();
        let before = match (self.side.visible, self.side.view) {
            (true, SideView::Palette) => {
                self.palette_return = None;
                None
            }
            (visible, view) => visible.then_some(view),
        };
        if !(self.side.visible && self.side.view == SideView::Live) {
            self.show_side(SideView::Live, true);
        }
        // A rename started during another keeps where the first goes back.
        self.rename_return = Some(back.unwrap_or(before));
        self.side.focused = true;
        let all = self.open_sessions();
        let rows = self.side.grid.rows();
        self.live_view.start_rename(id, &all, rows);
        self.refresh_chrome();
        self.request_full_redraw();
        self.refresh(self.focused_id());
    }

    /// After a rename that opened the session manager: the side pane goes
    /// back to what it showed, and the keyboard to the terminal.
    fn end_rename(&mut self) {
        match self.rename_return.take() {
            None => {}
            Some(None) => self.hide_side(),
            Some(Some(SideView::Live)) => self.focus_terminal(),
            Some(Some(view)) => {
                self.show_side(view, false);
                self.focus_terminal();
            }
        }
        self.update_menu_checks();
    }

    /// Gives pane `id`'s session the name (`None` clears it). A tmux pane's
    /// window takes it too, and the session saves it with the layout.
    fn rename_session(&mut self, id: PaneId, name: Option<String>) {
        let name = name.as_deref().and_then(live::clean_name);
        let Some(p) = self.panes.get_mut(&id) else {
            return;
        };
        p.name = name.clone();
        if let Some(gateway) = p.gateway()
            && let Some(t) = self.tmux.get_mut(&gateway).filter(|t| t.active())
        {
            let actions = t.rename(id, name.as_deref());
            self.run_tmux(gateway, actions);
            self.sync_tmux();
        }
        self.update_title();
        self.refresh_chrome();
    }

    /// The session manager's Delete, once the user said yes: closes the
    /// session's pane, or ends a snippet run's session that no tab shows.
    fn close_session(&mut self, id: PaneId) -> Option<Command> {
        if self.run_hidden.contains(&id) {
            self.drop_run_pane(id);
            self.refresh_chrome();
            return None;
        }
        if self.launch_hidden.contains(&id) {
            self.abandon_launch(id);
            return None;
        }
        self.launches.remove(&id);
        self.close_pane(id)
    }

    /// The X server forwarded X11 goes to: the X11Display setting, else
    /// `DISPLAY`, else display 0 on this PC.
    fn x11_display(&self) -> std::result::Result<Display, String> {
        let text = self
            .settings
            .x11_display
            .clone()
            .or_else(|| std::env::var("DISPLAY").ok().filter(|d| !d.is_empty()))
            .unwrap_or_else(|| "localhost:0".to_owned());
        Display::parse(&text).ok_or(text)
    }

    /// X11 forwarding for a new shell in pane `id`, on connection `shared`
    /// when it shares one: the screen and the fake cookie the server gets.
    /// The real cookie never goes to the worker: the forwards engine swaps
    /// it in (see [`X11Setup`]). A shared connection keeps the fake cookie
    /// its first shell got, as the worker does.
    fn x11_auth(&mut self, id: PaneId, shared: Option<ChannelId>) -> Option<X11Auth> {
        let display = match self.x11_display() {
            Ok(d) => d,
            Err(text) => {
                let text = format!(
                    "\x1b[0;31mX11Display \"{}\" is not a display (try localhost:0); X11 is \
                     not forwarded.\x1b[0m\r\n",
                    crate::ssh::sanitize(&text)
                );
                self.show(id, &text);
                return None;
            }
        };
        let earlier = shared.and_then(|conn| {
            self.panes.values().find_map(|p| match &p.host {
                Host::Ssh(s) if s.connection == conn && s.channel == conn => {
                    s.x11.as_ref().map(|a| a.cookie.clone())
                }
                _ => None,
            })
        });
        let cookie = match earlier {
            Some(c) => c,
            None => X11Setup::new_fake()?.to_vec(),
        };
        Some(X11Auth {
            screen: display.screen,
            protocol: MIT_COOKIE.to_owned(),
            cookie,
        })
    }

    /// The authorisation the X server at `display` expects, from
    /// `XAUTHORITY` or `~/.Xauthority` (none, for an X server without
    /// access control).
    fn x11_real_auth(display: &Display) -> (String, Vec<u8>) {
        let file = std::env::var_os("XAUTHORITY")
            .map(PathBuf::from)
            .unwrap_or_else(|| home().join(".Xauthority"));
        let entries = std::fs::read(file)
            .map(|b| xauth_entries(&b))
            .unwrap_or_default();
        find_cookie(&entries, display).unwrap_or_default()
    }

    /// A fresh login in pane `id`: starts the connection's forwards (an
    /// empty list too, so forwards can be added) and says what runs.
    fn start_forwards(&mut self, id: PaneId) {
        let Some(Host::Ssh(s)) = self.panes.get(&id).map(|p| &p.host) else {
            return;
        };
        if s.connection != s.channel {
            return;
        }
        let target = s.target.clone();
        let connection = s.connection;
        // The fake cookie the worker gave the server.
        let fake = s
            .x11
            .as_ref()
            .and_then(|a| <[u8; 16]>::try_from(a.cookie.as_slice()).ok());
        let x11 = target
            .forward_x11
            .then(|| self.x11_display().ok())
            .flatten()
            .zip(fake)
            .map(|(display, fake)| {
                let (real_name, real_data) = Self::x11_real_auth(&display);
                X11Setup {
                    display,
                    fake,
                    real_name,
                    real_data: Zeroizing::new(real_data),
                }
            });
        let mut notes: Vec<String> = target.forwards.iter().map(ToString::to_string).collect();
        if let Some(x) = &x11 {
            notes.push(format!("X11 to {}", x.display));
        }
        let Some(w) = self.workers.get(&connection) else {
            return;
        };
        w.forwarder.start(
            connection,
            target.label(),
            ForwardSetup {
                forwards: target.forwards,
                gateway_ports: target.gateway_ports,
                x11,
            },
        );
        if !notes.is_empty() {
            let text = format!(
                "\x1b[0;90mForwarding {}. Ctrl+Shift+P lists the forwards.\x1b[0m\r\n",
                notes.join(", ")
            );
            self.show(id, &text);
        }
    }

    /// Stops the forwards of connections no logged-in pane and no remote
    /// desktop uses any more.
    fn prune_forwards(&mut self) {
        self.prune_vdesks();
        for w in self.workers.values() {
            for v in w.forwarder.view() {
                let used = self.panes.values().any(|p| match &p.host {
                    Host::Ssh(s) => s.connection == v.connection && s.state() == State::Connected,
                    Host::Desktop { connection, .. } => {
                        *connection == v.connection && p.desktop.is_some()
                    }
                    _ => false,
                }) || self.mstsc.iter().any(|(_, c)| *c == v.connection);
                if !used {
                    w.forwarder.stop(v.connection);
                }
            }
        }
        self.prune_workers();
    }

    /// Retires the workers of connections that no pane logs in on or is
    /// logged in on, no remote desktop and no SFTP channel uses: each ends
    /// [`RETIRE_GRACE`] later.
    fn prune_workers(&mut self) {
        let unused: Vec<ChannelId> = self
            .workers
            .keys()
            .copied()
            .filter(|&c| !self.connection_in_use(c))
            .collect();
        if unused.is_empty() {
            return;
        }
        let now = Instant::now();
        for c in unused {
            if let Some(w) = self.workers.remove(&c) {
                self.retiring.push((w, now));
            }
            self.proxies.remove(&c);
        }
        // A diff tab does not keep its connection; git running there now
        // ends as a dropped connection would, with r to try again.
        let dropped: Vec<ChannelId> = self
            .diffs
            .keys()
            .copied()
            .filter(|&ch| {
                self.diff_on(ch)
                    .is_some_and(|c| !self.workers.contains_key(&c))
            })
            .collect();
        for channel in dropped {
            self.on_diff(
                channel,
                Message::Disconnected {
                    channel,
                    reason: "the connection was closed".into(),
                },
            );
        }
        let workers = &self.workers;
        self.sftp_routes.retain(|_, c| workers.contains_key(c));
        self.via.retain(|c, _| workers.contains_key(c));
        self.stats
            .retain(|_, f| workers.contains_key(&f.connection));
        self.system_reads
            .retain(|_, r| workers.contains_key(&r.connection));
        // SAFETY: our window and timer.
        unsafe {
            SetTimer(
                Some(self.hwnd),
                TIMER_RETIRE,
                u32::try_from(RETIRE_GRACE.as_millis()).unwrap_or(u32::MAX),
                None,
            );
        }
    }

    /// Whether anything still needs the SSH connection `connection`, or a
    /// connection that goes through it.
    fn connection_in_use(&self, connection: ChannelId) -> bool {
        self.used_directly(connection)
            || self
                .via
                .iter()
                .any(|(c, hops)| hops.contains(&connection) && self.used_directly(*c))
    }

    fn used_directly(&self, connection: ChannelId) -> bool {
        self.panes.values().any(|p| match &p.host {
            Host::Ssh(s) => {
                s.connection == connection
                    && matches!(s.state(), State::Connecting | State::Connected)
            }
            Host::Telnet(s) => {
                s.connection() == connection
                    && matches!(s.state(), State::Connecting | State::Connected)
            }
            Host::Winrm(s) => {
                s.connection() == connection
                    && matches!(s.state(), State::Connecting | State::Connected)
            }
            Host::Desktop { connection: c, .. } => *c == connection && p.desktop.is_some(),
            _ => false,
        }) || self.desktops.keys().any(|(c, ..)| *c == connection)
            // A virtual desktop on its way to a tab.
            || self
                .vdesks
                .values()
                .any(|v| v.connection == connection && v.tab && !v.shown)
            || self
                .sftp
                .values()
                .any(|r| r.connection() == Some(connection))
            || crate::remote_app::connections_in_use().contains(&connection)
            || self.mstsc.iter().any(|(_, c)| *c == connection)
            || self
                .winrm_closing
                .values()
                .any(|w| w.connection() == connection)
    }

    /// Ends the workers that retired long enough ago.
    fn on_retire_timer(&mut self) {
        self.retiring
            .retain(|(_, since)| since.elapsed() < RETIRE_GRACE);
        if self.retiring.is_empty() {
            // SAFETY: our window and timer.
            unsafe {
                let _ = KillTimer(Some(self.hwnd), TIMER_RETIRE);
            }
        }
    }

    /// The SSH connection pane `id` is logged in on; a tmux pane's is its
    /// gateway's.
    /// Whether pane `id`'s connection (its gateway's, for a tmux pane)
    /// uses the opt-in legacy algorithms.
    fn legacy_in_use(&self, id: PaneId) -> bool {
        match self.panes.get(&id).map(|p| &p.host) {
            Some(Host::Ssh(s)) => s.legacy_in_use(),
            Some(Host::Tmux { gateway, .. }) => self.legacy_in_use(*gateway),
            _ => false,
        }
    }

    /// Whether pane `id` is a Telnet session, which nothing encrypts.
    fn unencrypted(&self, id: PaneId) -> bool {
        matches!(self.panes.get(&id).map(|p| &p.host), Some(Host::Telnet(_)))
    }

    fn pane_connection(&self, id: PaneId) -> Option<ChannelId> {
        match self.panes.get(&id).map(|p| &p.host)? {
            Host::Ssh(s) if s.state() == State::Connected => Some(s.connection),
            Host::Tmux { gateway, .. } => self.pane_connection(*gateway),
            _ => None,
        }
    }

    /// Session > Remote desktop > Open remote desktop: asks the forwarding engine for a
    /// tunnel to the host's RDP port (or, for the built-in viewer in a
    /// tab, its RDP or VNC port); [`Self::desktop_events`] opens the
    /// viewer once it listens.
    fn open_desktop(&mut self, pane: PaneId, tab: Option<Protocol>) -> Option<Command> {
        let host = self.host_pane(pane);
        let (Some(connection), Some(Host::Ssh(s))) = (
            self.pane_connection(pane),
            self.panes.get(&host).map(|p| &p.host),
        ) else {
            return Some(Command::Notice(NO_DESKTOP_HOST.into()));
        };
        let profile = self.settings.profile(&s.target.alias);
        let label = s.target.label();
        let size = self.fixed_desktop_size(&s.target.alias);
        let clip_limit = self.desktop_clip_limit(&[&s.target.alias], self.launch_rules(pane, None));
        let rdp_port = profile
            .and_then(|p| p.desktop_port)
            .unwrap_or(DEFAULT_DESKTOP_PORT);
        let (port, local, want) = match tab {
            Some(protocol) => {
                let port = match protocol {
                    Protocol::Rdp => rdp_port,
                    Protocol::Vnc => profile.and_then(|p| p.vnc_port).unwrap_or(DEFAULT_VNC_PORT),
                };
                let user = s.target.user.clone();
                // Only the viewer connects; any free port will do.
                (
                    port,
                    0,
                    DesktopWant::Tab(TabWant {
                        label,
                        user,
                        protocol,
                        vdesk: None,
                        size,
                        clip_limit,
                    }),
                )
            }
            None => (
                rdp_port,
                desktop_port_for(&label),
                DesktopWant::Rdp {
                    pane,
                    size,
                    clipboard: self.desktop_clip(clip_limit) == (true, true),
                },
            ),
        };
        let w = self.workers.get(&connection)?;
        w.forwarder
            .open_desktop(connection, "localhost", port, local);
        self.desktops
            .insert((connection, "localhost".to_owned(), port), want);
        self.show(
            pane,
            &format!(
                "\x1b[0;90mOpening the remote desktop on port {port} of the server...\x1b[0m\r\n"
            ),
        );
        self.refresh(pane);
        None
    }

    /// Opens a viewer on the desktop tunnels that are ready, and says why
    /// the others failed.
    fn desktop_events(&mut self) {
        let events: Vec<DesktopEvent> = self
            .workers
            .values()
            .flat_map(|w| w.forwarder.take_desktop_events())
            .collect();
        for event in events {
            match event {
                DesktopEvent::Ready {
                    connection,
                    host,
                    port,
                    addr,
                } => match self.desktops.remove(&(connection, host.clone(), port)) {
                    Some(DesktopWant::Rdp {
                        pane,
                        size,
                        clipboard,
                    }) => {
                        let note = match launch_rdp_client(&addr, size, clipboard) {
                            Ok(child) => {
                                // The tunnel's connection stays while it runs.
                                self.mstsc.push((child, connection));
                                self.arm_launch_timer();
                                format!(
                                    "\x1b[0;90mRemote desktop tunnel at {addr}; Remote Desktop \
                                     Connection opens on it{}. The connection stays while it \
                                     runs.\x1b[0m\r\n",
                                    if clipboard {
                                        ""
                                    } else {
                                        ", without the clipboard"
                                    }
                                )
                            }
                            Err(e) => {
                                self.reveal_launch(pane);
                                format!(
                                    "\x1b[0;31mThe remote desktop tunnel listens at {addr}, but \
                                     Remote Desktop Connection (mstsc.exe) did not start: \
                                     {e}\x1b[0m\r\n"
                                )
                            }
                        };
                        self.show(pane, &note);
                        self.refresh(pane);
                    }
                    Some(DesktopWant::Tab(want)) => {
                        self.desktop_tab(connection, want, &host, port, &addr);
                    }
                    Some(DesktopWant::Vnc {
                        pane,
                        password,
                        clipboard,
                    }) => {
                        let note = match launch_vnc_viewer(&addr, clipboard) {
                            Some(viewer) => format!(
                                "\x1b[0;90mVirtual desktop tunnel at {addr}; {viewer} opens on \
                                 it. VNC password: {}\x1b[0m\r\n",
                                password.as_str()
                            ),
                            None => format!(
                                "\x1b[0;33mThe virtual desktop listens at {addr} (VNC password: \
                                 {}). No VNC viewer was found on this PC: install one (TigerVNC, \
                                 TightVNC, RealVNC or UltraVNC) and point it there, or use \
                                 ferossh-desktop.exe, which shows it in a tab.\x1b[0m\r\n",
                                password.as_str()
                            ),
                        };
                        self.show(pane, &note);
                        self.refresh(pane);
                    }
                    None => {}
                },
                DesktopEvent::Failed {
                    connection,
                    host,
                    port,
                    why,
                } => {
                    // A launch that waited for this desktop is over.
                    let waiting: Vec<PaneId> = self
                        .launches
                        .keys()
                        .copied()
                        .filter(|id| {
                            matches!(self.panes.get(id).map(|p| &p.host),
                                Some(Host::Ssh(s)) if s.connection == connection)
                        })
                        .collect();
                    for id in waiting {
                        self.abandon_launch(id);
                    }
                    let advice = match self.desktops.remove(&(connection, host, port)) {
                        // The script started that server: nothing to advise.
                        Some(DesktopWant::Vnc { .. })
                        | Some(DesktopWant::Tab(TabWant { vdesk: Some(_), .. })) => "",
                        Some(DesktopWant::Tab(TabWant {
                            protocol: Protocol::Vnc,
                            ..
                        })) => {
                            " Start a VNC server for your desktop there (x11vnc or TigerVNC \
                             for X11, wayvnc or GNOME's VNC mode for Wayland), or set VncPort \
                             in this host's profile if it listens elsewhere."
                        }
                        _ => {
                            " Install xrdp (sudo apt install xrdp) or turn on GNOME Remote \
                             Desktop, or set DesktopPort in this host's profile if it listens \
                             elsewhere."
                        }
                    };
                    self.queued.push(Command::Notice(format!("{why}{advice}")));
                }
            }
        }
    }

    /// The most the connections `names` let copied text travel to and
    /// from their desktops: each connection's `DesktopClipboard` only
    /// narrows it.
    fn desktop_clip_limit(&self, names: &[&str], rules: Policy) -> (bool, bool) {
        let (to_host, from_host) = names
            .iter()
            .filter_map(|n| self.settings.profile(n))
            .map(|p| ferossh_config::settings::clipboard_ways(p.desktop_clipboard.as_deref()))
            .fold((true, true), |(a, b), (x, y)| (a && x, b && y));
        // A security rule's `Clipboard no`: nothing from the host.
        (to_host, from_host && !rules.no_clipboard)
    }

    /// The security rules on pane `pane`'s connection, with those of
    /// connection `from` (a saved desktop or remote app opened through
    /// it, reaching `hostname`) added.
    fn launch_rules(&self, pane: PaneId, from: Option<(&str, Option<&str>)>) -> Policy {
        let own = self
            .panes
            .get(&self.host_pane(pane))
            .map(|p| p.policy)
            .unwrap_or_default();
        match from {
            Some((name, hostname)) => own.tightened(&self.policy_of(name, hostname, None)),
            None => own,
        }
    }

    /// Which ways copied text travels for a desktop: the global
    /// `DesktopClipboard` within the connection's `limit`.
    fn desktop_clip(&self, limit: (bool, bool)) -> (bool, bool) {
        let (a, b) = ferossh_config::settings::global_clipboard_ways(
            self.settings.desktop_clipboard.as_deref(),
        );
        (a && limit.0, b && limit.1)
    }

    /// The fixed desktop size set for connection `alias`; `None` when its
    /// desktops follow their pane.
    fn fixed_desktop_size(&self, alias: &str) -> Option<(u16, u16)> {
        self.settings
            .profile(alias)
            .and_then(|p| p.desktop_size)
            .and_then(|d| d.fixed())
    }

    /// The SSH host `pane` is logged in to, as the user knows it: where
    /// Copy public key to this server sends the key.
    fn key_host(&self, pane: PaneId) -> Option<String> {
        self.pane_connection(pane)?;
        match self.panes.get(&self.host_pane(pane)).map(|p| &p.host) {
            Some(Host::Ssh(s)) => Some(s.target.label()),
            _ => None,
        }
    }

    /// Sends `line` (a checked public key line) to the host `pane` is
    /// logged in to, for [`copy_id::command`] to add to its
    /// `authorized_keys`; [`Self::on_key_copy`] reports how it went.
    fn copy_key(&mut self, pane: PaneId, line: &str) -> Option<Command> {
        let (Some(connection), Some(label)) = (self.pane_connection(pane), self.key_host(pane))
        else {
            return Some(Command::Notice(NO_COPY_HOST.into()));
        };
        let channel = self.new_channel();
        let w = self.workers.get(&connection)?;
        w.link.send(Message::Exec {
            channel,
            connection,
            command: copy_id::command(),
            split_stderr: false,
        });
        w.link.send(Message::Data {
            channel,
            bytes: copy_id::input(line),
        });
        w.link.send(Message::Eof { channel });
        self.key_copies.insert(
            channel,
            KeyCopy {
                connection,
                label,
                out: Vec::new(),
                status: None,
            },
        );
        None
    }

    /// Keeps the server status bar's samples to what it shows: one feed
    /// for the focused pane's connection while the bar is on (feeds
    /// opened for other connections run on, so switching back shows
    /// figures at once), none while it is off.
    fn sync_stats(&mut self) {
        if !self.settings.status_bar {
            for (channel, feed) in std::mem::take(&mut self.stats) {
                if let Some(w) = self.workers.get(&feed.connection) {
                    w.link.send(Message::Close { channel });
                }
            }
            return;
        }
        let Some(connection) = self.pane_connection(self.focused_id()) else {
            return;
        };
        if self.stats.values().any(|f| f.connection == connection) {
            return;
        }
        let channel = self.new_channel();
        let Some(w) = self.workers.get(&connection) else {
            return;
        };
        w.link.send(Message::StatsOpen {
            channel,
            connection,
            interval: statusbar::INTERVAL,
        });
        self.stats.insert(
            channel,
            StatsFeed {
                connection,
                latest: None,
                ended: false,
            },
        );
    }

    /// What the server status bar shows for the focused pane.
    fn status_shown(&self) -> statusbar::Shown {
        let pane = self.focused_id();
        let (Some(connection), Some(host)) = (self.pane_connection(pane), self.key_host(pane))
        else {
            return statusbar::Shown::NoServer;
        };
        match self.stats.values().find(|f| f.connection == connection) {
            Some(StatsFeed { ended: true, .. }) => statusbar::Shown::Unavailable { host },
            Some(StatsFeed {
                latest: Some(stats),
                ..
            }) => statusbar::Shown::Stats {
                host,
                stats: *stats,
            },
            _ => statusbar::Shown::Waiting { host },
        }
    }

    /// Redraws the server status bar, opening the focused pane's samples
    /// first if need be.
    fn refresh_status(&mut self) {
        self.sync_stats();
        let Some(area) = self.areas.status else {
            return;
        };
        let shown = self.status_shown();
        let palette = self.strip_palette();
        statusbar::draw(&mut self.status_grid, &shown, &palette);
        // SAFETY: valid window and rect.
        unsafe {
            let _ = InvalidateRect(Some(self.hwnd), Some(&win_rect(area)), false);
        }
    }

    /// A sample for the server status bar, or the end of its samples.
    fn on_stats(&mut self, channel: ChannelId, msg: Message) {
        let Some(feed) = self.stats.get_mut(&channel) else {
            return;
        };
        match msg {
            Message::Stats { stats, .. } => feed.latest = Some(stats),
            // Not opened again until the connection is: a server that
            // cannot report would only fail again.
            Message::Disconnected { .. } => feed.ended = true,
            _ => return,
        }
        let connection = feed.connection;
        let shown = self
            .pane_connection(self.focused_id())
            .is_some_and(|c| c == connection);
        if shown {
            self.refresh_status();
        }
    }

    /// Pane `id` logged in: the inventory keeps when, and the host key;
    /// with `SystemInfo yes`, the server's OS and kernel are read too.
    /// Only listed connections are kept, not hosts typed at the prompt.
    fn inventory_login(&mut self, id: PaneId) {
        let Some(Host::Ssh(s)) = self.panes.get(&id).map(|p| &p.host) else {
            return;
        };
        // Renamed since the pane was opened: kept under the name it has now.
        let alias = self
            .inventory_renames
            .get(&id)
            .filter(|(was, _)| was.eq_ignore_ascii_case(&s.target.alias))
            .map_or_else(|| s.target.alias.clone(), |(_, now)| now.clone());
        let key = s.host_key_seen.clone();
        // The connection manager's list fills only once it is shown: a
        // saved connection opened before that is looked up where kept.
        if !self.side.list.has_host(&alias)
            && !host_items(&ssh_env(), &self.settings)
                .iter()
                .any(|h| h.name.eq_ignore_ascii_case(&alias))
        {
            return;
        }
        self.update_inventory(None, |inv| {
            let key = key.as_ref().map(|(k, f)| (k.as_str(), f.as_str()));
            inv.connected(&alias, crate::inventory_view::now(), key);
        });
        if !self.settings.profile(&alias).is_some_and(|p| p.system_info) {
            return;
        }
        let Some(connection) = self.pane_connection(id) else {
            return;
        };
        let channel = self.new_channel();
        let Some(w) = self.workers.get(&connection) else {
            return;
        };
        w.link.send(Message::Exec {
            channel,
            connection,
            command: ferossh_config::inventory::SYSTEM_COMMAND
                .as_bytes()
                .to_vec(),
            split_stderr: true,
        });
        w.link.send(Message::Eof { channel });
        self.system_reads.insert(
            channel,
            SystemRead {
                connection,
                alias,
                out: Vec::new(),
            },
        );
    }

    /// Changes the inventory file with `fix` (a rename or delete that must
    /// reach it in the end) and `change`, after what earlier failed writes
    /// left to do. When the file cannot be written, the fixes wait for the
    /// next change and the user is told; `change` (a login's time) is
    /// dropped.
    fn update_inventory(
        &mut self,
        fix: Option<InventoryFix>,
        change: impl FnOnce(&mut ferossh_config::inventory::Inventory),
    ) {
        let mut fixes = std::mem::take(&mut self.inventory_pending);
        fixes.extend(fix);
        let result = crate::inventory_view::update(|inv| {
            for f in &fixes {
                f.apply(inv);
            }
            change(inv);
        });
        if let Err(e) = result {
            self.inventory_pending = fixes;
            self.queued.push(Command::Notice(format!(
                "Could not update the connection log: {e}"
            )));
        }
    }

    /// Connection `old` is called `new` now: its inventory row, and a read
    /// of its OS still under way, follow.
    fn inventory_renamed(&mut self, old: &str, new: &str) {
        // Marks only for open panes still connecting as they did.
        let panes = &self.panes;
        self.inventory_renames.retain(|id, (was, _)| {
            matches!(panes.get(id).map(|p| &p.host),
                Some(Host::Ssh(s)) if s.target.alias.eq_ignore_ascii_case(was))
        });
        let under_old: Vec<(PaneId, String)> = self
            .panes
            .iter()
            .filter_map(|(id, p)| {
                let Host::Ssh(s) = &p.host else { return None };
                let now = self
                    .inventory_renames
                    .get(id)
                    .map_or(&s.target.alias, |(_, now)| now);
                now.eq_ignore_ascii_case(old)
                    .then(|| (*id, s.target.alias.clone()))
            })
            .collect();
        for (id, was) in under_old {
            self.inventory_renames.insert(id, (was, new.to_owned()));
        }
        for r in self.system_reads.values_mut() {
            if r.alias.eq_ignore_ascii_case(old) {
                r.alias = new.to_owned();
            }
        }
        self.update_inventory(
            Some(InventoryFix::Rename(old.to_owned(), new.to_owned())),
            |_| {},
        );
    }

    /// What the inventory's system command printed, or that it ended.
    fn on_system_read(&mut self, channel: ChannelId, msg: Message) {
        use ferossh_config::inventory::{MAX_SYSTEM_OUTPUT, parse_system};
        let Some(r) = self.system_reads.get_mut(&channel) else {
            return;
        };
        match msg {
            Message::Data { bytes, .. } => {
                let room = MAX_SYSTEM_OUTPUT.saturating_sub(r.out.len());
                r.out.extend_from_slice(bytes.get(..room).unwrap_or(&bytes));
            }
            Message::Disconnected { .. } => {
                let Some(r) = self.system_reads.remove(&channel) else {
                    return;
                };
                // A server without `sh` prints no mark: nothing is kept.
                let Some(info) = parse_system(&r.out) else {
                    return;
                };
                self.update_inventory(None, |inv| {
                    inv.system(&r.alias, crate::inventory_view::now(), &info);
                });
            }
            _ => {}
        }
    }

    /// What the key copy's command said, or that it ended.
    fn on_key_copy(&mut self, channel: ChannelId, msg: Message) {
        /// More is never needed: the answer is the last line.
        const KEEP: usize = 16 * 1024;
        let Some(k) = self.key_copies.get_mut(&channel) else {
            return;
        };
        match msg {
            Message::Data { bytes, .. } => {
                k.out.extend_from_slice(&bytes);
                if k.out.len() > KEEP {
                    let cut = k.out.len() - KEEP;
                    k.out.drain(..cut);
                }
            }
            Message::ExitStatus { code, .. } => k.status = Some(code),
            Message::Disconnected { reason, .. } => {
                let Some(k) = self.key_copies.remove(&channel) else {
                    return;
                };
                let host = crate::ssh::sanitize(&k.label);
                let text = match (k.status, copy_id::outcome(k.status, &k.out)) {
                    (_, copy_id::Outcome::Added) => format!(
                        "Added the key to ~/.ssh/authorized_keys on {host}. The next login \
                         there can use it."
                    ),
                    (_, copy_id::Outcome::Present) => format!(
                        "{host} has this key in ~/.ssh/authorized_keys already; nothing \
                         changed."
                    ),
                    (None, _) if k.out.is_empty() => format!(
                        "Could not confirm that the key was copied to {host} ({}). Check \
                         ~/.ssh/authorized_keys on the server.",
                        crate::ssh::sanitize(&reason)
                    ),
                    (_, copy_id::Outcome::Failed(why)) => {
                        format!("Could not copy the key to {host}: {why}.")
                    }
                };
                self.queued.push(Command::Notice(text));
            }
            _ => {}
        }
    }

    /// Makes the key the New SSH key window asked for, in the background:
    /// a security key waits for the user's touch.
    fn start_keygen(&mut self, request: crate::newkey::Request) {
        let (tx, rx) = std::sync::mpsc::channel();
        let wake = self.notifier();
        let spawned = std::thread::Builder::new()
            .name("new-key".into())
            .spawn(move || {
                let made = crate::newkey::make_kind(&ferossh_auth::webauthn::WebAuthn, &request);
                let _ = tx.send((request.path.clone(), made));
                wake();
            });
        match spawned {
            Ok(_) => self.keygen = Some(rx),
            Err(e) => self
                .queued
                .push(Command::Notice(format!("Could not make the key: {e}"))),
        }
    }

    fn poll_keygen(&mut self) -> Option<Command> {
        let rx = self.keygen.as_ref()?;
        if DIALOG_OPEN.get() {
            // Another dialog would swallow the answer: keep it, and look
            // again soon.
            // SAFETY: our window; replaces any earlier timer with this id.
            unsafe { SetTimer(Some(self.hwnd), TIMER_KEYGEN, 500, None) };
            return None;
        }
        let (path, result) = match rx.try_recv() {
            Ok(made) => made,
            Err(std::sync::mpsc::TryRecvError::Empty) => return None,
            Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                (PathBuf::new(), Err("it stopped".to_owned()))
            }
        };
        self.keygen = None;
        let pane = self.focused_id();
        let host = self.key_host(pane);
        Some(Command::KeyMade {
            path,
            result,
            pane,
            host,
        })
    }

    /// Session > Remote desktop > Open virtual desktop: runs [`vdesk::command`] on an exec
    /// channel of the pane's connection; [`Self::on_vdesk`] opens a viewer
    /// once x11vnc listens. A second ask on the same connection opens
    /// another viewer on the running one.
    /// `from` names a saved virtual desktop connection whose program and
    /// size to use; else the SSH host's own.
    fn open_virtual_desktop(&mut self, pane: PaneId, from: Option<&str>) -> Option<Command> {
        let host = self.host_pane(pane);
        let (Some(connection), Some(Host::Ssh(s))) = (
            self.pane_connection(pane),
            self.panes.get(&host).map(|p| &p.host),
        ) else {
            return Some(Command::Notice(NO_VDESK_HOST.into()));
        };
        let running = self
            .vdesks
            .iter()
            .find(|(_, v)| v.connection == connection)
            .map(|(&c, v)| (c, v.port));
        match running {
            Some((channel, Some(_))) => {
                self.vdesk_viewer(channel);
                return None;
            }
            Some((_, None)) => {
                return Some(Command::Notice(
                    "The virtual desktop on this connection is still starting.".into(),
                ));
            }
            None => {}
        }
        let alias = from.unwrap_or(&s.target.alias).to_owned();
        let program = self
            .settings
            .profile(&alias)
            .and_then(|p| p.virtual_desktop.clone());
        let label = from.map_or_else(|| s.target.label(), str::to_owned);
        let user = s.target.user.clone();
        let fixed = self.fixed_desktop_size(&alias);
        let (width, height) = fixed.unwrap_or_else(|| {
            self.panes
                .get(&pane)
                .map(|p| desktop_size(p.rect))
                .unwrap_or((1600, 900))
        });
        let follow = fixed.is_none();
        let password = vdesk::password();
        let rules = self.launch_rules(pane, from.map(|f| (f, None)));
        let clip_limit = self.desktop_clip_limit(&[&alias, &s.target.alias], rules);
        let (to_host, from_host) = self.desktop_clip(clip_limit);
        let clip = vdesk::Clip {
            to_host,
            from_host,
            selection: self.settings.desktop_share_selection,
        };
        let Some(input) = vdesk::input(&password, program.as_deref(), width, height, follow, clip)
        else {
            return Some(Command::Notice(
                "This host's VirtualDesktop command must be one line.".into(),
            ));
        };
        let channel = self.new_channel();
        let w = self.workers.get(&connection)?;
        w.link.send(Message::Exec {
            channel,
            connection,
            command: vdesk::command(),
            split_stderr: false,
        });
        w.link.send(Message::Data {
            channel,
            bytes: input.to_vec(),
        });
        self.vdesks.insert(
            channel,
            VirtualDesk {
                connection,
                pane,
                label,
                user,
                password,
                out: vdesk::Output::default(),
                port: None,
                size: (width, height),
                follow,
                resizes: false,
                tab: cfg!(feature = "vnc-viewer"),
                shown: false,
                reported: false,
                clip_limit,
            },
        );
        let what = match &program {
            Some(p) => format!(" running {}", crate::ssh::sanitize(p)),
            None => String::new(),
        };
        self.show(
            pane,
            &format!(
                "\x1b[0;90mStarting a virtual desktop{what} on the server (Xvfb or \
                 Xvnc)...\x1b[0m\r\n"
            ),
        );
        self.refresh(pane);
        None
    }

    /// Session > Remote apps > Run remote app: the palette offers programs
    /// (this connection's, the recent ones, xterm) and runs what is
    /// picked or typed, on the pane's host.
    fn pick_remote_app(&mut self, pane: PaneId) -> Option<Command> {
        let host = self.host_pane(pane);
        let (Some(_), Some(Host::Ssh(s))) = (
            self.pane_connection(pane),
            self.panes.get(&host).map(|p| &p.host),
        ) else {
            return Some(Command::Notice(NO_APP_HOST.into()));
        };
        let mut entries = Vec::new();
        if let Some(p) = self
            .settings
            .profile(&s.target.alias)
            .and_then(|p| p.remote_app.clone())
        {
            entries.push(palette::Entry::remote_app(&p, "this connection's"));
        }
        for p in &self.recent_apps {
            if !entries.iter().any(|e| e.label == *p) {
                entries.push(palette::Entry::remote_app(p, "recent"));
            }
        }
        if !entries.iter().any(|e| e.label == "xterm") {
            entries.push(palette::Entry::remote_app("xterm", "a terminal"));
        }
        if self.side.visible && self.side.view == SideView::Palette {
            self.leave_palette();
        }
        self.app_pane = Some(pane);
        self.palette.open_apps(entries);
        self.palette_return = (self.side.visible && !self.snippets_peek).then_some(self.side.view);
        self.snippets_peek = false;
        self.show_side(SideView::Palette, true);
        None
    }

    /// Runs `program` (a command line; `None` when attaching) on the
    /// pane's SSH connection as a remote app: no new login, the agent on
    /// an exec channel, the host's bytes decoded in a sandboxed process,
    /// the windows native ([`crate::remote_app`]). `from` names a saved
    /// remote app connection whose agent settings apply; else the SSH
    /// host's own.
    fn run_remote_app(
        &mut self,
        pane: PaneId,
        program: Option<&str>,
        from: Option<&str>,
        attach: ferostream_client::transport::AttachTo,
    ) -> Option<Command> {
        use ferostream_client::transport::{DEFAULT_AGENT_PATH, Place as AgentPlace};
        let host = self.host_pane(pane);
        let (Some(connection), Some(Host::Ssh(s))) = (
            self.pane_connection(pane),
            self.panes.get(&host).map(|p| &p.host),
        ) else {
            return Some(Command::Notice(NO_APP_HOST.into()));
        };
        let alias = s.target.alias.clone();
        let label = from.map_or_else(|| s.target.label(), str::to_owned);
        let argv = match program {
            Some(line) => match crate::stream::words(line) {
                Some(argv) => argv,
                None => {
                    return Some(Command::Notice(
                        "Type a program and its arguments; quotes must be closed.".into(),
                    ));
                }
            },
            None => Vec::new(),
        };
        let own = from
            .and_then(|f| self.settings.profile(f))
            .or_else(|| self.settings.profile(&alias));
        let copy = own
            .and_then(|p| p.remote_app_copy_agent)
            .unwrap_or(self.settings.remote_app_copy_agent);
        let remove = own
            .and_then(|p| p.remote_app_remove_agent)
            .unwrap_or(self.settings.remote_app_remove_agent);
        let path = self
            .settings
            .remote_app_agent_path
            .clone()
            .unwrap_or_else(|| DEFAULT_AGENT_PATH.to_owned());
        let place = match AgentPlace::new(&path, remove) {
            Ok(p) => p,
            Err(e) => {
                return Some(Command::Notice(format!(
                    "RemoteAppAgentPath in ferossh.conf: {e}"
                )));
            }
        };
        // A security rule's `Clipboard no` lets nothing come from the host.
        let clip_limit = self
            .launch_rules(pane, from.map(|f| (f, None)))
            .clipboard_limit(own.and_then(|p| p.remote_app_clipboard.as_deref()));
        let clipboard = crate::stream::app_clipboard(&self.settings, clip_limit.as_deref());
        let files = if copy {
            crate::remote_app::agent_files()
        } else {
            Vec::new()
        };
        let w = self.workers.get(&connection)?;
        let route = crate::remote_app::Route {
            connection,
            send: Arc::new(w.link.sender()),
            relays: w.link.relays().clone(),
        };
        let lookup = Box::new(|c: ChannelId| with_window(|w| w.remote_route(c)).flatten());
        let what = match program {
            Some(line) => crate::ssh::sanitize(line),
            None => "The remote app".into(),
        };
        let on_end = {
            let label = label.clone();
            let what = what.clone();
            Box::new(move |end: ferostream_client::win32::End| {
                let note = remote_app_note(&what, &label, &end);
                let Some(note) = note else { return };
                let hwnd = with_window(|w| {
                    w.queued.push(Command::Notice(note));
                    w.hwnd
                });
                // The notice shows when the window next takes its queue.
                if let Some(hwnd) = hwnd {
                    // SAFETY: posting to our own window.
                    unsafe {
                        let _ = PostMessageW(Some(hwnd), WM_SHELL_OUTPUT, WPARAM(0), LPARAM(0));
                    }
                }
            })
        };
        let app_host = crate::remote_app::AppHost::new(route, lookup, files.clone(), place, on_end);
        let settings = ferostream_client::win32::Settings {
            program: argv,
            clipboard,
            attach,
            packing: self
                .settings
                .remote_app_packing
                .as_deref()
                .and_then(ferostream_proto::Packing::parse)
                .unwrap_or_default(),
            raw_only: true,
        };
        match ferostream_client::win32::start(settings, Box::new(app_host)) {
            Ok(id) => {
                self.app_clip_limits.insert(id, clip_limit);
            }
            Err(e) => {
                return Some(Command::Notice(format!(
                    "The remote app did not start: {e}"
                )));
            }
        }
        if let Some(line) = program {
            let line = line.trim().to_owned();
            self.recent_apps.retain(|p| *p != line);
            self.recent_apps.insert(0, line);
            self.recent_apps.truncate(8);
        }
        let mut note = format!("\x1b[0;90mStarting {what} on the host; its windows open here");
        if copy && files.is_empty() {
            note.push_str(
                " (no ferostream-agent next to ferossh.exe: the host's own agent is used)",
            );
        }
        note.push_str("...\x1b[0m\r\n");
        self.show(pane, &note);
        self.refresh(pane);
        None
    }

    /// How a remote app reaches connection `connection`'s worker, while
    /// that worker runs.
    fn remote_route(&self, connection: ChannelId) -> Option<crate::remote_app::Route> {
        let w = self.workers.get(&connection)?;
        Some(crate::remote_app::Route {
            connection,
            send: Arc::new(w.link.sender()),
            relays: w.link.relays().clone(),
        })
    }

    /// Session > Remote desktop > Stop virtual desktop: ends the virtual desktops on the
    /// pane's connection, which stops Xvfb, x11vnc and the program there.
    fn stop_virtual_desktop(&mut self, pane: PaneId) -> Option<Command> {
        let connection = self.pane_connection(pane);
        let channels: Vec<ChannelId> = self
            .vdesks
            .iter()
            .filter(|(_, v)| Some(v.connection) == connection)
            .map(|(&c, _)| c)
            .collect();
        if channels.is_empty() {
            return Some(Command::Notice(
                "No virtual desktop runs on this pane's connection.".into(),
            ));
        }
        for channel in channels {
            self.close_vdesk(channel);
        }
        self.show(pane, "\x1b[0;90mVirtual desktop stopped.\x1b[0m\r\n");
        self.refresh(pane);
        self.prune_forwards();
        None
    }

    /// Closes a virtual desktop's script channel: the end of its input
    /// tells the script to stop everything it started.
    fn close_vdesk(&mut self, channel: ChannelId) {
        if let Some(v) = self.vdesks.remove(&channel)
            && let Some(w) = self.workers.get(&v.connection)
        {
            w.link.send(Message::Close { channel });
        }
    }

    /// Stops the virtual desktops nothing shows any more: the tab closed
    /// (or its viewer ended), or, for a viewer on this PC, no terminal is
    /// logged in on the connection.
    fn prune_vdesks(&mut self) {
        let unused: Vec<ChannelId> = self
            .vdesks
            .iter()
            .filter(|&(&c, v)| {
                if v.tab {
                    v.shown
                        && !self.panes.values().any(|p| {
                            matches!(p.host, Host::Desktop { vdesk: Some(d), .. } if d == c)
                                && p.desktop.is_some()
                        })
                } else {
                    !self.panes.values().any(|p| {
                        matches!(&p.host, Host::Ssh(s)
                            if s.connection == v.connection && s.state() == State::Connected)
                    })
                }
            })
            .map(|(&c, _)| c)
            .collect();
        for channel in unused {
            self.close_vdesk(channel);
        }
    }

    /// Opens a viewer on the running virtual desktop of script `channel`.
    fn vdesk_viewer(&mut self, channel: ChannelId) {
        // A viewer on this PC needs the password its pane shows.
        if let Some(pane) = self.vdesks.get(&channel).filter(|v| !v.tab).map(|v| v.pane) {
            self.reveal_launch(pane);
        }
        let Some(v) = self.vdesks.get(&channel) else {
            return;
        };
        let Some(port) = v.port else {
            return;
        };
        let (local, want) = if v.tab {
            (
                0,
                DesktopWant::Tab(TabWant {
                    label: v.label.clone(),
                    user: v.user.clone(),
                    protocol: Protocol::Vnc,
                    vdesk: Some((v.password.clone(), channel)),
                    // Xvnc follows the tab; Xvfb keeps its size.
                    size: (!(v.follow && v.resizes)).then_some(v.size),
                    clip_limit: v.clip_limit,
                }),
            )
        } else {
            (
                desktop_port_for(&format!("virtual {}", v.label)),
                DesktopWant::Vnc {
                    pane: v.pane,
                    password: v.password.clone(),
                    clipboard: self.desktop_clip(v.clip_limit),
                },
            )
        };
        let connection = v.connection;
        let Some(w) = self.workers.get(&connection) else {
            return;
        };
        // x11vnc listens on the server's IPv4 loopback only.
        w.forwarder
            .open_desktop(connection, VDESK_HOST, port, local);
        self.desktops
            .insert((connection, VDESK_HOST.to_owned(), port), want);
    }

    /// What a virtual desktop's script said, or that it ended.
    fn on_vdesk(&mut self, channel: ChannelId, msg: Message) {
        let Some(v) = self.vdesks.get_mut(&channel) else {
            return;
        };
        let pane = v.pane;
        match msg {
            Message::Data { bytes, .. } => {
                for event in v.out.feed(&bytes) {
                    self.vdesk_event(channel, pane, event);
                }
            }
            Message::Disconnected { reason, .. } => {
                let Some(v) = self.vdesks.remove(&channel) else {
                    return;
                };
                if v.port.is_none() && !v.reported {
                    let said = match v.out.other.is_empty() {
                        true => String::new(),
                        false => format!(
                            " The server said: {}",
                            crate::ssh::sanitize(&v.out.other.join(" / "))
                        ),
                    };
                    self.queued.push(Command::Notice(format!(
                        "The virtual desktop did not start ({}).{said}",
                        crate::ssh::sanitize(&reason)
                    )));
                }
                if v.port.is_none() {
                    self.abandon_launch(v.pane);
                }
                self.prune_forwards();
            }
            _ => {}
        }
    }

    fn vdesk_event(&mut self, channel: ChannelId, pane: PaneId, event: vdesk::Event) {
        match event {
            vdesk::Event::Missing(missing) => {
                if let Some(v) = self.vdesks.get_mut(&channel) {
                    v.reported = true;
                }
                self.abandon_launch(pane);
                self.queued
                    .push(Command::Notice(vdesk::install_advice(&missing)));
            }
            vdesk::Event::Error(why) => {
                if let Some(v) = self.vdesks.get_mut(&channel) {
                    v.reported = true;
                }
                self.abandon_launch(pane);
                self.queued.push(Command::Notice(format!(
                    "The virtual desktop did not start: {why}. Set VirtualDesktop in this \
                     host's connection settings to the desktop or program to run."
                )));
            }
            vdesk::Event::Ready {
                port,
                display,
                resizes,
            } => {
                let mut fixed_note = String::new();
                if let Some(v) = self.vdesks.get_mut(&channel) {
                    v.port = Some(port);
                    v.resizes = resizes;
                    if v.follow && !resizes {
                        fixed_note = format!(
                            " It stays {}x{}: to follow the window's size, install TigerVNC's \
                             Xvnc on the server (tigervnc-standalone-server).",
                            v.size.0, v.size.1
                        );
                    }
                }
                self.show(
                    pane,
                    &format!(
                        "\x1b[0;90mVirtual desktop {display} runs on the server; opening it \
                         through the SSH tunnel. It stops when its viewer tab closes, with \
                         Session > Remote desktop > Stop virtual desktop, or with this connection.{fixed_note}\x1b[0m\r\n"
                    ),
                );
                self.refresh(pane);
                self.vdesk_viewer(channel);
            }
            vdesk::Event::Ended(said) => {
                let said = if said.is_empty() {
                    String::new()
                } else {
                    format!(": {said}")
                };
                self.show(
                    pane,
                    &format!(
                        "\x1b[0;90mThe program in the virtual desktop ended, so the virtual \
                         desktop stopped{said}\x1b[0m\r\n"
                    ),
                );
                self.refresh(pane);
            }
        }
    }

    /// Opens the built-in viewer on the tunnel at `addr` in a new tab;
    /// `host` is the desktop server as the SSH server reaches it.
    #[cfg(feature = "viewer")]
    fn desktop_tab(
        &mut self,
        connection: ChannelId,
        want: TabWant,
        host: &str,
        port: u16,
        addr: &str,
    ) {
        let TabWant {
            label,
            user,
            protocol,
            vdesk,
            size,
            clip_limit,
        } = want;
        // The RDP viewer takes the server's certificate as it is, which is
        // safe only where the SSH host key already identified the server.
        if protocol == Protocol::Rdp && !crate::forwards::on_ssh_host(host) {
            self.queued.push(Command::Notice(format!(
                "The built-in RDP viewer only opens desktops on the SSH server itself; {} is \
                 another machine, whose certificate it cannot check. Open it with Remote \
                 Desktop Connection instead.",
                crate::ssh::sanitize(host)
            )));
            return;
        }
        // Without the SSH host to key it by, the certificate could not be
        // checked: do not open the desktop at all.
        let pins = if protocol == Protocol::Rdp {
            let Some(pins) = self.rdp_pin_store(connection, port) else {
                self.queued.push(Command::Notice(
                    "The SSH session this desktop would go through has closed, so its \
                     certificate cannot be checked. Connect again and open the desktop from \
                     there."
                        .into(),
                ));
                return;
            };
            Some(pins)
        } else {
            None
        };
        let id = self.new_tab_pane();
        // The server draws the desktop at the size of the tab, when it
        // can, unless a size was set.
        let (width, height) = size.unwrap_or_else(|| {
            self.panes
                .get(&id)
                .map(|p| desktop_size(p.rect))
                .unwrap_or((1024, 768))
        });
        let session = crate::desktop::Session {
            protocol,
            width,
            height,
            layout: keyboard_layout(),
            user,
            password: vdesk.as_ref().map(|(pw, _)| pw.clone()),
            fixed: size.is_some(),
            clipboard: self.desktop_clip(clip_limit),
            clipboard_limit: clip_limit,
            pins,
        };
        let script = vdesk.map(|(_, channel)| channel);
        // From here its tab decides: closing it, or a viewer that never
        // started, stops the virtual desktop.
        if let Some(v) = script.and_then(|c| self.vdesks.get_mut(&c)) {
            v.shown = true;
        }
        let started = sandbox::spawn_viewer().and_then(|v| {
            let to = v.to_worker.try_clone().map_err(io_error)?;
            let from = v.from_worker.try_clone().map_err(io_error)?;
            Desktop::start(addr, session, to, from, Box::new(v), self.notifier()).map_err(io_error)
        });
        let note = match started {
            Ok(desktop) => {
                if let Some(p) = self.panes.get_mut(&id) {
                    p.host = Host::Desktop {
                        label: match script {
                            Some(_) => format!("virtual desktop {label}"),
                            None => format!("desktop {label}"),
                        },
                        connection,
                        vdesk: script,
                    };
                    p.desktop = Some(Box::new(desktop));
                }
                let server = match protocol {
                    Protocol::Rdp => "RDP",
                    Protocol::Vnc => "VNC",
                };
                format!(
                    "\x1b[0;90mConnecting to the {server} server through the SSH tunnel...\x1b[0m\r\n"
                )
            }
            Err(e) => format!("\x1b[0;31mThe desktop viewer did not start: {e}\x1b[0m\r\n"),
        };
        self.show(id, &note);
        self.refresh(id);
        self.update_title();
    }

    /// Where the certificate of the RDP server on port `port` of
    /// connection `connection`'s SSH server is pinned: one per SSH host
    /// (as its host key names it) and port.
    #[cfg(feature = "viewer")]
    fn rdp_pin_store(&self, connection: ChannelId, port: u16) -> Option<crate::desktop::PinStore> {
        // Any pane on the connection names the same SSH host, also after
        // the pane that opened it has closed.
        let s = self.panes.values().find_map(|p| match &p.host {
            Host::Ssh(s) if s.connection == connection => Some(s),
            _ => None,
        })?;
        let (host, ssh_port) = s.target.key_host();
        Some(crate::desktop::PinStore {
            path: app_dir().join("rdp_certs"),
            key: format!("[{}]:{ssh_port}/rdp:{port}", host.to_ascii_lowercase()),
        })
    }

    #[cfg(not(feature = "viewer"))]
    fn desktop_tab(
        &mut self,
        _connection: ChannelId,
        _want: TabWant,
        _host: &str,
        _port: u16,
        _addr: &str,
    ) {
    }

    /// Gives each remote desktop its pane's size, after the layout
    /// settled.
    fn on_desktop_size_timer(&mut self) {
        // SAFETY: our window and timer.
        unsafe {
            let _ = KillTimer(Some(self.hwnd), TIMER_DESKTOP_SIZE);
        }
        for p in self.panes.values_mut() {
            let (w, h) = desktop_size(p.rect);
            if let Some(d) = p.desktop.as_mut() {
                d.resize(w, h);
            }
        }
    }

    /// Gives desktop pane `id` this PC's clipboard text, once per change
    /// of either: only the desktop being worked in sees it.
    fn desktop_clip_touch(&mut self, id: PaneId) {
        if self.clip_pane == Some(id) {
            return;
        }
        let hwnd = self.hwnd;
        let Some(d) = self.panes.get_mut(&id).and_then(|p| p.desktop.as_mut()) else {
            return;
        };
        if !d.takes_clipboard() {
            return;
        }
        self.clip_pane = Some(id);
        if let Some(text) = crate::clipboard::get_text(hwnd) {
            d.offer_clipboard(&text);
        }
    }

    /// WM_CLIPBOARDUPDATE: this PC's clipboard changed. A desktop being
    /// worked in gets it at once; the others when next used.
    fn clipboard_changed(&mut self) {
        self.clip_pane = None;
        let id = self.focused_id();
        if self.focused && !self.side.focused {
            self.desktop_clip_touch(id);
        }
    }

    /// Saves a changed desktop clipboard setting and applies it at once to
    /// the open desktops, each within its connection's limit.
    fn apply_desktop_clipboard(&mut self) {
        self.save_settings();
        self.update_menu_checks();
        let ways = ferossh_config::settings::global_clipboard_ways(
            self.settings.desktop_clipboard.as_deref(),
        );
        for p in self.panes.values_mut() {
            if let Some(d) = p.desktop.as_mut() {
                let limit = d.clipboard_limit();
                d.set_clipboard(ways.0 && limit.0, ways.1 && limit.1);
            }
        }
        self.clip_pane = None;
    }

    /// Applies what the remote desktops sent.
    fn poll_desktops(&mut self) {
        let ids: Vec<PaneId> = self
            .panes
            .iter()
            .filter(|(_, p)| p.desktop.is_some())
            .map(|(id, _)| *id)
            .collect();
        for id in ids {
            let (updates, fresh) = match self.panes.get_mut(&id).and_then(|p| p.desktop.as_mut()) {
                Some(d) => (d.poll(), d.take_fresh()),
                None => continue,
            };
            // The picture came up in the pane being worked in.
            if fresh && self.focused && !self.side.focused && self.focused_id() == id {
                self.clip_pane = None;
                self.desktop_clip_touch(id);
            }
            for update in updates {
                match update {
                    DesktopUpdate::Redraw => {
                        if let Some(p) = self.panes.get_mut(&id) {
                            p.grid.mark_all_dirty();
                        }
                        self.invalidate_dirty(id);
                    }
                    DesktopUpdate::Title(name) => {
                        if let Some(p) = self.panes.get_mut(&id) {
                            p.title = Some(name).filter(|n| !n.is_empty());
                        }
                        self.update_title();
                        self.refresh_chrome();
                    }
                    DesktopUpdate::Bell => {
                        if !self.is_visible(id)
                            && let Some(p) = self.panes.get_mut(&id)
                        {
                            p.bell = true;
                            self.refresh_chrome();
                        }
                    }
                    DesktopUpdate::Ask(prompt) => {
                        self.show(id, &prompt);
                        self.refresh(id);
                    }
                    DesktopUpdate::Note(note) => {
                        self.show(id, &format!("\x1b[0;33m{note}\x1b[0m\r\n"));
                        self.refresh(id);
                    }
                    DesktopUpdate::Clipboard(text) => {
                        // Windows keeps line ends as CR LF.
                        let text = text.replace("\r\n", "\n").replace('\n', "\r\n");
                        crate::clipboard::set_text(self.hwnd, &text);
                    }
                    DesktopUpdate::Ended(why) => {
                        if let Some(p) = self.panes.get_mut(&id) {
                            p.desktop = None;
                            p.grid.mark_all_dirty();
                        }
                        // The connection may have stayed open only for it.
                        self.prune_forwards();
                        let why = crate::ssh::sanitize(&why);
                        self.show(
                            id,
                            &format!("\r\n\x1b[0;31mThe remote desktop ended: {why}\x1b[0m\r\n"),
                        );
                        self.request_full_redraw();
                        self.refresh(id);
                    }
                }
            }
        }
    }

    /// Keyboard and mouse messages for a remote desktop pane; `true` when
    /// the desktop took the message.
    fn desktop_message(&mut self, msg: u32, wparam: WPARAM, lparam: LPARAM) -> bool {
        if !self.panes.values().any(|p| p.desktop.is_some()) {
            return false;
        }
        match msg {
            WM_KEYDOWN | WM_SYSKEYDOWN | WM_KEYUP | WM_SYSKEYUP => {
                let id = self.focused_id();
                if self.side.focused {
                    return false;
                }
                let vk = VIRTUAL_KEY(wparam.0 as u16);
                let down = matches!(msg, WM_KEYDOWN | WM_SYSKEYDOWN);
                // FeroSSH's own shortcuts still work in the pane.
                let mods = key_mods();
                if down && self.shortcut_for(vk, mods).is_some() {
                    return false;
                }
                let extended = lparam.0 & (1 << 24) != 0;
                let scan = ((lparam.0 >> 16) & 0xff) as u16;
                let Some(d) = self.panes.get_mut(&id).and_then(|p| p.desktop.as_mut()) else {
                    return false;
                };
                // A prompt (user name, password) reads WM_CHAR, Enter and
                // Backspace included: keep the terminal from taking them.
                if d.asking() {
                    return true;
                }
                if !d.running() {
                    return false;
                }
                if down {
                    self.desktop_clip_touch(id);
                }
                let Some(d) = self.panes.get_mut(&id).and_then(|p| p.desktop.as_mut()) else {
                    return true;
                };
                if d.key(vk.0, extended, scan, down) {
                    drop_pending_char(self.hwnd);
                }
                true
            }
            WM_CHAR | WM_SYSCHAR => {
                if self.side.focused {
                    return false;
                }
                let id = self.focused_id();
                let Some(d) = self.panes.get_mut(&id).and_then(|p| p.desktop.as_mut()) else {
                    return false;
                };
                if !d.asking() && !d.running() {
                    return false;
                }
                let Some(c) = char::from_u32(wparam.0 as u32) else {
                    return true;
                };
                if let Some(echo) = d.char(c) {
                    self.show(id, &echo);
                    self.refresh(id);
                }
                true
            }
            WM_LBUTTONDOWN | WM_LBUTTONUP | WM_RBUTTONDOWN | WM_RBUTTONUP | WM_MBUTTONDOWN
            | WM_MBUTTONUP | WM_MOUSEMOVE => {
                if self.drag.is_some() {
                    return false;
                }
                let (x, y) = lparam_point(lparam);
                let Spot::Pane(id) = self.spot(x, y) else {
                    return false;
                };
                let button = match msg {
                    WM_LBUTTONDOWN => Some((1, true)),
                    WM_LBUTTONUP => Some((1, false)),
                    WM_MBUTTONDOWN => Some((2, true)),
                    WM_MBUTTONUP => Some((2, false)),
                    WM_RBUTTONDOWN => Some((4, true)),
                    WM_RBUTTONUP => Some((4, false)),
                    _ => None,
                };
                let Some(p) = self.panes.get(&id) else {
                    return false;
                };
                if !p.desktop.as_ref().is_some_and(|d| d.running()) {
                    return false;
                }
                let area = (p.rect.x, p.rect.y, p.rect.right(), p.rect.bottom());
                // Ctrl+Shift+drag still moves panes.
                let mods = mouse_mods(wparam);
                if mods.ctrl && mods.shift {
                    return false;
                }
                if matches!(button, Some((_, true))) {
                    if self.side.visible && !self.settings.tools_pinned {
                        // Pin off: a click on a remote desktop ends the
                        // peek too; the desktop does not get it.
                        self.hide_side();
                        self.focus_pane(id);
                        return true;
                    }
                    if self.focused_id() != id {
                        self.focus_pane(id);
                    }
                    self.desktop_clip_touch(id);
                }
                if let Some(d) = self.panes.get_mut(&id).and_then(|p| p.desktop.as_mut()) {
                    d.mouse(area, x, y, button);
                }
                true
            }
            WM_MOUSEWHEEL => {
                let (x, y) = lparam_point(lparam);
                let mut pt = POINT { x, y };
                // SAFETY: our window and a local point.
                let _ = unsafe { ScreenToClient(self.hwnd, &mut pt) };
                let Spot::Pane(id) = self.spot(pt.x, pt.y) else {
                    return false;
                };
                let delta = ((wparam.0 >> 16) & 0xFFFF) as u16 as i16;
                let Some(p) = self.panes.get_mut(&id) else {
                    return false;
                };
                let area = (p.rect.x, p.rect.y, p.rect.right(), p.rect.bottom());
                match p.desktop.as_mut() {
                    Some(d) if d.running() => {
                        // Touchpads send part notches: each counts as one.
                        let notches = i32::from(delta) / WHEEL_DELTA_NOTCH;
                        let notches = if notches == 0 {
                            i32::from(delta).signum()
                        } else {
                            notches
                        };
                        d.wheel(area, pt.x, pt.y, notches);
                        true
                    }
                    _ => false,
                }
            }
            WM_KILLFOCUS => {
                let id = self.focused_id();
                if let Some(d) = self.panes.get_mut(&id).and_then(|p| p.desktop.as_mut()) {
                    d.focus_lost();
                }
                false
            }
            _ => false,
        }
    }

    /// Carries out what the forwards view asked for. Changes also go into
    /// the hosts of the connection's panes, so a reconnect keeps them.
    fn forwards_action(&mut self, action: Option<FwdAction>) -> Option<Command> {
        let view = self.forward_view();
        match action {
            Some(FwdAction::Add { spec, connection }) => {
                if let Err(why) = self.add_forward(connection, &spec, &view) {
                    self.forwards_view.refuse(&spec, why);
                }
            }
            Some(FwdAction::Remove { connection, index }) => {
                if let Some(f) = forwards_of(&view, connection).nth(index) {
                    let spec = f.spec.clone();
                    if let Some(w) = self.workers.get(&connection) {
                        w.forwarder.remove_spec(connection, spec.clone(), f.desktop);
                    }
                    self.keep_forwards(connection, |list| list.retain(|s| *s != spec));
                }
            }
            Some(FwdAction::Replace {
                connection,
                old,
                new,
            }) => {
                if old != new && forwards_of(&view, connection).any(|f| f.spec == new) {
                    self.forwards_view
                        .refuse(&new, "That forward is already there.".into());
                } else if let Some(w) = self.workers.get(&connection) {
                    w.forwarder.replace(connection, old.clone(), new.clone());
                    self.keep_forwards(connection, |list| {
                        if let Some(s) = list.iter_mut().find(|s| **s == old) {
                            *s = new.clone();
                        } else if !list.contains(&new) {
                            list.push(new.clone());
                        }
                    });
                }
            }
            Some(FwdAction::Cancel { cancel, connection }) => {
                if let Err(why) = self.cancel_forward(connection, &cancel, &view) {
                    self.forwards_view.say(why);
                }
            }
            Some(FwdAction::Leave) => self.focus_terminal(),
            None => {}
        }
        self.refresh_chrome();
        None
    }

    /// Adds `spec` to a running connection (see
    /// [`Self::forward_connection`]) and to the forwards its reconnects
    /// start; `Err` says why not.
    fn add_forward(
        &mut self,
        connection: Option<ChannelId>,
        spec: &ForwardSpec,
        view: &[ConnView],
    ) -> std::result::Result<ChannelId, String> {
        let c = self.forward_connection(connection, view)?;
        if forwards_of(view, c).any(|f| f.spec == *spec) {
            return Err("That forward is already there.".into());
        }
        if let Some(w) = self.workers.get(&c) {
            w.forwarder.add(c, spec.clone());
        }
        self.keep_forwards(c, |list| {
            if !list.contains(spec) {
                list.push(spec.clone());
            }
        });
        Ok(c)
    }

    /// Stops the one forward `cancel` names (`-KL 8080`), as ssh's `~C`
    /// does; returns it, or says why nothing stopped.
    fn cancel_forward(
        &mut self,
        connection: Option<ChannelId>,
        cancel: &ferossh_config::forward::CancelSpec,
        view: &[ConnView],
    ) -> std::result::Result<ForwardSpec, String> {
        let c = self.forward_connection(connection, view)?;
        let matching: Vec<&ForwardSpec> = forwards_of(view, c)
            .filter(|f| !f.desktop && cancel.cancels(&f.spec))
            .map(|f| &f.spec)
            .collect();
        let spec = match &matching[..] {
            [spec] => (*spec).clone(),
            [] => return Err("No forward listens there.".to_owned()),
            _ => return Err("More than one forward listens there: add the address.".to_owned()),
        };
        // By spec, not by place in the list: one cancelled just before
        // may not have left the view yet.
        if let Some(w) = self.workers.get(&c) {
            w.forwarder.remove_spec(c, spec.clone(), false);
        }
        self.keep_forwards(c, |list| list.retain(|s| *s != spec));
        Ok(spec)
    }

    /// The connection a forward goes to: the one picked in the list, else
    /// the focused pane's, else the only one there is.
    fn forward_connection(
        &self,
        picked: Option<ChannelId>,
        view: &[ConnView],
    ) -> std::result::Result<ChannelId, String> {
        let known =
            |c: &ChannelId| view.iter().any(|v| v.connection == *c) && self.workers.contains_key(c);
        picked
            .filter(known)
            .or_else(|| self.pane_connection(self.focused_id()).filter(known))
            .or_else(|| match view {
                [only] => Some(only.connection).filter(known),
                _ => None,
            })
            .ok_or_else(|| {
                if view.is_empty() {
                    "Log in to a host first.".to_owned()
                } else {
                    "Choose the connection in the On box.".to_owned()
                }
            })
    }

    /// Changes the forwards a reconnect of `connection`'s panes starts.
    fn keep_forwards(
        &mut self,
        connection: ChannelId,
        mut change: impl FnMut(&mut Vec<ForwardSpec>),
    ) {
        for p in self.panes.values_mut() {
            if let Host::Ssh(s) = &mut p.host
                && s.connection == connection
            {
                change(&mut s.target.forwards);
            }
        }
    }

    /// Starts the worker of the connection `connection` if it is not
    /// running: a new login gets a worker of its own.
    fn ensure_worker(&mut self, id: PaneId, connection: ChannelId) -> bool {
        if self.workers.contains_key(&connection) {
            return true;
        }
        let result = sandbox::spawn_worker(self.sandbox).and_then(|w| {
            let input = w.from_worker.try_clone().map_err(io_error)?;
            let output = w.to_worker.try_clone().map_err(io_error)?;
            let (forwarder, runner) = Forwarder::new();
            let link =
                Link::start(input, output, self.notifier(), forwarder.sink()).map_err(io_error)?;
            runner
                .spawn(link.sender(), self.notifier())
                .map_err(io_error)?;
            Ok(WorkerConn {
                link,
                forwarder,
                _process: w,
            })
        });
        match result {
            Ok(conn) => {
                self.workers.insert(connection, conn);
                true
            }
            Err(e) => {
                let text = format!(
                    "\x1b[0;31mCould not start the sandboxed SSH worker: {}\x1b[0m\r\n\
                     If this Windows does not allow AppContainers, start FeroSSH with \
                     --no-sandbox.\r\n",
                    e.message()
                );
                self.show(id, &text);
                false
            }
        }
    }

    fn ensure_broker(&mut self, id: PaneId) -> bool {
        if self.broker.is_some() {
            return true;
        }
        match Broker::spawn(self.notifier()) {
            Ok(b) => {
                self.broker = Some(b);
                true
            }
            Err(e) => {
                self.show(
                    id,
                    &format!("\x1b[0;31mCould not start the signing broker: {e}\x1b[0m\r\n"),
                );
                false
            }
        }
    }

    /// A workspace pane connected anywhere else than its own destination
    /// is a pane like any other: it runs nothing of the workspace's.
    fn workspace_elsewhere(&mut self, id: PaneId, destination: &str) {
        // As written: user names differ by case (and so do some hosts).
        let other = |d: &str| d.trim() != destination.trim();
        // One waiting for another pane's login waits no more, and its
        // tmux plan is not its own any more: it is saved, and kept, as
        // what it now opens.
        let waiting = self.workspace_waiting.destination(id).is_some_and(other);
        let extra = self
            .workspace_extra
            .get(&id)
            .is_some_and(|e| !e.dest.as_deref().is_some_and(|d| !other(d)));
        if waiting {
            self.workspace_waiting.forget(id);
        }
        if extra {
            self.workspace_extra.remove(&id);
        }
        if waiting || extra {
            self.workspace_tmux.remove(&id);
        }
    }

    /// Connects pane `id` to `destination` (`[user@]host[:port]` or a
    /// Host from ssh_config).
    fn connect(&mut self, id: PaneId, destination: &str) {
        self.connect_with(id, destination, &Extras::default());
    }

    /// Like [`Self::connect`], with the command line's `-N` and forwards
    /// for an SSH login.
    fn connect_with(&mut self, id: PaneId, destination: &str, extras: &Extras) {
        // A connection picked anew, even one with the old name, is not the
        // renamed one: only a reconnect follows a rename.
        self.inventory_renames.remove(&id);
        // An `ssh://` link is the host it names; one that does not parse
        // is never read as a host name.
        let link;
        let destination = if ferossh_config::ssh_config::has_scheme(destination, "ssh://") {
            match ferossh_config::ssh_config::ssh_url(destination) {
                Some(d) => {
                    link = d;
                    link.as_str()
                }
                None => {
                    self.end_host(id);
                    self.show(
                        id,
                        "\x1b[0;31mThat is not an SSH link: write ssh://user@host[:port].\x1b[0m\r\n",
                    );
                    self.ask_destination(id);
                    return;
                }
            }
        } else {
            destination
        };
        self.workspace_elsewhere(id, destination);
        if !extras.is_empty() && !self.ssh_destination(destination) {
            self.end_host(id);
            self.show(
                id,
                "\x1b[0;31m-N, -L, -R and -D are for SSH logins.\x1b[0m\r\n",
            );
            self.ask_destination(id);
            return;
        }
        if let Some(target) = serial::parse_target(destination) {
            self.open_serial(id, target, None);
            return;
        }
        let env = ssh_env();
        if !self.connect_allowed(id, destination, extras, &env) {
            return;
        }
        if let Some((destination, folder)) = ferossh_config::ssh_config::sftp_url(destination) {
            match Target::resolve_route(&destination, &env) {
                Ok(mut target) => {
                    target.sftp_only = true;
                    target.sftp_folder = folder;
                    extras.apply(&mut target);
                    self.connect_to(id, target, &env);
                }
                Err(why) => {
                    self.end_host(id);
                    self.show(id, &format!("\x1b[0;31m{why}\x1b[0m\r\n"));
                    self.ask_destination(id);
                }
            }
            return;
        }
        // Meant as an `sftp://` address but not one: never a shell login.
        if ferossh_config::ssh_config::has_scheme(destination, "sftp://") {
            self.end_host(id);
            self.show(
                id,
                "\x1b[0;31mThat is not an SFTP address: write sftp://user@host[:port][/folder].\x1b[0m\r\n",
            );
            self.ask_destination(id);
            return;
        }
        if let Some(target) = self.telnet_target(destination, &env) {
            self.connect_telnet(id, target);
            return;
        }
        if let Some(target) = self.winrm_target(destination, &env) {
            self.connect_winrm(id, target);
            return;
        }
        let mut target = match Target::resolve_route(destination, &env) {
            Ok(t) => t,
            Err(why) => {
                self.end_host(id);
                self.show(id, &format!("\x1b[0;31m{why}\x1b[0m\r\n"));
                self.ask_destination(id);
                return;
            }
        };
        extras.apply(&mut target);
        self.connect_to(id, target, &env);
    }

    /// What the security rules forbid for connection `alias` (reaching
    /// `hostname`, with ssh_config's `Tag` `tag`).
    fn policy_of(&self, alias: &str, hostname: Option<&str>, tag: Option<&str>) -> Policy {
        self.policy_and_peers(alias, hostname, tag).0
    }

    /// [`Self::policy_of`], and the other connections to the same machine
    /// whose rules added to it: rules follow the machine, so an address
    /// typed by hand or another alias gets a saved connection's tag and
    /// folder rules too.
    fn policy_and_peers(
        &self,
        alias: &str,
        hostname: Option<&str>,
        tag: Option<&str>,
    ) -> (Policy, Vec<String>) {
        if self.settings.security_rules.is_empty() {
            return (Policy::default(), Vec::new());
        }
        let tags = ferossh_config::settings::host_tags(tag, self.settings.profile(alias));
        let folder = self.rule_folder(alias);
        let all = self.rule_connections();
        let others: Vec<Subject<'_>> = all
            .iter()
            .map(|c| Subject {
                name: &c.name,
                hostname: c.hostname.as_deref(),
                tags: &c.tags,
                folder: c.folder.as_deref(),
            })
            .collect();
        let (policy, from) = ferossh_config::host_policy::policy_with_peers(
            &self.settings.security_rules,
            &Subject {
                name: alias,
                hostname,
                tags: &tags,
                folder: folder.as_deref(),
            },
            &others,
        );
        (policy, from.into_iter().map(str::to_owned).collect())
    }

    /// The folder the Connection manager shows connection `alias` in: a
    /// FeroSSH connection's own, else the one its ssh_config (an
    /// import's file) gives it.
    fn rule_folder(&self, alias: &str) -> Option<String> {
        load_saved()
            .into_iter()
            .find(|h| h.alias.eq_ignore_ascii_case(alias))
            .and_then(|h| h.folder)
            .or_else(|| {
                let env = ssh_env();
                let includes = ssh_config::DirIncludes {
                    home: env.home.clone(),
                };
                ssh_config::hosts(&env.config, &includes)
                    .into_iter()
                    .find(|h| h.name.eq_ignore_ascii_case(alias))
                    .and_then(|h| h.folder)
            })
    }

    /// Whether pane `id` may connect to `destination` now. A security
    /// rule that asks first, for the host or a jump host on the way,
    /// queues the question (asked once no state is borrowed) and the
    /// connection waits for it.
    fn connect_allowed(
        &mut self,
        id: PaneId,
        destination: &str,
        extras: &Extras,
        env: &Env,
    ) -> bool {
        if self.settings.security_rules.is_empty() {
            self.connect_confirmed.remove(&id);
            return true;
        }
        let (alias, endpoint, confirm) = self.connect_subject(destination, env);
        // A Yes holds for the endpoint and route it was given for: one
        // that changed meanwhile (an edited HostName, jump host or proxy)
        // is asked about again, even if no rule matches it now.
        match self.connect_confirmed.remove(&id) {
            Some(approved) if approved == endpoint => return true,
            Some(_) => {}
            None if !confirm => return true,
            None => {}
        }
        self.show(
            id,
            &format!(
                "\x1b[0;90mA security rule asks before connecting to {}.\x1b[0m\r\n",
                crate::ssh::sanitize_line(&alias)
            ),
        );
        self.connect_asked += 1;
        let token = self.connect_asked;
        self.connect_pending.insert(
            id,
            PendingConnect {
                token,
                endpoint: endpoint.clone(),
                after: AfterConfirm::Plain,
            },
        );
        self.workspace_asks.push(Command::ConfirmConnect {
            pane: id,
            token,
            destination: destination.to_owned(),
            endpoint,
            extras: extras.clone(),
        });
        // SAFETY: our window; replaces any earlier timer with this id.
        unsafe { SetTimer(Some(self.hwnd), TIMER_WORKSPACE_ASK, 50, None) };
        false
    }

    /// `destination` as a Telnet session: a saved Telnet connection, or
    /// a typed `telnet://` address.
    fn telnet_target(&self, destination: &str, env: &Env) -> Option<TelnetTarget> {
        if self
            .settings
            .profile(destination)
            .is_some_and(|p| p.kind == SessionKind::Telnet)
        {
            TelnetTarget::resolve(destination, env)
        } else {
            TelnetTarget::typed(destination)
        }
    }

    /// `destination` as a WinRM session: a saved WinRM connection (its
    /// port, HTTPS and login user), or a typed `winrm://` address.
    fn winrm_target(&self, destination: &str, env: &Env) -> Option<WinrmTarget> {
        match self.settings.profile(destination) {
            Some(p) if p.kind == SessionKind::WinRm => {
                let saved = load_saved()
                    .into_iter()
                    .find(|h| h.alias.eq_ignore_ascii_case(destination));
                WinrmTarget::resolve(
                    destination,
                    env,
                    p.winrm_command.as_deref(),
                    p.winrm_https,
                    saved.as_ref(),
                )
                .map(|t| {
                    t.with_login_user(
                        self.settings
                            .credential_of(destination)
                            .and_then(|c| c.user.as_deref()),
                    )
                })
            }
            _ => WinrmTarget::typed(destination),
        }
    }

    /// The connection `destination` names, as the security rules see
    /// it: its name, where it goes (user, host and port, and the jump
    /// hosts on the way) and whether a rule for it or for one of its
    /// jump hosts asks first.
    fn connect_subject(&self, destination: &str, env: &Env) -> (String, String, bool) {
        // As connect_with dispatches it, so the question names the port
        // the protocol will use.
        if ferossh_config::ssh_config::sftp_url(destination).is_none() {
            if let Some(t) = self.telnet_target(destination, env) {
                let policy = self.policy_of(&t.alias, Some(&t.hostname), t.tag.as_deref());
                let endpoint = format!("telnet {}:{}", t.hostname, t.port);
                return (t.alias, endpoint, policy.confirm_connect);
            }
            if let Some(t) = self.winrm_target(destination, env) {
                let policy = self.policy_of(&t.alias, Some(&t.hostname), t.tag.as_deref());
                let endpoint = format!(
                    "winrm{} {}{}:{}",
                    if t.https { "s" } else { "" },
                    t.user
                        .as_deref()
                        .map(|u| format!("{u}@"))
                        .unwrap_or_default(),
                    t.hostname,
                    t.port
                );
                return (t.alias, endpoint, policy.confirm_connect);
            }
        }
        let lookup = ferossh_config::ssh_config::sftp_url(destination)
            .map_or_else(|| destination.to_owned(), |(d, _)| d);
        let Some(target) = Target::resolve(&lookup, env) else {
            let policy = self.policy_of(&lookup, None, None);
            return (lookup.clone(), lookup, policy.confirm_connect);
        };
        let mut confirm = self
            .policy_of(&target.alias, Some(&target.hostname), target.tag.as_deref())
            .confirm_connect;
        for hop in &target.jumps {
            confirm |= self
                .policy_of(&hop.alias, Some(&hop.hostname), hop.tag.as_deref())
                .confirm_connect;
        }
        // The jump hosts as they resolve, and any proxy or command: a
        // change to any of them is another route.
        let mut endpoint = format!("{}@{}:{}", target.user, target.hostname, target.port);
        let route = target.route_key();
        if !route.is_empty() {
            endpoint.push_str(" via ");
            endpoint.push_str(&route.join(", "));
        }
        (target.alias, endpoint, confirm)
    }

    /// The answer to security rule question `token` before connecting
    /// pane `id` to `destination`. An answer to a question the pane no
    /// longer waits for (another connection took it) changes nothing.
    fn connect_answered(
        &mut self,
        id: PaneId,
        token: u64,
        destination: &str,
        extras: &Extras,
        yes: bool,
    ) {
        if !self.panes.contains_key(&id)
            || self
                .connect_pending
                .get(&id)
                .is_none_or(|p| p.token != token)
        {
            return;
        }
        let Some(pending) = self.connect_pending.remove(&id) else {
            return;
        };
        if yes {
            self.connect_confirmed.insert(id, pending.endpoint);
            match pending.after {
                AfterConfirm::Plain => self.connect_with(id, destination, extras),
                AfterConfirm::Run => {
                    self.connect_with(id, destination, extras);
                    if self.confirm_pending(id) {
                        self.after_confirm(id, AfterConfirm::Run);
                    } else {
                        self.run_connected(id);
                    }
                }
                AfterConfirm::Workspace { dir, spec } => {
                    self.connect_with_dir(id, destination, dir.as_deref());
                    if let Some(spec) = spec {
                        if self.confirm_pending(id) {
                            self.confirmed_look(id, &spec);
                        } else {
                            self.workspace_look(id, &spec);
                        }
                    }
                }
            }
            // Asked again (the endpoint changed): no Yes left over.
            if self.connect_pending.contains_key(&id) {
                self.connect_confirmed.remove(&id);
            }
        } else {
            self.connect_confirmed.remove(&id);
            if matches!(pending.after, AfterConfirm::Run) {
                self.fail_run_row(id, "not confirmed".into());
            }
            self.end_host(id);
            self.show(id, "\x1b[0;90mNot connected.\x1b[0m\r\n");
            self.ask_destination(id);
            self.refresh(id);
        }
    }

    /// Whether pane `id` waits for the answer to a security rule's
    /// question: it is not free for another request.
    fn confirm_pending(&self, id: PaneId) -> bool {
        self.connect_pending.contains_key(&id)
    }

    /// What pane `id`'s request does once a security rule's question
    /// it waits for is answered Yes.
    fn after_confirm(&mut self, id: PaneId, after: AfterConfirm) {
        if let Some(p) = self.connect_pending.get_mut(&id) {
            p.after = after;
        }
    }

    /// Puts the security rules' limits for a connection on pane `id`:
    /// a forced session log and no clipboard writes. Returns them, and
    /// says which apply.
    fn apply_policy(
        &mut self,
        id: PaneId,
        alias: &str,
        hostname: &str,
        tag: Option<&str>,
    ) -> Policy {
        let (policy, peers) = self.policy_and_peers(alias, Some(hostname), tag);
        let Some(p) = self.panes.get_mut(&id) else {
            return policy;
        };
        p.policy = policy;
        if policy.log_session {
            p.log.before_rule.get_or_insert(p.log.enabled);
            p.log.enabled = true;
        } else if let Some(before) = p.log.before_rule.take() {
            p.log.enabled = before;
        }
        if !policy.is_empty() {
            let peers = if peers.is_empty() {
                String::new()
            } else {
                format!(
                    " (also those of {}, which reaches the same machine)",
                    crate::ssh::sanitize_line(&peers.join(", "))
                )
            };
            let text = format!(
                "\x1b[0;90mSecurity rules: {}{peers}.\x1b[0m\r\n",
                policy.describe().join(", ")
            );
            self.show(id, &text);
            self.update_menu_checks();
        }
        self.warn_rule_lines(id, alias, hostname, tag);
        policy
    }

    /// Says so in pane `id` when a rule for the connection has lines this
    /// FeroSSH does not understand: a limit it may be meant to have, and
    /// does not get.
    fn warn_rule_lines(&mut self, id: PaneId, alias: &str, hostname: &str, tag: Option<&str>) {
        self.warn_rule_lines_for(id, alias, hostname, tag, false);
    }

    /// [`Self::warn_rule_lines`] for connection `alias`, a jump host on the
    /// way when `hop` (named in the warning).
    fn warn_rule_lines_for(
        &mut self,
        id: PaneId,
        alias: &str,
        hostname: &str,
        tag: Option<&str>,
        hop: bool,
    ) {
        if self
            .settings
            .security_rules
            .iter()
            .all(|r| r.unknown.is_empty())
        {
            return;
        }
        let tags = ferossh_config::settings::host_tags(tag, self.settings.profile(alias));
        let folder = self.rule_folder(alias);
        let subject = Subject {
            name: alias,
            hostname: Some(hostname),
            tags: &tags,
            folder: folder.as_deref(),
        };
        let rules = &self.settings.security_rules;
        let mut lines = ferossh_config::host_policy::not_understood(rules, &subject);
        // Rules follow the machine: so do the lines they are missing.
        let here = ferossh_config::host_policy::machine(&subject);
        for c in self.rule_connections() {
            let peer = Subject {
                name: &c.name,
                hostname: c.hostname.as_deref(),
                tags: &c.tags,
                folder: c.folder.as_deref(),
            };
            if c.name.eq_ignore_ascii_case(alias)
                || !ferossh_config::host_policy::same_machine(
                    ferossh_config::host_policy::machine(&peer),
                    here,
                )
            {
                continue;
            }
            for line in ferossh_config::host_policy::not_understood(rules, &peer) {
                if !lines.contains(&line) {
                    lines.push(line);
                }
            }
        }
        if lines.is_empty() {
            return;
        }
        let whose = if hop {
            format!("jump host {}", crate::ssh::sanitize_line(alias))
        } else {
            "this connection".to_owned()
        };
        let text = format!(
            "\x1b[0;33mA security rule for {whose} has lines this FeroSSH does not \
             understand, so they are not applied: {}. See Tools > Security rules.\x1b[0m\r\n",
            crate::ssh::sanitize_line(&lines.join("; "))
        );
        self.show(id, &text);
        // The login session of a desktop or remote app is hidden and goes
        // once the app holds the connection: shown in a tab instead, so
        // the warning is seen and stays.
        if self.launches.contains_key(&id) {
            // Also one already shown (to confirm the connection, say).
            self.launch_warned.insert(id);
            if self.launch_hidden.contains(&id) {
                self.reveal_launch(id);
            }
        }
    }

    /// Whether `destination` logs in over SSH: not a serial port, a
    /// Telnet or WinRM address, or a saved connection of another type.
    fn ssh_destination(&self, destination: &str) -> bool {
        use ferossh_config::ssh_config::has_scheme;
        if serial::parse_target(destination).is_some()
            || ["telnet://", "winrm://", "winrms://"]
                .iter()
                .any(|s| has_scheme(destination, s))
        {
            return false;
        }
        self.settings.profile(destination).is_none_or(|p| {
            matches!(
                p.kind,
                SessionKind::Ssh | SessionKind::Mosh | SessionKind::Sftp | SessionKind::Tunnel
            )
        })
    }

    /// Opens serial console `target` in pane `id`, with the look of saved
    /// session `session` (or the port's, by theme rules).
    fn open_serial(&mut self, id: PaneId, target: SerialTarget, session: Option<&str>) {
        self.end_host(id);
        let alias = session.unwrap_or(&target.port).to_owned();
        let (font, theme) = self.host_look(&alias, &target.port, None);
        let scrollback = self
            .settings
            .profile(&alias)
            .and_then(|p| p.scrollback)
            .or(self.settings.scrollback);
        let lock = look::lock_for(&self.settings, &alias, &target.port, None);
        if let Some(p) = self.panes.get_mut(&id) {
            p.term.set_settings(&term_settings(scrollback));
            p.term.scroll_to_bottom();
            p.hl_host = Some((alias.clone(), target.port.clone()));
            p.lock = lock;
        }
        self.apply_highlight(id, true);
        self.set_theme(id, theme);
        self.set_font(id, font);
        let notify = self.notifier();
        let opened = SerialPort::open(&target, notify);
        let text = match &opened {
            Ok(_) => format!(
                "\x1b[0;90mOpened {} at {} bits/s, {}, flow control {}. \
                 Session > Send break sends a break.\x1b[0m\r\n",
                target.port,
                target.settings.speed,
                target.settings.framing(),
                target.settings.flow.label()
            ),
            Err(e) => format!("\x1b[0;31m{e}\x1b[0m\r\nPress Enter to try again.\r\n"),
        };
        let opened = opened.ok();
        let is_open = opened.is_some();
        if let Some(p) = self.panes.get_mut(&id) {
            p.host = Host::Serial {
                port: opened.map(Box::new),
                target,
                session: session.map(str::to_owned),
            };
        }
        self.show(id, &text);
        self.start_log(id);
        if is_open && !self.start_script(id, &alias, false) {
            self.workspace_start(id, false);
        }
        self.update_title();
        self.refresh_chrome();
        self.refresh(id);
    }

    /// Connects pane `id` to `target`. When another pane is logged in to
    /// the same host, port and user, the new shell is a channel on that
    /// connection: no second login.
    fn connect_to(&mut self, id: PaneId, mut target: Target, env: &Env) {
        self.end_host(id);
        // The profile decides, every time: a reconnect or a split passes
        // the old target back, which may predate a change of type.
        target.mosh = self
            .settings
            .profile(&target.alias)
            .filter(|p| p.kind == SessionKind::Mosh)
            .map(|p| {
                Box::new(MoshOptions {
                    server: p
                        .mosh_server
                        .clone()
                        .unwrap_or_else(|| DEFAULT_MOSH_SERVER.to_owned()),
                    ports: p.mosh_ports,
                    predict: match p.mosh_predict.as_deref() {
                        Some("always") => MoshPredict::Always,
                        Some("never") => MoshPredict::Never,
                        _ => MoshPredict::Adaptive,
                    },
                })
            });
        // An `sftp://` address asks for file transfer only, whatever the
        // connection it names is.
        target.sftp_only |= self
            .settings
            .profile(&target.alias)
            .is_some_and(|p| p.kind == SessionKind::Sftp);
        // Likewise a connection of type *SSH tunnels only*, else
        // `SessionType none` or `-N` already said so.
        target.tunnel_only |= self
            .settings
            .profile(&target.alias)
            .is_some_and(|p| p.kind == SessionKind::Tunnel);
        // No shell, so no Mosh session in its place.
        if target.tunnel_only {
            target.mosh = None;
        }
        if let Some(p) = self.panes.get_mut(&id) {
            p.term.scroll_to_bottom();
        }
        // The rules first: they change what the login may use, and so
        // which connections it may share.
        let rules = self.policy_of(&target.alias, Some(&target.hostname), target.tag.as_deref());
        if rules.no_agent_forwarding {
            target.forward_agent = false;
        }
        if rules.keys_only {
            // A Kerberos ticket is no key either.
            target.gssapi = false;
        }
        // A keys-only login never rides on a connection another pane may
        // have logged in to with a password.
        // A jump host under KeysOnly may have logged in another way on a
        // connection already open (its rule came later): log in afresh.
        let hops_keys_only = target.jumps.iter().any(|j| {
            self.policy_of(&j.alias, Some(&j.hostname), j.tag.as_deref())
                .keys_only
        });
        // The connection to share, and the host key it was checked with
        // (the shared login sees no key of its own).
        let shared_with = (!rules.keys_only && !hops_keys_only)
            .then(|| {
                self.panes.values().find_map(|p| match &p.host {
                    Host::Ssh(s) if p.id != id && s.can_share(&target) => {
                        Some((s.connection, s.host_key_seen.clone()))
                    }
                    _ => None,
                })
            })
            .flatten();
        let shared = shared_with.as_ref().map(|(c, _)| *c);
        let channel = self.new_channel();
        // A new login runs in a worker of its own; a shared connection's
        // shell in that connection's.
        if !self.ensure_worker(id, shared.unwrap_or(channel)) || !self.ensure_broker(id) {
            self.refresh(id);
            return;
        }
        if !self.sandbox {
            self.show(
                id,
                "\x1b[0;31mThe SSH worker runs without its sandbox (--no-sandbox).\x1b[0m\r\n",
            );
        }
        self.apply_look(id, &target.alias, &target.hostname, target.tag.as_deref());
        let policy = self.apply_policy(id, &target.alias, &target.hostname, target.tag.as_deref());
        // A jump host's rule lines not understood are said too, also when
        // this pane shares a connection already open; its limits stay its
        // own.
        for j in &target.jumps {
            self.warn_rule_lines_for(id, &j.alias, &j.hostname, j.tag.as_deref(), true);
        }
        let x11 = target
            .forward_x11
            .then(|| self.x11_auth(id, shared))
            .flatten();
        let legacy = self
            .settings
            .profile(&target.alias)
            .is_some_and(|p| p.legacy_algorithms);
        let source = self.login_source(id, &target.alias);
        let auto_reconnect = self
            .settings
            .profile(&target.alias)
            .and_then(|p| p.auto_reconnect)
            .unwrap_or(self.settings.auto_reconnect);
        let mut session = SshSession::new(channel, target, env.known_hosts());
        session.auto_reconnect = auto_reconnect;
        if let Some((_, key)) = shared_with {
            session.host_key_seen = key;
        }
        // A saved proxy password is read only where no rule on the way
        // forbids saved passwords.
        let mut proxy_rules = policy;
        if shared.is_none() {
            // Each jump host logs in in a worker of its own.
            session = session.with_route(&mut || self.new_channel());
            let hops = session.hop_connections();
            for &hop in &hops {
                if !self.ensure_worker(id, hop) {
                    // No host after all: its rules go too.
                    if let Some(p) = self.panes.get_mut(&id) {
                        p.hl_host = None;
                    }
                    self.apply_highlight(id, false);
                    self.refresh(id);
                    return;
                }
            }
            if !hops.is_empty() {
                self.via.insert(channel, hops);
            }
            let hop_targets: Vec<(String, String, Option<String>)> = session
                .hops_mut()
                .map(|hop| {
                    let t = &hop.target;
                    (t.alias.clone(), t.hostname.clone(), t.tag.clone())
                })
                .collect();
            let hop_policies: Vec<Policy> = hop_targets
                .into_iter()
                .map(|(a, h, t)| self.policy_of(&a, Some(&h), t.as_deref()))
                .collect();
            for (hop, hop_policy) in session.hops_mut().zip(hop_policies) {
                proxy_rules.tighten(&hop_policy);
                if hop_policy.keys_only {
                    hop.target.gssapi = false;
                }
                let profile = self.settings.profile(&hop.target.alias);
                let source = hop_policy.allow_source(self.login_source(id, &hop.target.alias));
                hop.legacy = profile.is_some_and(|p| p.legacy_algorithms);
                hop.keys_only = hop_policy.keys_only;
                hop.password_source = source != PasswordSource::Ask;
                hop.remember_password = source == PasswordSource::Windows;
            }
        }
        if let Some(p) = self.panes.get_mut(&id) {
            p.route_policy = proxy_rules;
        }
        if !proxy_rules.no_saved_password
            && !proxy_rules.keys_only
            && let Some(p) = session.proxy_login()
            && let Some(user) = p.user.as_deref()
            && let Ok(Some(password)) = credman::read(&credman::proxy_target(user, &p.host, p.port))
        {
            session.set_proxy_password(password);
        }
        let source = policy.allow_source(source);
        session.x11 = x11;
        session.legacy = legacy;
        session.keys_only = policy.keys_only;
        session.password_source = source != PasswordSource::Ask;
        session.remember_password = source == PasswordSource::Windows;
        if self.run_login.contains(&id) {
            // A run never reconnects by itself, and the password typed
            // for it answers the logins that have none saved.
            // A password a run used is never saved: not the one typed for
            // it, and one already in the Credential Manager stays as it is.
            session.auto_reconnect = false;
            session.remember_password = false;
            let typed = self.run_password().is_some();
            session.password_source |= typed && !session.keys_only;
            for hop in session.hops_mut() {
                hop.password_source |= typed && !hop.keys_only;
                hop.remember_password = false;
            }
        }
        let Some(p) = self.panes.get_mut(&id) else {
            return;
        };
        let (cols, rows) = (clamp16(p.term.cols()), clamp16(p.term.rows()));
        let effects = match shared {
            Some(connection) => session.start_on(connection, cols, rows),
            None => session.start(cols, rows),
        };
        p.host = Host::Ssh(Box::new(session));
        self.apply(id, effects);
        self.update_title();
        self.refresh_chrome();
        self.refresh(id);
    }

    /// Opens Telnet session `target` in pane `id`, in a worker of its
    /// own: Telnet is parsed in the sandbox too.
    fn connect_telnet(&mut self, id: PaneId, target: TelnetTarget) {
        self.end_host(id);
        if let Some(p) = self.panes.get_mut(&id) {
            p.term.scroll_to_bottom();
        }
        let channel = self.new_channel();
        if !self.ensure_worker(id, channel) {
            self.refresh(id);
            return;
        }
        if !self.sandbox {
            self.show(
                id,
                "\x1b[0;31mThe Telnet worker runs without its sandbox (--no-sandbox).\x1b[0m\r\n",
            );
        }
        self.apply_look(id, &target.alias, &target.hostname, target.tag.as_deref());
        self.apply_policy(id, &target.alias, &target.hostname, target.tag.as_deref());
        let mut session = TelnetSession::new(channel, target);
        let Some(p) = self.panes.get_mut(&id) else {
            return;
        };
        let effects = session.start(clamp16(p.term.cols()), clamp16(p.term.rows()));
        p.host = Host::Telnet(Box::new(session));
        self.apply(id, effects);
        self.update_title();
        self.refresh_chrome();
        self.refresh(id);
    }

    /// Opens WinRM session `target` in pane `id`, in a worker of its own
    /// that parses everything the server sends; the login and the
    /// encryption run on the broker.
    fn connect_winrm(&mut self, id: PaneId, target: WinrmTarget) {
        self.connect_winrm_with(id, target, false);
    }

    /// Opens WinRM session `target` in pane `id`; `ask` skips the
    /// connection's password source (it just failed) and asks.
    fn connect_winrm_with(&mut self, id: PaneId, mut target: WinrmTarget, ask: bool) {
        self.end_host(id);
        if let Some(p) = self.panes.get_mut(&id) {
            p.term.scroll_to_bottom();
        }
        let channel = self.new_channel();
        if !self.ensure_broker(id) || !self.ensure_worker(id, channel) {
            self.refresh(id);
            return;
        }
        if !self.sandbox {
            self.show(
                id,
                "\x1b[0;31mThe WinRM worker runs without its sandbox (--no-sandbox).\x1b[0m\r\n",
            );
        }
        self.apply_look(id, &target.alias, &target.hostname, target.tag.as_deref());
        let policy = self
            .apply_policy(id, &target.alias, &target.hostname, target.tag.as_deref())
            .without_keys_only();
        if let Some(p) = self.panes.get_mut(&id) {
            p.policy = policy;
        }
        let profile = self
            .settings
            .profile(&target.alias)
            .filter(|p| p.kind == SessionKind::WinRm);
        // Read now, not carried over from the session a reconnect or a
        // split copies: NTLM over HTTP is allowed only while the saved
        // connection still says so.
        // Only for the saved connection itself: a typed address that
        // happens to share its name is another endpoint, and so is the
        // old address a reconnect or split carries after the connection
        // was edited to point elsewhere.
        let same_endpoint = || {
            self.saved_winrm_target(&target.alias).is_some_and(|now| {
                !now.https
                    && now.port == target.port
                    && now.hostname.eq_ignore_ascii_case(&target.hostname)
            })
        };
        target.ntlm = target.saved
            && !target.https
            && profile.is_some_and(|p| p.winrm_ntlm)
            && same_endpoint();
        let mut source = self.settings.password_source(&target.alias);
        if source == PasswordSource::Ask && self.workspace_login(id) {
            source = PasswordSource::Windows;
        }
        let source = policy.allow_source(source);
        let mut session = WinrmSession::new(channel, target);
        session.password_source = source != PasswordSource::Ask && !ask;
        session.remember_password = source == PasswordSource::Windows;
        session.cert_store = Some(app_dir().join("winrm_certs"));
        let effects = session.start();
        let Some(p) = self.panes.get_mut(&id) else {
            return;
        };
        p.host = Host::Winrm(Box::new(session));
        self.apply(id, effects);
        self.update_title();
        self.refresh_chrome();
        self.refresh(id);
    }

    /// Gives a pane the font, size, theme and scrollback its host's
    /// profile and the theme rules pick.
    fn apply_look(&mut self, id: PaneId, alias: &str, hostname: &str, tag: Option<&str>) {
        let (font, theme) = self.host_look(alias, hostname, tag);
        let scrollback = self
            .settings
            .profile(alias)
            .and_then(|p| p.scrollback)
            .or(self.settings.scrollback);
        let lock = look::lock_for(&self.settings, alias, hostname, tag);
        if let Some(p) = self.panes.get_mut(&id) {
            p.term.set_settings(&term_settings(scrollback));
            p.hl_host = Some((alias.to_owned(), hostname.to_owned()));
            p.lock = lock;
        }
        self.apply_highlight(id, true);
        self.set_theme(id, theme.clone());
        self.set_font(id, font);
        // A menu preview on this pane now goes back to the host's look,
        // not to the one from before (a reconnect during the preview).
        if let Some(p) = self.look_preview.as_mut().filter(|p| p.pane == id) {
            p.theme = theme;
            p.theme_by = None;
            p.theme_shown = None;
        }
    }

    /// Gives a pane the keyword highlighting and stop patterns its host's
    /// rules pick. With `report`, when a host connects, rules that do not
    /// compile are named in the pane.
    fn apply_highlight(&mut self, id: PaneId, report: bool) {
        let Some(p) = self.panes.get(&id) else {
            return;
        };
        let host = p.hl_host.as_ref().map(|(a, h)| (a.as_str(), h.as_str()));
        let got = highlight::for_host(&self.settings, host);
        if let Some(p) = self.panes.get_mut(&id) {
            p.term.set_highlighter(got.highlighter);
            p.term.set_stop_rules(got.stops);
        }
        for e in got.errors.into_iter().filter(|_| report) {
            let e: String = e.chars().filter(|c| !c.is_control()).collect();
            self.show(id, &format!("\x1b[0;33m{e} Left out.\x1b[0m\r\n"));
        }
    }

    /// Session > Highlight keywords.
    fn toggle_highlight(&mut self) {
        self.settings.highlight = !self.settings.highlight;
        self.save_settings();
        let ids: Vec<PaneId> = self.panes.keys().copied().collect();
        for id in ids {
            self.apply_highlight(id, false);
        }
        self.update_menu_checks();
        self.request_full_redraw();
    }

    /// Connects again to the pane's host, or asks for one.
    fn reconnect(&mut self, id: PaneId) {
        let target = match self.panes.get(&id).map(|p| &p.host) {
            Some(Host::Ssh(s)) => Some(s.target.clone()),
            Some(Host::Local { .. }) => {
                self.start_shell(id);
                return;
            }
            Some(Host::Serial {
                target, session, ..
            }) => {
                let (target, session) = (target.clone(), session.clone());
                self.open_serial(id, target, session.as_deref());
                return;
            }
            Some(Host::Telnet(s)) => {
                let target = s.target.clone();
                self.connect_telnet(id, target);
                return;
            }
            Some(Host::Winrm(s)) => {
                let (mut target, ask) = (s.target.clone(), s.source_refused());
                // A saved connection's credential may name another user now.
                // Start again from the connection's own user, so a credential
                // removed or replaced since leaves no user of its own behind.
                if target.saved {
                    let alias = target.alias.clone();
                    let saved = load_saved()
                        .into_iter()
                        .find(|h| h.alias.eq_ignore_ascii_case(&alias));
                    let own = WinrmTarget::resolve(
                        &alias,
                        &ssh_env(),
                        None,
                        target.https,
                        saved.as_ref(),
                    )
                    .and_then(|t| t.user);
                    let user = self
                        .settings
                        .credential_of(&alias)
                        .and_then(|c| c.user.clone());
                    target = target.with_login(own.as_deref(), user.as_deref());
                }
                self.connect_winrm_with(id, target, ask);
                return;
            }
            _ => None,
        };
        if let Some(mut target) = target {
            // A credential changed since counts.
            let env = ssh_env();
            if let Err(why) = target.refresh_login(&env) {
                self.show(id, &login_refused(&why));
                return;
            }
            self.connect_to(id, target, &env);
        }
    }

    /// SSH pane `id`'s connection dropped, or a reconnect did not get
    /// through: wait, then try again, or give up after a while.
    fn schedule_reconnect(&mut self, id: PaneId) {
        let now = Instant::now();
        let retry = self.retries.entry(id).or_insert_with(|| Retry::new(now));
        let text = match retry.schedule(now) {
            Next::In(wait) => reconnect::waiting_text(wait, retry.attempts()),
            Next::GiveUp => {
                let text = reconnect::gave_up_text(retry.down_for(now));
                self.retries.remove(&id);
                text
            }
        };
        self.show(id, &text);
        self.arm_reconnect_timer();
        self.refresh_chrome();
    }

    /// Starts SSH pane `id`'s next reconnect attempt now, keeping its log
    /// file open across it.
    fn retry_now(&mut self, id: PaneId) {
        let Some(mut retry) = self.retries.remove(&id) else {
            return;
        };
        retry.begin();
        let log = self.panes.get_mut(&id).and_then(|p| p.log.writer.take());
        self.reconnect(id);
        let Some(p) = self.panes.get_mut(&id) else {
            return;
        };
        if p.log.writer.is_none() {
            p.log.writer = log;
        }
        match &mut p.host {
            Host::Ssh(s) => {
                s.set_retrying();
                self.retries.insert(id, retry);
            }
            _ => self.stop_log(id),
        }
        self.arm_reconnect_timer();
        self.refresh_chrome();
        self.refresh(id);
    }

    /// The user stopped pane `id` reconnecting (Esc, or Disconnect).
    fn stop_reconnecting(&mut self, id: PaneId) {
        if self.retries.remove(&id).is_none() {
            return;
        }
        let effects = match self.panes.get_mut(&id).map(|p| &mut p.host) {
            Some(Host::Ssh(s)) if s.state() == State::Connecting => s.close(),
            _ => Vec::new(),
        };
        self.apply(id, effects);
        self.scripts.remove(&id);
        self.stop_log(id);
        self.restore_log_setting(id);
        self.show(
            id,
            "\r\n\x1b[0;90m[Stopped reconnecting. Press Enter to reconnect.]\x1b[0m\r\n",
        );
        self.arm_reconnect_timer();
        self.refresh_chrome();
        self.refresh(id);
    }

    /// Ticks while a pane waits to reconnect.
    fn arm_reconnect_timer(&mut self) {
        let waiting = self.retries.values().any(Retry::waiting);
        // SAFETY: our window; replaces any earlier timer with this id.
        unsafe {
            if waiting {
                SetTimer(Some(self.hwnd), TIMER_RECONNECT, RECONNECT_TICK_MS, None);
            } else {
                let _ = KillTimer(Some(self.hwnd), TIMER_RECONNECT);
            }
        }
    }

    /// Starts the reconnects that are due. Tabs that shared a connection
    /// go one at a time: the first logs in again and the others then open
    /// their shells on its new connection.
    fn on_reconnect_timer(&mut self) {
        let now = Instant::now();
        let mut due: Vec<PaneId> = self
            .retries
            .iter()
            .filter(|(_, r)| r.is_due(now))
            .map(|(id, _)| *id)
            .collect();
        due.sort_unstable();
        for id in due {
            let Some(Host::Ssh(s)) = self.panes.get(&id).map(|p| &p.host) else {
                self.retries.remove(&id);
                continue;
            };
            let busy = self.panes.values().any(|o| {
                o.id != id
                    && matches!(&o.host, Host::Ssh(t)
                        if t.state() == State::Connecting && t.target.same_login(&s.target))
            });
            if !busy {
                self.retry_now(id);
            }
        }
        self.arm_reconnect_timer();
    }

    /// Turns automatic reconnect on or off, for the open sessions too
    /// (a host's profile can still say otherwise).
    fn toggle_auto_reconnect(&mut self) {
        self.settings.auto_reconnect = !self.settings.auto_reconnect;
        self.save_settings();
        let global = self.settings.auto_reconnect;
        for p in self.panes.values_mut() {
            if let Host::Ssh(s) = &mut p.host {
                s.auto_reconnect = self
                    .settings
                    .profile(&s.target.alias)
                    .and_then(|p| p.auto_reconnect)
                    .unwrap_or(global);
            }
        }
        self.update_menu_checks();
    }

    /// A forwarded agent's request from the worker of `connection`. Only
    /// the connection's own login channel speaks for it, and only while a
    /// session with `ForwardAgent` is logged in on it.
    fn on_agent_request(&mut self, connection: ChannelId, msg: Message) {
        let peer = (msg.channel() == Some(connection))
            .then(|| {
                self.panes.values().find_map(|p| match &p.host {
                    Host::Ssh(s)
                        if s.connection == connection
                            && s.worker_for(Some(s.channel)) == Some(connection)
                            && s.state() == State::Connected =>
                    {
                        Some(crate::agent_fwd::Peer {
                            label: s.target.label(),
                            forward: s.target.forward_agent,
                            agent: s.target.agent.clone(),
                        })
                    }
                    _ => None,
                })
            })
            .flatten();
        let outs = self.agent_fwd.on_request(connection, msg, peer);
        self.agent_out(outs);
    }

    /// Carries out what agent forwarding decided.
    fn agent_out(&mut self, outs: Vec<crate::agent_fwd::Out>) {
        use crate::agent_fwd::Out;
        for out in outs {
            match out {
                Out::Send { connection, msg } => {
                    if let Some(w) = self.workers.get(&connection) {
                        w.link.send(msg);
                    }
                }
                Out::Broker { what, job } => {
                    if let Some(b) = &self.broker {
                        self.broker_jobs.push_back(BrokerFor::Agent(what));
                        b.submit(job);
                    }
                }
                Out::Ask => self.queued.push(Command::AskAgentSign),
            }
        }
    }

    /// The user's answer to the agent question.
    fn agent_answered(&mut self, answer: crate::agent_fwd::Answer) {
        let outs = self.agent_fwd.answer(answer);
        self.agent_out(outs);
    }

    /// Carries out what a pane's SSH session decided.
    fn apply(&mut self, id: PaneId, effects: Vec<Effect>) {
        // A run's row that ended: the next host may start.
        let mut pump = false;
        for effect in effects {
            if matches!(effect, Effect::Connected)
                && let Some(p) = self.panes.get_mut(&id)
            {
                p.escapes.reset();
            }
            match effect {
                Effect::Send(msg) => {
                    // Only to the worker of the login the channel is on.
                    let connection = match self.panes.get(&id).map(|p| &p.host) {
                        Some(Host::Ssh(s)) => s.worker_for(msg.channel()),
                        Some(Host::Telnet(s)) => Some(s.connection()),
                        Some(Host::Winrm(s)) => Some(s.connection()),
                        _ => None,
                    };
                    if let Some(w) = connection.and_then(|c| self.workers.get(&c)) {
                        w.link.send(msg);
                    }
                }
                Effect::Tunnel { from, to, channel } => {
                    if let (Some(a), Some(b)) = (self.workers.get(&from), self.workers.get(&to)) {
                        a.link.relay_with(&b.link, channel);
                    }
                }
                Effect::ProxyCommand {
                    connection,
                    tunnel,
                    command,
                } => {
                    // The worker's first bytes wait for the command, which
                    // may start only once the user allowed it.
                    let (sink, input) = crate::proxycmd::input();
                    if let Some(w) = self.workers.get(&connection) {
                        w.link.relays().insert(tunnel, sink);
                    }
                    if proxy_approved(&command.line) {
                        self.run_proxy(id, connection, tunnel, &command, input);
                    } else {
                        self.queued.push(Command::ApproveProxy {
                            pane: id,
                            connection,
                            tunnel,
                            command,
                            input,
                        });
                    }
                }
                Effect::Show(text) => self.show(id, &text),
                Effect::Echo(bytes) => {
                    if let Some(p) = self.panes.get_mut(&id) {
                        p.term.feed(&bytes);
                    }
                    // Local echo of the user's typing: logged, but not
                    // work for the quiet watch.
                    self.log_bytes(id, &bytes, false);
                }
                Effect::Output(bytes)
                    if matches!(self.panes.get(&id).map(|p| &p.host), Some(Host::Winrm(_))) =>
                {
                    // No tmux on the far side of WinRM: straight to the
                    // terminal, never through tmux's control-mode parser.
                    if let Some(p) = self.panes.get_mut(&id) {
                        p.term.feed(&bytes);
                    }
                    self.log(id, &bytes);
                    self.watch_output(id, &bytes);
                    self.script_output(id, &bytes);
                }
                Effect::Output(bytes) => {
                    self.host_output(id, &bytes);
                    self.script_output(id, &bytes);
                }
                Effect::Broker(job) => {
                    let channel = match self.panes.get(&id).map(|p| &p.host) {
                        Some(Host::Ssh(s)) => s.channel,
                        _ => 0,
                    };
                    if let Some(b) = &self.broker {
                        // Kerberos and WinRM's SSPI answer out of order,
                        // by login.
                        if !matches!(
                            job,
                            ferossh_auth::Job::Gssapi(_)
                                | ferossh_auth::Job::Sspi(_)
                                | ferossh_auth::Job::SspiEnd(_)
                        ) {
                            self.broker_jobs.push_back(BrokerFor::Login(channel));
                        }
                        b.submit(job);
                    }
                }
                Effect::FetchPassword => self.fetch_password(id),
                Effect::StorePassword {
                    user,
                    host,
                    port,
                    password,
                } => self.store_password(id, (&user, &host, port), &password),
                Effect::StoreProxyPassword { proxy, password } => {
                    let Some(user) = proxy.user.as_deref() else {
                        continue;
                    };
                    if self.panes.get(&id).is_some_and(|p| {
                        let r = p.policy.tightened(&p.route_policy);
                        r.no_saved_password || r.keys_only
                    }) {
                        continue;
                    }
                    let Some(password) = password.0.first() else {
                        continue;
                    };
                    let target = credman::proxy_target(user, &proxy.host, proxy.port);
                    let note = match credman::write(&target, user, password) {
                        Ok(()) => {
                            "Saved the proxy password in the Windows Credential Manager.".to_owned()
                        }
                        Err(e) => e,
                    };
                    self.show(id, &format!("\x1b[0;90m{note}\x1b[0m\r\n"));
                }
                Effect::ForgetProxyPassword { proxy } => {
                    if let Some(user) = proxy.user.as_deref()
                        && let Err(e) =
                            credman::delete(&credman::proxy_target(user, &proxy.host, proxy.port))
                    {
                        self.show(id, &format!("\x1b[0;90m{e}\x1b[0m\r\n"));
                    }
                }
                Effect::Connected if self.required_log_failed(id) => {
                    // A security rule wants this session logged and the log
                    // would not open: nothing starts on it (no script,
                    // forwards or tmux), and it is disconnected next, which
                    // redraws the chrome (no stats asked for meanwhile).
                    self.retries.remove(&id);
                }
                Effect::Connected
                    if self.run_login.contains(&id) || self.run_hidden.contains(&id) =>
                {
                    // Only the login script and the snippet run: no
                    // forwards, tmux or desktops for a run's sessions.
                    self.inventory_login(id);
                    self.retries.remove(&id);
                    self.start_log(id);
                    if self.run_login.contains(&id) {
                        let alias = match self.panes.get(&id).map(|p| &p.host) {
                            Some(Host::Ssh(s)) => s.target.alias.clone(),
                            Some(Host::Telnet(s)) => s.target.alias.clone(),
                            _ => String::new(),
                        };
                        if !self.start_script(id, &alias, false) {
                            self.begin_run_snippet(id);
                        }
                    }
                }
                Effect::Connected
                    if matches!(self.panes.get(&id).map(|p| &p.host), Some(Host::Winrm(_))) =>
                {
                    // Nothing of SSH (SFTP, forwards, tmux, desktops) and
                    // no login script: the line goes whole on Enter.
                    self.start_log(id);
                    self.refresh_chrome();
                    self.workspace_start(id, false);
                }
                Effect::Connected if self.unencrypted(id) => {
                    // Nothing of SSH (SFTP, forwards, tmux, desktops)
                    // runs over Telnet; a login script does.
                    self.start_log(id);
                    self.refresh_chrome();
                    let alias = match self.panes.get(&id).map(|p| &p.host) {
                        Some(Host::Telnet(s)) => s.target.alias.clone(),
                        _ => String::new(),
                    };
                    if !self.start_script(id, &alias, false) {
                        self.workspace_start(id, false);
                    }
                }
                Effect::Connected if self.tunnel_only(id) => {
                    // No shell: no login script, tmux or start folder.
                    // The tab holds the forwards open.
                    self.inventory_login(id);
                    self.retries.remove(&id);
                    self.arm_reconnect_timer();
                    self.start_log(id);
                    let none = matches!(
                        self.panes.get(&id).map(|p| &p.host),
                        Some(Host::Ssh(s)) if s.target.forwards.is_empty() && !s.target.forward_x11
                    );
                    self.show(
                        id,
                        if none {
                            "\x1b[0;90mTunnels only: no shell, and no port forwards yet. \
                             Add them in Port forwards (Ctrl+Shift+P); closing the tab \
                             logs out.\x1b[0m\r\n"
                        } else {
                            "\x1b[0;90mTunnels only: no shell. The forwards stay up while \
                             this tab is open; closing it logs out.\x1b[0m\r\n"
                        },
                    );
                    self.start_forwards(id);
                    if none && self.focused_id() == id {
                        self.show_side(SideView::Forwards, true);
                    }
                    // A desktop through this host opens now, and panes
                    // waiting for this login go on (to log in on their
                    // own: a tunnel-only connection is never shared).
                    // A transfer queue opened on this host carries on.
                    self.sftp_connected(id);
                    self.desktop_after_login(id);
                    self.release_workspace_panes(id, true);
                    self.refresh_chrome();
                }
                Effect::Connected if self.sftp_only(id) => {
                    // No shell: no login script, tmux or start folder.
                    // File transfer opens on the host instead.
                    self.inventory_login(id);
                    self.retries.remove(&id);
                    self.arm_reconnect_timer();
                    self.start_log(id);
                    self.show(
                        id,
                        "\x1b[0;90mFile transfer only: no shell. File transfer \
                         (Ctrl+Shift+E) shows this host; closing the tab logs out.\x1b[0m\r\n",
                    );
                    self.start_forwards(id);
                    if self.focused_id() == id {
                        self.show_side(SideView::Files, true);
                    } else {
                        self.ensure_sftp(id);
                    }
                    self.refresh_chrome();
                }
                Effect::Connected => {
                    self.inventory_login(id);
                    self.retries.remove(&id);
                    self.arm_reconnect_timer();
                    self.start_log(id);
                    self.sftp_connected(id);
                    self.start_forwards(id);
                    self.refresh_chrome();
                    // A login script runs first; tmux attaches after it.
                    let alias = match self.panes.get(&id).map(|p| &p.host) {
                        Some(Host::Ssh(s)) => s.target.alias.clone(),
                        _ => String::new(),
                    };
                    // A RemoteCommand runs instead of a shell: nothing
                    // is typed into it.
                    let command = matches!(
                        self.panes.get(&id).map(|p| &p.host),
                        Some(Host::Ssh(s)) if s.target.command.is_some()
                    );
                    if !command && !self.start_script(id, &alias, true) {
                        self.cd_after_login(id);
                        if self.tmux_after_login(id) {
                            self.workspace_drop(id);
                        } else {
                            self.workspace_start(id, false);
                        }
                    }
                    self.desktop_after_login(id);
                    self.release_workspace_panes(id, true);
                }
                Effect::Reconnect => {
                    self.workspace_shell_gone(id);
                    self.schedule_reconnect(id);
                }
                Effect::Ended => {
                    self.workspace_shell_gone(id);
                    self.release_workspace_panes(id, false);
                    if !self.run_login.contains(&id)
                        && let Some(row) =
                            self.snippets_view.report_mut().and_then(|r| r.row_mut(id))
                        && !row.state.over()
                    {
                        row.state = RowState::Failed("the connection ended".into());
                        pump = true;
                    }
                    self.proxy_errors(id);
                    self.scripts.remove(&id);
                    self.zmodem.remove(&id);
                    self.pending_desktops.remove(&id);
                    self.forget_preview_scans(id);
                    self.tmux_lost(id);
                    // A pane that reconnects keeps writing the same log.
                    if !self.retries.get(&id).is_some_and(Retry::waiting) {
                        self.retries.remove(&id);
                        self.stop_log(id);
                        // The user's own logging setting comes back. The
                        // rest of the rules stay until the pane connects or
                        // closes, so output still in this batch (an OSC 52
                        // clipboard request) is judged by them.
                        self.restore_log_setting(id);
                    }
                    self.prune_sftp();
                    self.prune_forwards();
                    let live: HashSet<ChannelId> = self
                        .panes
                        .values()
                        .filter_map(|p| match &p.host {
                            Host::Ssh(s) if s.state() == State::Connected => Some(s.connection),
                            _ => None,
                        })
                        .collect();
                    self.agent_fwd.retain(|c| live.contains(&c));
                    self.refresh_chrome();
                }
            }
        }
        if self.run_login.contains(&id) {
            self.check_run_login(id);
        }
        if self.launch_hidden.contains(&id) {
            self.check_launch(id);
        }
        // A hidden pane whose login asks for something shows again.
        if self.ws.is_hidden(id)
            && matches!(
                self.panes.get(&id).map(|p| &p.host),
                Some(Host::Ssh(s)) if s.prompt_asks().is_some()
            )
        {
            self.show_hidden(id);
        }
        // A WinRM session closed with its shell open: keep sealing for
        // the worker's goodbye after the pane moves on.
        if let Some(Host::Winrm(s)) = self.panes.get_mut(&id).map(|p| &mut p.host)
            && let Some(closer) = s.take_closer()
        {
            self.winrm_closing.insert(closer.channel, closer);
        }
        if pump {
            self.pump_run();
        }
    }

    /// What a closed WinRM session's closer asks for: only messages to
    /// its own worker and SSPI jobs.
    fn apply_winrm_closing(&mut self, channel: ChannelId, effects: Vec<Effect>) {
        for effect in effects {
            match effect {
                Effect::Send(msg) => {
                    if let Some(w) = self.workers.get(&channel) {
                        w.link.send(msg);
                    }
                }
                Effect::Broker(job) => {
                    if let Some(b) = &self.broker {
                        b.submit(job);
                    }
                }
                _ => {}
            }
        }
    }

    fn on_winrm_closing(&mut self, channel: ChannelId, msg: Message) {
        let Some(closer) = self.winrm_closing.get_mut(&channel) else {
            return;
        };
        let (effects, done) = closer.on_worker(msg);
        if done {
            self.winrm_closing.remove(&channel);
        }
        self.apply_winrm_closing(channel, effects);
        if done {
            self.prune_workers();
        }
    }

    /// What the worker said about a ZMODEM transfer in pane `id`, whose
    /// shell is `channel`.
    fn on_zmodem(&mut self, id: PaneId, channel: ChannelId, msg: Message) {
        if let Message::ZmodemStart { upload, .. } = msg {
            let effects = if !self.settings.zmodem {
                vec![zmodem::refuse(channel, true)]
            } else if self.zmodem.contains_key(&id) || self.scripts.contains_key(&id) {
                // One at a time; and a login script owns the pane's
                // output until it ends.
                vec![zmodem::refuse(channel, false)]
            } else if upload {
                self.queued.push(Command::PickZmodem { pane: id, channel });
                Vec::new()
            } else {
                // Files only come in once the user said yes: any output
                // (a MOTD, a `cat` of someone's file) can start a send.
                let host = self
                    .panes
                    .get(&id)
                    .map(Pane::host_label)
                    .unwrap_or_default();
                self.queued.push(Command::ConfirmZmodemReceive {
                    pane: id,
                    channel,
                    host,
                    folder: self.download_dir(),
                });
                Vec::new()
            };
            self.apply(id, effects);
            return;
        }
        let Some(transfer) = self.zmodem.get_mut(&id) else {
            return;
        };
        let (effects, over) = transfer.on_worker(msg);
        if over {
            self.zmodem.remove(&id);
        }
        self.apply(id, effects);
    }

    /// The user picked `paths` (or nothing) for the server's `rz` in pane
    /// `pane`.
    /// The user's answer to the server's `sz` in pane `pane`: receive into
    /// `folder`, or decline.
    fn zmodem_receive(&mut self, pane: PaneId, channel: ChannelId, folder: Option<PathBuf>) {
        let alive = match self.panes.get(&pane).map(|p| &p.host) {
            Some(Host::Ssh(s)) => s.channel == channel,
            Some(Host::Telnet(s)) => s.channel == channel,
            _ => false,
        };
        if !alive || self.zmodem.contains_key(&pane) {
            return;
        }
        let effects = match folder {
            Some(folder) => {
                let (transfer, effects) = zmodem::Transfer::receive(channel, folder);
                self.zmodem.insert(pane, transfer);
                effects
            }
            None => vec![zmodem::refuse(channel, false)],
        };
        self.apply(pane, effects);
        self.refresh_visible();
    }

    fn zmodem_send(&mut self, pane: PaneId, channel: ChannelId, paths: &[PathBuf]) {
        let alive = match self.panes.get(&pane).map(|p| &p.host) {
            Some(Host::Ssh(s)) => s.channel == channel,
            Some(Host::Telnet(s)) => s.channel == channel,
            _ => false,
        };
        if !alive {
            return;
        }
        let (transfer, effects) = zmodem::Transfer::send(channel, paths);
        if let Some(t) = transfer {
            self.zmodem.insert(pane, t);
        }
        self.apply(pane, effects);
        self.refresh_visible();
    }

    /// Starts `command` for the login of connection `connection` (in pane
    /// `id`), whose SSH connection runs over stream `tunnel`; `input` is
    /// what the worker sends on it.
    fn run_proxy(
        &mut self,
        id: PaneId,
        connection: ChannelId,
        tunnel: ChannelId,
        command: &ProxyCommand,
        input: std::sync::mpsc::Receiver<Message>,
    ) {
        let Some(w) = self.workers.get(&connection) else {
            return;
        };
        match ProxyRun::spawn(
            &command.program,
            &command.args,
            tunnel,
            input,
            w.link.sender(),
        ) {
            Ok(run) => {
                self.proxies.insert(connection, run);
            }
            Err(e) => {
                let why = format!(
                    "The ProxyCommand {} did not start ({e}). Is it installed and on PATH?",
                    command.program
                );
                self.proxy_refused(id, connection, tunnel, &why);
            }
        }
    }

    /// No `ProxyCommand` for stream `tunnel`: says why, and closes the
    /// stream, which ends the login waiting on it.
    fn proxy_refused(&mut self, id: PaneId, connection: ChannelId, tunnel: ChannelId, why: &str) {
        self.show(
            id,
            &format!("\x1b[0;31m{}\x1b[0m\r\n", crate::ssh::sanitize(why)),
        );
        if let Some(w) = self.workers.get(&connection) {
            w.link.relays().remove(tunnel);
            w.link.send(Message::Close { channel: tunnel });
        }
        self.refresh(id);
    }

    /// What the `ProxyCommand` of pane `id`'s connection printed on its
    /// error output, once the login ended.
    fn proxy_errors(&mut self, id: PaneId) {
        let Some(Host::Ssh(s)) = self.panes.get(&id).map(|p| &p.host) else {
            return;
        };
        let connections: Vec<ChannelId> = std::iter::once(s.connection)
            .chain(s.hop_connections())
            .collect();
        let said: Vec<String> = connections
            .iter()
            .filter_map(|c| self.proxies.get(c))
            .map(ProxyRun::errors)
            .filter(|e| !e.is_empty())
            .collect();
        for text in said {
            self.show(
                id,
                &format!("\x1b[0;90mThe ProxyCommand said: {text}\x1b[0m\r\n"),
            );
        }
    }

    /// The login of pane `id` that a password source answers: an SSH
    /// pane's (a jump host's, or its host's) or a WinRM pane's.
    fn password_login(&self, id: PaneId) -> Option<PasswordLogin> {
        match self.panes.get(&id).map(|p| &p.host)? {
            Host::Ssh(s) => {
                let t = s.login_target();
                Some(PasswordLogin {
                    alias: t.alias.clone(),
                    user: t.user.clone(),
                    hostname: t.hostname.clone(),
                    port: t.port,
                    channel: s.channel,
                    ssh: true,
                    tag: t.tag.clone(),
                })
            }
            Host::Winrm(s) => Some(PasswordLogin {
                alias: s.target.alias.clone(),
                user: s.target.user.clone()?,
                hostname: s.target.hostname.clone(),
                port: s.target.port,
                channel: s.channel,
                ssh: false,
                tag: s.target.tag.clone(),
            }),
            _ => None,
        }
    }

    /// Gets the login password of pane `id` (SSH or WinRM) from its
    /// password source.
    fn fetch_password(&mut self, id: PaneId) {
        let Some(t) = self.password_login(id) else {
            return;
        };
        let source = if t.ssh {
            self.login_source(id, &t.alias)
        } else {
            let source = self
                .settings
                .profile(&t.alias)
                .filter(|p| p.kind == SessionKind::WinRm)
                .map(|_| self.settings.password_source(&t.alias))
                .unwrap_or_default();
            if source == PasswordSource::Ask && self.workspace_login(id) {
                PasswordSource::Windows
            } else {
                source
            }
        };
        // The rules of the host logging in now (a jump host's own), as
        // the session started with them.
        let rules = self.policy_of(&t.alias, Some(&t.hostname), t.tag.as_deref());
        let rules = if t.ssh {
            rules
        } else {
            rules.without_keys_only()
        };
        if rules.keys_only {
            self.password_result(id, Err(String::new()), "");
            return;
        }
        let source = rules.allow_source(source);
        if t.ssh
            && self.run_login.contains(&id)
            && let Some(password) = self.run_password()
        {
            // A run's password answers the logins with none saved; one
            // in the Credential Manager comes first.
            let saved = match &source {
                PasswordSource::Windows => {
                    credman::read(&credman::target(&t.user, &t.hostname, t.port))
                        .ok()
                        .flatten()
                }
                _ => None,
            };
            if !matches!(source, PasswordSource::Command(_)) {
                match saved {
                    Some(saved) => {
                        self.password_result(id, Ok(saved), "the Windows Credential Manager");
                    }
                    None => self.password_result(id, Ok(password), "the run"),
                }
                return;
            }
        }
        match source {
            PasswordSource::Ask => {
                self.password_result(id, Err(String::new()), "");
            }
            PasswordSource::Windows => {
                let result = match credman::read(&credman::target(&t.user, &t.hostname, t.port)) {
                    Ok(Some(password)) => Ok(password),
                    Ok(None) => Err(
                        "No password saved in the Windows Credential Manager yet; type it \
                         and FeroSSH saves it once the login works."
                            .into(),
                    ),
                    Err(e) => Err(e),
                };
                self.password_result(id, result, "the Windows Credential Manager");
            }
            PasswordSource::Command(line) => {
                if command_approved(&line) {
                    self.run_password_command(id, &line);
                } else {
                    self.queued
                        .push(Command::ConfirmPasswordTool { pane: id, line });
                }
            }
        }
    }

    /// Runs the password manager command `line` for pane `id`'s login on
    /// a thread of its own; [`Self::poll_passwords`] takes the answer.
    fn run_password_command(&mut self, id: PaneId, line: &str) {
        let Some(t) = self.password_login(id) else {
            return;
        };
        let tokens = pw_source::Tokens {
            name: &t.alias,
            host: &t.hostname,
            user: &t.user,
            port: t.port,
        };
        let Some((program, args)) = pw_source::command(line, &tokens) else {
            self.password_result(id, Err("The password command is empty.".into()), "");
            return;
        };
        let channel = t.channel;
        let name = Path::new(&program)
            .file_stem()
            .map_or_else(|| program.clone(), |n| n.to_string_lossy().into_owned());
        self.show(
            id,
            &format!(
                "\x1b[0;90mGetting the password from {}...\x1b[0m\r\n",
                crate::ssh::sanitize(&name)
            ),
        );
        self.refresh(id);
        let answers = self.passwords.clone();
        let notify = self.notifier();
        std::thread::spawn(move || {
            let result = pwcommand::run(&program, &args, pwcommand::TIMEOUT);
            if let Ok(mut a) = answers.lock() {
                a.push((id, channel, name, result));
            }
            notify();
        });
    }

    /// Hands finished password commands to their panes, if those still
    /// wait for them.
    fn poll_passwords(&mut self) {
        let done = match self.passwords.lock() {
            Ok(mut a) => std::mem::take(&mut *a),
            Err(_) => return,
        };
        for (id, channel, name, result) in done {
            let waiting = match self.panes.get(&id).map(|p| &p.host) {
                Some(Host::Ssh(s)) => s.channel == channel && s.fetching_password(),
                Some(Host::Winrm(s)) => s.channel == channel && s.fetching_password(),
                _ => false,
            };
            if waiting {
                self.password_result(id, result, &name);
            }
        }
    }

    /// Gives pane `id`'s session the password its source found, or why
    /// there is none (it then asks at the prompt).
    fn password_result(
        &mut self,
        id: PaneId,
        result: std::result::Result<Zeroizing<String>, String>,
        from: &str,
    ) {
        let effects = match self.panes.get_mut(&id).map(|p| &mut p.host) {
            Some(Host::Ssh(s)) => s.password_fetched(result, from),
            Some(Host::Winrm(s)) => s.password_fetched(result, from),
            _ => return,
        };
        self.apply(id, effects);
        self.refresh(id);
    }

    /// Keeps the password that just worked for `user` at `host`:`port`
    /// (pane `id`'s host, or a jump host on the way) in the Windows
    /// Credential Manager.
    fn store_password(
        &mut self,
        id: PaneId,
        (user, host, port): (&str, &str, u16),
        password: &ferossh_ipc::Secrets,
    ) {
        let Some(password) = password.0.first() else {
            return;
        };
        let note = match credman::write(&credman::target(user, host, port), user, password) {
            Ok(()) => "Saved the password in the Windows Credential Manager.".to_owned(),
            Err(e) => e,
        };
        self.show(id, &format!("\x1b[0;90m{note}\x1b[0m\r\n"));
    }

    /// Starts the login script of session `alias` in pane `id`, if its
    /// profile has one; `tmux` attaches tmux after it as the profile asks.
    /// Returns whether a script started.
    fn start_script(&mut self, id: PaneId, alias: &str, tmux: bool) -> bool {
        let steps = self
            .settings
            .profile(alias)
            .map(|p| p.login_script.clone())
            .unwrap_or_default();
        if steps.is_empty() {
            return false;
        }
        self.script_runs += 1;
        let mut runner = Runner::new(steps);
        let actions = runner.start(Instant::now());
        self.scripts.insert(
            id,
            ScriptRun {
                runner,
                run: self.script_runs,
                tmux,
                report: false,
                login: true,
            },
        );
        self.script_actions(id, actions);
        true
    }

    /// Session > Scripts > Run login script again, in the focused pane.
    fn rerun_script(&mut self, id: PaneId) -> Option<Command> {
        let alias = match self.panes.get(&id).map(|p| &p.host) {
            Some(Host::Ssh(s)) if s.state() == State::Connected => Some(s.target.alias.clone()),
            Some(Host::Serial {
                port: Some(_),
                target,
                session,
            }) => Some(session.clone().unwrap_or_else(|| target.port.clone())),
            Some(Host::Telnet(s)) if s.state() == State::Connected => Some(s.target.alias.clone()),
            _ => None,
        };
        let Some(alias) = alias else {
            return Some(Command::Notice(
                "The login script runs in a pane logged in to an SSH or Telnet host or open \
                 on a serial port."
                    .into(),
            ));
        };
        self.scripts.remove(&id);
        if self.start_script(id, &alias, false) {
            self.refresh(id);
            None
        } else {
            Some(Command::Notice(format!(
                "{alias} has no login script. Add one under Extras in its session (F2 in \
                 the connection manager)."
            )))
        }
    }

    /// Hands pane `id`'s login script to `f` and carries out what it
    /// decided.
    fn with_script(
        &mut self,
        id: PaneId,
        f: impl FnOnce(&mut Runner) -> Vec<login_script::Action>,
    ) {
        let Some(run) = self.scripts.get_mut(&id) else {
            return;
        };
        let actions = f(&mut run.runner);
        self.script_actions(id, actions);
        // A hidden pane whose login script asks for a secret shows again.
        if self.ws.is_hidden(id)
            && self
                .scripts
                .get(&id)
                .is_some_and(|run| run.runner.prompting())
        {
            self.show_hidden(id);
        }
    }

    /// What pane `id`'s host printed, for its login script.
    fn script_output(&mut self, id: PaneId, bytes: &[u8]) {
        if self.scripts.contains_key(&id) {
            self.with_script(id, |r| r.feed(bytes, Instant::now()));
        }
    }

    /// Carries out what pane `id`'s login script decided.
    fn script_actions(&mut self, id: PaneId, actions: Vec<login_script::Action>) {
        if actions.is_empty() {
            return;
        }
        for action in actions {
            match action {
                login_script::Action::Send(bytes) => self.send(id, bytes.to_vec()),
                login_script::Action::Show(text) => self.show(id, &text),
                login_script::Action::Fetch(need) => self.fetch_secret(id, need),
                login_script::Action::Save(name, secret) => self.save_secret(id, &name, &secret),
                login_script::Action::Captured(value) => {
                    if let Some(row) = self.snippets_view.report_mut().and_then(|r| r.row_mut(id)) {
                        row.values.push(value);
                    }
                }
                login_script::Action::Done => {
                    let mut next = self.snippet_next.remove(&id);
                    if let Some(run) = self.scripts.remove(&id) {
                        if next.as_ref().is_some_and(|n| n.0 != run.run)
                            || matches!(
                                run.runner.outcome(),
                                Some(Outcome::Failed(_) | Outcome::Stopped)
                            )
                        {
                            next = None;
                        }
                        // The part after a move types what was captured
                        // before it, up to its own next capture, whose
                        // value its own runner fills in.
                        next = next.map(|(r, name, rest)| {
                            let mut captured = false;
                            let rest = rest
                                .into_iter()
                                .map(|s| {
                                    captured |= matches!(s, Step::Capture(_));
                                    if captured { s } else { run.runner.fill(s) }
                                })
                                .collect();
                            (r, name, rest)
                        });
                        if run.report
                            && let Some(row) =
                                self.snippets_view.report_mut().and_then(|r| r.row_mut(id))
                        {
                            row.state = match run.runner.outcome() {
                                Some(Outcome::Failed(why)) => RowState::Failed(why.clone()),
                                Some(Outcome::Stopped) => RowState::Stopped,
                                _ => RowState::Done,
                            };
                        }
                        // A workspace's script and command follow only a
                        // login script that finished.
                        let finished = !matches!(
                            run.runner.outcome(),
                            Some(Outcome::Failed(_) | Outcome::Stopped)
                        );
                        // A workspace's command waited for this script: only
                        // this run's, so one a newer run waits for stays.
                        let after = match self.workspace_after.get(&id) {
                            Some((r, _)) if *r == run.run => {
                                self.workspace_after.remove(&id).map(|(_, line)| line)
                            }
                            _ => None,
                        };
                        if let Some(line) = after
                            && finished
                            && !self.tmux.get(&id).is_some_and(Tmux::active)
                        {
                            self.workspace_type(id, &line);
                        }
                        if run.tmux {
                            self.cd_after_login(id);
                            if self.tmux_after_login(id) || !finished {
                                // tmux took the shell, or the login did
                                // not finish: the workspace's part is over.
                                self.workspace_drop(id);
                            } else {
                                self.workspace_start(id, false);
                            }
                        } else if run.login {
                            // Telnet and serial: no tmux, no start folder.
                            if finished {
                                self.workspace_start(id, false);
                            } else {
                                self.workspace_drop(id);
                            }
                        }
                        if run.report {
                            self.pump_run();
                        } else if self.run_login.contains(&id) {
                            // The login script of a run's host is over.
                            match run.runner.outcome() {
                                Some(Outcome::Failed(why)) => {
                                    self.fail_run_row(id, format!("login script: {why}"));
                                }
                                Some(Outcome::Stopped) => {
                                    self.fail_run_row(id, "the login script stopped".into());
                                }
                                _ => self.begin_run_snippet(id),
                            }
                        }
                    } else {
                        next = None;
                    }
                    if let Some((_, name, rest)) = next {
                        self.snippet_move(id, &name, rest);
                    }
                }
            }
        }
        if let Some(run) = self.scripts.get(&id)
            && run.report
            && let Some(row) = self.snippets_view.report_mut().and_then(|r| r.row_mut(id))
        {
            row.state = RowState::Running(run.runner.waiting_for());
        }
        if self.snippets_view.reporting() {
            self.refresh_chrome();
        }
        self.arm_script_timer();
        self.refresh(id);
    }

    /// Sets the timer for the first login script deadline.
    fn arm_script_timer(&mut self) {
        let next = self
            .scripts
            .values()
            .filter_map(|r| r.runner.deadline())
            .min();
        // SAFETY: our window; replaces any earlier timer with this id.
        unsafe {
            match next {
                Some(at) => {
                    let wait = at.saturating_duration_since(Instant::now());
                    let ms = u32::try_from(wait.as_millis()).unwrap_or(u32::MAX).max(1);
                    SetTimer(Some(self.hwnd), TIMER_SCRIPT, ms, None);
                }
                None => {
                    let _ = KillTimer(Some(self.hwnd), TIMER_SCRIPT);
                }
            }
        }
    }

    fn on_script_timer(&mut self) {
        let now = Instant::now();
        let ids: Vec<PaneId> = self.scripts.keys().copied().collect();
        for id in ids {
            self.with_script(id, |r| r.tick(now));
        }
        self.arm_script_timer();
    }

    /// Finds the secret pane `id`'s login script needs: the login
    /// password from the session's password source, or a named secret
    /// from its password manager command or the Windows Credential
    /// Manager. One that none has is asked for in the pane.
    fn fetch_secret(&mut self, id: PaneId, need: Need) {
        let (alias, is_ssh, login_target) = match self.panes.get(&id).map(|p| &p.host) {
            Some(Host::Ssh(s)) => (
                s.target.alias.clone(),
                true,
                credman::target(&s.target.user, &s.target.hostname, s.target.port),
            ),
            Some(Host::Serial {
                target, session, ..
            }) => (
                session.clone().unwrap_or_else(|| target.port.clone()),
                false,
                String::new(),
            ),
            Some(Host::Telnet(s)) => (s.target.alias.clone(), false, String::new()),
            _ => return,
        };
        let now = Instant::now();
        match need {
            Need::Password => {
                let source = if is_ssh {
                    self.login_source(id, &alias)
                } else {
                    PasswordSource::Ask
                };
                // The connection's rules hold for its scripts too: no
                // saved password read where they forbid it.
                let rules = self.panes.get(&id).map(|p| p.policy).unwrap_or_default();
                let source = rules.allow_source(source);
                let ask = "\r\nLogin password, for the login script: ";
                match source {
                    PasswordSource::Ask => self.with_script(id, |r| r.ask(ask, None)),
                    PasswordSource::Windows => match credman::read(&login_target) {
                        Ok(Some(pw)) => self.with_script(id, |r| r.secret(&pw, now)),
                        Ok(None) => self.with_script(id, |r| r.ask(ask, None)),
                        Err(e) => self.with_script(id, |r| r.secret_failed(&e)),
                    },
                    PasswordSource::Command(line) => self.script_command(id, line, None),
                }
            }
            Need::Secret(name) => {
                let command = self
                    .settings
                    .secrets
                    .iter()
                    .find(|x| x.name.eq_ignore_ascii_case(&name))
                    .map(|x| x.command.clone());
                if let Some(line) = command {
                    self.script_command(id, line, Some(name));
                    return;
                }
                if self
                    .panes
                    .get(&id)
                    .is_some_and(|p| p.policy.no_saved_password)
                {
                    // Typed each time: no Credential Manager read.
                    let text = format!("\r\nSecret {name}, for the login script: ");
                    self.with_script(id, |r| r.ask(&text, None));
                    return;
                }
                match credman::read(&secret_target(&name)) {
                    Ok(Some(secret)) => self.with_script(id, |r| r.secret(&secret, now)),
                    Ok(None) => {
                        let text = format!(
                            "\r\n\x1b[0;90mThe login script needs the secret {name}. FeroSSH \
                             keeps it in the Windows Credential Manager as {}.\x1b[0m\r\n\
                             Secret {name}: ",
                            secret_target(&name)
                        );
                        self.with_script(id, |r| r.ask(&text, Some(name.clone())));
                    }
                    Err(e) => self.with_script(id, |r| r.secret_failed(&e)),
                }
            }
        }
    }

    /// Gets a login script's secret from password manager command `line`,
    /// once the user allowed it; `name` is the secret's (`None` for the
    /// login password).
    fn script_command(&mut self, id: PaneId, line: String, name: Option<String>) {
        if command_approved(&line) {
            self.run_script_command(id, &line, name.as_deref());
        } else {
            self.queued.push(Command::ConfirmSecretTool {
                pane: id,
                line,
                name,
            });
        }
    }

    /// Runs password manager command `line` for pane `id`'s login script
    /// on a thread of its own; [`Self::poll_script_secrets`] takes the
    /// answer. `%n` is the secret's name, or the session's for the login
    /// password.
    fn run_script_command(&mut self, id: PaneId, line: &str, name: Option<&str>) {
        let Some(run) = self.scripts.get(&id).map(|r| r.run) else {
            return;
        };
        let (alias, host, user, port) = match self.panes.get(&id).map(|p| &p.host) {
            Some(Host::Ssh(s)) => (
                s.target.alias.clone(),
                s.target.hostname.clone(),
                s.target.user.clone(),
                s.target.port,
            ),
            Some(Host::Serial {
                target, session, ..
            }) => (
                session.clone().unwrap_or_else(|| target.port.clone()),
                target.port.clone(),
                String::new(),
                0,
            ),
            _ => return,
        };
        let tokens = pw_source::Tokens {
            name: name.unwrap_or(&alias),
            host: &host,
            user: &user,
            port,
        };
        let Some((program, args)) = pw_source::command(line, &tokens) else {
            self.with_script(id, |r| r.secret_failed("the password command is empty."));
            return;
        };
        let what = match name {
            Some(n) => format!("the secret {n}"),
            None => "the password".to_owned(),
        };
        let from = Path::new(&program)
            .file_stem()
            .map_or_else(|| program.clone(), |n| n.to_string_lossy().into_owned());
        self.show(
            id,
            &format!(
                "\x1b[0;90mGetting {what} from {}...\x1b[0m\r\n",
                crate::ssh::sanitize(&from)
            ),
        );
        self.refresh(id);
        let answers = self.script_secrets.clone();
        let notify = self.notifier();
        std::thread::spawn(move || {
            let result = pwcommand::run(&program, &args, pwcommand::TIMEOUT);
            if let Ok(mut a) = answers.lock() {
                a.push((id, run, result));
            }
            notify();
        });
    }

    /// Hands finished password manager commands to the login scripts
    /// still waiting for them.
    fn poll_script_secrets(&mut self) {
        let done = match self.script_secrets.lock() {
            Ok(mut a) => std::mem::take(&mut *a),
            Err(_) => return,
        };
        for (id, run, result) in done {
            if self.scripts.get(&id).is_none_or(|r| r.run != run) {
                continue;
            }
            match result {
                Ok(secret) => self.with_script(id, |r| r.secret(&secret, Instant::now())),
                Err(e) => self.with_script(id, |r| r.secret_failed(&e)),
            }
        }
    }

    /// Keeps a secret typed at a login script's prompt in the Windows
    /// Credential Manager.
    fn save_secret(&mut self, id: PaneId, name: &str, secret: &str) {
        if self
            .panes
            .get(&id)
            .is_some_and(|p| p.policy.no_saved_password)
        {
            return;
        }
        let note = match credman::write(&secret_target(name), name, secret) {
            Ok(()) => format!(
                "Saved the secret {name} in the Windows Credential Manager; remove it \
                 there to type a new one."
            ),
            Err(e) => e,
        };
        self.show(id, &format!("\x1b[0;90m{note}\x1b[0m\r\n"));
    }

    /// Opens the pane's log if logging is on and the pane has a host.
    fn start_log(&mut self, id: PaneId) {
        self.start_log_as(id, None);
    }

    /// [`Self::start_log`]; for a coding agent's pane, `agent` names it in
    /// the file's name and heading.
    fn start_log_as(&mut self, id: PaneId, agent: Option<&str>) {
        let Some(p) = self.panes.get(&id) else {
            return;
        };
        if !p.log.enabled || p.log.writer.is_some() {
            return;
        }
        let label = match &p.host {
            Host::Ssh(s) if s.state() == State::Connected => s.target.label(),
            Host::Telnet(s) if s.state() == State::Connected => s.target.label(),
            Host::Winrm(s) if s.state() == State::Connected => s.target.label(),
            Host::Local { exited: false, .. } => "local".to_owned(),
            Host::Tmux { label, .. } => label.clone(),
            Host::Serial {
                port: Some(_),
                target,
                ..
            } => target.port.clone(),
            _ => return,
        };
        let raw = p.log.raw;
        let dir = log_dir();
        let suffix = agent.map(|a| format!("-{a}")).unwrap_or_default();
        let opened = new_log_file(&label, id, &suffix);
        let what = match agent {
            Some(a) => format!("coding agent {a} on {label}"),
            None => label.clone(),
        };
        let header = format!("FeroSSH log of {what}, started {}", timestamp());
        let stamps = self
            .settings
            .log_timestamps
            .then_some(log_line_time as Clock);
        let writer = opened.and_then(|(f, chain, path, name)| {
            let mut writer = LogWriter::sealed(f, chain, &name, raw, &header)?;
            writer.set_timestamps(stamps);
            Ok((writer, path))
        });
        match writer {
            Ok((writer, path)) => {
                self.show(
                    id,
                    &format!("\x1b[0;90mLogging to {}\x1b[0m\r\n", path.display()),
                );
                if let Some(p) = self.panes.get_mut(&id) {
                    p.log.writer = Some(writer);
                    p.log.path = Some(path);
                    p.log.agent = agent.map(str::to_owned);
                }
            }
            Err(e) => {
                self.show(
                    id,
                    &format!(
                        "\x1b[0;31mCould not open a log file in {}: {e}\x1b[0m\r\n",
                        dir.display()
                    ),
                );
                if let Some(p) = self.panes.get_mut(&id) {
                    p.log.enabled = false;
                    if p.policy.log_session {
                        self.queued.push(Command::LogRequired(id));
                    }
                }
                self.update_menu_checks();
            }
        }
    }

    /// Session > Logs and recordings > Save output: each pane's scrollback and screen, as plain
    /// text, to a log file of its own. Returns what to tell the user.
    fn save_output(&self, panes: &[PaneId]) -> String {
        let mut saved = Vec::new();
        let mut failed = Vec::new();
        for id in panes {
            let Some(p) = self.panes.get(id) else {
                continue;
            };
            if matches!(p.host, Host::Desktop { .. }) {
                continue;
            }
            let lines = p.term.all_text();
            if lines.is_empty() {
                continue;
            }
            match save_text_log(&p.host_label(), *id, &lines) {
                Ok(path) => saved.push(format!("{} ({} lines)", path.display(), lines.len())),
                Err(e) => failed.push(format!("{}: {e}", p.label())),
            }
        }
        let mut text = match saved.len() {
            0 if failed.is_empty() => "There was no output to save.".to_owned(),
            0 => String::new(),
            1 => format!("Saved the output to\n\n{}", saved.join("")),
            n => format!("Saved the output of {n} panes to\n\n{}", saved.join("\n")),
        };
        if !failed.is_empty() {
            if !text.is_empty() {
                text.push_str("\n\n");
            }
            text.push_str(&format!(
                "Could not save to {}:\n\n{}",
                log_dir().display(),
                failed.join("\n")
            ));
        }
        text
    }

    fn stop_log(&mut self, id: PaneId) {
        let Some(p) = self.panes.get_mut(&id) else {
            return;
        };
        let Some(writer) = p.log.writer.take() else {
            return;
        };
        let footer = format!("Log ended {}", timestamp());
        if let (Ok(Some(sealed)), Some(name)) = (
            writer.finish_sealed(&footer),
            p.log.path.as_deref().and_then(Path::file_name),
        ) {
            let name = name.to_string_lossy();
            if let Err(e) = add_to_log_index(&name, &sealed) {
                self.show(
                    id,
                    &format!("\x1b[0;31mCould not add the log to the log index: {e}\x1b[0m\r\n"),
                );
            }
        }
    }

    /// Writes host output to the pane's recording, if it records.
    fn record(&mut self, id: PaneId, bytes: &[u8]) {
        let Some(p) = self.panes.get_mut(&id) else {
            return;
        };
        let Some(writer) = p.cast.as_mut().and_then(|r| r.writer.as_mut()) else {
            return;
        };
        if let Err(e) = writer.output(bytes) {
            // Dropping it seals what was written.
            p.cast = None;
            self.show(
                id,
                &format!("\r\n\x1b[0;31mRecording stopped: {e}\x1b[0m\r\n"),
            );
            self.update_menu_checks();
        }
    }

    /// Session > Logs and recordings > Record this pane: starts recording the pane's output with
    /// its timing, or ends the recording and says where it is.
    fn toggle_record(&mut self, id: PaneId) {
        let Some(p) = self.panes.get_mut(&id) else {
            return;
        };
        if let Some(mut rec) = p.cast.take() {
            let text = match rec.finish() {
                Ok(()) => format!(
                    "\x1b[0;90mRecording saved to {}\x1b[0m\r\n",
                    rec.path.display()
                ),
                Err(e) => format!(
                    "\x1b[0;31mCould not finish the recording {}: {e}\x1b[0m\r\n",
                    rec.path.display()
                ),
            };
            self.show(id, &text);
        } else if matches!(
            p.host,
            Host::Replay(_) | Host::Desktop { .. } | Host::Diff(_)
        ) {
            return;
        } else {
            let text = self.start_recording(id, None);
            self.show(id, &text);
        }
        self.update_menu_checks();
        self.refresh(id);
    }

    /// Starts recording pane `id` (not a replay or a desktop); for a
    /// coding agent's pane, `agent` names it in the file's name and title.
    /// Returns what to show in the pane.
    fn start_recording(&mut self, id: PaneId, agent: Option<&str>) -> String {
        let Some(p) = self.panes.get_mut(&id) else {
            return String::new();
        };
        if matches!(
            p.host,
            Host::Replay(_) | Host::Desktop { .. } | Host::Diff(_)
        ) {
            return String::new();
        }
        let label = p.host_label();
        let title = match agent {
            Some(a) => format!("FeroSSH recording of coding agent {a} on {label}"),
            None => format!("FeroSSH recording of {label}"),
        };
        let header = CastHeader {
            cols: clamp16(p.term.cols()),
            rows: clamp16(p.term.rows()),
            timestamp: SystemTime::now()
                .duration_since(SystemTime::UNIX_EPOCH)
                .map_or(0, |d| d.as_secs()),
            title,
        };
        let suffix = agent.map(|a| format!("-{a}")).unwrap_or_default();
        let opened =
            new_log_file_ext(&label, id, &suffix, "cast").and_then(|(f, chain, path, name)| {
                Ok((CastWriter::sealed(f, chain, &name, &header)?, path))
            });
        match opened {
            Ok((writer, path)) => {
                let text = format!(
                    "\x1b[0;90mRecording this pane to {} (what the host shows, not what you type)\x1b[0m\r\n",
                    path.display()
                );
                p.cast = Some(Recording {
                    writer: Some(writer),
                    path,
                });
                text
            }
            Err(e) => format!(
                "\x1b[0;31mCould not start a recording in {}: {e}\x1b[0m\r\n",
                log_dir().display()
            ),
        }
    }

    /// Session > Logs and recordings > Play a recording: opens `path` in a new replay tab, or
    /// says why it cannot.
    fn open_replay(&mut self, path: &Path) -> std::result::Result<(), String> {
        let shown = path.display();
        let too_big = std::fs::metadata(path)
            .map_err(|e| format!("Could not read {shown}: {e}"))?
            .len()
            > ferossh_term::cast::MAX_FILE as u64;
        let cast = if too_big {
            Err(ferossh_term::cast::CastError::TooBig)
        } else {
            let bytes = std::fs::read(path).map_err(|e| format!("Could not read {shown}: {e}"))?;
            Cast::parse(&bytes)
        }
        .map_err(|e| format!("Could not play {shown}: {e}."))?;
        // Without `.cast`: the tab has little room.
        let name = path.file_stem().map_or_else(
            || "recording".to_owned(),
            |n| n.to_string_lossy().into_owned(),
        );
        let (cols, rows) = (cast.cols, cast.rows);
        let id = self.new_tab_pane();
        let scrollback = self.settings.scrollback;
        let Some(p) = self.panes.get_mut(&id) else {
            return Ok(());
        };
        p.term = replay_terminal(cols, rows, scrollback, &p.theme, p.metrics);
        p.grid.mark_all_dirty();
        p.host = Host::Replay(Box::new(Replay {
            player: Player::new(cast, Instant::now()),
            name,
            shown: None,
        }));
        self.focus_terminal();
        self.replay_tick();
        self.refresh_chrome();
        self.request_full_redraw();
        Ok(())
    }

    /// Plays what is due in every replay tab, and sets the timer for what
    /// comes next.
    fn replay_tick(&mut self) {
        let now = Instant::now();
        let scrollback = self.settings.scrollback;
        let mut next: Option<Duration> = None;
        let mut chrome = false;
        let mut fed_panes = Vec::new();
        for (id, p) in &mut self.panes {
            let Pane {
                host: Host::Replay(r),
                term,
                grid,
                theme,
                metrics,
                ..
            } = p
            else {
                continue;
            };
            let mut fed = false;
            for play in r.player.due(now) {
                fed = true;
                match play {
                    // Going back: from an empty terminal again.
                    Play::Reset(cols, rows) => {
                        *term = replay_terminal(cols, rows, scrollback, theme, *metrics);
                    }
                    Play::Output(text) => term.feed(text.as_bytes()),
                    Play::Resize(cols, rows) => term.resize(usize::from(cols), usize::from(rows)),
                }
            }
            if fed {
                grid.mark_all_dirty();
                fed_panes.push(*id);
            }
            let shown = (
                r.player.position(now) as u64,
                r.player.paused(),
                r.player.ended(),
            );
            if r.shown != Some(shown) {
                r.shown = Some(shown);
                chrome = true;
            }
            if let Some(wait) = r.player.wait(now) {
                let wait = wait.min(Duration::from_millis(REPLAY_TICK_MS));
                next = Some(next.map_or(wait, |n| n.min(wait)));
            }
        }
        for id in fed_panes {
            self.refresh(id);
        }
        match next {
            Some(wait) => {
                let ms = u32::try_from(wait.as_millis()).unwrap_or(u32::MAX).max(1);
                // SAFETY: our window; replaces any earlier timer with this id.
                unsafe { SetTimer(Some(self.hwnd), TIMER_REPLAY, ms, None) };
            }
            None => {
                // SAFETY: our window and timer.
                unsafe {
                    let _ = KillTimer(Some(self.hwnd), TIMER_REPLAY);
                }
            }
        }
        if chrome {
            self.refresh_chrome();
            // The window title is the focused pane's label too.
            self.update_title();
        }
    }

    fn on_replay_timer(&mut self) -> Vec<Command> {
        self.replay_tick();
        self.after_feed()
    }

    /// A key in replay pane `id`: Space pauses and plays, Left and Right go
    /// 5 seconds back and on, Up and Down change the speed, Home starts
    /// again and End goes to the end. Other keys do nothing (there is no
    /// host to send them to). `true` when the pane is a replay pane.
    fn replay_key(&mut self, id: PaneId, vk: VIRTUAL_KEY, mods: Mods) -> bool {
        let now = Instant::now();
        let Some(p) = self.panes.get_mut(&id) else {
            return false;
        };
        let Host::Replay(r) = &mut p.host else {
            return false;
        };
        if mods.ctrl || mods.alt {
            // Shortcuts not taken before this (copy, scrolling) carry on.
            return false;
        }
        let player = &mut r.player;
        let step = if mods.shift { 30.0 } else { 5.0 };
        match vk {
            VK_SPACE => player.toggle_pause(now),
            VK_LEFT => player.seek(player.position(now) - step, now),
            VK_RIGHT => player.seek(player.position(now) + step, now),
            VK_UP => player.change_speed(true, now),
            VK_DOWN => player.change_speed(false, now),
            VK_HOME => player.seek(0.0, now),
            VK_END => player.seek(f64::MAX, now),
            // Page Up and Down scroll back through the recording's output.
            VK_PRIOR => p.term.scroll_pages(1),
            VK_NEXT => p.term.scroll_pages(-1),
            _ => {}
        }
        r.shown = None;
        self.replay_tick();
        // Scrolling feeds nothing, so the tick may not have redrawn it.
        self.refresh(id);
        self.refresh_chrome();
        true
    }

    fn log(&mut self, id: PaneId, bytes: &[u8]) {
        self.log_bytes(id, bytes, true);
    }

    /// Session > Disconnect, for pane `pane`'s connection (a native
    /// tmux pane's, its gateway's), saying `note` (grey) once closed; a
    /// connection that waits to reconnect stops waiting.
    fn disconnect(&mut self, pane: PaneId, note: &str) {
        let pane = self.host_pane(pane);
        if self.retries.contains_key(&pane) {
            self.stop_reconnecting(pane);
            return;
        }
        self.tmux_lost(pane);
        let effects = match self.panes.get_mut(&pane).map(|p| &mut p.host) {
            Some(Host::Ssh(session))
                if matches!(session.state(), State::Connecting | State::Connected) =>
            {
                session.close()
            }
            Some(Host::Telnet(session))
                if matches!(session.state(), State::Connecting | State::Connected) =>
            {
                session.close()
            }
            Some(Host::Winrm(session))
                if matches!(session.state(), State::Connecting | State::Connected) =>
            {
                session.close()
            }
            _ => return,
        };
        self.apply(pane, effects);
        self.stop_log(pane);
        self.drop_rules(pane);
        self.update_menu_checks();
        self.show(pane, &format!("\r\n\x1b[0;90m{note}\x1b[0m\r\n"));
        self.refresh_chrome();
        self.refresh(pane);
    }

    /// Whether a security rule wants pane `id`'s session logged and its
    /// log will not open: tried here, before anything starts on the
    /// session (the failure queues the disconnect).
    fn required_log_failed(&mut self, id: PaneId) -> bool {
        if !self.panes.get(&id).is_some_and(|p| p.policy.log_session) {
            return false;
        }
        self.start_log(id);
        self.panes.get(&id).is_some_and(|p| p.log.writer.is_none())
    }

    /// Pane `id`'s connection is over: its security rules go, and Log to
    /// file goes back to the user's own setting. The next connection
    /// puts its own rules on.
    fn drop_rules(&mut self, id: PaneId) {
        if let Some(p) = self.panes.get_mut(&id) {
            p.policy = Policy::default();
            p.route_policy = Policy::default();
        }
        self.restore_log_setting(id);
    }

    /// Gives pane `id` back the logging setting its user chose, which a
    /// `LogSession` rule overrode while the session was live.
    fn restore_log_setting(&mut self, id: PaneId) {
        if let Some(p) = self.panes.get_mut(&id)
            && let Some(before) = p.log.before_rule.take()
        {
            p.log.enabled = before;
        }
    }

    /// A security rule wants pane `id`'s session logged, and its log
    /// could not be opened or written: the session ends, rather than go
    /// on unlogged. Asked through [`Command::LogRequired`], once no state
    /// is borrowed.
    fn log_required_failed(&mut self, id: PaneId) {
        let Some(p) = self.panes.get(&id) else {
            return;
        };
        if !p.policy.log_session || p.log.writer.is_some() {
            return;
        }
        let note = format!(
            "[Disconnected: a security rule requires this session's log, and it could not be \
             written. Make sure {} can be written to, then press Enter to connect again.]",
            log_dir().display()
        );
        self.disconnect(id, &note);
    }

    /// [`Self::log`]; `live` when the host sent `bytes` (not local echo),
    /// which the quiet watch counts as work.
    fn log_bytes(&mut self, id: PaneId, bytes: &[u8], live: bool) {
        self.record(id, bytes);
        let Some(p) = self.panes.get_mut(&id) else {
            return;
        };
        // Every live output passes here (not FeroSSH's own notices).
        if live && let Some(w) = p.quiet.as_mut() {
            w.output(Instant::now());
        }
        let Some(writer) = &mut p.log.writer else {
            return;
        };
        if let Err(e) = writer.write(bytes) {
            p.log.writer = None;
            p.log.enabled = false;
            if p.policy.log_session {
                self.queued.push(Command::LogRequired(id));
            }
            self.show(
                id,
                &format!("\r\n\x1b[0;31mLogging stopped: {e}\x1b[0m\r\n"),
            );
            self.update_menu_checks();
        }
    }

    /// Sends the terminal's answers and other non-user bytes to the host.
    /// They never go into a local prompt.
    fn send(&mut self, id: PaneId, bytes: Vec<u8>) {
        let bytes = self.escape_sent(id, bytes);
        if let Some(gateway) = self.panes.get(&id).and_then(Pane::gateway) {
            let actions = self
                .tmux
                .get_mut(&gateway)
                .map(|t| t.input(id, &bytes))
                .unwrap_or_default();
            self.run_tmux(gateway, actions);
            return;
        }
        let effects = match self.panes.get_mut(&id).map(|p| &mut p.host) {
            Some(Host::Local {
                shell: Some(shell),
                exited: false,
            }) => {
                shell.write(bytes);
                return;
            }
            Some(Host::Ssh(session)) if !session.prompt_active() => session.input(&bytes),
            Some(Host::Telnet(session)) => session.input(&bytes),
            Some(Host::Winrm(session)) => session.input(&bytes),
            Some(Host::Serial {
                port: Some(port), ..
            }) => {
                port.write(bytes);
                return;
            }
            _ => return,
        };
        self.apply(id, effects);
    }

    /// Sends what the user typed or pasted; brings the view to the bottom.
    /// Local prompts, the connect prompt and "Press Enter to reconnect"
    /// take it first.
    fn input(&mut self, id: PaneId, bytes: Vec<u8>) {
        let Some(p) = self.panes.get_mut(&id) else {
            return;
        };
        if matches!(p.host, Host::Diff(_)) {
            self.diff_key(id, &bytes);
            return;
        }
        if p.term.display_offset() != 0 || p.term.stopped() {
            p.term.scroll_to_bottom();
            self.refresh(id);
        }
        // A login script's secret prompt takes the typing; other typing
        // stops the script and goes on to the host.
        if let Some(run) = self.scripts.get_mut(&id) {
            let prompt = run.runner.prompting();
            let actions = if prompt {
                run.runner.prompt_input(&bytes, Instant::now())
            } else {
                run.runner.cancel()
            };
            self.script_actions(id, actions);
            if prompt {
                return;
            }
        }
        // Typing starts paused auto-responses again, and is recorded.
        if let Some(w) = self.watches.get_mut(&id) {
            w.resume();
        }
        // What comes next answers the typing: a quiet watch starts over.
        if let Some(w) = self.panes.get_mut(&id).and_then(|p| p.quiet.as_mut()) {
            w.typed();
        }
        // An escape character held back goes first, so the recording
        // holds what the shell gets. It is recorded on its own, so a
        // bracketed paste after it still starts with its marker.
        let typed = bytes.len();
        let bytes = self.escape_sent_held(id, bytes);
        if let Some((pane, rec)) = &mut self.recording
            && *pane == id
        {
            let (held, rest) = bytes.split_at(bytes.len() - typed);
            if !held.is_empty() {
                rec.input(held);
            }
            rec.input(rest);
        }
        let enter = matches!(bytes.as_slice(), b"\r" | b"\r\n" | b"\n");
        let Some(p) = self.panes.get_mut(&id) else {
            return;
        };
        match &mut p.host {
            Host::Local { exited: true, .. } => {
                if enter {
                    self.start_shell(id);
                }
            }
            Host::Local { .. } => {
                self.track_typing(id, &bytes);
                self.send(id, bytes);
            }
            // Typing reaches the desktop before this; the pane only shows
            // messages once it ended. A recording has no host.
            Host::Desktop { .. } | Host::Replay(_) | Host::Diff(_) => {}
            Host::Ask(text) => {
                if enter {
                    let destination = std::mem::take(text);
                    self.show(id, "\r\n");
                    if destination.trim().is_empty() {
                        self.show(id, CONNECT_PROMPT);
                    } else {
                        self.note_recent(destination.trim());
                        self.connect(id, destination.trim());
                    }
                } else if let [0x7f] | [0x08] = bytes.as_slice() {
                    if text.pop().is_some() {
                        self.show(id, "\x08 \x08");
                    }
                } else if !bytes.starts_with(&[0x1b]) {
                    let typed: String = String::from_utf8_lossy(&bytes)
                        .chars()
                        .filter(|c| !c.is_control())
                        .collect();
                    text.push_str(&typed);
                    self.show(id, &typed);
                }
                self.refresh(id);
            }
            Host::Ssh(session) if session.prompt_active() => {
                let effects = session.prompt_input(&bytes);
                self.apply(id, effects);
                self.refresh(id);
            }
            Host::Ssh(session)
                if session.state() == State::Connecting
                    && is_escape(&bytes)
                    && self.retries.contains_key(&id) =>
            {
                self.stop_reconnecting(id);
            }
            Host::Ssh(session) if session.state() == State::Ended => {
                if self.retries.contains_key(&id) {
                    if enter {
                        self.retry_now(id);
                    } else if is_escape(&bytes) {
                        self.stop_reconnecting(id);
                    }
                } else if enter {
                    self.reconnect(id);
                }
            }
            Host::Serial {
                port: None,
                target,
                session,
            } => {
                if enter {
                    let (target, session) = (target.clone(), session.clone());
                    self.open_serial(id, target, session.as_deref());
                }
            }
            Host::Telnet(session) if session.state() == State::Ended => {
                if enter {
                    self.reconnect(id);
                }
            }
            Host::Winrm(session) if session.state() == State::Ended => {
                if enter {
                    self.reconnect(id);
                }
            }
            Host::Ssh(_)
            | Host::Tmux { .. }
            | Host::Serial { .. }
            | Host::Telnet(_)
            | Host::Winrm(_) => {
                self.track_typing(id, &bytes);
                self.send(id, bytes);
            }
        }
    }

    /// Bytes for the host of pane `id` pass the SSH escape state: an
    /// escape character still held back goes first (a paste or a script
    /// came after it, not a command key), and whether the next key is
    /// first on a line follows what went. Everything that goes to the
    /// host passes here, as everything ssh reads passes its escape check.
    fn escape_sent(&mut self, id: PaneId, bytes: Vec<u8>) -> Vec<u8> {
        let bytes = self.escape_sent_held(id, bytes);
        if let Some(p) = self.panes.get_mut(&id)
            && matches!(p.host, Host::Ssh(_) | Host::Tmux { .. })
        {
            p.escapes.sent(&bytes);
        }
        bytes
    }

    /// `bytes` after the escape character pane `id` holds back, if any.
    fn escape_sent_held(&mut self, id: PaneId, mut bytes: Vec<u8>) -> Vec<u8> {
        let held = self.escape_char_of(id);
        let Some(p) = self.panes.get_mut(&id) else {
            return bytes;
        };
        if matches!(p.host, Host::Ssh(_) | Host::Tmux { .. })
            && p.escapes.take_pending()
            && let Some(e) = held
        {
            bytes.insert(0, e);
        }
        bytes
    }

    /// The SSH escape character of pane `id`: its host's `EscapeChar`, else
    /// the window's setting. `None` when escapes are off, or the pane is
    /// not a logged-in SSH shell (a prompt, a Mosh session with its own
    /// keys, Telnet, a local shell), or a tmux pane of one.
    fn escape_char_of(&self, id: PaneId) -> Option<u8> {
        let p = self.panes.get(&id)?;
        match &p.host {
            Host::Ssh(s)
                if self.settings.escapes
                    && s.state() == State::Connected
                    && !s.prompt_active()
                    && s.target.mosh.is_none()
                    && !s.target.sftp_only =>
            {
                match s.target.escape_char.unwrap_or(self.settings.escape_char) {
                    EscapeChar::None => None,
                    EscapeChar::Char(c) => Some(c),
                }
            }
            Host::Tmux { gateway, .. } => self.escape_char_of(*gateway),
            _ => None,
        }
    }

    /// A key typed in pane `id`, for the SSH escape sequences, before it
    /// is encoded or goes anywhere: `Some` when they took it, with what
    /// to run; `None` when it goes on as usual (after the held escape
    /// character, when no command followed it).
    fn escape_typed(&mut self, id: PaneId, typed: escape::Typed) -> Option<Option<Command>> {
        // A login script's secret prompt takes the typing.
        if self.scripts.get(&id).is_some_and(|r| r.runner.prompting()) {
            return None;
        }
        let esc = self.escape_char_of(id);
        let p = self.panes.get_mut(&id)?;
        // The shell ended, or escapes were turned off: a `~C` line or a
        // held character left open goes, and keys go on as usual (Enter
        // reconnects).
        if esc.is_none() {
            p.escapes.cancel();
            return None;
        }
        let outcome = p.escapes.key(esc, typed);
        let e = esc.unwrap_or(b'~');
        match outcome {
            EscapeOutcome::Pass => None,
            EscapeOutcome::Taken => Some(None),
            EscapeOutcome::EscapeThenPass => {
                self.type_escape(id, e);
                None
            }
            EscapeOutcome::SendEscape => {
                self.type_escape(id, e);
                Some(None)
            }
            EscapeOutcome::Echo(text) => {
                self.show(id, &text);
                self.refresh(id);
                Some(None)
            }
            EscapeOutcome::Command(line) => {
                self.escape_command(id, &line);
                Some(None)
            }
            EscapeOutcome::Run(what) => Some(self.run_escape(id, what, e)),
        }
    }

    /// Types the escape character itself, in pane `id` and the panes
    /// broadcast input goes to.
    fn type_escape(&mut self, id: PaneId, e: u8) {
        let targets = self.broadcast_targets(id);
        self.input(id, vec![e]);
        self.send_typed(&targets, &Typed::Bytes(vec![e]));
    }

    /// Carries out an escape sequence typed in pane `id`.
    fn run_escape(&mut self, id: PaneId, what: Escape, e: u8) -> Option<Command> {
        let note = |text: &str| format!("\r\n\x1b[0;90m{text}\x1b[0m\r\n");
        match what {
            Escape::Disconnect => return Some(Command::Id(cmd::DISCONNECT)),
            Escape::Help => self.show(id, &escape::help(&EscapeChar::Char(e).text())),
            Escape::Forwards => {
                let text = self.forwards_text(id);
                self.show(id, &text);
            }
            Escape::CommandLine => self.show(id, "\r\nssh> "),
            Escape::Rekey => {
                let host = self.host_pane(id);
                let channel = match self.panes.get(&host).map(|p| &p.host) {
                    Some(Host::Ssh(s)) => Some(s.channel),
                    _ => None,
                };
                if let Some(channel) = channel {
                    self.apply(host, vec![Effect::Send(Message::Rekey { channel })]);
                    self.show(id, &note("Asked the server for a new key exchange."));
                }
            }
            Escape::Break => self.show(
                id,
                &note(
                    "FeroSSH cannot send a BREAK over SSH. (Session > Send break is for \
                     serial ports.)",
                ),
            ),
            Escape::Verbosity => self.show(
                id,
                &note("FeroSSH has no log level to change. Session > Logs and recordings keeps the output."),
            ),
            Escape::Background => self.show(
                id,
                &note(
                    "FeroSSH does not send a connection to the background: the tab keeps \
                     it. Session > Disconnect ends it.",
                ),
            ),
        }
        self.refresh(id);
        None
    }

    /// `~#`: the forwards of pane `id`'s connection and their open
    /// connections.
    fn forwards_text(&self, id: PaneId) -> String {
        let Some(c) = self.pane_connection(id) else {
            return "\r\nNot connected.\r\n".into();
        };
        let views = self.forward_view();
        let mut out = String::from("\r\nForwards of this connection:\r\n");
        let mut any = false;
        if let Some(v) = views.iter().find(|v| v.connection == c) {
            for f in &v.forwards {
                any = true;
                let state = match &f.state {
                    FwdState::Starting => "starting".to_owned(),
                    FwdState::Listening(at) => format!("listening on {at}"),
                    FwdState::Failed(why) => format!("failed: {why}"),
                };
                let desktop = if f.desktop { " (remote desktop)" } else { "" };
                out.push_str(&crate::ssh::sanitize_line(&format!(
                    "  {}{desktop}  {state}; {} open, {} since it started",
                    f.spec, f.open, f.total
                )));
                out.push_str("\r\n");
                for stream in &f.streams {
                    out.push_str(&crate::ssh::sanitize_line(&format!("      {stream}")));
                    out.push_str("\r\n");
                }
                if let Some(e) = &f.error {
                    out.push_str(&crate::ssh::sanitize_line(&format!(
                        "      last error: {e}"
                    )));
                    out.push_str("\r\n");
                }
            }
            if let Some(x) = &v.x11 {
                any = true;
                out.push_str(&crate::ssh::sanitize_line(&format!(
                    "  X11 to {}  {} open, {} since it started",
                    x.display, x.open, x.total
                )));
                out.push_str("\r\n");
            }
        }
        if !any {
            out.push_str("  none\r\n");
        }
        out
    }

    /// Runs what was typed on the `~C` command line of pane `id`.
    fn escape_command(&mut self, id: PaneId, line: &str) {
        self.show(id, "\r\n");
        // This pane's own connection, never another one's.
        let view = self.forward_view();
        let connection = self
            .pane_connection(id)
            .ok_or_else(|| "Not connected.".to_owned())
            .and_then(|c| {
                if view.iter().any(|v| v.connection == c) && self.workers.contains_key(&c) {
                    Ok(c)
                } else {
                    Err(
                        "This connection's forwards are not ready yet; try again in a moment."
                            .to_owned(),
                    )
                }
            });
        let text = match escape::parse_command(line) {
            CommandLine::Nothing => String::new(),
            CommandLine::Help => escape::COMMAND_HELP.to_owned(),
            CommandLine::Add(spec) => match connection
                .and_then(|c| self.add_forward(Some(c), &spec, &view))
            {
                Ok(_) => {
                    format!("Forwarding {spec}. Tools > Port forwards shows whether it listens.")
                }
                Err(why) => why,
            },
            CommandLine::Cancel(cancel) => {
                match connection.and_then(|c| self.cancel_forward(Some(c), &cancel, &view)) {
                    Ok(spec) => format!("Cancelled {spec}."),
                    Err(why) => why,
                }
            }
            CommandLine::Bad(why) => why,
        };
        if !text.is_empty() {
            let text = crate::ssh::sanitize(&text);
            self.show(id, &format!("\x1b[0;90m{text}\x1b[0m\r\n"));
        }
        self.refresh_chrome();
        self.refresh(id);
    }

    /// The history that pane `id`'s commands go in: per host (and user and
    /// port), a tmux pane's being its connection's. `None` for prompts and
    /// desktops.
    fn history_key(&self, id: PaneId) -> Option<String> {
        let p = self.panes.get(&id)?;
        Some(match &p.host {
            Host::Ssh(s) => format!(
                "ssh:{}@{}:{}",
                s.target.user,
                s.target.hostname.to_ascii_lowercase(),
                s.target.port
            ),
            Host::Tmux { gateway, .. } => return self.history_key(*gateway),
            Host::Local { .. } => "local".to_owned(),
            Host::Serial { target, .. } => format!("serial:{}", target.port),
            Host::Telnet(s) => format!(
                "telnet:{}:{}",
                s.target.hostname.to_ascii_lowercase(),
                s.target.port
            ),
            Host::Winrm(s) => format!(
                "winrm:{}@{}:{}",
                s.target.user.as_deref().unwrap_or("").to_lowercase(),
                s.target.hostname.to_ascii_lowercase(),
                s.target.port
            ),
            Host::Ask(_) | Host::Desktop { .. } | Host::Replay(_) | Host::Diff(_) => return None,
        })
    }

    /// Edit > Suggest commands as you type: follows what is typed in pane
    /// `id` before it goes to the host, and keeps a line an earlier Enter
    /// ran.
    fn track_typing(&mut self, id: PaneId, bytes: &[u8]) {
        if !self.settings.command_suggestions {
            return;
        }
        let Some(p) = self.panes.get_mut(&id) else {
            return;
        };
        if p.desktop.is_some() {
            return;
        }
        // What shows was for the line before this key: until the echo
        // redraws it, no key takes it.
        if self.ghost.as_ref().is_some_and(|g| g.pane == id) {
            self.ghost = None;
        }
        let Some(p) = self.panes.get_mut(&id) else {
            return;
        };
        let done = p.typing.typed(&p.term, bytes);
        if let Some(line) = done {
            self.keep_command(id, &line);
        }
    }

    /// Puts `line` in pane `id`'s host history and saves it.
    fn keep_command(&mut self, id: PaneId, line: &str) {
        let Some(key) = self.history_key(id) else {
            return;
        };
        // Run again: no longer dismissed.
        self.dismissed.remove(&(key.clone(), line.to_owned()));
        self.change_history(&key, |h| h.record(line));
    }

    /// Changes host `key`'s history as kept on disk (which another FeroSSH
    /// window may have changed or cleared), saves it if `change` changed
    /// it, and keeps the result.
    fn change_history(&mut self, key: &str, change: impl FnOnce(&mut suggest::History) -> bool) {
        #[cfg(windows)]
        {
            // Not saved (the folder cannot be written): this window keeps
            // the change, with the file's old time so it is not read over.
            let kept = self.histories.get(key).map(|(h, _)| h);
            let fresh = match crate::history_store::update(key, kept, change) {
                Ok(fresh) => fresh,
                Err((kept, _)) => kept,
            };
            self.histories.insert(key.to_owned(), fresh);
        }
        #[cfg(not(windows))]
        {
            let (h, _) = self
                .histories
                .entry(key.to_owned())
                .or_insert_with(|| (suggest::History::new(key), None));
            change(h);
        }
    }

    /// The history of host `key`: read from disk the first time, and again
    /// when another window changed or cleared the file.
    fn history(&mut self, key: &str) -> &suggest::History {
        #[cfg(windows)]
        {
            let stamp = crate::history_store::modified(key);
            let stale = self.histories.get(key).is_none_or(|(_, s)| *s != stamp);
            if stale {
                let loaded = crate::history_store::load(key);
                self.histories.insert(key.to_owned(), loaded);
            }
        }
        &self
            .histories
            .entry(key.to_owned())
            .or_insert_with(|| (suggest::History::new(key), None))
            .0
    }

    /// The suggestion for what is typed in pane `id` now, if one shows:
    /// suggestions on, the pane focused, at the bottom of its output, and
    /// the cursor at the end of a line typed at a prompt.
    fn find_ghost(&mut self, id: PaneId) -> Option<Ghost> {
        if !self.settings.command_suggestions || id != self.focused_id() || self.side.focused {
            return None;
        }
        let key = self.history_key(id)?;
        let p = self.panes.get_mut(&id)?;
        if p.desktop.is_some()
            || p.cursor.is_none()
            || p.term.search_active()
            || p.term.display_offset() != 0
            || p.term.stopped()
            || !self.takes_broadcast(id)
        {
            return None;
        }
        let p = self.panes.get_mut(&id)?;
        let typed = p.typing.line(&p.term)?.before;
        let choice = p.typing.choice;
        let mut choices = suggest::choices(Some(self.history(&key)), &typed);
        choices.retain(|c| !self.dismissed.contains(&(key.clone(), c.clone())));
        if choices.is_empty() {
            return None;
        }
        let line = choices.get(choice % choices.len())?.clone();
        let rest = line.get(typed.len()..)?.to_owned();
        Some(Ghost {
            pane: id,
            line,
            rest,
            count: choices.len(),
        })
    }

    /// Draws the suggestion greyed after the cursor in pane `id`'s grid,
    /// as far as the row goes.
    fn draw_ghost(&mut self, id: PaneId) {
        let Some(g) = self.ghost.as_ref().filter(|g| g.pane == id) else {
            return;
        };
        let Some(p) = self.panes.get_mut(&id) else {
            return;
        };
        let Some(c) = p.cursor else {
            return;
        };
        let cols = p.grid.cols();
        let mut x = c.x;
        for ch in g.rest.chars() {
            let w = unicode_width::UnicodeWidthChar::width(ch).unwrap_or(0);
            if w == 0 || x + w > cols {
                break;
            }
            let Some(cell) = p.grid.cell_mut(x, c.y) else {
                break;
            };
            cell.ch = ch;
            cell.flags = if w == 2 {
                ferossh_render::Flags::DIM.union(ferossh_render::Flags::WIDE)
            } else {
                ferossh_render::Flags::DIM
            };
            cell.fg = ferossh_render::Color::Default;
            if w == 2
                && let Some(spacer) = p.grid.cell_mut(x + 1, c.y)
            {
                *spacer = ferossh_render::Cell::new(
                    ' ',
                    ferossh_render::Color::Default,
                    spacer.bg,
                    ferossh_render::Flags::WIDE_SPACER,
                );
            }
            x += w;
        }
    }

    /// Suggestion key `action` (a `cmd::SUGGEST_*`, by Settings > Key
    /// bindings) pressed in pane `id`: types the rest of the suggestion
    /// showing there or its next word, shows another match, or forgets
    /// it. `false` when no suggestion shows, there is no other match, or
    /// the key belongs to tmux (it is the prefix, or comes after it): it
    /// goes on to the terminal.
    fn ghost_key(&mut self, id: PaneId, action: u32, vk: VIRTUAL_KEY, mods: Mods) -> bool {
        let Some(g) = self.ghost.as_ref().filter(|g| g.pane == id) else {
            return false;
        };
        let (rest, line, count) = (g.rest.clone(), g.line.clone(), g.count);
        if self.tmux_armed == Some(id) {
            return false;
        }
        // Ctrl with a letter, Space, 2, 6 or / is a control code (as
        // `on_key_down` sends it), which may be the prefix.
        let control = match vk {
            _ if !mods.ctrl => None,
            VK_SPACE | VIRTUAL_KEY(0x32) => Some('\x00'),
            VIRTUAL_KEY(0x36) => Some('\x1e'),
            VK_OEM_2 => Some('\x1f'),
            _ if (0x41..=0x5A).contains(&vk.0) => {
                Some(char::from(u8::try_from(vk.0 - 0x40).unwrap_or(0)))
            }
            _ => None,
        };
        if let Some(ch) = control {
            let prefix = tmux_keys::Prefix { ch, alt: mods.alt };
            if self.tmux_keys_of(id).is_some_and(|k| k.is_prefix(prefix)) {
                return false;
            }
        }
        match action {
            cmd::SUGGEST_TAKE => self.type_ghost(id, &rest),
            cmd::SUGGEST_WORD => self.type_ghost(id, suggest::next_word(&rest)),
            cmd::SUGGEST_NEXT | cmd::SUGGEST_PREV if count > 1 => {
                if let Some(p) = self.panes.get_mut(&id) {
                    p.typing.choice = if action == cmd::SUGGEST_NEXT {
                        (p.typing.choice + 1) % count
                    } else {
                        (p.typing.choice + count - 1) % count
                    };
                }
                self.refresh(id);
            }
            cmd::SUGGEST_FORGET => {
                // A built-in command is not in the history: it stays out of
                // the suggestions until FeroSSH restarts.
                if let Some(k) = self.history_key(id) {
                    self.dismissed.insert((k.clone(), line.clone()));
                    self.change_history(&k, |h| h.remove(&line));
                }
                self.refresh(id);
            }
            _ => return false,
        }
        true
    }

    /// Types `text` of a suggestion into pane `id` (and the panes
    /// broadcast input goes to), as if typed.
    fn type_ghost(&mut self, id: PaneId, text: &str) {
        if text.is_empty() {
            return;
        }
        let targets = self.broadcast_targets(id);
        let bytes = text.as_bytes().to_vec();
        self.input(id, bytes.clone());
        self.send_typed(&targets, &Typed::Bytes(bytes));
    }

    /// Whether pane `id` passes typing straight to its host, so it may
    /// send or receive broadcast input. Prompts and ended sessions do not.
    fn takes_broadcast(&self, id: PaneId) -> bool {
        let Some(p) = self.panes.get(&id) else {
            return false;
        };
        if p.desktop.is_some() || self.scripts.get(&id).is_some_and(|r| r.runner.prompting()) {
            return false;
        }
        match &p.host {
            Host::Local {
                shell: Some(_),
                exited: false,
            }
            | Host::Tmux { .. }
            | Host::Serial { port: Some(_), .. } => true,
            // An SFTP-only or tunnel-only login has no shell to type into.
            Host::Ssh(s) => {
                s.state() == State::Connected && !s.prompt_active() && !s.target.no_shell()
            }
            Host::Telnet(s) => s.state() == State::Connected,
            Host::Winrm(s) => s.state() == State::Connected,
            _ => false,
        }
    }

    /// The other panes that get what is typed in pane `id`.
    fn broadcast_targets(&self, id: PaneId) -> Vec<PaneId> {
        if self.broadcast == broadcast::Scope::Off {
            return Vec::new();
        }
        broadcast::targets(
            self.broadcast,
            id,
            &self.visible_ids(),
            &self.ws.all_panes(),
            |p| self.panes.get(&p).is_none_or(|p| p.no_broadcast),
            |p| self.takes_broadcast(p),
        )
    }

    /// Sends a key, character or paste to each of `targets`, encoded by
    /// that pane's own terminal: its cursor-key mode, bracketed paste and
    /// keypad mode can differ from the focused pane's.
    fn send_typed(&mut self, targets: &[PaneId], typed: &Typed) {
        for &id in targets {
            let Some(p) = self.panes.get_mut(&id) else {
                continue;
            };
            let bytes = match typed {
                Typed::Char(ch, alt) => Some(p.term.text(*ch, *alt)),
                Typed::Key(key, mods) => p.term.key(*key, *mods),
                Typed::Ctrl(key, code, mods) => Some(p.term.ctrl_key(*key, *code, *mods)),
                Typed::Bytes(b) => Some(b.clone()),
                Typed::Paste(text) => Some(p.term.paste(text).bytes),
            };
            if let Some(bytes) = bytes {
                self.input(id, bytes);
            }
        }
    }

    /// Pastes into a local prompt; `false` if no prompt is open and the
    /// paste goes to the host.
    fn paste_local(&mut self, id: PaneId, text: &str) -> bool {
        if let Some(run) = self.scripts.get_mut(&id)
            && run.runner.prompting()
        {
            run.runner.prompt_paste(text);
            return true;
        }
        // The `~C` command line takes a paste's first line, without
        // running it: Enter does.
        if self.escape_char_of(id).is_some()
            && self.panes.get(&id).is_some_and(|p| p.escapes.in_command())
        {
            for c in text.chars().take_while(|c| !matches!(c, '\r' | '\n')) {
                if !c.is_control() {
                    self.escape_typed(id, escape::Typed::Char(c));
                }
            }
            return true;
        }
        let Some(p) = self.panes.get_mut(&id) else {
            return true;
        };
        match &mut p.host {
            Host::Ssh(session) if session.prompt_active() => {
                let effects = session.prompt_paste(text);
                self.apply(id, effects);
            }
            Host::Ask(typed) => {
                let clean: String = text.chars().filter(|c| !c.is_control()).collect();
                typed.push_str(&clean);
                self.show(id, &clean);
            }
            _ => return false,
        }
        self.refresh(id);
        true
    }

    /// Reads what the shells, the worker and the broker have queued.
    fn on_output(&mut self) -> Vec<Command> {
        self.output_pending.store(false, Ordering::Release);
        let mut fed = 0;
        let mut more = false;
        // The local shells.
        let ids: Vec<PaneId> = self.panes.keys().copied().collect();
        for id in ids {
            while let Some(Pane {
                host:
                    Host::Local {
                        shell: Some(shell),
                        exited: false,
                    },
                ..
            }) = self.panes.get_mut(&id)
            {
                let Some(out) = shell.try_read() else {
                    break;
                };
                match out {
                    Output::Data(data) => {
                        fed += data.len();
                        if let Some(p) = self.panes.get_mut(&id) {
                            p.term.feed(&data);
                        }
                        self.log(id, &data);
                        // A script waiting for the shell's answer.
                        self.script_output(id, &data);
                    }
                    Output::Exited(code) => {
                        self.workspace_shell_gone(id);
                        // A script typing into the shell is over with it,
                        // and nothing waits for it: Enter starts a new shell.
                        if let Some(run) = self.scripts.remove(&id) {
                            self.snippet_next.remove(&id);
                            self.workspace_after.remove(&id);
                            self.arm_script_timer();
                            if run.report {
                                self.fail_run_row(id, "the shell exited".into());
                            }
                        }
                        self.stop_log(id);
                        if let Some(p) = self.panes.get_mut(&id) {
                            p.host = Host::Local {
                                shell: None,
                                exited: true,
                            };
                        }
                        let text = format!(
                            "\r\n\x1b[0;90m[Process exited with code {code}. Press Enter to start a new one.]\x1b[0m\r\n"
                        );
                        self.show(id, &text);
                    }
                }
                if fed >= OUTPUT_BUDGET {
                    more = true;
                    break;
                }
            }
        }
        // The serial consoles.
        let ids: Vec<PaneId> = self.panes.keys().copied().collect();
        for id in ids {
            while let Some(Pane {
                host: Host::Serial {
                    port: Some(port), ..
                },
                ..
            }) = self.panes.get_mut(&id)
            {
                let Some(out) = port.try_read() else {
                    break;
                };
                match out {
                    SerialOutput::Data(data) => {
                        fed += data.len();
                        if let Some(p) = self.panes.get_mut(&id) {
                            p.term.feed(&data);
                        }
                        self.log(id, &data);
                        self.script_output(id, &data);
                        self.watch_output(id, &data);
                    }
                    SerialOutput::Closed(why) => {
                        self.stop_log(id);
                        self.scripts.remove(&id);
                        if let Some(Host::Serial { port, .. }) =
                            self.panes.get_mut(&id).map(|p| &mut p.host)
                        {
                            *port = None;
                        }
                        let text = format!(
                            "\r\n\x1b[0;31m[The serial port stopped: {}. Press Enter to open it again.]\x1b[0m\r\n",
                            why.trim()
                        );
                        self.show(id, &text);
                        self.refresh_chrome();
                    }
                }
                if fed >= OUTPUT_BUDGET {
                    more = true;
                    break;
                }
            }
        }
        // The signing broker answers in the order it was asked, except
        // Kerberos, which says whose login it is.
        while let Some(reply) = self.broker.as_ref().and_then(Broker::try_recv) {
            let channel = match &reply {
                ferossh_auth::Reply::Gssapi { login, .. }
                | ferossh_auth::Reply::Sspi { login, .. } => *login,
                _ => match self.broker_jobs.pop_front() {
                    Some(BrokerFor::Agent(what)) => {
                        let outs = self.agent_fwd.on_broker(what, reply);
                        self.agent_out(outs);
                        continue;
                    }
                    Some(BrokerFor::Login(channel)) => channel,
                    None => 0,
                },
            };
            if matches!(reply, ferossh_auth::Reply::Sspi { .. })
                && let Some(closer) = self.winrm_closing.get(&channel)
            {
                let effects = closer.on_broker(reply);
                self.apply_winrm_closing(channel, effects);
                continue;
            }
            let Some(id) = self.pane_of_channel(channel) else {
                continue;
            };
            let effects = match self.panes.get_mut(&id).map(|p| &mut p.host) {
                Some(Host::Ssh(session)) => session.on_broker(reply),
                Some(Host::Winrm(session)) => session.on_broker(reply),
                _ => Vec::new(),
            };
            self.apply(id, effects);
        }
        // The workers, a message from each in turn so that a flooding
        // host does not hold up the others.
        let mut transfers = false;
        let connections: Vec<ChannelId> = self.workers.keys().copied().collect();
        while !more {
            let mut idle = true;
            for &connection in &connections {
                let Some(event) = self
                    .workers
                    .get(&connection)
                    .and_then(|w| w.link.try_recv())
                else {
                    continue;
                };
                idle = false;
                transfers |= self.on_worker_event(connection, event, &mut fed);
                more = fed >= OUTPUT_BUDGET;
                if more {
                    break;
                }
            }
            if idle {
                break;
            }
        }
        let mut pasted = None;
        if transfers {
            pasted = self.settle_pastes();
            self.flush_sftp();
            if self.files_visible() {
                self.refresh_chrome();
            }
        }
        self.desktop_events();
        self.poll_desktops();
        // A launch's desktop may have just taken over its connection.
        if self.launches.values().next().is_some()
            && self.panes.values().any(|p| p.desktop.is_some())
        {
            self.retire_launches();
        }
        self.poll_passwords();
        self.poll_script_secrets();
        // The forwards list and the tab badges.
        if self
            .workers
            .values()
            .fold(false, |changed, w| w.forwarder.take_changed() | changed)
        {
            self.refresh_chrome();
            self.update_title();
            self.settle_previews();
        }
        if more && !self.output_pending.swap(true, Ordering::AcqRel) {
            // Let the window paint, then carry on.
            // SAFETY: posting to our own window.
            unsafe {
                let _ = PostMessageW(Some(self.hwnd), WM_SHELL_OUTPUT, WPARAM(0), LPARAM(0));
            }
        }
        let mut commands = self.after_feed();
        commands.extend(pasted);
        commands
    }

    /// Handles what the worker of the connection `connection` sent, and
    /// returns whether it was for a file transfer. A worker only reaches
    /// the shells and SFTP channels on its own connection: anything it
    /// says about another one's is dropped.
    fn on_worker_event(
        &mut self,
        connection: ChannelId,
        event: LinkEvent,
        fed: &mut usize,
    ) -> bool {
        match event {
            LinkEvent::Message(msg) => {
                match &msg {
                    Message::Data { bytes, .. }
                    | Message::ZmodemData { bytes, .. }
                    | Message::ExecStderr { bytes, .. } => {
                        *fed += bytes.len();
                    }
                    Message::SftpReply {
                        reply: SftpReply::Data(data),
                        ..
                    } => *fed += data.len(),
                    _ => {}
                }
                let Some(c) = msg.channel() else {
                    return false;
                };
                if matches!(msg, Message::AgentList { .. } | Message::AgentSign { .. }) {
                    self.on_agent_request(connection, msg);
                    return false;
                }
                if self
                    .vdesks
                    .get(&c)
                    .is_some_and(|v| v.connection == connection)
                {
                    self.on_vdesk(c, msg);
                    return false;
                }
                if self
                    .key_copies
                    .get(&c)
                    .is_some_and(|k| k.connection == connection)
                {
                    self.on_key_copy(c, msg);
                    return false;
                }
                if self
                    .system_reads
                    .get(&c)
                    .is_some_and(|r| r.connection == connection)
                {
                    self.on_system_read(c, msg);
                    return false;
                }
                if self.diff_on(c) == Some(connection) {
                    self.on_diff(c, msg);
                    return false;
                }
                if self
                    .stats
                    .get(&c)
                    .is_some_and(|f| f.connection == connection)
                {
                    self.on_stats(c, msg);
                    return false;
                }
                if self
                    .winrm_closing
                    .get(&c)
                    .is_some_and(|w| w.connection() == connection)
                {
                    self.on_winrm_closing(c, msg);
                    return false;
                }
                if let Some(remote) = self
                    .sftp
                    .values_mut()
                    .find(|r| r.channel() == Some(c) && r.connection() == Some(connection))
                {
                    remote.on_message(msg);
                    return true;
                }
                let Some(id) = self.pane_of_channel(c) else {
                    return false;
                };
                if zmodem::is_zmodem(&msg) {
                    let own = match self.panes.get(&id).map(|p| &p.host) {
                        Some(Host::Ssh(s)) => c == s.channel && s.connection == connection,
                        Some(Host::Telnet(s)) => s.connection() == connection,
                        _ => false,
                    };
                    if own {
                        self.on_zmodem(id, c, msg);
                    }
                    return false;
                }
                let effects = match self.panes.get_mut(&id).map(|p| &mut p.host) {
                    Some(Host::Ssh(session)) if session.worker_for(Some(c)) == Some(connection) => {
                        session.on_worker(msg)
                    }
                    Some(Host::Telnet(session)) if session.connection() == connection => {
                        session.on_worker(msg)
                    }
                    Some(Host::Winrm(session)) if session.connection() == connection => {
                        session.on_worker(msg)
                    }
                    _ => Vec::new(),
                };
                self.apply(id, effects);
                false
            }
            LinkEvent::Closed(why) => {
                if let Some(w) = self.workers.remove(&connection) {
                    w.forwarder.worker_gone();
                }
                crate::remote_app::connection_gone(connection);
                self.proxies.remove(&connection);
                let gone: Vec<ChannelId> = self
                    .winrm_closing
                    .iter()
                    .filter(|(_, w)| w.connection() == connection)
                    .map(|(&c, _)| c)
                    .collect();
                for c in gone {
                    if let Some(closer) = self.winrm_closing.remove(&c) {
                        let effects = closer.end();
                        self.apply_winrm_closing(c, effects);
                    }
                }
                self.vdesks.retain(|_, v| v.connection != connection);
                self.stats.retain(|_, f| f.connection != connection);
                self.system_reads.retain(|_, r| r.connection != connection);
                let lost: Vec<ChannelId> = self
                    .key_copies
                    .iter()
                    .filter(|(_, k)| k.connection == connection)
                    .map(|(&c, _)| c)
                    .collect();
                for c in lost {
                    self.on_key_copy(
                        c,
                        Message::Disconnected {
                            channel: c,
                            reason: why.clone(),
                        },
                    );
                }
                let lost: Vec<ChannelId> = self
                    .diffs
                    .keys()
                    .copied()
                    .filter(|&c| self.diff_on(c) == Some(connection))
                    .collect();
                for c in lost {
                    self.on_diff(
                        c,
                        Message::Disconnected {
                            channel: c,
                            reason: why.clone(),
                        },
                    );
                }
                let mut orphaned = Vec::new();
                for (key, remote) in &mut self.sftp {
                    if remote.connection() == Some(connection) {
                        remote.detach();
                        orphaned.push(key.clone());
                    }
                }
                let ids: Vec<PaneId> = self.panes.keys().copied().collect();
                for id in ids {
                    let effects = match self.panes.get_mut(&id).map(|p| &mut p.host) {
                        Some(Host::Ssh(session))
                            if matches!(session.state(), State::Connecting | State::Connected) =>
                        {
                            // The login in that worker: the pane's own, or
                            // a jump host's on the way.
                            match session.login_on(connection) {
                                Some(channel) => session.on_worker(Message::Disconnected {
                                    channel,
                                    reason: why.clone(),
                                }),
                                None => Vec::new(),
                            }
                        }
                        Some(Host::Telnet(session))
                            if session.connection() == connection
                                && matches!(
                                    session.state(),
                                    State::Connecting | State::Connected
                                ) =>
                        {
                            session.on_worker(Message::Disconnected {
                                channel: session.channel,
                                reason: why.clone(),
                            })
                        }
                        Some(Host::Winrm(session))
                            if session.connection() == connection
                                && matches!(
                                    session.state(),
                                    State::Connecting | State::Connected
                                ) =>
                        {
                            session.on_worker(Message::Disconnected {
                                channel: session.channel,
                                reason: why.clone(),
                            })
                        }
                        _ => Vec::new(),
                    };
                    self.apply(id, effects);
                }
                // The panes on that worker are down now: another login to
                // the same host takes their queues over.
                self.hand_over_sftp(orphaned);
                true
            }
        }
    }

    /// Acts on what the terminals asked for and redraws.
    fn after_feed(&mut self) -> Vec<Command> {
        let mut commands = Vec::new();
        let mut deadline: Option<Instant> = None;
        let focused = self.focused_id();
        let ids: Vec<PaneId> = self.panes.keys().copied().collect();
        let mut chrome = false;
        for id in ids {
            let visible = self.is_visible(id);
            let Some(p) = self.panes.get_mut(&id) else {
                continue;
            };
            let mut actions = p.term.take_actions();
            let replay = matches!(p.host, Host::Replay(_) | Host::Diff(_));
            if replay {
                // A recording plays to the screen only: it cannot write
                // the clipboard or move the file view, and nothing answers.
                actions.retain(|a| matches!(a, Action::Title(_) | Action::Bell));
            }
            // One clipboard question per burst of output: the last request
            // wins, so a flood of OSC 52 cannot line up a dialog for each.
            if let Some(last) = actions
                .iter()
                .rposition(|a| matches!(a, Action::ClipboardRequest(_)))
            {
                let mut i = 0;
                actions.retain(|a| {
                    let keep = i == last || !matches!(a, Action::ClipboardRequest(_));
                    i += 1;
                    keep
                });
            }
            if let Some(d) = p.term.sync_deadline() {
                deadline = Some(deadline.map_or(d, |old| old.min(d)));
            }
            let notified = actions.iter().any(|a| matches!(a, Action::Notify(_)));
            for action in actions {
                match action {
                    // tmux answered its panes' queries already.
                    Action::Reply(_)
                        if self.panes.get(&id).is_some_and(|p| p.gateway().is_some()) => {}
                    Action::Reply(bytes) | Action::ImageReply(bytes) => self.send(id, bytes),
                    Action::Title(title) => {
                        if let Some(p) = self.panes.get_mut(&id) {
                            p.title = title;
                        }
                        if id == focused {
                            commands.push(Command::UpdateTitle);
                        }
                        chrome = true;
                    }
                    // A security rule may keep the server off this PC's
                    // clipboard.
                    Action::ClipboardRequest(_)
                        if self.panes.get(&id).is_some_and(|p| p.policy.no_clipboard) => {}
                    Action::ClipboardRequest(text) => commands.push(Command::ClipboardWrite(text)),
                    Action::Bell => {
                        if !visible && let Some(p) = self.panes.get_mut(&id) {
                            p.bell = true;
                            chrome = true;
                        }
                        if !self.focused {
                            commands.push(Command::Bell);
                        }
                        // A notification in the same output says more than
                        // the bell that often comes with it.
                        if self.settings.notify_bell && !replay && !notified {
                            chrome |= self.alert(id, None, "The bell rang.".into());
                        }
                    }
                    Action::Notify(n) => {
                        chrome |= self.alert(id, n.title, n.body);
                    }
                    Action::WorkingDirectory(dir) => {
                        if self.on_working_dir(id, dir) {
                            chrome = true;
                        }
                    }
                }
            }
            if replay {
                continue;
            }
            if self.read_prompt(id) {
                chrome = true;
            }
            self.read_local_prompt(id);
        }
        if let Some(deadline) = deadline {
            let wait = deadline.saturating_duration_since(Instant::now());
            let ms = u32::try_from(wait.as_millis()).unwrap_or(u32::MAX).max(1);
            // SAFETY: our window; replaces any earlier timer with this id.
            unsafe { SetTimer(Some(self.hwnd), TIMER_SYNC, ms, None) };
        }
        if chrome {
            self.refresh_chrome();
        }
        self.refresh_visible();
        if let Some(found) = self.poll_update_check() {
            commands.push(found);
        }
        if let Some(made) = self.poll_keygen() {
            commands.push(made);
        }
        commands.append(&mut self.queued);
        commands
    }

    /// Session > Coding agents, as it opens: Agent dashboard, then a Start
    /// item for each agent command.
    /// Session > Coding agents > Show what changed here: the changes in
    /// the git repository pane `pane` is in, side by side in a new tab. A
    /// tmux pane's folder comes from tmux (an agent there reports none);
    /// another pane's from its shell (OSC 7 or the prompt).
    fn show_changes(&mut self, pane: PaneId) -> Option<Command> {
        if self.pane_connection(pane).is_none() {
            return Some(Command::Notice(DIFF_HOW.into()));
        }
        if let Some(g) = self.panes.get(&pane).and_then(Pane::gateway) {
            let actions = self
                .tmux
                .get_mut(&g)
                .filter(|t| t.active())
                .map(|t| t.ask_diff_dir(pane))
                .unwrap_or_default();
            if !actions.is_empty() {
                self.run_tmux(g, actions);
                return None;
            }
        }
        let Some(dir) = self.panes.get(&pane).and_then(|p| p.cwd.clone()) else {
            return Some(Command::Notice(
                "FeroSSH does not know which folder this pane is in: its shell has not \
                 said (by OSC 7, or in a prompt FeroSSH can read). Run the agent in tmux, \
                 or use this from a shell in the project's folder."
                    .into(),
            ));
        };
        self.open_diff(pane, dir)
    }

    /// Opens a tab showing what changed in the git repository folder `dir`
    /// is in, on pane `from`'s connection, and starts git there.
    fn open_diff(&mut self, from: PaneId, dir: Vec<u8>) -> Option<Command> {
        // A tmux pane gets a new id when its gateway reconnects; the
        // gateway keeps its own, so r follows that one.
        let source = self.host_pane(from);
        let Some(connection) = self.pane_connection(from) else {
            return Some(Command::Notice(DIFF_HOW.into()));
        };
        if crate::diff::input(&dir).is_none() {
            return Some(Command::Notice(
                "That folder's name has a line break in it; FeroSSH cannot ask git about it."
                    .into(),
            ));
        }
        let (label, theme, lock) = self.panes.get(&from).map_or_else(
            || {
                (
                    String::new(),
                    self.default_theme.clone(),
                    look::Lock::default(),
                )
            },
            |p| (p.host_label(), p.theme.clone(), p.lock.clone()),
        );
        let id = self.new_tab_pane();
        if let Some(p) = self.panes.get_mut(&id) {
            p.lock = lock;
            // The host's look (a Production host stays red), room for the
            // longest diff shown, and never part of a broadcast.
            p.term.set_theme(&theme);
            p.theme = theme;
            p.term.set_settings(&term_settings(Some(
                crate::diff::MAX_ROWS + DIFF_SPARE_ROWS,
            )));
            p.no_broadcast = true;
            p.host = Host::Diff(Box::new(DiffTab {
                connection,
                label,
                dir,
                channel: None,
                out: Vec::new(),
                err: Vec::new(),
                status: None,
                partial: false,
                interrupted: None,
                from: source,
                shown: None,
                files: Vec::new(),
            }));
        }
        // The enforced font and size too (the lock holds them from now on).
        if let Some(font) = self.panes.get(&id).map(|p| p.font.clone()) {
            self.set_font(id, font);
        }
        self.run_diff(id);
        // Keys go to the new tab, not to a tools pane that had them.
        self.focus_terminal();
        self.refresh_chrome();
        self.request_full_redraw();
        None
    }

    /// Which connection the git of diff channel `channel` runs on.
    fn diff_on(&self, channel: ChannelId) -> Option<ChannelId> {
        let id = self.diffs.get(&channel)?;
        match &self.panes.get(id)?.host {
            Host::Diff(d) if d.channel == Some(channel) => Some(d.connection),
            _ => None,
        }
    }

    /// Runs git for diff tab `id` (again): what it shows now stays until
    /// the answer is in.
    fn run_diff(&mut self, id: PaneId) {
        self.stop_diff(id);
        let channel = self.new_channel();
        // The connection it came from, or the one the pane it was opened
        // from has now (after a reconnect).
        let from = match self.panes.get(&id).map(|p| &p.host) {
            Some(Host::Diff(d)) if !self.workers.contains_key(&d.connection) => {
                self.pane_connection(d.from)
            }
            _ => None,
        };
        let Some(Host::Diff(d)) = self.panes.get_mut(&id).map(|p| &mut p.host) else {
            return;
        };
        if let Some(c) = from {
            d.connection = c;
        }
        let (Some(w), Some(input)) = (self.workers.get(&d.connection), crate::diff::input(&d.dir))
        else {
            let label = crate::ssh::sanitize(&d.label);
            self.show(
                id,
                &format!(
                    "\x1b[?7h\r\n\x1b[0;31mThe connection to {label} is closed. Reconnect the \
                     pane this was opened from, then press r here; or open it again from a pane \
                     logged in there.\x1b[0m"
                ),
            );
            // Below a long diff: brought into view.
            if let Some(p) = self.panes.get_mut(&id) {
                p.term.scroll_to_bottom();
                p.grid.mark_all_dirty();
            }
            self.refresh(id);
            return;
        };
        w.link.send(Message::Exec {
            channel,
            connection: d.connection,
            command: crate::diff::command(),
            split_stderr: true,
        });
        w.link.send(Message::Data {
            channel,
            bytes: input,
        });
        w.link.send(Message::Eof { channel });
        d.channel = Some(channel);
        d.out.clear();
        d.err.clear();
        d.status = None;
        d.partial = false;
        d.interrupted = None;
        let first = d.shown.is_none();
        let dir = crate::diff::clean(&String::from_utf8_lossy(&d.dir));
        let label = crate::diff::clean(&d.label);
        self.diffs.insert(channel, id);
        if first {
            self.show(
                id,
                &format!(
                    "\x1b[?25l\x1b[0;90mAsking git on {label} what changed in {dir}...\x1b[0m"
                ),
            );
            self.refresh(id);
        }
    }

    /// Stops diff tab `id`'s git, if it runs.
    fn stop_diff(&mut self, id: PaneId) {
        let Some(Host::Diff(d)) = self.panes.get_mut(&id).map(|p| &mut p.host) else {
            return;
        };
        if let Some(channel) = d.channel.take() {
            self.diffs.remove(&channel);
            if let Some(w) = self.workers.get(&d.connection) {
                w.link.send(Message::Close { channel });
            }
        }
    }

    /// What git said for a diff tab, or that it ended.
    fn on_diff(&mut self, channel: ChannelId, msg: Message) {
        /// Of standard error, the end is enough to say what went wrong.
        const ERR: usize = 4096;
        let Some(&id) = self.diffs.get(&channel) else {
            return;
        };
        let Some(Host::Diff(d)) = self.panes.get_mut(&id).map(|p| &mut p.host) else {
            self.diffs.remove(&channel);
            return;
        };
        let done = match msg {
            Message::Data { bytes, .. } => {
                let room = crate::diff::KEEP.saturating_sub(d.out.len());
                if let Some(part) = bytes.get(..room).filter(|_| bytes.len() > room) {
                    d.out.extend_from_slice(part);
                    d.partial = true;
                    true
                } else {
                    d.out.extend_from_slice(&bytes);
                    false
                }
            }
            Message::ExecStderr { bytes, .. } => {
                d.err.extend_from_slice(&bytes);
                if d.err.len() > ERR {
                    let cut = d.err.len() - ERR;
                    d.err.drain(..cut);
                }
                false
            }
            Message::ExitStatus { code, .. } => {
                d.status = Some(code);
                false
            }
            Message::Disconnected { reason, .. } => {
                // git's exit status comes first when it ran to its end.
                if d.status.is_none() && !d.partial {
                    d.interrupted = Some(reason);
                }
                true
            }
            _ => false,
        };
        if !done {
            return;
        }
        if d.partial {
            // Enough: the part read so far shows.
            if let Some(w) = self.workers.get(&d.connection) {
                w.link.send(Message::Close { channel });
            }
        }
        self.diffs.remove(&channel);
        d.channel = None;
        let out = std::mem::take(&mut d.out);
        d.shown = Some(Shown {
            outcome: crate::diff::parse(&out),
            partial: d.partial,
            interrupted: d.interrupted.take(),
            err: std::mem::take(&mut d.err),
            status: d.status,
        });
        self.render_diff(id);
    }

    /// Lays diff tab `id` out again at its width: the whole text is
    /// written anew, from its top.
    fn render_diff(&mut self, id: PaneId) {
        let Some(p) = self.panes.get_mut(&id) else {
            return;
        };
        let cols = p.term.cols();
        let look = crate::diff::Look {
            removed: rgb(mix(p.theme.background, Rgb::new(220, 50, 50), 0.22)),
            added: rgb(mix(p.theme.background, Rgb::new(50, 180, 70), 0.2)),
        };
        let Host::Diff(d) = &mut p.host else {
            return;
        };
        let say = |text: &str| format!("{}\x1b[0m", crate::diff::clean(text));
        let dir = crate::diff::clean(&String::from_utf8_lossy(&d.dir));
        let Some(shown) = &d.shown else {
            return;
        };
        let mut wrap = true;
        let text = match &shown.outcome {
            crate::diff::Outcome::NoGit => say(&format!("{} has no git command.", d.label)),
            crate::diff::Outcome::NoDir => say(&format!(
                "The folder {dir} is not on {} any more, or cannot be entered.",
                d.label
            )),
            crate::diff::Outcome::NoRepo => say(&format!(
                "{dir} is not in a git repository, so there is nothing to compare with."
            )),
            crate::diff::Outcome::Changes(diff)
                if diff.top.is_empty() && shown.interrupted.is_some() =>
            {
                say(&format!(
                    "The connection dropped before git answered ({}). Press r to try again.",
                    shown.interrupted.as_deref().unwrap_or("")
                ))
            }
            crate::diff::Outcome::Changes(diff) if diff.top.is_empty() => {
                let err = String::from_utf8_lossy(&shown.err);
                let why = err
                    .lines()
                    .rev()
                    .find(|l| !l.trim().is_empty())
                    .unwrap_or("");
                let status = shown
                    .status
                    .map(|c| format!(" (exit status {c})"))
                    .unwrap_or_default();
                say(&format!(
                    "The server could not run git for this{status}: {why}. It needs sh and \
                     git, as Linux and macOS servers have."
                ))
            }
            crate::diff::Outcome::Changes(diff) => {
                let mut notes = Vec::new();
                if shown.partial {
                    notes.push("Only part of the changes: there was too much to show.".to_owned());
                }
                if let Some(why) = &shown.interrupted {
                    notes.push(format!(
                        "git stopped before it finished ({}), so files may be missing here.",
                        crate::diff::clean(why)
                    ));
                }
                let r = crate::diff::render(diff, cols, &look, &notes);
                d.files = r.files;
                // Laid out at least 20 columns wide: a narrower pane cuts
                // the rows instead of wrapping them, so each stays one
                // line and n/p find the headings.
                wrap = false;
                r.text
            }
        };
        if wrap {
            d.files.clear();
        }
        // Plain messages wrap.
        p.term.feed(if wrap {
            b"\x1b[?25l\x1b[?7h\x1b[0m\x1b[2J\x1b[3J\x1b[H"
        } else {
            b"\x1b[?25l\x1b[?7l\x1b[0m\x1b[2J\x1b[3J\x1b[H"
        });
        p.term.clear_scrollback();
        p.term.feed(text.as_bytes());
        p.term.scroll_to_top();
        p.grid.mark_all_dirty();
        self.refresh(id);
    }

    /// A key in a diff tab: r looks again, n and p go to the next and
    /// previous file, and the usual keys scroll. Nothing goes to a host.
    fn diff_key(&mut self, id: PaneId, bytes: &[u8]) {
        let Some(p) = self.panes.get_mut(&id) else {
            return;
        };
        let page = i32::try_from(p.term.rows().saturating_sub(1).max(1)).unwrap_or(1);
        match bytes {
            b"r" | b"R" => {
                self.run_diff(id);
                return;
            }
            b"n" | b"p" | b"N" | b"P" => {
                let Host::Diff(d) = &p.host else {
                    return;
                };
                let history = p.term.history_len();
                let top = history - p.term.display_offset().min(history);
                let target = if bytes.eq_ignore_ascii_case(b"n") {
                    d.files.iter().copied().find(|&r| r > top)
                } else {
                    d.files.iter().rev().copied().find(|&r| r < top)
                };
                let Some(row) = target else {
                    return;
                };
                p.term.scroll_to_bottom();
                p.term
                    .scroll_lines(i32::try_from(history.saturating_sub(row)).unwrap_or(i32::MAX));
            }
            b"\x1b[A" | b"\x1bOA" | b"k" => p.term.scroll_lines(1),
            b"\x1b[B" | b"\x1bOB" | b"j" | b"\r" => p.term.scroll_lines(-1),
            b"\x1b[5~" | b"b" => p.term.scroll_lines(page),
            b"\x1b[6~" | b" " => p.term.scroll_lines(-page),
            b"\x1b[H" | b"\x1bOH" | b"\x1b[1~" | b"g" => p.term.scroll_to_top(),
            b"\x1b[F" | b"\x1bOF" | b"\x1b[4~" | b"G" => p.term.scroll_to_bottom(),
            _ => return,
        }
        p.grid.mark_all_dirty();
        self.refresh(id);
    }

    fn fill_agents(&mut self, menu: HMENU) {
        let commands = crate::agents::commands(&self.settings.agent_commands);
        // SAFETY: our popup menu; it is being opened, when changing it is
        // allowed. Everything after Agent dashboard, Show what changed and
        // the six options is replaced.
        unsafe {
            while GetMenuItemCount(Some(menu)) > 8 {
                let _ = DeleteMenu(menu, 8, MF_BYPOSITION);
            }
            let _ = AppendMenuW(menu, MF_SEPARATOR, 0, None);
            for (id, c) in (cmd::AGENT_START..cmd::AGENT_END).zip(&commands) {
                let label = format!("Start {} in tmux", c.replace('&', "&&"));
                let _ = AppendMenuW(menu, MF_STRING, id as usize, &HSTRING::from(label));
            }
        }
    }

    /// Starts coding agent `command` from pane `id`, in tmux on its server
    /// (see [`crate::agents`]): in a new window of the tmux session that
    /// shows on that host, or else in session `agents`, attached here.
    /// A pane with the Production theme asks first, while Session >
    /// Scripts > Confirm scripts and agents on Production hosts is on.
    fn start_agent(&mut self, id: PaneId, command: &str) -> Option<Command> {
        if self.settings.confirm_production
            && let Some(p) = self.panes.get(&id)
            && p.theme.name == "Production"
        {
            return Some(Command::ConfirmAgent {
                pane: id,
                command: command.to_owned(),
                host: p.host_label(),
            });
        }
        self.start_agent_now(id, command)
    }

    /// [`Self::start_agent`], asked already where it asks.
    fn start_agent_now(&mut self, id: PaneId, command: &str) -> Option<Command> {
        const HOW: &str = "A coding agent starts in tmux on a server: use it from a pane \
            that is logged in to one over SSH.";
        // A tmux pane: a new window in its own session.
        if let Some(g) = self.panes.get(&id).and_then(Pane::gateway) {
            let actions = self
                .tmux
                .get_mut(&g)
                .filter(|t| t.active())
                .map(|t| t.start_agent(id, command, None))?;
            self.run_tmux(g, actions);
            return None;
        }
        let Some(Host::Ssh(s)) = self.panes.get(&id).map(|p| &p.host) else {
            return Some(Command::Notice(HOW.into()));
        };
        if s.state() != State::Connected || s.target.no_shell() {
            return Some(Command::Notice(HOW.into()));
        }
        if s.target.mosh.is_some() {
            return Some(Command::Notice(
                "tmux integration needs an SSH shell: it does not work over Mosh, so coding \
                 agents cannot start from a Mosh pane."
                    .into(),
            ));
        }
        // A RemoteCommand runs instead of the shell: nothing would read
        // the line that starts tmux.
        if s.target.command.is_some() {
            return Some(Command::Notice(
                "This connection runs a RemoteCommand instead of a shell, so a coding agent \
                 cannot start from it."
                    .into(),
            ));
        }
        // tmux already shows on this host (only one pane per host may),
        // reached the same way: the agent joins that session.
        let route = route_key(&s.target);
        let shown = self
            .tmux
            .iter()
            .find(|(g, t)| {
                t.active()
                    && matches!(
                        self.panes.get(g).map(|p| &p.host),
                        Some(Host::Ssh(other)) if route_key(&other.target) == route
                    )
            })
            .map(|(g, _)| *g);
        if let Some(g) = shown {
            // In this shell's directory, when it is known as an absolute
            // path; otherwise the tmux pane's.
            let dir = self
                .panes
                .get(&id)
                .and_then(|p| p.cwd.as_deref())
                .and_then(|d| std::str::from_utf8(d).ok())
                .filter(|d| d.starts_with('/'))
                .map(str::to_owned);
            let next_to = self.tmux.get(&g).and_then(|t| t.natives().first().copied());
            let actions = match (self.tmux.get_mut(&g), next_to) {
                (Some(t), Some(n)) => t.start_agent(n, command, dir.as_deref()),
                // Still bringing its windows back.
                _ => {
                    return Some(Command::Notice(
                        "tmux on this host is still starting; try again in a moment.".into(),
                    ));
                }
            };
            self.run_tmux(g, actions);
            return None;
        }
        let line = crate::agents::start_line(command);
        self.send_host(id, line.as_bytes());
        self.attach_tmux(id, crate::agents::SESSION, false);
        None
    }

    /// A tmux pane just appeared: if its window runs a coding agent, its
    /// output is watched, for its state in the Session manager and, with
    /// notifications on, to say when it goes quiet.
    fn watch_agent(&mut self, gateway: PaneId, native: PaneId) {
        let agent = self
            .tmux
            .get(&gateway)
            .and_then(|t| t.agent_of(native))
            .is_some();
        if let Some(p) = self.panes.get_mut(&native)
            && agent
            && p.quiet.is_none()
        {
            p.quiet = Some(crate::attention::Watch::new());
            self.update_quiet_timer();
        }
        if agent && self.settings.agent_audit {
            self.audit_agent(native);
        }
    }

    /// Session > Coding agents > Log and record agent panes: starts the
    /// sealed log and the recording of agent pane `id`, unless they run
    /// already. Their files are named after the host and the agent.
    fn audit_agent(&mut self, id: PaneId) {
        let Some(agent) = self.agent_of(id).map(str::to_owned) else {
            return;
        };
        let Some(p) = self.panes.get_mut(&id) else {
            return;
        };
        let record = p.cast.is_none();
        p.log.enabled = true;
        // An ordinary log opened before the pane was known to run an agent
        // ends, and the agent's own log follows it.
        if p.log.writer.is_some() && p.log.agent.as_deref() != Some(agent.as_str()) {
            self.stop_log(id);
        }
        self.start_log_as(id, Some(&agent));
        if record {
            let text = self.start_recording(id, Some(&agent));
            self.show(id, &text);
        }
        self.update_menu_checks();
    }

    /// The yes-or-no question coding agent pane `id` shows, while Session >
    /// Coding agents > Answer yes-or-no questions from the notification
    /// is on.
    fn agent_question(&self, id: PaneId) -> Option<crate::agents::Question> {
        if !self.settings.answer_from_notification {
            return None;
        }
        self.agent_of(id)?;
        crate::agents::question(&self.panes.get(&id)?.term.screen_text())
    }

    /// Answers the question agent pane `id` showed (`asked`), yes or no,
    /// if it still shows it: the agent may have moved on, or been
    /// answered in its pane, since the notification. Returns what to tell
    /// the user when it was not answered.
    fn answer_agent(
        &mut self,
        id: PaneId,
        asked: &crate::agents::Question,
        yes: bool,
    ) -> Option<Command> {
        let now = self
            .agent_of(id)
            .and_then(|_| self.panes.get(&id))
            .and_then(|p| crate::agents::question(&p.term.screen_text()));
        if now.as_ref() != Some(asked) {
            return Some(Command::Notice(format!(
                "The agent no longer asks \"{}\", so nothing was typed. Its pane shows \
                 what it does now.",
                asked.text
            )));
        }
        let keys = if yes { &asked.yes } else { &asked.no };
        self.input(id, keys.clone());
        if let Some(p) = self.panes.get_mut(&id) {
            p.attention = false;
        }
        self.refresh_chrome();
        None
    }

    /// Each of `panes` that is still open, with the coding agent it runs
    /// and whether it has the Production theme: what a paste was confirmed
    /// for.
    fn receivers(&self, panes: &[PaneId], text: &str) -> Vec<Receiver> {
        panes
            .iter()
            .filter_map(|id| {
                let p = self.panes.get(id)?;
                Some((
                    *id,
                    self.agent_of(*id).map(str::to_owned),
                    p.theme.name == "Production",
                    self.link_of(*id),
                    self.scripts.get(id).is_some_and(|r| r.runner.prompting()),
                    p.term.paste(text).bytes,
                ))
            })
            .collect()
    }

    /// Which SSH connection pane `id` types into, and whether it is logged
    /// in: each connection has a channel of its own, so a reconnect (or a
    /// login prompt) is not the shell a paste was confirmed for. A tmux
    /// pane types into its gateway's connection.
    fn link_of(&self, id: PaneId) -> Option<(ChannelId, bool)> {
        match &self.panes.get(&id)?.host {
            Host::Ssh(s) => Some((
                s.channel,
                s.state() == State::Connected && !s.prompt_active(),
            )),
            Host::Tmux { gateway, .. } => self.link_of(*gateway),
            _ => None,
        }
    }

    /// The Production-themed panes among `panes` that run a coding agent,
    /// as "agent on host", while Confirm scripts and agents on Production
    /// hosts is on: input for them asks first.
    fn production_agents(&self, panes: &[PaneId]) -> Vec<String> {
        if !self.settings.confirm_production {
            return Vec::new();
        }
        panes
            .iter()
            .filter_map(|id| {
                let p = self.panes.get(id)?;
                let agent = self.agent_of(*id)?;
                (p.theme.name == "Production").then(|| format!("{agent} on {}", p.host_label()))
            })
            .collect()
    }

    /// The coding agent pane `id` runs, by name, if it runs one.
    fn agent_of(&self, id: PaneId) -> Option<&str> {
        let g = self.panes.get(&id).and_then(Pane::gateway)?;
        self.tmux.get(&g)?.agent_of(id)
    }

    /// Pane `id` asks for attention: a notification the host sent (with
    /// its heading `what`), the bell, or quiet after work. Unless the user
    /// is looking at it, its tab gets a badge, and unless it is in sight
    /// in the window in front, a Windows notification goes up (at most
    /// one per pane every few seconds). Only with Settings > Desktop
    /// notifications on. Returns whether the tab strip must redraw.
    fn alert(&mut self, id: PaneId, what: Option<String>, body: String) -> bool {
        if !self.settings.notifications {
            return false;
        }
        // SAFETY: plain query.
        let front = unsafe { GetForegroundWindow() } == self.hwnd;
        let visible = self.is_visible(id);
        if front && visible && self.focused_id() == id {
            return false;
        }
        let now = Instant::now();
        let Some(p) = self.panes.get_mut(&id) else {
            return false;
        };
        let badge = !std::mem::replace(&mut p.attention, true);
        if badge {
            p.attention_since = Some(Instant::now());
        }
        if (front && visible) || !p.throttle.allow(now) {
            return badge;
        }
        // Each balloon is paired with its pane in order: with too many
        // waiting, this one keeps only its badge.
        if self.toast_queue.len() >= MAX_TOAST_QUEUE {
            return badge;
        }
        let pane = p.label();
        let title = crate::attention::heading(what.as_deref(), &pane);
        let body = match self.agent_question(id) {
            Some(q) => format!("{}\nClick to answer yes or no.", q.text),
            None => body,
        };
        self.toast_queue.push_back(id);
        let waiting = self.panes.values().filter(|p| p.attention).count();
        self.queued.push(Command::Toast {
            pane: id,
            title,
            body,
            waiting: match waiting {
                1 => "FeroSSH: a pane wants you".to_owned(),
                n => format!("FeroSSH: {n} panes want you"),
            },
        });
        badge
    }

    /// Whether pane `id` still wants the user and is out of their sight,
    /// so its queued Windows notification should go up.
    fn still_wants(&self, id: PaneId) -> bool {
        // SAFETY: plain query.
        let front = unsafe { GetForegroundWindow() } == self.hwnd;
        self.settings.notifications
            && self.panes.get(&id).is_some_and(|p| p.attention)
            && !(front && self.is_visible(id))
    }

    /// Pane `id`'s balloon did not go up: it is not waiting its turn.
    fn toast_dropped(&mut self, id: PaneId) {
        if let Some(i) = self.toast_queue.iter().rposition(|&p| p == id) {
            self.toast_queue.remove(i);
        }
    }

    /// Explorer made the taskbar anew: balloons asked for before are gone.
    fn toasts_lost(&mut self) {
        self.toast_queue.clear();
        self.toast_pane = None;
    }

    /// Session > Notify when this pane goes quiet: on or off for pane `id`.
    fn toggle_quiet(&mut self, id: PaneId) {
        let notifications = self.settings.notifications;
        if let Some(p) = self.panes.get_mut(&id) {
            p.quiet = match p.quiet.take() {
                Some(_) => None,
                // A shortcut works while the menu item is greyed.
                None if !notifications || !quiet_watchable(p) => None,
                None => Some(crate::attention::Watch::new()),
            };
        }
        self.update_quiet_timer();
        self.update_menu_checks();
    }

    /// Runs the once-a-second check while any pane has a quiet watch.
    /// Also runs while the Session manager is shown with an agent pane
    /// open, so each agent's state and last line there stay current.
    fn update_quiet_timer(&self) {
        let shown = self.side.visible && self.side.view == SideView::Live;
        let any = self.panes.values().any(|p| p.quiet.is_some())
            || (shown && self.panes.keys().any(|id| self.agent_of(*id).is_some()));
        // SAFETY: our window and timer id.
        unsafe {
            if any {
                SetTimer(Some(self.hwnd), TIMER_QUIET, 1000, None);
            } else {
                let _ = KillTimer(Some(self.hwnd), TIMER_QUIET);
            }
        }
    }

    /// The quiet watches' tick: a pane whose stretch of output just ended
    /// asks for attention.
    fn on_quiet_timer(&mut self) -> Vec<Command> {
        // A pane that reconnected as SFTP-only has no shell left to watch.
        let mut dropped = false;
        for p in self.panes.values_mut() {
            if p.quiet.is_some() && !quiet_watchable(p) {
                p.quiet = None;
                dropped = true;
            }
        }
        if dropped {
            self.update_menu_checks();
        }
        // Stops once the last watched pane closed and the Session manager
        // has no agent to keep current.
        self.update_quiet_timer();
        let now = Instant::now();
        let mut quiet = Vec::new();
        for (id, p) in &mut self.panes {
            if let Some(worked) = p.quiet.as_mut().and_then(|w| w.tick(now)) {
                quiet.push((*id, worked));
            }
        }
        // The Session manager shows each agent's state: keep it current.
        let mut chrome = false;
        if self.side.visible && self.side.view == SideView::Live {
            // As the rows say it: the state and how long, so "quiet 5 s"
            // does not stay while it is a minute.
            let states: Vec<AgentShown> = self
                .panes
                .iter()
                .filter(|(id, _)| self.agent_of(**id).is_some())
                .map(|(id, p)| {
                    let state = p
                        .quiet
                        .as_ref()
                        .map_or(crate::attention::State::Idle, |w| w.state(now));
                    let asked = p.attention_since.filter(|_| p.attention);
                    let (what, since) = crate::agents::status(asked, state, now);
                    (
                        *id,
                        what,
                        since.map(crate::attention::spoken),
                        crate::agents::last_line(&p.term.screen_text()),
                    )
                })
                .collect();
            if states != self.agent_states {
                self.agent_states = states;
                chrome = true;
            }
        }
        for (id, worked) in quiet {
            let body = format!(
                "Output stopped after {} of work: done, or waiting for you.",
                crate::attention::spoken(worked)
            );
            chrome |= self.alert(id, None, body);
        }
        if chrome {
            self.refresh_chrome();
        }
        std::mem::take(&mut self.queued)
    }

    /// A Windows notification came on screen: the oldest one asked for.
    fn on_toast_shown(&mut self) {
        if let Some(id) = self.toast_queue.pop_front() {
            self.toast_pane = Some(id);
        }
    }

    /// The pane a click on a notification (or the icon) is for: the one
    /// on screen, or, clicked later from the notification centre, which
    /// does not say which one, or on the icon: a pane that still wants
    /// the user. Decided before FeroSSH comes forward, which takes the
    /// badge off the pane that has the keyboard.
    fn toast_target(&self) -> Option<PaneId> {
        let wants = |id: PaneId| self.panes.get(&id).is_some_and(|p| p.attention);
        self.toast_pane.filter(|&id| wants(id)).or_else(|| {
            self.panes
                .iter()
                .find(|(_, p)| p.attention)
                .map(|(&id, _)| id)
        })
    }

    /// The user clicked a notification and FeroSSH came forward: pane
    /// `target` ([`Self::toast_target`]) comes forward with the keyboard.
    /// With Session > Coding agents > Answer yes-or-no questions from the
    /// notification on, a coding agent that asks one is answered from a
    /// dialog instead, and its tab is not switched to.
    fn on_toast_click(&mut self, target: Option<PaneId>) -> Vec<Command> {
        if let Some(id) = target {
            if self.toast_pane == Some(id) {
                self.toast_pane = None;
            }
            if let Some(question) = self.agent_question(id) {
                let p = self.panes.get(&id);
                self.queued.push(Command::AnswerAgent {
                    pane: id,
                    agent: self.agent_of(id).unwrap_or("agent").to_owned(),
                    host: p.map(Pane::host_label).unwrap_or_default(),
                    production: p.is_some_and(|p| p.theme.name == "Production"),
                    question,
                });
            } else if self.panes.contains_key(&id)
                && let Some(c) = self.live_action(Some(LiveAction::Show(id)))
            {
                self.queued.push(c);
            }
        }
        std::mem::take(&mut self.queued)
    }

    /// Starts Help > Check for updates in the background, unless one is
    /// already running; its answer wakes the window like shell output.
    fn start_update_check(&mut self, asked: bool) {
        if self.update.is_some() {
            return;
        }
        let (tx, rx) = std::sync::mpsc::channel();
        let wake = self.notifier();
        let spawned = std::thread::Builder::new()
            .name("update-check".into())
            .spawn(move || {
                let _ = tx.send(crate::update::check());
                wake();
            });
        if spawned.is_ok() {
            self.update = Some((rx, asked));
        }
    }

    /// The finished update check's answer, as a command that shows it.
    fn poll_update_check(&mut self) -> Option<Command> {
        let (rx, asked) = self.update.as_ref()?;
        let asked = *asked;
        let outcome = match rx.try_recv() {
            Ok(outcome) => outcome,
            Err(std::sync::mpsc::TryRecvError::Empty) => return None,
            Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                crate::update::Outcome::Failed("the check stopped".into())
            }
        };
        self.update = None;
        if !matches!(outcome, crate::update::Outcome::Failed(_)) {
            crate::update::checked();
        }
        Some(Command::UpdateFound { outcome, asked })
    }

    fn on_sync_timer(&mut self) -> Vec<Command> {
        // SAFETY: our window and timer.
        unsafe {
            let _ = KillTimer(Some(self.hwnd), TIMER_SYNC);
        }
        let soon = Instant::now() + Duration::from_millis(1);
        for p in self.panes.values_mut() {
            if p.term.sync_deadline().is_some_and(|d| d <= soon) {
                p.term.flush_sync();
            }
        }
        self.after_feed()
    }

    /// Copies a visible pane's terminal into its grid and asks Windows to
    /// repaint the rows that changed.
    fn refresh(&mut self, id: PaneId) {
        if !self.is_visible(id) {
            return;
        }
        let keyboard = self.has_keyboard(id);
        let Some(pane) = self.panes.get_mut(&id) else {
            return;
        };
        let old = pane.cursor;
        pane.cursor = pane.term.draw_into(&mut pane.grid, keyboard);
        if self.settings.command_suggestions {
            let done = pane.typing.poll(&pane.term);
            if let Some(line) = done {
                self.keep_command(id, &line);
            }
            let ghost = self.find_ghost(id);
            if ghost.is_some() || self.ghost.as_ref().is_some_and(|g| g.pane == id) {
                self.ghost = ghost;
            }
            self.draw_ghost(id);
        }
        let Some(pane) = self.panes.get_mut(&id) else {
            return;
        };
        if old != pane.cursor {
            for c in [old, pane.cursor].into_iter().flatten() {
                pane.grid.mark_dirty(c.y);
            }
        }
        // A moved or hidden mark: repaint the rows under where it was and
        // where it goes; the mark itself is drawn over them as a fill.
        let mark = pane.scroll_mark(self.dpi);
        if mark != pane.mark {
            let (_, oy) = pane.origin(self.dpi);
            let ch = pane.metrics.height.max(1) as i32;
            let last = pane.grid.rows().saturating_sub(1);
            for r in [pane.mark, mark].into_iter().flatten() {
                let first = ((r.y - oy) / ch).max(0) as usize;
                let end = ((r.bottom() - 1 - oy) / ch).max(0) as usize;
                for y in first.min(last)..=end.min(last) {
                    pane.grid.mark_dirty(y);
                }
            }
            pane.mark = mark;
        }
        self.invalidate_dirty(id);
    }

    fn refresh_visible(&mut self) {
        for id in self.visible_ids() {
            self.refresh(id);
        }
    }

    /// The colours of the drawn side pane tools: the window's own (the
    /// focused pane's theme by default), or with Windows' light look the
    /// focused pane's theme, as before window colours existed.
    fn chrome_palette(&self) -> Palette {
        let c = self.ui_colours();
        if c.custom {
            return c.strip;
        }
        let theme = self
            .panes
            .get(&self.focused_id())
            .map_or_else(|| self.default_theme.clone(), |p| p.theme.clone());
        Palette::of(&theme)
    }

    /// The window's own colours (Settings > Window colours): by default
    /// from the focused pane's theme.
    fn ui_colours(&self) -> UiColours {
        let theme = self
            .panes
            .get(&self.focused_id())
            .map_or(&self.default_theme, |p| &p.theme);
        let mode = self.settings.window_colours;
        // A theme previewed on this pane may carry the committed theme's
        // name: its own window colours come from the item shown.
        let previewed = self
            .look_preview
            .as_ref()
            .filter(|p| p.pane == self.focused_id())
            .and_then(|p| p.theme_by);
        let custom = match previewed {
            Some(id) => self.custom_at(id),
            None => self.custom_named(theme.name),
        };
        if mode == WindowColours::Theme
            && let Some(custom_theme::WindowSpec::Colours(bg, text, accent)) =
                custom.and_then(|c| c.window)
        {
            return ui_colours::custom(bg, text, accent);
        }
        ui_colours::resolve(
            mode,
            theme,
            &ui_theme::system(mode == WindowColours::System),
        )
    }

    /// The tab strip's colours: the menu bar's, so the strip reads as part
    /// of the window frame rather than of a terminal.
    fn strip_palette(&self) -> Palette {
        self.ui_colours().strip
    }

    /// What the tools rail shows: the open tool, the pin, and the tab
    /// strip's (system menu bar) colours.
    fn rail_look(&self) -> rail::Look {
        let p = self.strip_palette();
        let active = self.side.visible.then_some(match self.side.view {
            SideView::Sessions => RailItem::Connections,
            SideView::Live => RailItem::Sessions,
            SideView::Files => RailItem::Files,
            SideView::Forwards => RailItem::Forwards,
            SideView::Snippets => RailItem::Snippets,
            SideView::KnownHosts => RailItem::KnownHosts,
            SideView::Inventory => RailItem::Inventory,
            SideView::Hosts => RailItem::Hosts,
            SideView::Credentials => RailItem::Credentials,
            SideView::SecurityRules => RailItem::SecurityRules,
            SideView::Themes => RailItem::Themes,
            SideView::ThemeRules => RailItem::ThemeRules,
            SideView::Palette => RailItem::Palette,
        });
        rail::Look {
            active,
            pinned: self.settings.tools_pinned,
            background: p.strip,
            selected: p.active,
            text: p.text,
            accent: p.accent,
            dpi: self.dpi,
        }
    }

    /// Whether the connection manager shows as native controls: its list
    /// is open (not the session form or the import page, which have
    /// their own).
    fn conn_native(&self) -> bool {
        self.side.visible
            && self.side.view == SideView::Sessions
            && self.side.form.is_none()
            && self.side.import.is_none()
    }

    /// Whether the session manager shows as native controls.
    fn live_native(&self) -> bool {
        self.side.visible && self.side.view == SideView::Live
    }

    /// Whether the command palette shows as native controls.
    fn palette_native(&self) -> bool {
        self.side.visible && self.side.view == SideView::Palette
    }

    /// Reads the known_hosts files again for Tools > Known hosts: the one
    /// FeroSSH writes and the `UserKnownHostsFile`s `~/.ssh/config` names.
    /// A file that cannot be read is named in the panel.
    fn reload_known_hosts(&mut self) {
        let env = ssh_env();
        let files = known_hosts_view::files_to_list(&env.known_hosts(), &env.config, &env.home);
        self.known_hosts_view.reload(files);
    }

    /// Whether the known hosts manager shows (always native controls).
    fn known_hosts_native(&self) -> bool {
        self.side.visible && self.side.view == SideView::KnownHosts
    }

    /// Reads the inventory and the connections again for Tools >
    /// Inventory, and shows them.
    fn reload_inventory(&mut self) {
        // A file that cannot be read leaves what the list showed, and
        // says why: a reload never blanks the login history.
        let inventory = match crate::inventory_view::read() {
            Ok(inventory) => inventory,
            Err(e) => {
                inventory_panel::set_status(format!("Could not read the connection log: {e}"));
                return;
            }
        };
        let items = host_items(&ssh_env(), &self.settings);
        let rows = crate::inventory_view::rows(&items, &inventory, &self.settings);
        inventory_panel::set_rows(
            rows,
            self.download_dir(),
            self.settings.connection_log_delete,
        );
    }

    /// Whether the inventory shows (always native controls).
    fn inventory_native(&self) -> bool {
        self.side.visible && self.side.view == SideView::Inventory
    }

    /// Reads the inventory and the connections again for Tools > Hosts,
    /// and shows them taken together by machine.
    fn reload_hosts(&mut self) {
        // As for Inventory: a file that cannot be read leaves the list.
        let inventory = match crate::inventory_view::read() {
            Ok(inventory) => inventory,
            Err(e) => {
                hosts_panel::set_status(format!("Could not read the connection log: {e}"));
                return;
            }
        };
        let items = host_items(&ssh_env(), &self.settings);
        let rows = crate::inventory_view::rows(&items, &inventory, &self.settings);
        hosts_panel::set_rows(crate::hosts_view::hosts(&rows));
    }

    /// Whether the hosts show (always native controls).
    fn hosts_native(&self) -> bool {
        self.side.visible && self.side.view == SideView::Hosts
    }

    /// Reads the credentials and saved passwords again for Tools >
    /// Credential manager, and shows them.
    fn reload_credentials(&mut self) {
        credential_panel::set_rows(self.credential_rows());
    }

    /// Whether the credential manager shows (always native controls).
    fn credentials_native(&self) -> bool {
        self.side.visible && self.side.view == SideView::Credentials
    }

    /// Reads the security rules again for Tools > Security rules, and
    /// shows them: what another FeroSSH changed in a shared settings file
    /// first, as a save would.
    fn reload_rules(&mut self) {
        self.pull_vault_settings();
        rules_panel::set_rows(self.rule_rows());
    }

    /// Whether the security rules show (always native controls).
    fn rules_native(&self) -> bool {
        self.side.visible && self.side.view == SideView::SecurityRules
    }

    /// Reads the theme rules, themes and fonts again for Tools > Theme
    /// manager, and shows them (after what the shared vault brings in,
    /// as a save would: its host profiles and credentials).
    fn reload_themes(&mut self) {
        self.pull_vault_settings();
        // The themes folder too, so a theme file copied in shows (and a
        // rule may name it), refilling Settings > Custom themes with it:
        // its menu ids index the list. If the folder cannot be read, the
        // themes known before stay, and that menu says why.
        if let Some(menu) = custom_themes_menu(self.menu) {
            self.fill_custom_themes(menu);
        }
        let page = if self.side.view == SideView::ThemeRules {
            crate::theme_view::Page::Rules
        } else {
            crate::theme_view::Page::Looks
        };
        theme_panel::set_page(page);
        let defaults = theme_panel::Defaults {
            theme: self.default_theme.name.to_owned(),
            font: self.default_font.family.clone(),
            size: self.default_font.size_pt,
        };
        theme_panel::set_rows(self.theme_rows(), defaults);
    }

    /// Whether the theme manager or the theme rules show (always native
    /// controls, on one panel).
    fn themes_native(&self) -> bool {
        self.side.visible && matches!(self.side.view, SideView::Themes | SideView::ThemeRules)
    }

    /// Whether port forwards show as native controls.
    fn fwd_native(&self) -> bool {
        self.side.visible && self.side.view == SideView::Forwards
    }

    /// Whether the scripts show as native controls: the list is open (not
    /// the editor, the arguments, the host picker or a report).
    fn scripts_native(&self) -> bool {
        self.side.visible
            && self.side.view == SideView::Snippets
            && !self.snippets_view.editing()
            && !self.snippets_view.asking()
            && !self.snippets_view.picking()
            && !self.snippets_view.reporting()
    }

    /// Whether the page asking for a script's arguments shows as native
    /// controls.
    fn script_args_native(&self) -> bool {
        self.side.visible
            && self.side.view == SideView::Snippets
            && self.snippets_view.asking()
            && !self.snippets_view.picking()
            && !self.snippets_view.reporting()
    }

    /// Whether the page picking the hosts to run a script on shows as
    /// native controls.
    fn script_hosts_native(&self) -> bool {
        self.side.visible
            && self.side.view == SideView::Snippets
            && self.snippets_view.picking()
            && !self.snippets_view.reporting()
    }

    /// Whether a script run's report shows as native controls.
    fn script_report_native(&self) -> bool {
        self.side.visible && self.side.view == SideView::Snippets && self.snippets_view.reporting()
    }

    /// Whether the script editor shows as native controls.
    fn script_editor_native(&self) -> bool {
        self.side.visible
            && self.side.view == SideView::Snippets
            && self.snippets_view.editing()
            && !self.snippets_view.asking()
            && !self.snippets_view.picking()
            && !self.snippets_view.reporting()
    }

    /// Whether the connection form shows as native controls.
    fn form_native(&self) -> bool {
        self.side.visible
            && self.side.view == SideView::Sessions
            && self.side.form.is_some()
            && self.side.import.is_none()
    }

    /// Whether the import page (File > Import and export > Import connections or scripts)
    /// shows as native controls.
    fn import_native(&self) -> bool {
        self.side.visible
            && self.side.view == SideView::Sessions
            && self.side.form.is_none()
            && self.side.import.is_some()
    }

    /// The connection form as the native controls show it.
    fn native_form(&self) -> Option<form_view::Form> {
        let f = self.side.form.as_ref()?;
        Some(form_view::Form {
            title: match &f.original {
                Some(name) => format!("Edit {name}"),
                None => "New connection".to_owned(),
            },
            sections: f.sections(),
            rows: f.native_rows(),
            error: f.error().map(str::to_owned),
            delete: f.button_names().contains(&"Delete"),
        })
    }

    /// The open native tool's controls have the keyboard.
    fn active_tool_has_focus(&self) -> bool {
        if self.form_native() {
            form_view::has_focus()
        } else if self.import_native() {
            import_panel::has_focus()
        } else if self.conn_native() {
            conn_view::has_focus()
        } else if self.live_native() {
            live_panel::has_focus()
        } else if self.palette_native() {
            palette_panel::has_focus()
        } else if self.files_visible() {
            files_panel::has_focus()
        } else if self.fwd_native() {
            fwd_panel::has_focus()
        } else if self.known_hosts_native() {
            known_hosts_panel::has_focus()
        } else if self.inventory_native() {
            inventory_panel::has_focus()
        } else if self.hosts_native() {
            hosts_panel::has_focus()
        } else if self.credentials_native() {
            credential_panel::has_focus()
        } else if self.rules_native() {
            rules_panel::has_focus()
        } else if self.themes_native() {
            theme_panel::has_focus()
        } else if self.scripts_native() {
            scripts_panel::has_focus()
        } else if self.script_editor_native() {
            script_editor::has_focus()
        } else if self.script_args_native() {
            script_args::has_focus()
        } else if self.script_hosts_native() {
            script_hosts::has_focus()
        } else if self.script_report_native() {
            script_report::has_focus()
        } else {
            false
        }
    }

    /// Shows, fills and places the native tools' controls, and moves the
    /// keyboard to them or back as the side pane's focus says. Focus
    /// changes are posted: they send messages that need this window's
    /// state, which is borrowed here.
    fn sync_conn_view(&mut self) {
        if self.conn_native() {
            conn_view::set_nodes(self.side.list.tree());
            conn_view::place(self.areas.side, self.areas.side_width, self.dpi);
        } else {
            conn_view::place(None, 0, self.dpi);
        }
        if self.live_native() {
            let all = self.open_sessions();
            live_panel::set_search(self.live_view.query());
            let rows = self.live_view.rows(&all);
            let dashboard = self.live_view.dashboard();
            // The dashboard counts its agents; the list, every session.
            let total = if dashboard { rows.len() } else { all.len() };
            live_panel::set_rows(rows, total, dashboard);
            live_panel::place(self.areas.side, self.areas.side_width, self.dpi);
        } else {
            live_panel::place(None, 0, self.dpi);
        }
        if self.palette_native() {
            palette_panel::set_view(self.palette.native());
            palette_panel::place(self.areas.side, self.areas.side_width, self.dpi);
        } else {
            palette_panel::place(None, 0, self.dpi);
        }
        // The focused pane's host first, so the view never shows the
        // host the pane had before.
        self.sync_files();
        if self.files_visible() {
            files_panel::set_view(self.files_view());
            files_panel::place(self.areas.side, self.areas.side_width, self.dpi);
        } else {
            files_panel::place(None, 0, self.dpi);
        }
        if self.fwd_native() {
            fwd_panel::set_view(&self.forward_view());
            if let Some((spec, why)) = self.forwards_view.take_notice() {
                fwd_panel::notice(spec, why);
            }
            fwd_panel::place(self.areas.side, self.areas.side_width, self.dpi);
        } else {
            fwd_panel::place(None, 0, self.dpi);
        }
        if self.known_hosts_native() {
            known_hosts_panel::set_search(self.known_hosts_view.query());
            let note = match self.known_hosts_view.errors() {
                [] => String::new(),
                errors => format!("Could not read {}", errors.join("; ")),
            };
            known_hosts_panel::set_rows(
                self.known_hosts_view.rows(),
                self.known_hosts_view.total(),
                note,
            );
            known_hosts_panel::place(self.areas.side, self.areas.side_width, self.dpi);
        } else {
            known_hosts_panel::place(None, 0, self.dpi);
        }
        if self.inventory_native() {
            inventory_panel::place(self.areas.side, self.areas.side_width, self.dpi);
        } else {
            inventory_panel::place(None, 0, self.dpi);
        }
        if self.hosts_native() {
            hosts_panel::place(self.areas.side, self.areas.side_width, self.dpi);
        } else {
            hosts_panel::place(None, 0, self.dpi);
        }
        if self.credentials_native() {
            credential_panel::place(self.areas.side, self.areas.side_width, self.dpi);
        } else {
            credential_panel::place(None, 0, self.dpi);
        }
        if self.rules_native() {
            rules_panel::place(self.areas.side, self.areas.side_width, self.dpi);
        } else {
            rules_panel::place(None, 0, self.dpi);
        }
        if self.themes_native() {
            theme_panel::place(self.areas.side, self.areas.side_width, self.dpi);
        } else {
            theme_panel::place(None, 0, self.dpi);
        }
        if self.scripts_native() {
            scripts_panel::seed_folds(self.settings.expanded_script_cats.clone());
            let all = &self.settings.snippets;
            scripts_panel::set_view(
                self.snippets_view.native_rows(all),
                self.snippets_view.native_selected(all),
                self.snippets_view.filter(),
                all.len(),
            );
            scripts_panel::place(self.areas.side, self.areas.side_width, self.dpi);
        } else {
            scripts_panel::place(None, 0, self.dpi);
        }
        if let Some(draft) = self
            .snippets_view
            .native_draft()
            .filter(|_| self.script_editor_native())
        {
            script_editor::set_draft(draft);
            script_editor::place(self.areas.side, self.areas.side_width, self.dpi);
        } else {
            script_editor::place(None, 0, self.dpi);
        }
        if let Some(ask) = self
            .snippets_view
            .native_ask()
            .filter(|_| self.script_args_native())
        {
            script_args::set_ask(ask);
            script_args::place(self.areas.side, self.areas.side_width, self.dpi);
            // A script with arguments just opened the page: the first
            // argument gets the keyboard, so the user can type at once.
            if script_args::take_focus_pending() {
                script_args::focus_first();
            }
        } else {
            script_args::place(None, 0, self.dpi);
        }
        if let Some(picker) = self
            .snippets_view
            .native_picker()
            .filter(|_| self.script_hosts_native())
        {
            script_hosts::set_picker(picker);
            script_hosts::place(self.areas.side, self.areas.side_width, self.dpi);
        } else {
            script_hosts::place(None, 0, self.dpi);
        }
        if let Some(report) = self
            .snippets_view
            .native_report()
            .filter(|_| self.script_report_native())
        {
            script_report::set_report(report);
            script_report::place(self.areas.side, self.areas.side_width, self.dpi);
        } else {
            script_report::place(None, 0, self.dpi);
        }
        if let Some(form) = self.native_form().filter(|_| self.form_native()) {
            form_view::set_form(form);
            form_view::place(self.areas.side, self.areas.side_width, self.dpi);
        } else {
            form_view::place(None, 0, self.dpi);
        }
        if let Some(view) = self.side.import.as_ref().filter(|_| self.import_native()) {
            import_panel::set_view(view.native());
            import_panel::place(self.areas.side, self.areas.side_width, self.dpi);
        } else {
            import_panel::place(None, 0, self.dpi);
        }
        let want = self.wants_tools_focus();
        let to = if want && self.focused && self.live_native() && self.wants_name_edit() {
            Some(2)
        } else if want && self.focused && !self.active_tool_has_focus() {
            Some(1)
        } else if !want && tools_have_focus() {
            Some(0)
        } else {
            None
        };
        if let Some(to) = to {
            // SAFETY: posting to our own window.
            unsafe {
                let _ = PostMessageW(Some(self.hwnd), WM_TOOLS_FOCUS, WPARAM(to), LPARAM(0));
            }
        }
    }

    /// A rename waits for the session manager's list to start its edit.
    fn wants_name_edit(&self) -> bool {
        self.live_native() && self.live_view.renaming_pane().is_some() && !live_panel::editing()
    }

    /// A native tool's controls should have the keyboard.
    fn wants_tools_focus(&self) -> bool {
        (self.conn_native()
            || self.live_native()
            || self.palette_native()
            || self.form_native()
            || self.import_native()
            || self.files_visible()
            || self.fwd_native()
            || self.known_hosts_native()
            || self.inventory_native()
            || self.hosts_native()
            || self.credentials_native()
            || self.rules_native()
            || self.themes_native()
            || self.scripts_native()
            || self.script_editor_native()
            || self.script_args_native()
            || self.script_hosts_native()
            || self.script_report_native())
            && self.side.focused
    }

    /// A theme whose background is the chrome's, for drawing its padding.
    fn chrome_theme(&self) -> Theme {
        let mut t = self
            .panes
            .get(&self.focused_id())
            .map_or_else(|| self.default_theme.clone(), |p| p.theme.clone());
        t.background = self.chrome_palette().strip;
        t
    }

    /// Redraws the tab strip and side pane grids, and repaints the menu
    /// bar and tools pane when the window's colours change.
    fn refresh_chrome(&mut self) {
        ui_theme::apply(self.hwnd, self.ui_colours());
        rail::set_look(self.rail_look());
        self.sync_conn_view();
        self.refresh_status();
        let palette = self.chrome_palette();
        if let Some(strip) = self.areas.strip {
            let palette = self.strip_palette();
            let active = self.ws.active;
            let views = self.forward_view();
            let labels: Vec<TabLabel> = self
                .ws
                .tabs
                .iter()
                .enumerate()
                .map(|(i, t)| {
                    let pane = self.panes.get(&t.focus);
                    let bell = i != active
                        && t.root
                            .panes()
                            .iter()
                            .any(|id| self.panes.get(id).is_some_and(|p| p.bell));
                    let attention = t
                        .root
                        .panes()
                        .iter()
                        .any(|id| self.panes.get(id).is_some_and(|p| p.attention));
                    TabLabel {
                        title: pane.map(Pane::label).unwrap_or_default(),
                        // A pane waiting to reconnect shows as connecting.
                        health: if self.retries.contains_key(&t.focus) {
                            Health::Connecting
                        } else {
                            pane.map_or(Health::Idle, Pane::health)
                        },
                        bell,
                        attention,
                        forwarding: self.forwarding(&views, t.focus),
                        legacy: self.legacy_in_use(t.focus),
                        unencrypted: self.unencrypted(t.focus),
                    }
                })
                .collect();
            self.strip_layout = tabstrip::draw(&mut self.strip_grid, &labels, active, &palette);
            // The strip is drawn whole (the active tab's background and
            // line reach past the text row).
            // SAFETY: valid window and rect.
            unsafe {
                let _ = InvalidateRect(Some(self.hwnd), Some(&win_rect(strip)), false);
            }
        }
        if let Some(side) = self.areas.side {
            let focused = self.side.focused && self.focused;
            match self.side.view {
                SideView::Sessions => match (&mut self.side.form, &mut self.side.import) {
                    (Some(form), _) => form.draw(&mut self.side.grid, &palette, focused),
                    (None, Some(view)) => view.draw(&mut self.side.grid, &palette, focused),
                    (None, None) => self.side.list.draw(&mut self.side.grid, &palette, focused),
                },
                SideView::Forwards => {
                    let view = self.forward_view();
                    self.forwards_view
                        .draw(&mut self.side.grid, &palette, focused, &view);
                }
                SideView::Palette => {
                    self.palette.draw(&mut self.side.grid, &palette, focused);
                }
                SideView::Live => {
                    let all = self.open_sessions();
                    self.live_view
                        .draw(&mut self.side.grid, &palette, focused, &all);
                }
                SideView::Snippets => {
                    self.snippets_view.draw(
                        &mut self.side.grid,
                        &palette,
                        focused,
                        &self.settings.snippets,
                    );
                }
                // Native controls (`files_panel`, `known_hosts_panel`,
                // `inventory_panel`, `hosts_panel`, `credential_panel`,
                // `rules_panel`, `theme_panel`).
                SideView::Files
                | SideView::KnownHosts
                | SideView::Inventory
                | SideView::Hosts
                | SideView::Credentials
                | SideView::SecurityRules
                | SideView::Themes
                | SideView::ThemeRules => {}
            }
            self.invalidate_grid(side);
        }
    }

    /// Invalidates the dirty rows of the side pane's grid in `area`.
    fn invalidate_grid(&self, area: Rect) {
        let grid = &self.side.grid;
        let Some((first, last)) = grid.dirty_span() else {
            return;
        };
        let pad = scale(CHROME_PADDING_DIP, self.dpi);
        let ch = self.chrome_metrics.height as i32;
        let r = RECT {
            left: area.x,
            top: area.y + pad + first as i32 * ch,
            right: area.right(),
            bottom: area.y + pad + (last as i32 + 1) * ch,
        };
        // SAFETY: valid window and rect.
        unsafe {
            let _ = InvalidateRect(Some(self.hwnd), Some(&r), false);
        }
    }

    /// Splits the client area into tools rail, side pane, tab strip and
    /// panes. The side pane keeps its width; the terminal covers what of
    /// it does not show (see `toolpane`).
    fn compute_areas(&mut self) -> Areas {
        let cpad = scale(CHROME_PADDING_DIP, self.dpi);
        let cm = self.chrome_metrics;
        let mut areas = Areas::default();
        if self.side.width <= 0 {
            self.side.width = SIDE_COLS * cm.width as i32 + 2 * cpad;
        }
        let parts = toolpane::split(&self.tools_input());
        if self.side.visible {
            self.side.width = parts.width;
            self.side.shown = parts.shown.map_or(0, |r| r.w);
        }
        areas.rail = parts.rail;
        areas.side = parts.shown;
        areas.side_width = parts.width;
        areas.side_edge = parts.edge.filter(|e| e.w > 0);
        let mut main = parts.main;
        if self.settings.status_bar {
            let sh = self.strip_metrics.height as i32 + 2 * scale(STATUS_PAD_DIP, self.dpi);
            let sh = sh.min(main.h);
            areas.status = Some(Rect::new(main.x, main.y + main.h - sh, main.w, sh));
            main = Rect::new(main.x, main.y, main.w, main.h - sh);
        }
        if self.settings.tab_strip && self.ws.tabs.len() >= 2 {
            let sh = self.strip_metrics.height as i32 + 2 * scale(STRIP_PAD_DIP, self.dpi);
            areas.strip = Some(Rect::new(main.x, main.y, main.w, sh));
            main = Rect::new(main.x, main.y + sh, main.w, (main.h - sh).max(0));
        }
        areas.panes = main;
        areas
    }

    /// What the tools pane's geometry depends on.
    fn tools_input(&self) -> toolpane::Input {
        toolpane::Input {
            client: self.client,
            rail: if self.settings.tools_rail {
                scale(toolpane::RAIL_DIP, self.dpi)
            } else {
                0
            },
            width: self.side.width,
            shown: self.side.shown,
            open: self.side.visible,
            right: self.settings.side_pane_right,
            gap: gap(self.dpi),
        }
    }

    /// Fits every pane, and the chrome, to the client area.
    fn layout(&mut self) {
        let mut r = RECT::default();
        // SAFETY: valid window and out-pointer.
        if unsafe { GetClientRect(self.hwnd, &mut r) }.is_err() {
            return;
        }
        let (w, h) = (r.right - r.left, r.bottom - r.top);
        self.client = (w, h);
        self.renderer.resize(w.max(1) as u32, h.max(1) as u32);
        self.areas = self.compute_areas();
        // The panels let the mouse through to the edge's strip.
        crate::native::set_edge_grab(self.hwnd, self.edge_grab());
        let cpad = scale(CHROME_PADDING_DIP, self.dpi);
        let cm = self.chrome_metrics;
        let cells = |r: Rect| {
            (
                ((r.w - 2 * cpad).max(0) / cm.width.max(1) as i32).max(1) as usize,
                ((r.h - 2 * cpad).max(0) / cm.height.max(1) as i32).max(1) as usize,
            )
        };
        if let Some(s) = self.areas.strip {
            let cols = ((s.w - 2 * cpad).max(0) / self.strip_metrics.width.max(1) as i32).max(1);
            self.strip_grid.resize(cols as usize, 1);
            self.strip_grid.mark_all_dirty();
        }
        if let Some(s) = self.areas.status {
            let cols = ((s.w - 2 * cpad).max(0) / self.strip_metrics.width.max(1) as i32).max(1);
            self.status_grid.resize(cols as usize, 1);
            self.status_grid.mark_all_dirty();
        }
        if let Some(s) = self.areas.side {
            // Laid out for its whole width, covered or not, so covering
            // it does not rewrap it.
            let (c, rows) = cells(Rect::new(s.x, s.y, self.areas.side_width, s.h));
            self.side.grid.resize(c, rows);
            self.side.grid.mark_all_dirty();
        }
        rail::place(self.areas.rail);
        self.sync_conn_view();
        // Every tab, so background shells know their size too.
        let pad = padding(self.dpi);
        let g = gap(self.dpi);
        let mut relaid = Vec::new();
        let placed: Vec<(PaneId, Rect)> = self
            .ws
            .tabs
            .iter()
            .flat_map(|t| t.root.layout(self.areas.panes, g))
            .collect();
        for (id, rect) in placed {
            let Some(p) = self.panes.get_mut(&id) else {
                continue;
            };
            p.rect = rect;
            if p.gateway().is_some() {
                // tmux sizes its panes; see sync_tmux.
                let m = p.metrics;
                p.term.set_cell_size(m.width, m.height);
                continue;
            }
            if matches!(p.host, Host::Replay(_)) {
                // A recording keeps the size it was made at.
                let m = p.metrics;
                p.term.set_cell_size(m.width, m.height);
                continue;
            }
            let m = p.metrics;
            let cols = ((rect.w - 2 * pad).max(0) / m.width.max(1) as i32).max(1) as usize;
            let rows = ((rect.h - 2 * pad).max(0) / m.height.max(1) as i32).max(1) as usize;
            let before = (p.term.cols(), p.term.rows());
            p.term.resize(cols, rows);
            p.term.set_cell_size(m.width, m.height);
            let (cols, rows) = (p.term.cols(), p.term.rows());
            if before != (cols, rows) {
                p.record_resize();
                if matches!(p.host, Host::Diff(_)) && before.0 != cols {
                    relaid.push(id);
                }
            }
            let effect = match &p.host {
                Host::Local {
                    shell: Some(shell), ..
                } => {
                    shell.resize(cols, rows);
                    None
                }
                Host::Ssh(session) => session.resize(clamp16(cols), clamp16(rows)),
                Host::Telnet(session) => session.resize(clamp16(cols), clamp16(rows)),
                _ => None,
            };
            if let Some(e) = effect {
                self.apply(id, vec![e]);
            }
        }
        for id in relaid {
            self.render_diff(id);
        }
        if self.panes.values().any(|p| p.desktop.is_some()) {
            // SAFETY: our window; replaces any earlier timer with this id.
            unsafe { SetTimer(Some(self.hwnd), TIMER_DESKTOP_SIZE, DESKTOP_SIZE_MS, None) };
        }
        self.sync_tmux();
        self.refresh_chrome();
        self.refresh_visible();
        self.request_full_redraw();
    }

    fn request_full_redraw(&mut self) {
        self.full_redraw = true;
        // SAFETY: valid window; no erase, the renderer paints everything.
        unsafe {
            let _ = InvalidateRect(Some(self.hwnd), None, false);
        }
    }

    /// Asks Windows to repaint the band of rows a pane's grid marked dirty.
    fn invalidate_dirty(&self, id: PaneId) {
        let Some(p) = self.panes.get(&id) else {
            return;
        };
        let Some((first, last)) = p.grid.dirty_span() else {
            return;
        };
        let (_, oy) = p.origin(self.dpi);
        let ch = p.metrics.height as i32;
        let r = RECT {
            left: p.rect.x,
            top: oy + first as i32 * ch,
            right: p.rect.right(),
            bottom: oy + (last as i32 + 1) * ch,
        };
        // SAFETY: valid window and rect.
        unsafe {
            let _ = InvalidateRect(Some(self.hwnd), Some(&r), false);
        }
    }

    /// Dividers, the focus frame, the side pane's edge and a drop marker.
    fn fills(&self) -> Vec<(PixelRect, Rgb)> {
        let mut out = Vec::new();
        let palette = self.chrome_palette();
        let line = mix(palette.strip, palette.text, 0.18);
        let g = gap(self.dpi);
        if let Some(e) = self.areas.side_edge {
            out.push((pixel(e), line));
        }
        if let Some(s) = self.areas.strip {
            self.strip_fills(s, &mut out);
        }
        let Some(tab) = self.ws.tab() else {
            return out;
        };
        for d in tab.root.dividers(self.areas.panes, g) {
            out.push((pixel(d.rect), line));
        }
        let split = tab.root.panes().len() > 1;
        let receivers = self.broadcast_targets(tab.focus);
        if !receivers.is_empty() {
            // Every pane that gets the typing, the focused one too, is
            // framed in amber while broadcast is on.
            for id in std::iter::once(tab.focus).chain(receivers) {
                if let Some(p) = self.panes.get(&id)
                    && self.is_visible(id)
                {
                    frame(p.rect, g, BROADCAST_FRAME, &mut out);
                }
            }
        } else if split
            && !self.side.focused
            && let Some(p) = self.panes.get(&tab.focus)
        {
            frame(p.rect, g, p.theme.cursor, &mut out);
        }
        for id in self.visible_ids() {
            if let Some(p) = self.panes.get(&id)
                && let Some(m) = p.scroll_mark(self.dpi)
            {
                out.push((pixel(m), p.mark_colour()));
            }
        }
        if let Some(Drag::Pane { active: true, .. } | Drag::Tab { out: true, .. }) = &self.drag {
            let accent = Rgb::new(0xe5, 0xb5, 0x3b);
            if let Some(r) = self.drop_marker() {
                frame(r, 2 * g, accent, &mut out);
            }
        }
        out
    }

    /// The tab strip's shapes: the active tab's background above and below
    /// its text row, its accent line, and thin lines between the others.
    fn strip_fills(&self, s: Rect, out: &mut Vec<(PixelRect, Rgb)>) {
        let p = self.strip_palette();
        let cpad = scale(CHROME_PADDING_DIP, self.dpi);
        let spad = scale(STRIP_PAD_DIP, self.dpi);
        let cw = self.strip_metrics.width as i32;
        let ch = self.strip_metrics.height as i32;
        let g = gap(self.dpi);
        let x_of = |col: usize| s.x + cpad + col as i32 * cw;
        let active = self.ws.active;
        for i in 0..self.strip_layout.len() {
            let Some((start, end)) = self.strip_layout.span(i) else {
                continue;
            };
            let (x0, x1) = (x_of(start), x_of(end));
            if i == active {
                let top = Rect::new(x0, s.y, x1 - x0, spad);
                let bottom =
                    Rect::new(x0, s.y + spad + ch, x1 - x0, s.bottom() - (s.y + spad + ch));
                out.push((pixel(top), p.active));
                out.push((pixel(bottom), p.active));
                let accent = scale(ACCENT_DIP, self.dpi).max(1);
                out.push((pixel(Rect::new(x0, s.y, x1 - x0, accent)), p.accent));
            } else if i + 1 != active {
                // A short line after each inactive tab not next to the
                // active one.
                let line = Rect::new(x1 - g, s.y + spad, g, ch);
                out.push((pixel(line), tabstrip::mix(p.strip, p.text, 0.25)));
            }
        }
    }

    /// Where a dragged pane or tab would land, outlined while dragging.
    fn drop_marker(&self) -> Option<Rect> {
        let (x, y) = self.mouse.at;
        let (pane, tab) = match &self.drag {
            Some(Drag::Pane { id, .. }) => (Some(*id), None),
            Some(Drag::Tab {
                index, out: true, ..
            }) => (None, Some(*index)),
            _ => return None,
        };
        if pane.is_some()
            && let Some(s) = self.areas.strip
            && s.contains(x, y)
        {
            return Some(s);
        }
        let Spot::Pane(target) = self.spot(x, y) else {
            return None;
        };
        if Some(target) == pane || tab.is_some_and(|t| self.ws.tab_of(target) == Some(t)) {
            return None;
        }
        let r = self.panes.get(&target)?.rect;
        let zone = if tab.is_some() {
            Drop::Side(layout::join_side(r, x, y))
        } else {
            layout::drop_zone(r, x, y)
        };
        Some(match zone {
            Drop::Swap => r,
            Drop::Side(Dir::Left) => Rect::new(r.x, r.y, r.w / 2, r.h),
            Drop::Side(Dir::Right) => Rect::new(r.x + r.w / 2, r.y, r.w - r.w / 2, r.h),
            Drop::Side(Dir::Up) => Rect::new(r.x, r.y, r.w, r.h / 2),
            Drop::Side(Dir::Down) => Rect::new(r.x, r.y + r.h / 2, r.w, r.h - r.h / 2),
        })
    }

    fn paint(&mut self, update: RECT) {
        self.place_previews();
        // Rows Windows wants repainted (e.g. after a restore) join the
        // grids' own dirty rows; anything outside a pane's rows means
        // everything.
        let ids = self.visible_ids();
        let mut inside = false;
        for id in &ids {
            let Some(p) = self.panes.get_mut(id) else {
                continue;
            };
            let r = p.rect;
            if update.right <= r.x
                || update.left >= r.right()
                || update.bottom <= r.y
                || update.top >= r.bottom()
            {
                continue;
            }
            let pad = padding(self.dpi);
            let ch = p.metrics.height.max(1) as i32;
            let rows = p.grid.rows() as i32;
            let top = r.y + pad;
            if update.top >= top && update.bottom <= top + rows * ch {
                inside = true;
                for y in (update.top - top) / ch..=(update.bottom - 1 - top) / ch {
                    p.grid.mark_dirty(y.max(0) as usize);
                }
            }
        }
        let in_chrome = [self.areas.strip, self.areas.side, self.areas.status]
            .into_iter()
            .flatten()
            .any(|r| {
                update.left >= r.x
                    && update.right <= r.right()
                    && update.top >= r.y
                    && update.bottom <= r.bottom()
            });
        if !inside && !in_chrome {
            self.full_redraw = true;
        }
        let full = self.full_redraw;
        let chrome_theme = self.chrome_theme();
        let mut strip_theme = chrome_theme.clone();
        strip_theme.background = self.strip_palette().strip;
        let cpad = scale(CHROME_PADDING_DIP, self.dpi);
        let spad = scale(STRIP_PAD_DIP, self.dpi);
        let fills = self.fills();
        let mut views: Vec<PaneView<'_>> = Vec::new();
        for id in &ids {
            let Some(p) = self.panes.get(id) else {
                continue;
            };
            views.push(PaneView {
                grid: &p.grid,
                font: &p.font,
                theme: &p.theme,
                rect: pixel(p.rect),
                origin: p.origin(self.dpi),
                cursor: p.cursor,
                full,
                image: p.image(),
                ligatures: self.settings.font_ligatures,
            });
        }
        // Port-forward previews, over their panes' top right corner.
        for id in &ids {
            let Some(pv) = self.previews.get(id).filter(|pv| pv.rect.w > 0) else {
                continue;
            };
            views.push(PaneView {
                grid: &pv.grid,
                font: &self.strip_font,
                theme: &strip_theme,
                rect: pixel(pv.rect),
                origin: (pv.rect.x + cpad, pv.rect.y + spad),
                cursor: None,
                full: true,
                image: None,
                ligatures: false,
            });
        }
        if let Some(s) = self.areas.strip {
            views.push(PaneView {
                grid: &self.strip_grid,
                font: &self.strip_font,
                theme: &strip_theme,
                rect: pixel(s),
                origin: (s.x + cpad, s.y + spad),
                cursor: None,
                full: true,
                image: None,
                ligatures: false,
            });
        }
        if let Some(s) = self.areas.status {
            views.push(PaneView {
                grid: &self.status_grid,
                font: &self.strip_font,
                theme: &strip_theme,
                rect: pixel(s),
                origin: (s.x + cpad, s.y + scale(STATUS_PAD_DIP, self.dpi)),
                cursor: None,
                full: true,
                image: None,
                ligatures: false,
            });
        }
        if let Some(s) = self.areas.side {
            views.push(PaneView {
                grid: &self.side.grid,
                font: &self.chrome_font,
                theme: &chrome_theme,
                rect: pixel(s),
                origin: (s.x + cpad, s.y + cpad),
                cursor: None,
                full,
                image: None,
                ligatures: false,
            });
        }
        let result = self.renderer.draw(&views, &fills, self.dpi);
        drop(views);
        match result {
            Ok(Frame::Presented) => {
                for id in &ids {
                    if let Some(p) = self.panes.get_mut(id) {
                        p.grid.clear_dirty();
                        if let Some(d) = p.desktop.as_mut() {
                            d.drawn();
                        }
                    }
                }
                self.strip_grid.clear_dirty();
                self.status_grid.clear_dirty();
                self.side.grid.clear_dirty();
                self.full_redraw = false;
            }
            Ok(Frame::Lost) => self.request_full_redraw(),
            // Leave the rows dirty; the next change or resize retries.
            Err(_) => {}
        }
    }

    /// A character from WM_CHAR or WM_SYSCHAR; what a tmux key asked
    /// for comes back.
    fn on_char(&mut self, unit: u16, alt: bool) -> Option<Command> {
        let ch = match unit {
            0xD800..=0xDBFF => {
                self.high_surrogate = Some(unit);
                return None;
            }
            0xDC00..=0xDFFF => {
                let high = self.high_surrogate.take()?;
                char::decode_utf16([high, unit]).next().and_then(|r| r.ok())
            }
            _ => char::from_u32(u32::from(unit)),
        };
        let ch = ch?;
        if self.side.focused {
            if !ch.is_control() {
                self.side_key(SideKey::Char(ch));
            }
            return None;
        }
        let id = self.focused_id();
        let p = self.panes.get_mut(&id)?;
        if p.term.search_active() {
            if !ch.is_control() {
                let mut query = p.term.search_query().unwrap_or_default().to_owned();
                query.push(ch);
                p.term.search_set(&query);
                self.refresh(id);
            }
            return None;
        }
        if let Some(command) = self.tmux_char(id, ch, alt) {
            return command;
        }
        let typed = if alt {
            escape::Typed::Other
        } else {
            escape::Typed::Char(ch)
        };
        if let Some(command) = self.escape_typed(id, typed) {
            return command;
        }
        let p = self.panes.get_mut(&id)?;
        let bytes = p.term.text(ch, alt);
        // Who else gets it is decided first: the key may end a prompt.
        let targets = self.broadcast_targets(id);
        self.input(id, bytes);
        self.send_typed(&targets, &Typed::Char(ch, alt));
        None
    }

    /// The prefix keys of the tmux session pane `id` shows, when tmux
    /// keybindings are on and it is a pane of a tmux session.
    /// The prefix of an open tmux session as a key (Ctrl+B), for the
    /// warnings of Settings > Key bindings; `None` when none is open or
    /// its prefix is no Ctrl key.
    fn tmux_prefix_key(&self) -> Option<Hotkey> {
        let keys = self
            .tmux
            .values()
            .filter(|t| t.active())
            .find_map(|t| t.keys().and_then(tmux_keys::Keys::parse))?;
        let p = keys.prefixes.first()?;
        match p.ch {
            c @ '\x01'..='\x1a' => Some(keymap::chord(
                u16::from(b'A' + c as u8 - 1),
                true,
                p.alt,
                false,
            )),
            _ => None,
        }
    }

    fn tmux_keys_of(&self, id: PaneId) -> Option<tmux_keys::Keys> {
        if !self.settings.tmux_keys {
            return None;
        }
        let gateway = self.panes.get(&id).and_then(Pane::gateway)?;
        let t = self.tmux.get(&gateway).filter(|t| t.active())?;
        // Until tmux answers, its default.
        Some(
            t.keys()
                .and_then(tmux_keys::Keys::parse)
                .unwrap_or_default(),
        )
    }

    /// A character typed in pane `id`, for the tmux keybindings: the
    /// prefix arms them, and the next key is a window or pane key.
    /// `Some` when they took it, with what to run.
    fn tmux_char(&mut self, id: PaneId, ch: char, alt: bool) -> Option<Option<Command>> {
        let keys = self.tmux_keys_of(id)?;
        if self.tmux_armed.take() == Some(id) {
            return Some(self.tmux_key(id, &keys, tmux_keys::Key::Char(ch, alt)));
        }
        // Repeating: another repeatable key needs no prefix; any other key
        // ends the repeat and is typed (or arms the prefix) as usual.
        if self.tmux_repeating(false) {
            let key = tmux_keys::Key::Char(ch, alt);
            if tmux_keys::repeatable(tmux_keys::action(&keys, key)) {
                return Some(self.tmux_key(id, &keys, key));
            }
        }
        self.tmux_repeat = None;
        if keys.is_prefix(tmux_keys::Prefix { ch, alt }) {
            self.tmux_armed = Some(id);
            return Some(None);
        }
        None
    }

    /// Carries out a tmux window or pane key typed after the prefix in
    /// pane `id`.
    fn tmux_key(
        &mut self,
        id: PaneId,
        keys: &tmux_keys::Keys,
        key: tmux_keys::Key,
    ) -> Option<Command> {
        let dir_index = |d: Dir| DIRS.iter().position(|x| *x == d).unwrap_or(0) as u32;
        let run = |c: u32| Some(Command::Id(c));
        let action = tmux_keys::action(keys, key);
        self.tmux_repeat = tmux_keys::repeatable(action)
            .then(|| Instant::now() + Duration::from_millis(keys.repeat_ms));
        match action {
            TmuxKey::SendPrefix(p) => {
                self.input(id, p.bytes());
                None
            }
            TmuxKey::NewTab => run(cmd::NEW_TAB),
            TmuxKey::SplitRight => run(cmd::SPLIT_RIGHT),
            TmuxKey::SplitDown => run(cmd::SPLIT_DOWN),
            TmuxKey::NextTab => run(cmd::NEXT_TAB),
            TmuxKey::PrevTab => run(cmd::PREV_TAB),
            TmuxKey::LastTab => {
                if let Some(p) = self.last_tab_pane.filter(|p| self.ws.tab_of(*p).is_some()) {
                    self.focus_pane(p);
                }
                None
            }
            TmuxKey::Tab(n) => {
                if n < self.ws.tabs.len() {
                    self.select_tab(n);
                }
                None
            }
            TmuxKey::NextPane => {
                let panes = self.ws.tab().map(|t| t.root.panes()).unwrap_or_default();
                let at = panes.iter().position(|p| *p == id).unwrap_or(0);
                if let Some(next) = panes.get((at + 1) % panes.len().max(1)).copied() {
                    self.focus_pane(next);
                }
                None
            }
            TmuxKey::LastPane => {
                let same_tab = self.last_pane.filter(|p| {
                    self.ws.tab_of(*p).is_some() && self.ws.tab_of(*p) == self.ws.tab_of(id)
                });
                if let Some(p) = same_tab {
                    self.focus_pane(p);
                }
                None
            }
            TmuxKey::Focus(d) => run(cmd::FOCUS + dir_index(d)),
            TmuxKey::Resize(d) => run(cmd::RESIZE + dir_index(d)),
            TmuxKey::ClosePane => Some(Command::Confirm {
                text: "Close this tmux pane? tmux ends the program in it (kill-pane).".into(),
                then: Box::new(Command::Id(cmd::CLOSE_PANE)),
            }),
            TmuxKey::CloseTab => {
                let n = self.ws.tab().map_or(0, |t| t.root.panes().len());
                let panes = if n == 1 {
                    "its pane".to_owned()
                } else {
                    format!("its {n} panes")
                };
                Some(Command::Confirm {
                    text: format!(
                        "Close this tab and {panes}? tmux ends the programs in them \
                         (kill-window)."
                    ),
                    then: Box::new(Command::CloseTabNow(self.ws.active)),
                })
            }
            TmuxKey::BreakPane => run(cmd::PANE_TO_TAB),
            TmuxKey::Detach => run(cmd::TMUX_DETACH),
            TmuxKey::ChooseSession => run(cmd::TMUX_PICK),
            TmuxKey::ScrollBack => run(cmd::SCROLL_PAGE_UP),
            TmuxKey::ScrollForward => run(cmd::SCROLL_PAGE_DOWN),
            TmuxKey::Palette => run(cmd::PALETTE),
            TmuxKey::Find => run(cmd::FIND),
            TmuxKey::Help => {
                let prefix = keys
                    .prefixes
                    .first()
                    .map_or_else(|| "the prefix".to_owned(), |p| tmux_keys::name(*p));
                Some(Command::Message(tmux_keys::help(&prefix, keys.repeat_ms)))
            }
            TmuxKey::Nothing => None,
        }
    }

    /// Whether a repeatable tmux key still needs no prefix: within
    /// `repeat-time` of the last one, or while that key is held down and
    /// Windows repeats it (its first repeat can come later than 500 ms).
    fn tmux_repeating(&self, held: bool) -> bool {
        self.tmux_repeat
            .is_some_and(|until| held || Instant::now() < until)
    }

    /// A key-down while the tmux prefix is armed in the focused pane, or
    /// while repeatable keys work without it. Armed: arrows, PageUp,
    /// PageDown and Escape are tmux keys, and any other key that types no
    /// text ends the wait, as tmux ignores an unbound key. Repeating: a
    /// repeatable key runs again, and any other key ends the repeat and
    /// goes on as usual. Text keys wait for their WM_CHAR. `held` is set
    /// for Windows' auto-repeat of a key held down.
    fn tmux_key_down(&mut self, vk: VIRTUAL_KEY, mods: Mods, held: bool) -> Option<KeyOutcome> {
        let id = self.focused_id();
        let armed = self.tmux_armed == Some(id);
        if self.side.focused || (!armed && !self.tmux_repeating(held)) {
            return None;
        }
        if matches!(
            vk,
            VK_SHIFT | VK_CONTROL | VK_MENU | VK_CAPITAL | VK_LWIN | VK_RWIN
        ) {
            return None;
        }
        let Some(keys) = self.tmux_keys_of(id) else {
            self.tmux_armed = None;
            self.tmux_repeat = None;
            return None;
        };
        let arrow = |dir| tmux_keys::Key::Arrow {
            dir,
            ctrl: mods.ctrl,
            alt: mods.alt,
        };
        let key = match vk {
            VK_LEFT => arrow(Dir::Left),
            VK_RIGHT => arrow(Dir::Right),
            VK_UP => arrow(Dir::Up),
            VK_DOWN => arrow(Dir::Down),
            VK_PRIOR => tmux_keys::Key::PageUp,
            VK_NEXT => tmux_keys::Key::PageDown,
            VK_ESCAPE => tmux_keys::Key::Escape,
            // Enter, Backspace, Tab, F-keys and the like: no binding.
            _ if terminal_key(vk).is_some() => tmux_keys::Key::Escape,
            // A text key, or Ctrl with one: its WM_CHAR follows, unless
            // it is a FeroSSH shortcut, which also ends the wait.
            _ => {
                if self.shortcut_for(vk, mods).is_some() {
                    self.tmux_armed = None;
                    self.tmux_repeat = None;
                }
                return None;
            }
        };
        if !armed && !tmux_keys::repeatable(tmux_keys::action(&keys, key)) {
            // Not a repeat: the key goes to the pane as usual.
            self.tmux_repeat = None;
            return None;
        }
        self.tmux_armed = None;
        drop_pending_char(self.hwnd);
        Some(match self.tmux_key(id, &keys, key) {
            Some(c) => KeyOutcome::Run(c),
            None => KeyOutcome::Handled,
        })
    }

    /// Handles a key-down: window shortcuts first, then the side pane or
    /// the search bar, then keys that do not type text. Text keys are left
    /// to the WM_CHAR that TranslateMessage made from the keyboard layout,
    /// which is what gets AltGr, dead keys and IME input right.
    fn on_key_down(&mut self, vk: VIRTUAL_KEY, held: bool) -> KeyOutcome {
        let mods = key_mods();
        if mods.alt && vk == VK_F4 {
            return KeyOutcome::Default;
        }
        // F11: full screen, before the tmux prefix and the panes, so it
        // works in a side pane, the search bar and a remote desktop too.
        // Held down, it does not flip back and forth.
        if self.full_screen_f11(vk, mods) {
            drop_pending_char(self.hwnd);
            return if held {
                KeyOutcome::Handled
            } else {
                KeyOutcome::Run(Command::FullScreen)
            };
        }
        // The key after the tmux prefix, before FeroSSH's own shortcuts:
        // Alt+arrow there resizes, as in tmux.
        if let Some(outcome) = self.tmux_key_down(vk, mods, held) {
            return outcome;
        }
        // Ctrl+Shift+F1 to F12: the snippet with that hotkey, if there is
        // one for this host; otherwise the key goes on.
        if mods.ctrl
            && mods.shift
            && !mods.alt
            && (0x70..0x70 + u16::from(login::MAX_HOTKEY)).contains(&vk.0)
            && let Ok(n) = u8::try_from(vk.0 - 0x6f)
            && let Some(command) = self.snippet_hotkey(n)
        {
            drop_pending_char(self.hwnd);
            return match command {
                Some(c) => KeyOutcome::Run(c),
                None => KeyOutcome::Handled,
            };
        }
        // Shift+End follows the output again when the view is scrolled
        // back or stopped at a match; otherwise it is the program's.
        if vk == VK_END
            && mods.shift
            && !mods.ctrl
            && !mods.alt
            && !self.side.focused
            && self.panes.get(&self.focused_id()).is_some_and(|p| {
                !p.term.search_active() && (p.term.display_offset() != 0 || p.term.stopped())
            })
        {
            drop_pending_char(self.hwnd);
            return KeyOutcome::Run(Command::Id(cmd::SCROLL_BOTTOM));
        }
        if let Some(id) = self.shortcut_for(vk, mods) {
            drop_pending_char(self.hwnd);
            return KeyOutcome::Run(Command::Id(id));
        }
        if self.side.focused {
            if let Some(key) = side_key(vk, mods) {
                drop_pending_char(self.hwnd);
                return match self.side_key(key) {
                    Some(command) => KeyOutcome::Run(command),
                    None => KeyOutcome::Handled,
                };
            }
            return KeyOutcome::Default;
        }
        let id = self.focused_id();
        let Some(p) = self.panes.get_mut(&id) else {
            return KeyOutcome::Default;
        };
        if p.term.search_active() {
            return self.search_key(id, vk, mods);
        }
        if self.replay_key(id, vk, mods) {
            drop_pending_char(self.hwnd);
            return KeyOutcome::Handled;
        }
        // A suggestion key (Settings > Key bindings) while a suggestion
        // shows: Right, End, Ctrl+E, Ctrl+F and the rest by default.
        if let Some(action) = self
            .keymap
            .suggestion(keymap::chord(vk.0, mods.ctrl, mods.alt, mods.shift))
            && self.ghost_key(id, action, vk, mods)
        {
            drop_pending_char(self.hwnd);
            return KeyOutcome::Handled;
        }
        if let Some(key) = terminal_key(vk) {
            drop_pending_char(self.hwnd);
            let typed = match key {
                Key::Enter => escape::Typed::Enter,
                Key::Backspace => escape::Typed::Backspace,
                Key::Escape => escape::Typed::Escape,
                _ => escape::Typed::Other,
            };
            if let Some(command) = self.escape_typed(id, typed) {
                return command.map_or(KeyOutcome::Handled, KeyOutcome::Run);
            }
            let targets = self.broadcast_targets(id);
            let Some(p) = self.panes.get_mut(&id) else {
                return KeyOutcome::Handled;
            };
            if let Some(bytes) = p.term.key(key, mods) {
                self.input(id, bytes);
            }
            self.send_typed(&targets, &Typed::Key(key, mods));
            return KeyOutcome::Handled;
        }
        // Control codes that have no character on most layouts. AltGr
        // (Ctrl+Alt) is left alone.
        if mods.ctrl && !mods.alt {
            let code = match vk {
                VK_SPACE => Some((' ', 0x00)),
                VIRTUAL_KEY(0x32) => Some(('2', 0x00)), // Ctrl+2, as in xterm
                VIRTUAL_KEY(0x36) => Some(('6', 0x1E)), // Ctrl+6
                VK_OEM_2 => Some(('/', 0x1F)),          // Ctrl+/
                _ => None,
            };
            if let Some((key, code)) = code {
                drop_pending_char(self.hwnd);
                // Ctrl+Space can be the tmux prefix (C-Space).
                if let Some(command) = self.tmux_char(id, char::from(code), false) {
                    return command.map_or(KeyOutcome::Handled, KeyOutcome::Run);
                }
                // `EscapeChar ^@` or `^_` starts an escape on these keys.
                if let Some(command) = self.escape_typed(id, escape::Typed::Char(char::from(code)))
                {
                    return command.map_or(KeyOutcome::Handled, KeyOutcome::Run);
                }
                let targets = self.broadcast_targets(id);
                let typed = Typed::Ctrl(key, code, mods);
                self.send_typed(&[id], &typed);
                self.send_typed(&targets, &typed);
                return KeyOutcome::Handled;
            }
        }
        KeyOutcome::Default
    }

    /// Whether the key is the full screen key (F11 unless Settings > Key
    /// bindings changed it) and it switches full screen (Settings > F11
    /// switches full screen); when that is off, F11 goes to the terminal
    /// as `ESC [ 2 3 ~`, for programs that use it.
    fn full_screen_f11(&self, vk: VIRTUAL_KEY, mods: Mods) -> bool {
        self.shortcut_for(vk, mods) == Some(cmd::FULL_SCREEN)
    }

    /// The action a key runs here, by Settings > Key bindings: tab keys
    /// only with more than one tab, pane keys only with more than one
    /// pane, the full screen key only while it switches full screen.
    fn shortcut_for(&self, vk: VIRTUAL_KEY, mods: Mods) -> Option<u32> {
        let split = self.ws.tab().is_some_and(|t| t.root.panes().len() > 1);
        let id = shortcut(&self.keymap, vk, mods, self.ws.tabs.len() > 1, split)?;
        (id != cmd::FULL_SCREEN || self.settings.full_screen_key).then_some(id)
    }

    /// Whether a key pressed in a tool pane's controls is a shortcut that
    /// goes to the window, not to the control (see
    /// [`keymap::reaches_main_from_tools`]).
    fn tools_shortcut(&self, vk: VIRTUAL_KEY, mods: Mods) -> bool {
        self.shortcut_for(vk, mods).is_some()
            && keymap::reaches_main_from_tools(keymap::chord(vk.0, mods.ctrl, mods.alt, mods.shift))
    }

    /// Shows the key bindings in the menus (after a tab, as menus do), in
    /// the rail's tooltips, and so in the command palette.
    fn apply_key_labels(&self) {
        let label = |id: u32| self.keymap.keys(id).first().map(|k| hotkey_label(*k));
        let full = match label(cmd::FULL_SCREEN) {
            Some(k) => format!("{k} switches full scree&n"),
            None => "The full screen key switches full scree&n".to_owned(),
        };
        menu_key_labels(self.menu, &|id| {
            match id {
                cmd::FULL_SCREEN_KEY => MenuText::Whole(full.clone()),
                // Windows closes the window on Alt+F4 whatever is bound.
                cmd::EXIT => MenuText::Key(label(id).or_else(|| Some("Alt+F4".to_owned()))),
                _ => MenuText::Key(label(id)),
            }
        });
        rail::set_keys(RailItem::ALL.map(|i| {
            let id = match i {
                RailItem::Connections => cmd::SESSIONS,
                RailItem::Sessions => cmd::LIVE,
                RailItem::Files => cmd::FILES,
                RailItem::Forwards => cmd::FORWARDS,
                RailItem::Snippets => cmd::SNIPPETS,
                RailItem::KnownHosts => cmd::KNOWN_HOSTS,
                RailItem::Inventory => cmd::INVENTORY,
                RailItem::Hosts => cmd::HOSTS,
                RailItem::Credentials => cmd::CREDENTIAL_MANAGER,
                RailItem::SecurityRules => cmd::SECURITY_RULES,
                RailItem::ThemeRules => cmd::THEME_RULES,
                RailItem::Themes => cmd::THEME_MANAGER,
                RailItem::Palette => cmd::PALETTE,
                RailItem::Pin => return String::new(),
            };
            label(id).unwrap_or_default()
        }));
    }

    fn search_key(&mut self, id: PaneId, vk: VIRTUAL_KEY, mods: Mods) -> KeyOutcome {
        let Some(p) = self.panes.get_mut(&id) else {
            return KeyOutcome::Default;
        };
        let term = &mut p.term;
        match vk {
            VK_ESCAPE => term.search_close(),
            VK_RETURN | VK_F3 => term.search_next(!mods.shift),
            VK_BACK => {
                let mut query = term.search_query().unwrap_or_default().to_owned();
                query.pop();
                term.search_set(&query);
            }
            // Characters arrive as WM_CHAR.
            _ => return KeyOutcome::Default,
        }
        drop_pending_char(self.hwnd);
        self.refresh(id);
        KeyOutcome::Handled
    }

    /// A key for the side pane; what it picked runs here.
    fn side_key(&mut self, key: SideKey) -> Option<Command> {
        if self.side.view == SideView::Palette {
            let action = self.palette.key(key, self.side.grid.rows());
            return self.palette_action(action);
        }
        if self.side.view == SideView::Snippets {
            let rows = self.side.grid.rows();
            let action = self.snippets_view.key(key, &self.settings.snippets, rows);
            return self.snippets_action(action);
        }
        if self.side.view == SideView::Forwards {
            let view = self.forward_view();
            let rows = self.side.grid.rows();
            let action = self.forwards_view.key(key, &view, rows);
            return self.forwards_action(action);
        }
        if self.side.view == SideView::Live {
            let all = self.open_sessions();
            let action = self.live_view.key(key, &all, self.side.grid.rows());
            // Every key changes what the view shows: the filter, the
            // selection or the name being typed.
            self.refresh_chrome();
            if action.is_none() && !self.live_view.renaming() && self.rename_return.is_some() {
                // Escape ended the rename.
                self.end_rename();
                return None;
            }
            return self.live_action(action);
        }
        if let Some(form) = &mut self.side.form {
            let action = form.key(key, self.side.grid.rows());
            return self.form_action(action);
        }
        if let Some(view) = &mut self.side.import {
            let action = view.key(key, self.side.grid.rows());
            return self.import_action(action);
        }
        let visible = SessionList::visible(self.side.grid.rows());
        let action = self.side.list.key(key, visible);
        self.side_action(action)
    }

    fn side_action(&mut self, action: Option<SideAction>) -> Option<Command> {
        let mut out = None;
        match action {
            Some(SideAction::Open { host, split }) => {
                self.open_host(&host, split);
            }
            Some(SideAction::ToggleFavourite(host)) => {
                self.settings.toggle_favourite(&host);
                self.side
                    .list
                    .set_favourites(self.settings.favourites.clone());
                self.save_settings();
            }
            Some(SideAction::SaveSearch(query)) => {
                if let Some(q) = ferossh_config::host_query::saved_text(&query)
                    && !self
                        .settings
                        .saved_searches
                        .iter()
                        .any(|s| s.eq_ignore_ascii_case(&q))
                {
                    self.settings.saved_searches.push(q);
                    self.side
                        .list
                        .set_saved_searches(self.settings.saved_searches.clone());
                    self.save_settings();
                }
            }
            Some(SideAction::RemoveSearch(query)) => {
                self.settings
                    .saved_searches
                    .retain(|s| !s.eq_ignore_ascii_case(&query));
                self.side
                    .list
                    .set_saved_searches(self.settings.saved_searches.clone());
                self.save_settings();
            }
            Some(SideAction::Bulk(action)) => self.bulk_action(action),
            Some(SideAction::New) => self.open_form(None),
            Some(SideAction::Edit(host)) => self.open_form(Some(host)),
            Some(SideAction::Delete(host)) => {
                out = Some(
                    if load_saved()
                        .iter()
                        .any(|h| h.alias.eq_ignore_ascii_case(&host))
                    {
                        Command::DeleteSession(host)
                    } else {
                        Command::Notice(format!(
                            "{host} comes from {}, which FeroSSH does not change. Edit or \
                             remove it there.",
                            host_file(&host)
                        ))
                    },
                );
            }
            Some(SideAction::OpenWorkspace(name)) => out = self.open_workspace_named(&name),
            Some(SideAction::DeleteWorkspace(name)) => out = Some(Command::DeleteWorkspace(name)),
            Some(SideAction::EditWorkspace(name)) => out = Some(Command::EditWorkspace(name)),
            Some(SideAction::Leave) => self.focus_terminal(),
            None => {}
        }
        self.refresh_chrome();
        out
    }

    /// Carries out what the snippets view decided.
    fn snippets_action(&mut self, action: Option<SnipAction>) -> Option<Command> {
        let mut out = None;
        match action {
            Some(SnipAction::Send { name, lines, enter }) => {
                out = self.send_snippet(&name, &lines, enter);
            }
            Some(SnipAction::Type { name, steps }) => out = self.type_snippet(&name, steps),
            Some(SnipAction::Copy(text)) => {
                clipboard::set_text(self.hwnd, &text);
            }
            Some(SnipAction::Save { index, mut snippet }) => {
                let all = &mut self.settings.snippets;
                let index = index.filter(|&i| i < all.len());
                // An edit keeps the snippet's file, so a new name or
                // category moves it.
                snippet.file = index.and_then(|i| all.get(i)).and_then(|s| s.file.clone());
                if let Err(e) = snippet_store::save(&snippets_dir(), &mut snippet) {
                    self.snippets_view.fail(e);
                    self.refresh_chrome();
                    return None;
                }
                match index {
                    Some(i) => {
                        if let Some(slot) = all.get_mut(i) {
                            *slot = snippet.clone();
                        }
                    }
                    None => all.push(snippet.clone()),
                }
                snippet_store::sort(all);
                let at = all.iter().position(|s| s.file == snippet.file);
                self.snippets_view.saved(&self.settings.snippets, at);
            }
            Some(SnipAction::Delete(i)) => out = Some(Command::DeleteSnippet(i)),
            Some(SnipAction::PickHosts { name, lines }) => out = self.pick_hosts(&name, &lines),
            Some(SnipAction::RunOn { name, hosts, run }) => out = self.run_on(name, hosts, run),
            Some(SnipAction::ShowRow(id)) => out = self.show_run_pane(id),
            Some(SnipAction::SaveCsv(text)) => {
                let name = self
                    .snippets_view
                    .report()
                    .map(|r| r.name.clone())
                    .unwrap_or_default();
                out = Some(Command::Notice(self.save_report(&name, &text)));
            }
            Some(SnipAction::Retry) => self.retry_run(),
            Some(SnipAction::Cancel) => self.cancel_run(),
            Some(SnipAction::CloseReport(report)) => self.close_report(&report),
            Some(SnipAction::Leave) => self.leave_snippets(),
            None => {}
        }
        self.refresh_chrome();
        out
    }

    /// Saves a report as CSV in the download folder; what happened.
    fn save_report(&self, name: &str, text: &str) -> String {
        let (y, mo, d, h, mi, sec) = local_time();
        let name: String = name
            .chars()
            .map(|c| {
                if c.is_alphanumeric() || c == '-' {
                    c
                } else {
                    '_'
                }
            })
            .take(60)
            .collect();
        let dir = self.download_dir();
        let path = dir.join(format!(
            "{name}-{y:04}{mo:02}{d:02}-{h:02}{mi:02}{sec:02}.csv"
        ));
        match std::fs::create_dir_all(&dir).and_then(|()| std::fs::write(&path, text)) {
            Ok(()) => format!("Saved the report as {}.", path.display()),
            Err(e) => format!("Could not save the report as {}: {e}", path.display()),
        }
    }

    /// Ctrl+Shift+A: the command palette, on every menu action, session
    /// and snippet; again, back to the terminal. A palette that lost the
    /// keyboard to a click in a pane gets it back first.
    fn toggle_palette(&mut self) {
        if self.side.visible && self.side.view == SideView::Palette {
            if self.side.focused {
                self.leave_palette();
            } else {
                self.side.focused = true;
                self.refresh_chrome();
                self.request_full_redraw();
                self.refresh(self.focused_id());
            }
            return;
        }
        // The menu's check marks are brought up to date first, since the
        // palette shows them.
        self.update_menu_checks();
        let mut entries = menu_entries(self.menu);
        // The workspaces Window > Workspaces listed are offered fresh below.
        entries.retain(|e| match e.kind {
            palette::Kind::Action(id) => {
                id != cmd::PALETTE
                    && !(cmd::WORKSPACE_OPEN..cmd::WORKSPACE_END).contains(&id)
                    && !(cmd::RECENT..cmd::RECENT_END).contains(&id)
            }
            _ => true,
        });
        let env = ssh_env();
        entries.extend(
            host_items(&env, &self.settings)
                .iter()
                .map(|h| palette::Entry::session(&h.name, &h.detail_with_tags(), h.kind)),
        );
        let place = self.place(self.focused_id()).map(|p| p.0);
        entries.extend(
            self.settings
                .snippets
                .iter()
                .enumerate()
                .filter(|(_, s)| s.applies(place.as_ref()))
                .map(|(i, s)| palette::Entry::snippet(i, &s.name, &s.lines)),
        );
        entries.extend(
            wsfile::list(&workspaces_dir())
                .iter()
                .map(|n| palette::Entry::workspace(n)),
        );
        self.palette.open(entries);
        // Snippets that only peeked go with the palette.
        self.palette_return = (self.side.visible && !self.snippets_peek).then_some(self.side.view);
        self.snippets_peek = false;
        self.show_side(SideView::Palette, true);
    }

    /// Closes the palette: the side pane shows what it showed before, or
    /// hides again, and the keyboard goes back to the terminal.
    fn leave_palette(&mut self) {
        match self.palette_return.take() {
            Some(view) => {
                self.side.view = view;
                self.side.focused = false;
                // A save while the palette was open may have merged in
                // rules from another window or PC.
                if view == SideView::SecurityRules && self.rules_native() {
                    rules_panel::set_rows(self.rule_rows());
                }
                self.refresh_chrome();
                self.request_full_redraw();
                self.refresh(self.focused_id());
            }
            None => self.hide_side(),
        }
        self.update_menu_checks();
        // The Session manager may be back, with agents to keep current.
        self.update_quiet_timer();
    }

    /// Carries out what the palette picked, once it is closed, so what
    /// runs sees the side pane as it was.
    fn palette_action(&mut self, action: Option<PalAction>) -> Option<Command> {
        let Some(action) = action else {
            self.refresh_chrome();
            return None;
        };
        self.leave_palette();
        match action {
            // Picked by name like a menu item: a side pane that is open
            // hides at once instead of first taking the keyboard.
            PalAction::Run(id) if is_side_pane(id) => self.toggle_side(id, true),
            PalAction::Run(id) => return Some(Command::Id(id)),
            PalAction::Open { host, split } => self.open_host(&host, split),
            PalAction::OpenWorkspace(name) => return self.open_workspace_named(&name),
            PalAction::Send { index, enter } => {
                let s = self.settings.snippets.get(index)?.clone();
                return self.send_snippet(&s.name, &s.lines, enter);
            }
            PalAction::RunApp(program) => {
                let pane = self.app_pane.take().unwrap_or_else(|| self.focused_id());
                return self.run_remote_app(
                    pane,
                    Some(&program),
                    None,
                    ferostream_client::transport::AttachTo::New,
                );
            }
            PalAction::Leave => {}
        }
        None
    }

    /// Pastes into the snippets view when it has the keyboard; `false`
    /// when the paste is for the terminal.
    /// Whether a paste is for the Known hosts tool.
    fn known_hosts_paste(&self) -> bool {
        self.side.visible && self.side.focused && self.side.view == SideView::KnownHosts
    }

    /// Whether a paste is for the Inventory tool.
    fn inventory_paste(&self) -> bool {
        self.side.visible && self.side.focused && self.side.view == SideView::Inventory
    }

    /// Whether a paste is for the Hosts tool.
    fn hosts_paste(&self) -> bool {
        self.side.visible && self.side.focused && self.side.view == SideView::Hosts
    }

    /// Whether a paste is for the credential manager.
    fn credentials_paste(&self) -> bool {
        self.side.visible && self.side.focused && self.side.view == SideView::Credentials
    }

    /// Whether a paste is for the security rules.
    fn rules_paste(&self) -> bool {
        self.side.visible && self.side.focused && self.side.view == SideView::SecurityRules
    }

    /// Whether a paste is for the theme manager.
    fn themes_paste(&self) -> bool {
        self.side.visible
            && self.side.focused
            && matches!(self.side.view, SideView::Themes | SideView::ThemeRules)
    }

    fn paste_side(&mut self, text: &str) -> bool {
        if self.side.visible
            && self.side.focused
            && self.side.view == SideView::Live
            && self.live_view.renaming()
        {
            self.live_view.paste(text);
            self.refresh_chrome();
            return true;
        }
        // The search box takes it (see `Command::Paste`: the box's change
        // event needs the window, so the paste comes after this borrow);
        // the list has nowhere to paste into, and the terminal behind must
        // not get it either.
        if self.known_hosts_paste()
            || self.inventory_paste()
            || self.hosts_paste()
            || self.credentials_paste()
            || self.rules_paste()
            || self.themes_paste()
        {
            return true;
        }
        if !(self.side.visible && self.side.focused && self.side.view == SideView::Snippets) {
            return false;
        }
        // The native editor's fields take it themselves.
        if self.script_editor_native() {
            script_editor::paste(text);
            return true;
        }
        if self.script_args_native() {
            script_args::paste(text);
            return true;
        }
        if self.script_hosts_native() {
            script_hosts::paste(text);
            return true;
        }
        // A report has nowhere to paste into.
        if self.script_report_native() {
            return true;
        }
        self.snippets_view.paste(text);
        self.refresh_chrome();
        true
    }

    /// Back to the terminal from the snippets: the side pane hides again
    /// when Ctrl+Shift+Space only peeked it, but a pinned pane stays open
    /// (the user asked for it to stay), so leaving just returns focus to
    /// the terminal.
    fn leave_snippets(&mut self) {
        if self.snippets_peek && !self.settings.tools_pinned {
            self.hide_side();
        } else {
            self.focus_terminal();
        }
    }

    /// Types snippet `name` (see [`Self::type_snippet`]); one with
    /// arguments first asks for them in the snippets view.
    fn send_snippet(&mut self, name: &str, lines: &[String], enter: bool) -> Option<Command> {
        let id = self.focused_id();
        if !self.takes_broadcast(id) {
            return Some(Command::Notice(
                "Scripts are typed into a pane with a running shell or console; this \
                 pane has none, or is at a prompt."
                    .into(),
            ));
        }
        let vars = self.vars(id, lines, true);
        if let Some(SnipAction::Type { name, steps }) =
            self.snippets_view.send(name, lines, enter, vars)
        {
            return self.type_snippet(&name, steps);
        }
        if self.side.visible && self.side.view == SideView::Snippets {
            self.side.focused = true;
            self.request_full_redraw();
        } else {
            let peek = !self.side.visible;
            self.show_side(SideView::Snippets, true);
            self.snippets_peek = peek;
        }
        self.refresh_chrome();
        None
    }

    /// Types a snippet's steps, arguments and variables filled in, into
    /// the focused pane and the panes broadcast input reaches; asks first
    /// when one of them has the Production theme.
    fn type_snippet(&mut self, name: &str, steps: Vec<Step>) -> Option<Command> {
        let id = self.focused_id();
        if !self.takes_broadcast(id) {
            return Some(Command::Notice(
                "Scripts are typed into a pane with a running shell or console; this \
                 pane has none, or is at a prompt."
                    .into(),
            ));
        }
        let mut panes = vec![id];
        panes.extend(self.broadcast_targets(id));
        let red: Vec<PaneId> = panes
            .iter()
            .copied()
            .filter(|p| {
                self.panes
                    .get(p)
                    .is_some_and(|p| p.theme.name == "Production")
            })
            .collect();
        let production: Vec<String> = red.into_iter().map(|p| self.pane_label(p)).collect();
        if self.settings.confirm_production && !production.is_empty() {
            return Some(Command::ConfirmSnippet {
                name: name.to_owned(),
                steps,
                panes,
                production,
            });
        }
        self.run_snippet(name, steps, &panes)
    }

    /// Types `steps` into `panes`: at once when none waits, else as a run
    /// in each pane, with a live report when it runs in several or
    /// captures values.
    fn run_snippet(&mut self, name: &str, steps: Vec<Step>, panes: &[PaneId]) -> Option<Command> {
        let capture = steps.iter().any(|s| matches!(s, Step::Capture(_)));
        if (capture || panes.len() > 1)
            && let Some(notice) = self.run_still_open()
        {
            return Some(notice);
        }
        // The steps from the first `@pane` or `@tab` on follow in the
        // pane it moves to, once the steps before it are done.
        let mut steps = steps;
        let after = steps
            .iter()
            .position(Step::moves)
            .map(|at| steps.split_off(at));
        if after.is_some() && panes.len() > 1 {
            return Some(Command::Notice(format!(
                "The script {name} moves to another pane or tab (@pane, @tab), so it runs \
                 in one pane only, not in {} at once.",
                panes.len()
            )));
        }
        self.leave_snippets();
        if !capture && let Some(bytes) = login::steps_bytes(&steps) {
            for &p in panes {
                self.input(p, bytes.clone());
            }
            if let (Some(after), Some(&p)) = (after, panes.first()) {
                self.snippet_move(p, name, after);
            }
            return None;
        }
        let report = capture || panes.len() > 1;
        let mut rows = Vec::new();
        for &p in panes {
            let label = self.pane_label(p);
            let state = if self.scripts.contains_key(&p) {
                RowState::Failed("another script runs there".into())
            } else {
                RowState::Running(None)
            };
            rows.push(ReportRow::new(&label, Some(p), state));
        }
        if report {
            self.show_report(Report::new(name, rows, None));
        }
        let what = format!("the script {name}");
        for &p in panes {
            if self.scripts.contains_key(&p) {
                continue;
            }
            if let Some(w) = self.watches.get_mut(&p) {
                w.resume();
            }
            self.script_runs += 1;
            let mut runner = Runner::named(&what, steps.clone());
            if let Some(after) = &after {
                self.snippet_next
                    .insert(p, (self.script_runs, name.to_owned(), after.clone()));
            }
            let actions = runner.start(Instant::now());
            self.scripts.insert(
                p,
                ScriptRun {
                    runner,
                    run: self.script_runs,
                    tmux: false,
                    report,
                    login: false,
                },
            );
            self.script_actions(p, actions);
        }
        self.refresh_chrome();
        None
    }

    /// The rest of snippet `name` after the part that ran in pane `from`:
    /// `rest` starts with an `@pane` or `@tab` step, which focuses the
    /// pane it names; the steps after it run there.
    fn snippet_move(&mut self, from: PaneId, name: &str, mut rest: Vec<Step>) {
        if rest.is_empty() {
            return;
        }
        let step = rest.remove(0);
        let Some(t) = self.ws.tab_of(from) else {
            return;
        };
        let (to, missing) = match &step {
            Step::Pane(d) => {
                let dir = match d.as_str() {
                    "left" => Dir::Left,
                    "right" => Dir::Right,
                    "up" => Dir::Up,
                    _ => Dir::Down,
                };
                let g = gap(self.dpi);
                let to = self.ws.tabs.get(t).and_then(|tab| {
                    layout::neighbour(&tab.root.layout(self.areas.panes, g), from, dir)
                });
                (to, format!("there is no pane {d} of this one"))
            }
            Step::Tab(w) => {
                let n = self.ws.tabs.len();
                let i = if w == "next" {
                    (t + 1) % n.max(1)
                } else {
                    (t + n - 1) % n.max(1)
                };
                let to = Some(i)
                    .filter(|&i| i != t)
                    .and_then(|i| self.ws.tabs.get(i))
                    .map(|tab| tab.focus);
                (to, "there is no other tab".to_owned())
            }
            _ => return,
        };
        let Some(to) = to else {
            self.show(
                from,
                &format!("\x1b[0;31m[the script {name} stopped: {missing}]\x1b[0m\r\n"),
            );
            return;
        };
        self.focus_pane(to);
        if let Some(Command::Notice(text)) = self.run_snippet(name, rest, &[to]) {
            self.show(to, &format!("\x1b[0;31m{text}\x1b[0m\r\n"));
        }
    }

    /// Shows `report` in the snippets view, which takes the keyboard.
    fn show_report(&mut self, report: Report) {
        if !(self.side.visible && self.side.view == SideView::Snippets) {
            let peek = !self.side.visible;
            self.show_side(SideView::Snippets, true);
            self.snippets_peek = peek;
        } else {
            self.side.focused = true;
        }
        self.snippets_view.show_report(report);
    }

    /// A notice when the report of a run on picked hosts is still open:
    /// its sessions go only when it closes, so a new report waits.
    fn run_still_open(&self) -> Option<Command> {
        let r = self.snippets_view.report().filter(|r| r.run.is_some())?;
        Some(Command::Notice(format!(
            "The report of the run of {} is still open. Close it first: Escape in the \
             scripts view (Ctrl+Shift+Space).",
            r.name
        )))
    }

    /// The password typed for the run on picked hosts, if one was.
    fn run_password(&self) -> Option<Zeroizing<String>> {
        let run = self.snippets_view.report()?.run.as_ref()?;
        run.password.as_ref().map(|p| p.0.clone())
    }

    /// F5 in the snippets view: the page that picks the hosts to run
    /// snippet `name` on. The hosts the snippet is kept to come picked.
    fn pick_hosts(&mut self, name: &str, lines: &[String]) -> Option<Command> {
        if let Some(notice) = self.run_still_open() {
            return Some(notice);
        }
        let snippet = self
            .settings
            .snippets
            .iter()
            .find(|s| s.name == name)
            .cloned()
            .unwrap_or_default();
        let env = ssh_env();
        let hosts: Vec<PickHost> = host_items(&env, &self.settings)
            .into_iter()
            .filter(|h| h.kind == SessionKind::Ssh)
            .map(|h| {
                let detail = h.detail_with_tags();
                let host = Target::resolve(&h.name, &env)
                    .map(|t| t.hostname)
                    .unwrap_or_default();
                let place = Place {
                    session: h.name,
                    host,
                    folder: h.folder,
                };
                let picked = !snippet.everywhere() && snippet.applies(Some(&place));
                PickHost {
                    place,
                    detail,
                    picked,
                }
            })
            .collect();
        if hosts.is_empty() {
            return Some(Command::Notice(
                "There are no saved SSH sessions to run the script on. Save the hosts in \
                 the connection manager first."
                    .into(),
            ));
        }
        let parallel = self
            .settings
            .run_parallel
            .unwrap_or(batch::DEFAULT_PARALLEL);
        self.snippets_view
            .show_picker(Picker::new(name, lines, hosts, parallel));
        None
    }

    /// Runs snippet `name` on `hosts`; asks first when one of them has
    /// the Production theme.
    fn run_on(&mut self, name: String, hosts: Vec<Place>, run: Run) -> Option<Command> {
        if let Some(notice) = self.run_still_open() {
            return Some(notice);
        }
        if self
            .settings
            .run_parallel
            .unwrap_or(batch::DEFAULT_PARALLEL)
            != run.parallel
        {
            self.settings.run_parallel = Some(run.parallel);
            self.save_settings();
        }
        let env = ssh_env();
        let production: Vec<String> = hosts
            .iter()
            .filter(|h| {
                let tag = Target::resolve(&h.session, &env).and_then(|t| t.tag);
                let (_, theme) = look::for_host(
                    &self.settings,
                    &h.session,
                    &h.host,
                    tag.as_deref(),
                    &self.default_font,
                    &self.default_theme,
                );
                theme.name == "Production"
            })
            .map(|h| h.session.clone())
            .collect();
        if self.settings.confirm_production && !production.is_empty() {
            return Some(Command::ConfirmRun {
                name,
                hosts,
                run,
                production,
            });
        }
        self.start_run(&name, &hosts, run);
        None
    }

    /// Starts the run of snippet `name` on `hosts`: its report opens and
    /// the first hosts log in.
    fn start_run(&mut self, name: &str, hosts: &[Place], run: Run) {
        let rows = hosts
            .iter()
            .map(|h| ReportRow::new(&h.session, None, RowState::Queued))
            .collect();
        self.show_report(Report::new(name, rows, Some(run)));
        self.pump_run();
    }

    /// Starts the queued hosts of the run there is room for, each in a
    /// session of its own that no tab shows (a new channel on a
    /// connection another pane already has to it).
    fn pump_run(&mut self) {
        let starts: Vec<(usize, String)> = match self.snippets_view.report_mut() {
            Some(r) => r
                .starting(Instant::now())
                .into_iter()
                .filter_map(|i| r.rows.get(i).map(|row| (i, row.label.clone())))
                .collect(),
            None => Vec::new(),
        };
        for (i, session) in starts {
            let id = self.ws.alloc_id();
            self.add_pane(id);
            self.run_hidden.insert(id);
            self.run_login.insert(id);
            if let Some(row) = self
                .snippets_view
                .report_mut()
                .and_then(|r| r.rows.get_mut(i))
            {
                row.pane = Some(id);
            }
            self.connect(id, &session);
            if self.confirm_pending(id) {
                // The row waits for the security rule's answer.
                self.after_confirm(id, AfterConfirm::Run);
            } else {
                self.run_connected(id);
            }
        }
        self.arm_run_timer();
        self.refresh_chrome();
    }

    /// A run's host that was just asked to connect: its row fails if it
    /// did not, else its login is watched.
    fn run_connected(&mut self, id: PaneId) {
        if self
            .panes
            .get(&id)
            .is_some_and(|p| matches!(p.host, Host::Ask(_)))
        {
            let why = self.run_notes.get(&id).cloned();
            self.fail_run_row(id, why.unwrap_or_else(|| "could not connect".into()));
        } else {
            self.check_run_login(id);
        }
    }

    /// A run's host that is logging in: its row fails when the login
    /// asks for anything (a host key, a password, a code) or ends. The
    /// session stays, so it can be shown and answered by hand.
    fn check_run_login(&mut self, id: PaneId) {
        if !self.run_login.contains(&id) {
            return;
        }
        // A key whose passphrase is not in the agent is skipped, as an
        // empty passphrase does by hand: the login goes on with the next
        // key or the password.
        if let Some(Host::Ssh(s)) = self.panes.get_mut(&id).map(|p| &mut p.host)
            && s.prompt_asks() == Some("a key passphrase")
        {
            let effects = s.prompt_input(b"\r");
            self.apply(id, effects);
            return;
        }
        let said = || self.run_notes.get(&id).cloned();
        // A pane with no host yet is still being set up: `pump_run` checks
        // that the connection started.
        let why = match self.panes.get(&id).map(|p| &p.host) {
            Some(Host::Ssh(s)) => match s.state() {
                State::Blocked => Some("the host key changed".to_owned()),
                State::Ended => {
                    Some(said().unwrap_or_else(|| "could not connect or log in".into()))
                }
                _ => s.prompt_asks().map(|what| format!("asked for {what}")),
            },
            Some(Host::Telnet(s)) if s.state() == State::Ended => {
                Some(said().unwrap_or_else(|| "could not connect".into()))
            }
            Some(Host::Winrm(s)) if s.state() == State::Ended => {
                Some(said().unwrap_or_else(|| "could not connect or log in".into()))
            }
            Some(_) => None,
            None => Some("the session was closed".to_owned()),
        };
        if let Some(why) = why {
            self.fail_run_row(id, why);
        }
    }

    /// Fails the row of a run's pane `id`; the next host may start.
    fn fail_run_row(&mut self, id: PaneId, why: String) {
        self.run_login.remove(&id);
        self.run_notes.remove(&id);
        self.scripts.remove(&id);
        if let Some(row) = self.snippets_view.report_mut().and_then(|r| r.row_mut(id))
            && !row.state.over()
        {
            row.state = RowState::Failed(why);
        }
        self.pump_run();
    }

    /// A run's host is logged in (its login script over): the snippet
    /// starts there, its arguments and that host's variables filled in.
    fn begin_run_snippet(&mut self, id: PaneId) {
        self.run_login.remove(&id);
        self.run_notes.remove(&id);
        let Some((name, lines, args)) = self.snippets_view.report().and_then(|r| {
            let run = r.run.as_ref()?;
            Some((r.name.clone(), run.lines.clone(), run.args.clone()))
        }) else {
            return;
        };
        let vars = self.vars(id, &lines, true);
        let steps = login::expand(
            &lines,
            true,
            |n| {
                args.iter()
                    .find(|(k, _)| *k == n)
                    .map(|(_, v)| v.clone())
                    .unwrap_or_default()
            },
            |v| {
                vars.iter()
                    .find(|(k, _)| *k == v)
                    .map(|(_, x)| x.clone())
                    .unwrap_or_default()
            },
        );
        if let Some(row) = self.snippets_view.report_mut().and_then(|r| r.row_mut(id)) {
            row.state = RowState::Running(None);
        }
        self.script_runs += 1;
        let mut runner = Runner::named(&format!("the script {name}"), steps);
        let actions = runner.start(Instant::now());
        self.scripts.insert(
            id,
            ScriptRun {
                runner,
                run: self.script_runs,
                tmux: false,
                report: true,
                login: false,
            },
        );
        self.script_actions(id, actions);
    }

    /// Ends a run's session that no tab shows.
    fn drop_run_pane(&mut self, id: PaneId) {
        self.run_login.remove(&id);
        self.run_notes.remove(&id);
        self.scripts.remove(&id);
        if self.run_hidden.remove(&id) {
            self.end_host(id);
            self.panes.remove(&id);
            self.watches.remove(&id);
        }
    }

    /// Escape while the run goes: the queued hosts never start, and the
    /// running ones stop. Sessions still logging in end.
    fn cancel_run(&mut self) {
        let panes = self
            .snippets_view
            .report_mut()
            .map(Report::cancel)
            .unwrap_or_default();
        for p in panes {
            self.scripts.remove(&p);
            self.run_notes.remove(&p);
            if self.run_login.remove(&p) && self.run_hidden.contains(&p) {
                self.end_host(p);
            }
        }
        self.arm_run_timer();
    }

    /// R in the report: the failed and stopped hosts run again, in new
    /// sessions.
    fn retry_run(&mut self) {
        let panes = self
            .snippets_view
            .report_mut()
            .map(Report::retry)
            .unwrap_or_default();
        for p in panes {
            self.drop_run_pane(p);
        }
        self.pump_run();
    }

    /// The report closed: the sessions of a run that no tab shows end.
    fn close_report(&mut self, report: &Report) {
        if report.run.is_some() {
            for p in report.rows.iter().filter_map(|r| r.pane) {
                self.drop_run_pane(p);
            }
        }
        self.arm_run_timer();
        self.leave_snippets();
    }

    /// Enter on a report row: that host's session in a tab of its own,
    /// live, or its tab when it has one.
    fn show_run_pane(&mut self, id: PaneId) -> Option<Command> {
        if !self.panes.contains_key(&id) {
            return Some(Command::Notice("That session was closed.".into()));
        }
        if self.run_hidden.remove(&id) {
            let at = self.ws.tabs.len();
            self.ws.insert_tab(at, layout::Node::Leaf(id), id);
        }
        self.focus_pane(id);
        self.after_structure_change();
        self.focus_terminal();
        None
    }

    /// Sets the timer for the next host of the run to take too long.
    fn arm_run_timer(&mut self) {
        let next = self.snippets_view.report().and_then(Report::deadline);
        // SAFETY: our window; replaces any earlier timer with this id.
        unsafe {
            match next {
                Some(at) => {
                    let wait = at.saturating_duration_since(Instant::now());
                    let ms = u32::try_from(wait.as_millis()).unwrap_or(u32::MAX).max(1);
                    SetTimer(Some(self.hwnd), TIMER_RUN, ms, None);
                }
                None => {
                    let _ = KillTimer(Some(self.hwnd), TIMER_RUN);
                }
            }
        }
    }

    fn on_run_timer(&mut self) {
        let late = self
            .snippets_view
            .report_mut()
            .map(|r| r.timed_out(Instant::now()))
            .unwrap_or_default();
        for p in late {
            self.scripts.remove(&p);
            self.run_login.remove(&p);
            self.run_notes.remove(&p);
            // A row that timed out waiting for a security rule's answer
            // is over: a late Yes no longer connects it.
            if self
                .connect_pending
                .get(&p)
                .is_some_and(|c| matches!(c.after, AfterConfirm::Run))
            {
                self.connect_pending.remove(&p);
            }
        }
        self.pump_run();
    }

    /// Ctrl+Shift+F`n`: the first snippet with that hotkey for the
    /// focused pane's host; `None` when there is none.
    fn snippet_hotkey(&mut self, n: u8) -> Option<Option<Command>> {
        let place = self.place(self.focused_id()).map(|p| p.0);
        let s = self
            .settings
            .snippets
            .iter()
            .find(|s| s.hotkey == Some(n) && s.applies(place.as_ref()))?
            .clone();
        Some(self.send_snippet(&s.name, &s.lines, true))
    }

    /// A short name for pane `id`'s host, for the report.
    fn pane_label(&mut self, id: PaneId) -> String {
        match self.place(id) {
            Some((place, ..)) if !place.session.is_empty() => place.session,
            _ => format!("pane {id}"),
        }
    }

    /// Where pane `id` is connected, with its user and port.
    fn place(&mut self, id: PaneId) -> Option<(Place, String, u16)> {
        let (session, host, user, port) = match &self.panes.get(&id)?.host {
            Host::Ssh(s) => (
                s.target.alias.clone(),
                s.target.hostname.clone(),
                s.target.user.clone(),
                s.target.port,
            ),
            Host::Telnet(s) => (
                s.target.alias.clone(),
                s.target.hostname.clone(),
                String::new(),
                s.target.port,
            ),
            Host::Serial {
                target, session, ..
            } => (
                session.clone().unwrap_or_else(|| target.port.clone()),
                target.port.clone(),
                String::new(),
                0,
            ),
            Host::Winrm(s) => (
                s.target.alias.clone(),
                s.target.hostname.clone(),
                s.target.user.clone().unwrap_or_default(),
                s.target.port,
            ),
            Host::Tmux { gateway, .. } => {
                let gateway = *gateway;
                return self.place(gateway);
            }
            _ => return None,
        };
        let folder = self.folder_of(&session);
        Some((
            Place {
                session,
                host,
                folder,
            },
            user,
            port,
        ))
    }

    /// Session `name`'s folder in the connection manager, read again from
    /// ssh_config at most every half minute.
    fn folder_of(&mut self, name: &str) -> Option<String> {
        if self
            .folders
            .as_ref()
            .is_none_or(|(at, _)| at.elapsed() > Duration::from_secs(30))
        {
            let env = ssh_env();
            let map = host_items(&env, &self.settings)
                .into_iter()
                .filter_map(|h| Some((h.name, h.folder?)))
                .collect();
            self.folders = Some((Instant::now(), map));
        }
        self.folders.as_ref()?.1.get(name).cloned()
    }

    /// The variables' values in pane `id`; the clipboard is read only
    /// when `lines` use it and `clipboard` allows it.
    fn vars(&mut self, id: PaneId, lines: &[String], clipboard: bool) -> Vars {
        let (y, mo, d, h, mi, sec) = local_time();
        let mut vars: Vars = vec![
            ("date", format!("{y:04}-{mo:02}-{d:02}")),
            ("time", format!("{h:02}:{mi:02}:{sec:02}")),
            (
                "stamp",
                format!("{y:04}{mo:02}{d:02}-{h:02}{mi:02}{sec:02}"),
            ),
        ];
        if let Some((place, user, port)) = self.place(id) {
            vars.push(("session", place.session));
            vars.push(("host", place.host));
            vars.push(("user", user));
            if port != 0 {
                vars.push(("port", port.to_string()));
            }
        }
        if clipboard && login::uses_var(lines, "clipboard") {
            vars.push((
                "clipboard",
                clipboard::get_text(self.hwnd).unwrap_or_default(),
            ));
        }
        vars
    }

    /// Every terminal sends keys as the settings now say; turning the
    /// kitty keyboard protocol off ends it for programs that had it on.
    fn apply_keys(&mut self) {
        let keys = key_options(&self.settings);
        KEY_OPTIONS.set(keys);
        for p in self.panes.values_mut() {
            p.term.set_keys(keys);
        }
    }

    /// Looks for a web server's address in what pane `id`'s host printed
    /// and offers to forward its port (Session > Coding agents > Offer
    /// to forward and open web servers). Only SSH panes, logged in, can
    /// forward; a port forwarded or turned down is not offered again on
    /// that connection.
    fn scan_preview(&mut self, id: PaneId, bytes: &[u8]) {
        if !self.settings.port_previews {
            return;
        }
        let Some(connection) = self.pane_connection(id) else {
            self.preview_scans.remove(&id);
            return;
        };
        let scan = self
            .preview_scans
            .entry(id)
            .or_insert_with(|| (connection, crate::preview::Scanner::default()));
        if scan.0 != connection {
            *scan = (connection, crate::preview::Scanner::default());
        }
        let found = scan.1.feed(bytes);
        if found.is_empty() {
            return;
        }
        let host_id = self.host_pane(id);
        let Some(Host::Ssh(s)) = self.panes.get(&host_id).map(|p| &p.host) else {
            return;
        };
        if s.target.no_shell() || !self.workers.contains_key(&connection) {
            return;
        }
        let host = s.target.label();
        let Some(url) = found
            .into_iter()
            .rev()
            .find(|u| !self.preview_done.contains(&(connection, u.port)))
        else {
            return;
        };
        let since = Instant::now();
        if let Some(pv) = self.previews.get_mut(&id)
            && pv.connection == connection
            && pv.url == url
        {
            // Printed again: it shows for longer.
            pv.since = since;
            return;
        }
        self.previews.insert(
            id,
            Preview {
                url,
                host,
                connection,
                since,
                grid: Grid::new(1, 1),
                rect: Rect::default(),
            },
        );
        self.preview_moved(id);
        // SAFETY: our window and timer id.
        unsafe {
            SetTimer(Some(self.hwnd), TIMER_PREVIEW, PREVIEW_TICK_MS, None);
        }
    }

    /// Pane `id`'s bar came, went or changed: the pane is drawn again
    /// under it.
    fn preview_moved(&mut self, id: PaneId) {
        if let Some(p) = self.panes.get_mut(&id) {
            p.grid.mark_all_dirty();
            let r = p.rect;
            // SAFETY: valid window and rect.
            unsafe {
                let _ = InvalidateRect(Some(self.hwnd), Some(&win_rect(r)), false);
            }
        }
    }

    /// Takes pane `id`'s bar away; `done` keeps its port from being
    /// offered again on that connection.
    fn drop_preview(&mut self, id: PaneId, done: bool) -> Option<Preview> {
        let pv = self.previews.remove(&id)?;
        self.preview_moved(id);
        if done {
            let key = (pv.connection, pv.url.port);
            self.preview_done.insert(key);
            // Other panes' bars for the same port go too: it is offered
            // once per connection.
            let same: Vec<PaneId> = self
                .previews
                .iter()
                .filter(|(_, o)| (o.connection, o.url.port) == key)
                .map(|(id, _)| *id)
                .collect();
            for other in same {
                self.previews.remove(&other);
                self.preview_moved(other);
            }
        }
        Some(pv)
    }

    /// Pane `id`'s connection ended: its watch, and those of its tmux
    /// panes, start afresh with the next one, so text cut off at the end
    /// is not read with what comes next.
    fn forget_preview_scans(&mut self, id: PaneId) {
        let panes = &self.panes;
        self.preview_scans
            .retain(|p, _| *p != id && panes.get(p).and_then(Pane::gateway) != Some(id));
    }

    /// Fits each bar into its pane's top right corner and draws it; a bar
    /// that does not fit, or whose pane does not show, is not drawn.
    fn place_previews(&mut self) {
        if self.previews.is_empty() {
            return;
        }
        self.previews.retain(|id, _| self.panes.contains_key(id));
        let visible: HashSet<PaneId> = self.visible_ids().into_iter().collect();
        let pad = padding(self.dpi);
        let cpad = scale(CHROME_PADDING_DIP, self.dpi);
        let spad = scale(STRIP_PAD_DIP, self.dpi);
        let cw = self.strip_metrics.width.max(1) as i32;
        let ch = self.strip_metrics.height as i32 + 2 * spad;
        let palette = self.strip_palette();
        for (id, pv) in &mut self.previews {
            pv.rect = Rect::default();
            let Some(p) = self.panes.get(id).filter(|_| visible.contains(id)) else {
                continue;
            };
            let r = p.rect;
            let room = ((r.w - 2 * pad - 2 * cpad) / cw).max(0) as usize;
            let cols = crate::preview::width(&pv.url, &pv.host, room);
            // Too small a pane: the bar would cover it.
            if cols < 24 || ch * 3 > r.h {
                continue;
            }
            let w = cols as i32 * cw + 2 * cpad;
            pv.rect = Rect::new(r.right() - pad - w, r.y + pad, w, ch);
            if pv.grid.cols() != cols {
                pv.grid.resize(cols, 1);
            }
            crate::preview::draw(&mut pv.grid, &pv.url, &pv.host, &palette);
        }
    }

    /// What a click at (`x`, `y`) on pane `id`'s bar does, if it is on it.
    fn preview_hit(&self, id: PaneId, x: i32, y: i32) -> Option<crate::preview::Hit> {
        let pv = self.previews.get(&id)?;
        if pv.rect.w <= 0 || !pv.rect.contains(x, y) {
            return None;
        }
        let cpad = scale(CHROME_PADDING_DIP, self.dpi);
        let cw = self.strip_metrics.width.max(1) as i32;
        let col = ((x - pv.rect.x - cpad).max(0) / cw) as usize;
        Some(crate::preview::hit(col, pv.grid.cols()))
    }

    /// A click on pane `id`'s bar: the close button takes it away; the
    /// rest forwards the port to a free one here (the same number when
    /// it is free) and opens the browser once it listens. The forward is
    /// listed in Tools > Port forwards like any other, and a reconnect
    /// starts it again.
    fn preview_click(&mut self, id: PaneId, hit: crate::preview::Hit) -> Option<Command> {
        let pv = self.drop_preview(id, true)?;
        if hit == crate::preview::Hit::Dismiss {
            return None;
        }
        let url = pv.url;
        let target = ferossh_config::forward::Target::Tcp(url.target().to_owned(), url.port);
        let view = self.forward_view();
        if !view.iter().any(|v| v.connection == pv.connection) {
            return Some(Command::Notice(format!(
                "{} is not logged in any more, so port {} cannot be forwarded.",
                pv.host, url.port
            )));
        }
        // A forward that already goes there serves.
        if let Some(f) = forwards_of(&view, pv.connection).find(|f| {
            // A socket listener has no address a browser could open.
            f.spec.kind == ForwardKind::Local
                && f.spec.socket.is_none()
                && f.spec.target.as_ref() == Some(&target)
        }) {
            match &f.state {
                FwdState::Listening(addrs) => {
                    return url
                        .local(addrs.split(", ").next().unwrap_or_default())
                        .map(Command::OpenPreview);
                }
                FwdState::Starting => {
                    self.preview_waiting.push(PreviewWait {
                        connection: pv.connection,
                        spec: f.spec.clone(),
                        url,
                        since: Instant::now(),
                    });
                    return None;
                }
                // A failed one is left as it is; a new one is tried.
                FwdState::Failed(_) => {}
            }
        }
        let Some(local) = free_local_port(url.port) else {
            return Some(Command::Notice(
                "No local port is free to forward to.".into(),
            ));
        };
        let spec = ForwardSpec {
            kind: ForwardKind::Local,
            bind: Some("127.0.0.1".into()),
            port: local,
            socket: None,
            target: Some(target),
        };
        let w = self.workers.get(&pv.connection)?;
        w.forwarder.add(pv.connection, spec.clone());
        self.keep_forwards(pv.connection, |list| {
            if !list.contains(&spec) {
                list.push(spec.clone());
            }
        });
        self.preview_waiting.push(PreviewWait {
            connection: pv.connection,
            spec,
            url,
            since: Instant::now(),
        });
        None
    }

    /// Opens the browser on the forwards from a bar that listen now, and
    /// says why the ones that failed did.
    fn settle_previews(&mut self) {
        if self.preview_waiting.is_empty() {
            return;
        }
        let view = self.forward_view();
        let mut out = Vec::new();
        self.preview_waiting.retain(|w| {
            let state = forwards_of(&view, w.connection)
                .find(|f| f.spec == w.spec)
                .map(|f| &f.state);
            match state {
                Some(FwdState::Listening(addrs)) => {
                    if let Some(url) = w.url.local(addrs.split(", ").next().unwrap_or_default()) {
                        out.push(Command::OpenPreview(url));
                    }
                    false
                }
                Some(FwdState::Failed(why)) => {
                    out.push(Command::Notice(format!(
                        "Port {} could not be forwarded to this PC: {why}",
                        w.url.port
                    )));
                    false
                }
                Some(FwdState::Starting) if w.since.elapsed() >= PREVIEW_WAIT => {
                    out.push(Command::Notice(format!(
                        "The forward of port {} did not start listening on this PC, so the \
                         browser was not opened. Tools > Port forwards shows it.",
                        w.url.port
                    )));
                    false
                }
                Some(FwdState::Starting) => true,
                None => w.since.elapsed() < PREVIEW_WAIT,
            }
        });
        self.queued.extend(out);
    }

    /// Takes away the bars nobody clicked, and the watches of panes that
    /// are gone; a port whose bar went this way is offered again when it
    /// is printed again.
    fn on_preview_timer(&mut self) {
        let old: Vec<PaneId> = self
            .previews
            .iter()
            .filter(|(id, pv)| !self.panes.contains_key(id) || pv.since.elapsed() >= PREVIEW_SHOWN)
            .map(|(id, _)| *id)
            .collect();
        for id in old {
            self.drop_preview(id, false);
        }
        self.preview_scans
            .retain(|id, _| self.panes.contains_key(id));
        self.settle_previews();
        if self.previews.is_empty() && self.preview_waiting.is_empty() {
            // SAFETY: our window and timer id.
            unsafe {
                let _ = KillTimer(Some(self.hwnd), TIMER_PREVIEW);
            }
        }
    }

    /// What pane `id`'s host printed, for auto-responses and a recording.
    fn watch_output(&mut self, id: PaneId, bytes: &[u8]) {
        self.scan_preview(id, bytes);
        if let Some((pane, rec)) = &mut self.recording
            && *pane == id
        {
            rec.output(bytes);
        }
        // A running script or snippet owns the pane's answers.
        if !self.settings.auto_responses
            || self.scripts.contains_key(&id)
            || !self.settings.snippets.iter().any(|s| !s.when.is_empty())
        {
            self.watches.remove(&id);
            return;
        }
        let place = self.place(id).map(|p| p.0);
        let whens: Vec<(usize, &str)> = self
            .settings
            .snippets
            .iter()
            .enumerate()
            .filter(|(_, s)| {
                !s.when.is_empty() && s.auto_problem().is_none() && s.applies(place.as_ref())
            })
            .map(|(i, s)| (i, s.when.as_str()))
            .collect();
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map_or(0, |d| u64::try_from(d.as_millis()).unwrap_or(u64::MAX));
        let fires = self.watches.entry(id).or_default().feed(bytes, &whens, now);
        for fire in fires {
            match fire {
                Fire::Snippet(i) => {
                    let Some(s) = self.settings.snippets.get(i).cloned() else {
                        continue;
                    };
                    // No clipboard: the host decides when this types.
                    let vars = self.vars(id, &s.lines, false);
                    let steps = login::expand(
                        &s.lines,
                        true,
                        |_| String::new(),
                        |n| {
                            vars.iter()
                                .find(|(k, _)| *k == n)
                                .map(|(_, v)| v.clone())
                                .unwrap_or_default()
                        },
                    );
                    if let Some(bytes) = login::steps_bytes(&steps) {
                        self.send(id, bytes);
                    }
                }
                Fire::Paused => self.show(
                    id,
                    "\r\n\x1b[0;90m[Auto-responses paused: the host asked too often. They \
                     start again when you type.]\x1b[0m\r\n",
                ),
            }
        }
    }

    /// Session > Scripts > Record keystrokes as script: starts recording the focused
    /// pane's typing, or stops and opens the recording in the snippets
    /// view to name and check.
    fn toggle_recording(&mut self) -> Option<Command> {
        if let Some((pane, rec)) = self.recording.take() {
            self.show(pane, "\x1b[0;90m[Recording stopped]\x1b[0m\r\n");
            self.refresh(pane);
            self.update_menu_checks();
            let rec = rec.finish();
            if rec.lines.is_empty() {
                return Some(Command::Notice("Nothing was typed while recording.".into()));
            }
            self.snippets_view.new_recorded(rec);
            self.show_side(SideView::Snippets, true);
            self.snippets_peek = false;
            self.refresh_chrome();
            return None;
        }
        let id = self.focused_id();
        if !self.takes_broadcast(id) {
            return Some(Command::Notice(
                "Recording takes typing in a pane with a running shell or console.".into(),
            ));
        }
        self.recording = Some((id, Recorder::default()));
        self.show(
            id,
            "\x1b[0;90m[Recording keystrokes as a script. Session > Scripts > Record keystrokes as script \
             again stops it.]\x1b[0m\r\n",
        );
        self.refresh(id);
        self.update_menu_checks();
        None
    }

    fn delete_snippet(&mut self, index: usize) -> Option<Command> {
        let mut out = None;
        if index < self.settings.snippets.len() {
            let s = self.settings.snippets.remove(index);
            if s.file.is_none() {
                // One still kept in ferossh.conf.
                self.save_settings();
            } else if let Err(e) = snippet_store::remove(&snippets_dir(), &s) {
                out = Some(Command::Notice(format!(
                    "Could not remove the script's file: {e}"
                )));
            }
        }
        self.snippets_view.saved(&self.settings.snippets, None);
        self.refresh_chrome();
        out
    }

    /// Reads the snippets folder again, so snippet files copied into it
    /// show up. Snippets still kept in `ferossh.conf` (the folder could
    /// not be written) stay.
    fn reload_snippets(&mut self) {
        let dir = snippets_dir();
        if self.settings.snippets.iter().any(|s| s.file.is_none()) {
            if snippet_store::migrate(&dir, &self.settings.snippets).is_err() {
                return;
            }
            self.settings.snippets = snippet_store::load(&dir).0;
            self.save_settings();
            return;
        }
        self.settings.snippets = snippet_store::load(&dir).0;
    }

    /// File > Import and export > Import scripts: the import page, on what other programs
    /// on this account have.
    fn open_snippet_import(&mut self, found: Vec<SnippetSource>, problems: Vec<String>) {
        let list = found
            .into_iter()
            .map(|(c, origin, s)| found_snippets(c, origin, s))
            .collect();
        self.side.form = None;
        self.side.import = Some(ImportView::snippets(list, problems));
        self.show_side(SideView::Sessions, true);
        self.refresh_chrome();
    }

    /// Snippets read from a file the user picked on the import page.
    fn add_snippet_import(&mut self, (client, origin, snippets): SnippetSource) {
        if let Some(view) = &mut self.side.import {
            view.add(found_snippets(client, origin, snippets));
        }
        self.refresh_chrome();
    }

    /// Adds imported snippets to the snippets folder; says what happened.
    fn write_snippet_import(&mut self, snippets: Vec<Snippet>) -> String {
        let dir = snippets_dir();
        let mut done = 0;
        let mut failed = None;
        for mut s in snippets {
            match snippet_store::add(&dir, &mut s) {
                Ok(()) => done += 1,
                Err(e) => {
                    failed = Some(e);
                    break;
                }
            }
        }
        self.reload_snippets();
        self.side.import = None;
        self.show_side(SideView::Snippets, true);
        let mut text = format!(
            "Imported {done} script{} into {}. Each has a file there, in a folder named \
             after its category.",
            plural(done),
            dir.display()
        );
        if let Some(e) = failed {
            text.push_str(&format!("\n\nThe rest were not imported: {e}"));
        }
        text
    }

    /// File > Import and export > Import connections: the import page, on what the clients
    /// on this account have saved.
    fn open_import(&mut self, sessions: Vec<ImportSource>, problems: Vec<String>) {
        let list = sessions
            .into_iter()
            .map(|(c, origin, s)| found(c, origin, s))
            .collect();
        self.side.form = None;
        self.side.import = Some(ImportView::new(list, problems));
        self.show_side(SideView::Sessions, true);
        self.refresh_chrome();
    }

    /// Sessions read from a file the user picked on the import page.
    fn add_import(&mut self, (client, origin, sessions): ImportSource) {
        if let Some(view) = &mut self.side.import {
            view.add(found(client, origin, sessions));
        }
        self.refresh_chrome();
    }

    /// Carries out what the import page asked for.
    fn import_action(&mut self, action: Option<ImportAction>) -> Option<Command> {
        let mut out = None;
        match action {
            Some(ImportAction::Close) => self.side.import = None,
            Some(ImportAction::FromFile) => out = Some(Command::PickImportFile),
            Some(ImportAction::Import { client, sessions }) => {
                out = Some(Command::Notice(self.write_import(client, &sessions)));
            }
            Some(ImportAction::ImportSnippets(snippets)) => {
                out = Some(Command::Notice(self.write_snippet_import(snippets)));
            }
            None => {}
        }
        self.refresh_chrome();
        out
    }

    /// Writes `client`'s import file (replacing an earlier import from
    /// it) and the fonts the sessions bring; says what happened.
    fn write_import(&mut self, client: Client, sessions: &[import::Session]) -> String {
        let path = imported_path(client);
        let all: Vec<&import::Session> = sessions.iter().collect();
        if let Err(e) = write_app_file(&path, &import::to_config(client, &all)) {
            return format!("Could not write {}: {e}", path.display());
        }
        // Fonts become profiles, unless the host already has one.
        for s in sessions {
            if let Some(p) = import::profile(s)
                && self.settings.profile(&p.host).is_none()
            {
                let host = p.host.clone();
                *self.settings.profile_mut(&host) = p;
            }
        }
        self.save_settings();
        self.side.import = None;
        self.show_side(SideView::Sessions, true);
        self.update_menu_checks();
        let n = sessions.len();
        let mut text = format!(
            "Imported {n} connection{} from {} into the {} folder of the connection manager.",
            plural(n),
            client.name(),
            client.name(),
        );
        let saved = sessions.iter().filter(|s| s.had_password).count();
        if saved > 0 {
            text.push_str(&format!(
                "\n\n{saved} of them had a password saved in {}, which FeroSSH does not import. \
                 To log in without typing it, pick a password source with F2 on the session.",
                client.name()
            ));
        }
        text
    }

    /// Opens the session form on `host`, or on a new session.
    fn open_form(&mut self, host: Option<String>) {
        let env = ssh_env();
        let items = host_items(&env, &self.settings);
        let names: Vec<String> = items.iter().map(|h| h.name.clone()).collect();
        let font = FontSpec::default();
        let hints = Hints {
            local_user: env.local_user.clone(),
            font: font.family,
            font_size: font.size_pt,
            scrollback: self
                .settings
                .scrollback
                .unwrap_or(TermSettings::DEFAULT_SCROLLBACK),
            credentials: self
                .settings
                .credentials
                .iter()
                .map(|c| c.name.clone())
                .collect(),
            credential_logins: self.settings.credentials.clone(),
        };
        let themes: Vec<String> = Theme::builtin().iter().map(|t| t.name.to_owned()).collect();
        let form = match host {
            None => SessionForm::new(None, Source::New, Values::default(), hints, names, themes),
            Some(name) => {
                let profile = self.settings.profile(&name);
                let saved = load_saved();
                match saved.iter().find(|h| h.alias.eq_ignore_ascii_case(&name)) {
                    Some(h) => SessionForm::new(
                        Some(h.alias.clone()),
                        Source::Saved,
                        Values::from_saved(h).with_profile(profile),
                        hints,
                        names,
                        themes,
                    ),
                    None => {
                        let folder = items
                            .iter()
                            .find(|h| h.name == name)
                            .and_then(|h| h.folder.clone());
                        let values = match Target::resolve(&name, &env) {
                            Some(t) => {
                                let key = t
                                    .key_files
                                    .iter()
                                    .find(|k| k.explicit)
                                    .map(|k| k.path.display().to_string());
                                Values {
                                    forward_agent: t.forward_agent,
                                    // With jump hosts, the proxy is the
                                    // first one's.
                                    proxy: t
                                        .proxy_server
                                        .as_ref()
                                        .filter(|_| t.jumps.is_empty())
                                        .map(ToString::to_string)
                                        .unwrap_or_default(),
                                    ..Values::from_resolved(
                                        &name,
                                        folder.as_deref(),
                                        &t.hostname,
                                        &t.user,
                                        t.port,
                                        key.as_deref(),
                                        &t.jumps
                                            .iter()
                                            .map(|j| j.alias.as_str())
                                            .collect::<Vec<_>>()
                                            .join(","),
                                        &t.forwards,
                                    )
                                }
                            }
                            None => Values {
                                name: name.clone(),
                                ..Values::default()
                            },
                        };
                        let source = Source::ReadOnly(host_file(&name));
                        SessionForm::new(
                            Some(name),
                            source,
                            values.with_profile(profile),
                            hints,
                            names,
                            themes,
                        )
                    }
                }
            }
        };
        self.side.form = Some(form);
        self.side.focused = true;
        self.refresh_chrome();
    }

    /// Carries out what the session form asked for.
    fn form_action(&mut self, action: Option<FormAction>) -> Option<Command> {
        let mut out = None;
        match action {
            Some(FormAction::Cancel) => self.side.form = None,
            Some(FormAction::Save { connect }) => {
                // Checked against the credentials as they are now, not as
                // they were when the form opened: another PC's changes to
                // a shared vault taken in first, before either file is
                // written (the save merges again and keeps what is ours).
                vault_ui::sync_settings(&mut self.settings);
                let credentials = self.settings.credentials.clone();
                if !self.side.form.as_mut()?.recheck_with(&credentials) {
                    self.refresh_chrome();
                    return None;
                }
                let form = self.side.form.as_ref()?;
                let mut hosts = load_saved();
                let mut settings = self.settings.clone();
                let name = form.apply(&mut hosts, &mut settings);
                // The inventory follows a renamed connection (a read-only one
                // saved under a new name is a copy: it has none yet).
                let renamed = form
                    .original
                    .clone()
                    .filter(|o| !o.eq_ignore_ascii_case(&name))
                    .filter(|_| !matches!(form.source, Source::ReadOnly(_)));
                // Off the Windows Credential Manager, or to another user, host
                // or port: the old saved password goes. Its name is resolved
                // before the connection's settings change.
                let was_windows = form
                    .original
                    .as_deref()
                    .is_some_and(|o| self.settings.password_source(o) == PasswordSource::Windows);
                let still_windows = settings.password_source(&name) == PasswordSource::Windows;
                // A renamed read-only connection is saved as a copy: the
                // original stays, and so does its password.
                let old_target = was_windows
                    .then(|| form.original.clone())
                    .flatten()
                    .filter(|o| {
                        !matches!(form.source, Source::ReadOnly(_)) || o.eq_ignore_ascii_case(&name)
                    })
                    .and_then(|o| self.saved_password_target(&o));
                if let Err(e) = write_app_file(&sessions_path(), &saved::to_text(&hosts)) {
                    return Some(Command::Notice(format!(
                        "Could not save the connection to {}: {e}",
                        sessions_path().display()
                    )));
                }
                // The connection has its new name now: its inventory row
                // goes with it, whatever happens to the settings below.
                if let Some(old) = renamed.as_deref() {
                    self.inventory_renamed(old, &name);
                }
                self.settings = settings;
                // Not saved: the form stays open, so nothing typed is lost.
                if let Err(e) = self.try_save_settings() {
                    return Some(Command::Notice(e));
                }
                // Unless another connection keeps its password there too.
                if let Some(old) = old_target
                    && (!still_windows || self.saved_password_target(&name).as_ref() != Some(&old))
                {
                    self.forget_unused_passwords(vec![old]);
                }
                self.side.form = None;
                self.reload_sessions(Some(&name));
                if connect {
                    self.open_host(&name, false);
                }
            }
            Some(FormAction::Delete) => {
                out = self
                    .side
                    .form
                    .as_ref()
                    .and_then(|f| f.original.clone())
                    .map(Command::DeleteSession);
            }
            Some(FormAction::BrowseKey) => out = Some(Command::PickKey),
            None => {}
        }
        self.refresh_chrome();
        out
    }

    /// Saved WinRM connection `name` as the settings describe it now: its
    /// current host, port and transport.
    fn saved_winrm_target(&self, name: &str) -> Option<WinrmTarget> {
        let saved = load_saved()
            .into_iter()
            .find(|h| h.alias.eq_ignore_ascii_case(name));
        let https = self.settings.profile(name).is_some_and(|p| p.winrm_https);
        WinrmTarget::resolve(name, &ssh_env(), None, https, saved.as_ref()).map(|t| {
            t.with_login_user(
                self.settings
                    .credential_of(name)
                    .and_then(|c| c.user.as_deref()),
            )
        })
    }

    /// The Credential Manager entry of saved connection `name`'s password:
    /// its WinRM or SSH login, as the settings now describe it.
    fn saved_password_target(&self, name: &str) -> Option<String> {
        self.saved_password_target_in(name, &ssh_env())
    }

    /// [`Self::saved_password_target`] with ssh_config already read.
    fn saved_password_target_in(&self, name: &str, env: &Env) -> Option<String> {
        // A typed `winrm://` or `winrms://` address, as a workspace keeps it.
        if let Some(t) = WinrmTarget::typed(name) {
            return Some(credman::target(t.user.as_deref()?, &t.hostname, t.port));
        }
        if self
            .settings
            .profile(name)
            .is_some_and(|p| p.kind == SessionKind::WinRm)
        {
            let t = self.saved_winrm_target(name)?;
            return Some(credman::target(t.user.as_deref()?, &t.hostname, t.port));
        }
        let t = Target::resolve(name, env)?;
        Some(credman::target(&t.user, &t.hostname, t.port))
    }

    /// Where a login to `name` takes its password from: the source of the
    /// connection it resolves to, as the login itself looks it up
    /// (`bob@web:22` goes by `web`, `winrms://bob@web` by `web`).
    fn source_of_name(&self, name: &str, env: &Env) -> PasswordSource {
        if self.settings.profile(name).is_some() {
            return self.settings.password_source(name);
        }
        // A typed WinRM address goes by its host's saved connection only
        // when that is a WinRM one, as its login does.
        if let Some(t) = WinrmTarget::typed(name) {
            return self
                .settings
                .profile(&t.alias)
                .filter(|p| p.kind == SessionKind::WinRm)
                .map(|_| self.settings.password_source(&t.alias))
                .unwrap_or_default();
        }
        let alias = Target::resolve(name, env).map(|t| t.alias);
        self.settings
            .password_source(alias.as_deref().unwrap_or(name))
    }

    /// The Credential Manager entries `names` keep their Windows-stored
    /// passwords under now, to compare after a change.
    fn windows_targets_of(&self, names: &[String]) -> Vec<String> {
        let env = ssh_env();
        names
            .iter()
            .filter(|n| match self.settings.password_source(n) {
                PasswordSource::Windows => true,
                // A workspace that logs in by itself keeps an asking
                // connection's password there too.
                PasswordSource::Ask => self.settings.workspace_auto_login,
                PasswordSource::Command(_) => false,
            })
            .filter_map(|n| self.saved_password_target_in(n, &env))
            .collect()
    }

    /// Tools > Credential manager's rows: every named credential with the
    /// connections that pick it, and every password FeroSSH keeps (in the
    /// Windows Credential Manager or the vault) with the connections whose
    /// login keeps it there. No password is kept in a row.
    /// Tools > Security rules: each rule with the saved connections it
    /// covers, matched as a connection is (its folder as the connection
    /// manager shows it).
    fn rule_rows(&self) -> Vec<crate::rules_view::Row> {
        crate::rules_view::rows(&self.settings.security_rules, &self.rule_connections())
    }

    /// Every connection the Connection manager lists, as the security
    /// rules see it.
    fn rule_connections(&self) -> Vec<crate::rules_view::Connection> {
        use crate::rules_view::Connection;
        let saved = load_saved();
        host_items(&ssh_env(), &self.settings)
            .into_iter()
            .map(|h| {
                let own = saved
                    .iter()
                    .find(|s| s.alias.eq_ignore_ascii_case(&h.name))
                    .and_then(|s| s.folder.clone());
                Connection {
                    folder: own.or(h.folder),
                    name: h.name,
                    hostname: h.hostname,
                    tags: h.tags,
                }
            })
            .collect()
    }

    /// The menu item that puts theme or font `row` on the pane: Settings
    /// > Theme's or Font's.
    fn look_menu_id(&self, row: &crate::theme_view::Row) -> Option<u32> {
        if let Some(name) = row.preset_theme() {
            if let Some(i) = Theme::builtin().iter().position(|t| t.name == name) {
                return Some(cmd::THEME + i as u32);
            }
            let i = self
                .custom_themes
                .iter()
                .position(|c| c.theme.name == name)?;
            return Some(cmd::THEME + Theme::builtin().len() as u32 + i as u32);
        }
        let family = row.preset_font()?;
        let i = FONT_CHOICES.iter().position(|f| *f == family)?;
        Some(cmd::FONT + i as u32)
    }

    /// Theme manager > Set as default: new tabs open with theme or font
    /// `row` from now on; why not, when it cannot be saved.
    fn set_default_look(&mut self, row: &crate::theme_view::Row) -> Option<String> {
        let before = (
            self.settings.default_theme.clone(),
            self.settings.default_font.clone(),
        );
        if let Some(name) = row.preset_theme() {
            let theme = Theme::by_name(name)?;
            self.settings.default_theme = Some(theme.name.to_owned());
            if let Err(e) = self.try_save_settings() {
                (self.settings.default_theme, self.settings.default_font) = before;
                return Some(e);
            }
            self.default_theme = theme;
        } else if let Some(family) = row.preset_font() {
            if !self.renderer.has_family(family) {
                return Some(format!(
                    "{family} is not installed on this PC. Install it first (Apply to this \
                     pane offers the download page)."
                ));
            }
            self.settings.default_font = Some(family.to_owned());
            if let Err(e) = self.try_save_settings() {
                (self.settings.default_theme, self.settings.default_font) = before;
                return Some(e);
            }
            self.default_font = FontSpec::new(family, self.default_font.size_pt);
        }
        None
    }

    /// Tools > Theme rules and Theme manager: the theme rules with the
    /// saved connections each matches, then the built-in and custom
    /// themes and the fonts.
    fn theme_rows(&self) -> Vec<crate::theme_view::Row> {
        use crate::theme_view::{Connection, Font, Group, rows};
        let all: Vec<Connection> = host_items(&ssh_env(), &self.settings)
            .into_iter()
            .map(|h| Connection {
                name: h.name,
                hostname: h.hostname,
                tags: h.tags,
            })
            .collect();
        let builtin: Vec<(&str, Group)> = Theme::builtin()
            .iter()
            .map(|t| {
                let group = match t.group() {
                    ThemeGroup::Dark => Group::Dark,
                    ThemeGroup::Light => Group::Light,
                    ThemeGroup::Warning => Group::Warning,
                    ThemeGroup::Classic => Group::Classic,
                };
                (t.name, group)
            })
            .collect();
        let custom: Vec<&str> = self.custom_themes.iter().map(|c| c.theme.name).collect();
        let fonts: Vec<Font> = FONT_CHOICES
            .iter()
            .enumerate()
            .map(|(i, f)| Font {
                family: (*f).to_owned(),
                installed: self.renderer.has_family(f),
                windows: i < WINDOWS_FONTS,
            })
            .collect();
        rows(&self.settings.theme_rules, &builtin, &custom, &fonts, &all)
    }

    fn credential_rows(&self) -> Vec<crate::credential_view::Row> {
        use crate::credential_view::{Place, credential_rows, password_row};
        let mut rows = credential_rows(&self.settings);
        let env = ssh_env();
        // Which connection keeps its password where, as the cleanup counts
        // them: listed ones set to Windows, and with Log in automatically
        // on what the saved workspaces open, asking ones too.
        let mut users: HashMap<String, Vec<String>> = HashMap::new();
        let mut add = |name: String, ask_too: bool| {
            // An SSH login on the way, through a proxy or jump hosts, keeps
            // their passwords apart. A WinRM connection takes neither.
            let ssh = WinrmTarget::typed(&name).is_none()
                && !self
                    .settings
                    .profile(&name)
                    .is_some_and(|p| p.kind == SessionKind::WinRm);
            if let Some(t) = ssh.then(|| Target::resolve(&name, &env)).flatten() {
                let mut uses = |target: String| {
                    let list = users.entry(target).or_default();
                    if !list.iter().any(|n| n.eq_ignore_ascii_case(&name)) {
                        list.push(name.clone());
                    }
                };
                if let Some(p) = t.proxy_server.as_ref()
                    && let Some(user) = p.user.as_deref()
                {
                    uses(credman::proxy_target(user, &p.host, p.port));
                }
                // Each jump host by its own source, as its login takes it.
                for hop in &t.jumps {
                    let keeps = match self.source_of_name(&hop.alias, &env) {
                        PasswordSource::Windows => true,
                        PasswordSource::Ask => ask_too,
                        PasswordSource::Command(_) => false,
                    };
                    if keeps {
                        uses(credman::target(&hop.user, &hop.hostname, hop.port));
                    }
                }
            }
            let keeps = match self.source_of_name(&name, &env) {
                PasswordSource::Windows => true,
                PasswordSource::Ask => ask_too,
                PasswordSource::Command(_) => false,
            };
            if let Some(t) = keeps
                .then(|| self.saved_password_target_in(&name, &env))
                .flatten()
            {
                let list = users.entry(t).or_default();
                if !list.iter().any(|n| n.eq_ignore_ascii_case(&name)) {
                    list.push(name);
                }
            }
        };
        for h in load_saved() {
            add(h.alias, false);
        }
        for p in &self.settings.profiles {
            add(p.host.clone(), false);
        }
        for h in host_items(&env, &self.settings) {
            add(h.name, false);
        }
        if self.settings.workspace_auto_login {
            for n in ferossh_config::workspace::all_connections(&workspaces_dir()) {
                add(workspace_destination(n), true);
            }
        }
        // Open panes too (a workspace opened from outside the folder
        // among them): what each logs in to now, it and its jump hosts,
        // by the source its own login takes.
        for (&id, p) in &self.panes {
            let Host::Ssh(s) = &p.host else {
                continue;
            };
            let name = &s.target.alias;
            let hops = std::iter::once(&s.target).chain(&s.target.jumps);
            for t in hops {
                if self.login_source(id, &t.alias) == PasswordSource::Windows {
                    let list = users
                        .entry(credman::target(&t.user, &t.hostname, t.port))
                        .or_default();
                    if !list.iter().any(|n| n.eq_ignore_ascii_case(name)) {
                        list.push(name.clone());
                    }
                }
            }
        }
        let mut saved: Vec<(String, String, Place)> = Vec::new();
        let mut keep = |target: String, user: String, windows: bool| {
            let at = match saved.iter().position(|e| e.0 == target) {
                Some(i) => i,
                None => {
                    saved.push((target, user, Place::default()));
                    saved.len() - 1
                }
            };
            if let Some(e) = saved.get_mut(at) {
                if windows {
                    e.2.windows = true;
                } else {
                    e.2.vault = true;
                }
            }
        };
        // A portable FeroSSH leaves the PC's own passwords alone.
        if !crate::portable::is_portable() {
            for s in credman::os_list() {
                keep(s.target.clone(), s.user.clone(), true);
            }
        }
        for s in crate::vault::secrets() {
            keep(s.target.clone(), s.user.clone(), false);
        }
        for (target, user, place) in saved {
            let used = users.remove(&target).unwrap_or_default();
            rows.extend(password_row(&target, &user, place, used));
        }
        rows
    }

    /// Forgets the Windows-stored passwords under `old` that no saved
    /// connection uses any more (as the settings are now): one moved off
    /// the Windows Credential Manager, or kept under another name. One
    /// another connection still uses stays. Failures become notices.
    fn forget_unused_passwords(&mut self, old: Vec<String>) {
        if old.is_empty() {
            return;
        }
        let env = ssh_env();
        let targets = |names: Vec<String>, ask_too: bool| -> Vec<String> {
            names
                .iter()
                .filter(|n| match self.source_of_name(n, &env) {
                    PasswordSource::Windows => true,
                    PasswordSource::Ask => ask_too,
                    PasswordSource::Command(_) => false,
                })
                .filter_map(|n| self.saved_password_target_in(n, &env))
                .collect()
        };
        // Every saved connection and profile set to the Windows
        // Credential Manager (a named credential's source included).
        let mut names: Vec<String> = load_saved().into_iter().map(|h| h.alias).collect();
        names.extend(self.settings.profiles.iter().map(|p| p.host.clone()));
        names.extend(host_items(&env, &self.settings).into_iter().map(|h| h.name));
        let mut in_use = targets(names, false);
        // With Log in automatically on, what the saved workspaces open, as
        // written there (`bob@web` included), keeps its password when it
        // would ask too; an asking connection no workspace opens does not.
        if self.settings.workspace_auto_login {
            in_use.extend(targets(
                ferossh_config::workspace::all_connections(&workspaces_dir())
                    .into_iter()
                    .map(workspace_destination)
                    .collect(),
                true,
            ));
        }
        // Every open pane that keeps its login there: under the host, port
        // and user it logs in to now, which a reconnect keeps even when
        // the config has changed since (a workspace opened from outside
        // the folder too).
        for (&id, p) in &self.panes {
            if let Host::Ssh(s) = &p.host
                && self.login_source(id, &s.target.alias) == PasswordSource::Windows
            {
                let t = &s.target;
                in_use.push(credman::target(&t.user, &t.hostname, t.port));
            }
        }
        let mut done: Vec<String> = Vec::new();
        for t in old {
            if in_use.contains(&t) || done.contains(&t) {
                continue;
            }
            if let Err(e) = credman::delete(&t) {
                self.queued.push(Command::Notice(e));
            }
            done.push(t);
        }
    }

    /// Removes saved session `name` (after the user said yes).
    fn delete_session(&mut self, name: &str) {
        self.delete_sessions(&[name.to_string()]);
    }

    /// Removes the saved sessions `names` (after the user said yes): the
    /// file is written once, and settings change only once it is.
    fn delete_sessions(&mut self, names: &[String]) {
        // Where their Windows-stored passwords are, found while the
        // connections are still saved; removed once they are gone.
        let targets: Vec<String> = names
            .iter()
            .filter(|name| self.settings.password_source(name) == PasswordSource::Windows)
            .filter_map(|name| self.saved_password_target(name))
            .collect();
        let mut hosts = load_saved();
        let mut settings = self.settings.clone();
        for name in names {
            session_form::delete(name, &mut hosts, &mut settings);
        }
        if let Err(e) = write_app_file(&sessions_path(), &saved::to_text(&hosts)) {
            self.queued.push(Command::Notice(format!(
                "Could not save {}: {e}",
                sessions_path().display()
            )));
            return;
        }
        self.settings = settings;
        // Unless another connection keeps its password there too.
        self.forget_unused_passwords(targets);
        // A read still under way for one of them keeps nothing.
        self.system_reads
            .retain(|_, r| !names.iter().any(|n| n.eq_ignore_ascii_case(&r.alias)));
        self.update_inventory(Some(InventoryFix::Remove(names.to_vec())), |_| {});
        self.save_settings();
        self.side.form = None;
        self.reload_sessions(None);
        self.refresh_chrome();
    }

    /// Carries out a change to several connections from the connection
    /// manager's menu.
    fn bulk_action(&mut self, action: crate::bulk::BulkAction) {
        use crate::bulk::BulkAction;
        match action {
            BulkAction::OpenAll(names) => {
                for name in &names {
                    self.open_host(name, false);
                }
            }
            BulkAction::AddTag(names, tag) => {
                crate::bulk::add_tag(&mut self.settings, &names, &tag);
                self.save_settings();
                self.reload_sessions(None);
            }
            BulkAction::RemoveTag(names, tag) => {
                crate::bulk::remove_tag(&mut self.settings, &names, &tag);
                self.save_settings();
                self.reload_sessions(None);
            }
            BulkAction::MoveTo(names, folder) => {
                let mut hosts = load_saved();
                let out = crate::bulk::move_to_folder(&mut hosts, &names, folder.as_deref());
                if out.changed > 0 {
                    if let Err(e) = write_app_file(&sessions_path(), &saved::to_text(&hosts)) {
                        self.queued.push(Command::Notice(format!(
                            "Could not save {}: {e}",
                            sessions_path().display()
                        )));
                        return;
                    }
                    self.reload_sessions(None);
                }
                if !out.skipped.is_empty() {
                    self.queued.push(Command::Notice(format!(
                        "Left in their folders: {}. They come from ~/.ssh/config or an \
                         import, which FeroSSH does not change.",
                        crate::bulk::name_list(&out.skipped)
                    )));
                }
            }
            BulkAction::Edit(plan) => {
                // Profiles in a shared vault, and sessions.conf, may have
                // changed since the preview: take both in before checking.
                // The vault refresh comes first, so the hosts read next
                // are the ones written back.
                vault_ui::sync_settings(&mut self.settings);
                let mut hosts = load_saved();
                let conflicts = crate::bulk_edit::conflicts(&plan, &hosts, &self.settings);
                // As in the form: a password kept in the Windows Credential
                // Manager goes once the connection is off it or its user
                // changes the name it is kept under. Names are resolved
                // before anything changes.
                let old_targets: Vec<String> = if matches!(
                    plan.field,
                    crate::bulk_edit::EditField::User
                        | crate::bulk_edit::EditField::Password
                        | crate::bulk_edit::EditField::Credential
                ) {
                    let names: Vec<String> = plan
                        .changes
                        .iter()
                        .filter(|c| !conflicts.contains(&c.name))
                        .map(|c| c.name.clone())
                        .collect();
                    self.windows_targets_of(&names)
                } else {
                    Vec::new()
                };
                if crate::bulk_edit::apply(&plan, &mut hosts, &mut self.settings)
                    && let Err(e) = write_app_file(&sessions_path(), &saved::to_text(&hosts))
                {
                    self.queued.push(Command::Notice(format!(
                        "Could not save {}: {e}",
                        sessions_path().display()
                    )));
                    return;
                }
                let saved_settings = self.try_save_settings();
                if saved_settings.is_ok() {
                    self.forget_unused_passwords(old_targets);
                }
                self.reload_sessions(None);
                if let Err(e) = saved_settings {
                    self.queued.push(Command::Notice(e));
                }
                if !conflicts.is_empty() {
                    self.queued.push(Command::Notice(format!(
                        "Left alone, because they changed since the preview and the change no longer fits: {}.",
                        crate::bulk::name_list(&conflicts)
                    )));
                }
            }
        }
        conn_view::clear_marks();
        self.refresh_chrome();
    }

    /// Reads the hosts again after a session was saved or deleted.
    /// Takes in host profiles, credentials, rules and saved searches that
    /// another PC (in a shared vault) or another FeroSSH window changed,
    /// and shows them: in the connection list, and in the Security rules
    /// page when it is open. Connections made from now on follow the
    /// rules taken in.
    fn pull_vault_settings(&mut self) {
        if vault_ui::pull_settings(&mut self.settings) {
            self.reload_sessions(None);
            if self.rules_native() {
                rules_panel::set_rows(self.rule_rows());
            }
        }
    }

    fn reload_sessions(&mut self, select: Option<&str>) {
        let env = ssh_env();
        self.side.list.set_hosts(
            host_items(&env, &self.settings),
            self.settings.favourites.clone(),
        );
        self.side
            .list
            .set_saved_searches(self.settings.saved_searches.clone());
        if let Some(name) = select {
            self.side.list.select(name);
        }
    }

    /// A desktop session: Remote Desktop Connection straight to the
    /// machine, or a tunnel through the session named in Via once that
    /// SSH session has logged in.
    fn open_desktop_session(
        &mut self,
        name: &str,
        kind: SessionKind,
        via: Option<String>,
        split: bool,
    ) {
        let env = ssh_env();
        let includes = ssh_config::DirIncludes {
            home: env.home.clone(),
        };
        let cfg = ssh_config::resolve_in(&env.config, name, &includes);
        let port = cfg.port.unwrap_or(match kind {
            SessionKind::Vnc => DEFAULT_VNC_PORT,
            _ => DEFAULT_DESKTOP_PORT,
        });
        let Some(via) = via else {
            if kind != SessionKind::Rdp {
                self.queued.push(Command::Notice(format!(
                    "A VNC or virtual desktop goes through an SSH connection. Choose one under \
                     Via SSH in the connection form (F2 on {name})."
                )));
                return;
            }
            let host = cfg.hostname.unwrap_or_else(|| name.to_owned());
            let addr = if host.contains(':') {
                format!("[{host}]:{port}")
            } else {
                format!("{host}:{port}")
            };
            let rules = self.policy_of(name, Some(&host), cfg.tag.as_deref());
            // Remote Desktop Connection shares the clipboard both ways or
            // not at all: `Clipboard no` turns it off.
            let clipboard =
                self.desktop_clip(self.desktop_clip_limit(&[name], rules)) == (true, true);
            let size = self.fixed_desktop_size(name);
            // No pane to ask in: a security rule that asks before
            // connecting asks in a message box before mstsc starts.
            if rules.confirm_connect {
                self.workspace_asks.push(Command::ConfirmRdp {
                    name: name.to_owned(),
                    addr,
                    size,
                    clipboard,
                });
                // SAFETY: our window; replaces any earlier timer with this id.
                unsafe { SetTimer(Some(self.hwnd), TIMER_WORKSPACE_ASK, 50, None) };
                return;
            }
            if let Err(e) = launch_rdp_client(&addr, size, clipboard) {
                self.queued.push(Command::Notice(format!(
                    "Remote Desktop Connection (mstsc.exe) did not start: {e}"
                )));
            }
            return;
        };
        if kind == SessionKind::Vnc && !cfg!(feature = "vnc-viewer") {
            self.queued.push(Command::Notice(
                "This FeroSSH has no built-in VNC viewer. VNC sessions open in the desktop \
                 build (ferossh-desktop.exe)."
                    .into(),
            ));
            return;
        }
        // Without a host of its own, the desktop is on the SSH host.
        let host = cfg.hostname.unwrap_or_else(|| "localhost".to_owned());
        // VNC to another machine is plain past the SSH server: ask first.
        let plain_key = crate::forwards::plain_desktop_key(name, &host, port, &via);
        if kind == SessionKind::Vnc
            && !crate::forwards::on_ssh_host(&host)
            && !self.plain_vnc_ok.contains(&plain_key)
        {
            self.queued.push(Command::ApprovePlainVnc {
                key: plain_key,
                name: name.to_owned(),
                target: host,
                via,
                split,
            });
            return;
        }
        let pending = PendingDesktop {
            label: name.to_owned(),
            host,
            port,
            kind,
            user: cfg.user,
            tag: cfg.tag,
            confirmed: false,
        };
        // Only the desktop or app shows: the SSH login runs in a session
        // no tab shows, which shows when the login asks for something or
        // fails, and goes once the desktop or app holds the connection.
        let _ = split;
        let id = self.ws.alloc_id();
        self.add_pane(id);
        self.launches.insert(id, Instant::now());
        self.launch_hidden.insert(id);
        self.pending_desktops.insert(id, pending);
        self.connect(id, &via);
        self.check_launch(id);
        self.arm_launch_timer();
        self.refresh_chrome();
    }

    /// A launch's hidden login session shows in a tab of its own when it
    /// needs the user: a prompt, a changed host key, or a failure.
    fn check_launch(&mut self, id: PaneId) {
        if !self.launch_hidden.contains(&id) {
            return;
        }
        let needs_user = match self.panes.get(&id).map(|p| &p.host) {
            Some(Host::Ssh(s)) => {
                s.prompt_asks().is_some() || matches!(s.state(), State::Blocked | State::Ended)
            }
            Some(Host::Ask(_)) => true,
            Some(_) => false,
            None => {
                self.launches.remove(&id);
                self.launch_hidden.remove(&id);
                return;
            }
        };
        if needs_user {
            self.reveal_launch(id);
        }
    }

    /// Shows a launch's hidden login session in a tab of its own.
    fn reveal_launch(&mut self, id: PaneId) {
        if self.launch_hidden.remove(&id) && self.panes.contains_key(&id) {
            let at = self.ws.tabs.len();
            self.ws.insert_tab(at, layout::Node::Leaf(id), id);
            self.focus_pane(id);
            self.after_structure_change();
            self.focus_terminal();
        }
    }

    /// A launch failed (the reason was told): its hidden login session
    /// ends; one in a tab stays for the user.
    fn abandon_launch(&mut self, id: PaneId) {
        if !self.launches.contains_key(&id) {
            return;
        }
        self.launches.remove(&id);
        if self.launch_hidden.remove(&id) {
            self.end_host(id);
            self.panes.remove(&id);
            self.watches.remove(&id);
            self.refresh_chrome();
        }
    }

    /// The launches whose desktop or app now holds the connection: their
    /// login sessions go. A session still hidden after [`LAUNCH_WAIT`]
    /// with nothing holding it shows instead.
    fn retire_launches(&mut self) {
        let before = self.mstsc.len();
        self.mstsc
            .retain_mut(|(child, _)| matches!(child.try_wait(), Ok(None)));
        let apps = crate::remote_app::connections_in_use();
        let mut held = Vec::new();
        let mut late = Vec::new();
        for (&id, &since) in &self.launches {
            let Some(Host::Ssh(s)) = self.panes.get(&id).map(|p| &p.host) else {
                continue;
            };
            if s.state() != State::Connected
                || self.pending_desktops.contains_key(&id)
                || self.desktop_asks.contains(&id)
            {
                continue;
            }
            let c = s.connection;
            let holds = self.panes.iter().any(|(&o, p)| {
                o != id
                    && matches!(p.host, Host::Desktop { connection, .. } if connection == c)
                    && p.desktop.is_some()
            }) || apps.contains(&c)
                || self.mstsc.iter().any(|(_, m)| *m == c);
            if holds {
                held.push(id);
            } else if since.elapsed() > LAUNCH_WAIT {
                late.push(id);
            }
        }
        let changed = !late.is_empty() || !held.is_empty();
        for id in late {
            self.launches.remove(&id);
            self.reveal_launch(id);
        }
        for id in held {
            self.launches.remove(&id);
            if self.launch_hidden.remove(&id) {
                self.end_host(id);
                self.panes.remove(&id);
                self.watches.remove(&id);
            } else if !self.launch_warned.contains(&id)
                && (self.ws.tabs.len() > 1
                    || self.ws.tab().is_some_and(|t| t.root.panes().len() > 1))
            {
                if let Some(c) = self.close_pane(id) {
                    self.queued.push(c);
                }
            } else {
                // The window's only tab, or one showing a rule warning: it
                // stays, free for another connection.
                self.launch_warned.remove(&id);
                self.end_host(id);
                self.show(
                    id,
                    "\r\n\x1b[0;90mThe login is done; the connection stays while its desktop \
                     or app runs.\x1b[0m\r\n",
                );
                self.refresh(id);
            }
        }
        let panes = &self.panes;
        self.launches.retain(|id, _| panes.contains_key(id));
        self.launch_hidden.retain(|id| panes.contains_key(id));
        self.launch_warned.retain(|id| panes.contains_key(id));
        self.desktop_asks.retain(|id| panes.contains_key(id));
        if self.mstsc.len() != before {
            self.prune_forwards();
        }
        self.arm_launch_timer();
        if changed {
            self.refresh_chrome();
        }
    }

    /// Keeps [`TIMER_LAUNCH`] running while launches or tunnelled Remote
    /// Desktop Connections need watching.
    fn arm_launch_timer(&mut self) {
        // SAFETY: our window and timer.
        unsafe {
            if self.launches.is_empty() && self.mstsc.is_empty() {
                let _ = KillTimer(Some(self.hwnd), TIMER_LAUNCH);
            } else {
                SetTimer(Some(self.hwnd), TIMER_LAUNCH, LAUNCH_TICK_MS, None);
            }
        }
    }

    /// After a login on SSH pane `id`: opens the desktop a desktop session
    /// waited for.
    fn desktop_after_login(&mut self, id: PaneId) {
        let Some(p) = self.pending_desktops.remove(&id) else {
            return;
        };
        let (Some(connection), Some(Host::Ssh(s))) = (
            self.pane_connection(id),
            self.panes.get(&id).map(|p| &p.host),
        ) else {
            return;
        };
        if p.kind == SessionKind::Xvfb {
            if let Some(c) = self.open_virtual_desktop(id, Some(&p.label)) {
                self.queued.push(c);
                self.abandon_launch(id);
            }
            return;
        }
        if p.kind == SessionKind::RemoteApp {
            let program = self
                .settings
                .profile(&p.label)
                .and_then(|pr| pr.remote_app.clone())
                .unwrap_or_else(|| "xterm".into());
            if let Some(c) = self.run_remote_app(
                id,
                Some(&program),
                Some(&p.label),
                ferostream_client::transport::AttachTo::New,
            ) {
                self.queued.push(c);
                self.abandon_launch(id);
            }
            self.retire_launches();
            return;
        }
        let size = self.fixed_desktop_size(&p.label);
        // With the desktop's own ssh_config Tag, as a direct one has it.
        let rules = self
            .launch_rules(id, Some((&p.label, Some(&p.host))))
            .tightened(&self.policy_of(&p.label, Some(&p.host), p.tag.as_deref()));
        // The tunnel reaches the desktop itself: a security rule that asks
        // before connecting to it asks here, in a message box, as for a
        // direct Remote Desktop connection.
        if rules.confirm_connect && !p.confirmed {
            self.desktop_asks.insert(id);
            self.workspace_asks.push(Command::ConfirmDesktop {
                pane: id,
                desktop: p,
            });
            // SAFETY: our window; replaces any earlier timer with this id.
            unsafe { SetTimer(Some(self.hwnd), TIMER_WORKSPACE_ASK, 50, None) };
            return;
        }
        let clip_limit = self.desktop_clip_limit(&[&p.label, &s.target.alias], rules);
        let (local, want) = match p.kind {
            SessionKind::Vnc => (
                0,
                DesktopWant::Tab(TabWant {
                    label: p.label.clone(),
                    user: p.user.clone().unwrap_or_else(|| s.target.user.clone()),
                    protocol: Protocol::Vnc,
                    vdesk: None,
                    size,
                    clip_limit,
                }),
            ),
            _ => (
                desktop_port_for(&p.label),
                DesktopWant::Rdp {
                    pane: id,
                    size,
                    clipboard: self.desktop_clip(clip_limit) == (true, true),
                },
            ),
        };
        let Some(w) = self.workers.get(&connection) else {
            return;
        };
        w.forwarder.open_desktop(connection, &p.host, p.port, local);
        self.desktops
            .insert((connection, p.host.clone(), p.port), want);
        self.show(
            id,
            &format!(
                "\x1b[0;90mOpening the desktop {} on {} port {}...\x1b[0m\r\n",
                crate::ssh::sanitize(&p.label),
                crate::ssh::sanitize(&p.host),
                p.port
            ),
        );
        self.refresh(id);
    }

    /// The pane a session opens in: the focused one if it waits at the
    /// connect prompt, else a new tab (or, with `split`, a split).
    fn host_pane_for(&mut self, split: bool) -> Option<PaneId> {
        let focused = self.focused_id();
        let idle = matches!(
            self.panes.get(&focused).map(|p| &p.host),
            Some(Host::Ask(t)) if t.is_empty()
        ) && !self.confirm_pending(focused);
        if split {
            self.split(Dir::Right)
        } else if idle {
            Some(focused)
        } else {
            Some(self.new_tab_pane())
        }
    }

    /// Opens `host` from the connection manager: in the focused pane if it is
    /// waiting at the connect prompt, else in a new tab (or a split).
    fn open_host(&mut self, host: &str, split: bool) {
        self.pull_vault_settings();
        self.note_recent(host);
        if let Some(p) = self.settings.profile(host)
            && p.kind == SessionKind::Serial
        {
            let line = p.serial.unwrap_or_default();
            let hostname = Target::resolve(host, &ssh_env()).map(|t| t.hostname);
            let port = hostname.as_deref().and_then(serial::port_name);
            match port.or_else(|| serial::port_name(host)) {
                Some(port) => {
                    if let Some(id) = self.host_pane_for(split) {
                        self.focus_terminal();
                        let target = SerialTarget {
                            port,
                            settings: line,
                        };
                        self.workspace_elsewhere(id, host);
                        self.open_serial(id, target, Some(host));
                    }
                }
                None => self.queued.push(Command::Notice(format!(
                    "The connection {host} has no COM port: press F2 on it and fill one in."
                ))),
            }
            return;
        }
        if let Some(p) = self.settings.profile(host)
            && !matches!(
                p.kind,
                SessionKind::Ssh
                    | SessionKind::Telnet
                    | SessionKind::Mosh
                    | SessionKind::Sftp
                    | SessionKind::Tunnel
                    | SessionKind::WinRm
            )
        {
            let (kind, via) = (p.kind, p.via.clone());
            self.open_desktop_session(host, kind, via, split);
            return;
        }
        if let Some(id) = self.host_pane_for(split) {
            self.focus_terminal();
            self.connect(id, host);
        }
    }

    /// What pane `id` opens, for a saved workspace; `None` leaves it out
    /// (a remote desktop, or a tmux pane whose session another pane
    /// already stands for, in tmux layout). `tmux` collects the tmux
    /// sessions seen.
    fn workspace_pane(&self, id: PaneId, tmux: &mut HashSet<PaneId>) -> Option<PaneSpec> {
        let p = self.panes.get(&id)?;
        // A tmux window is a pane on its session's connection, marked
        // with the session, which opens the session again (or makes it
        // again with these panes). In tmux layout, where tmux keeps the
        // splits, a session is one pane.
        let gateway = p
            .gateway()
            .or_else(|| self.tmux.get(&id).filter(|t| t.active()).map(|_| id));
        let (from, session) = match gateway {
            Some(g) => {
                let t = self.tmux.get(&g).filter(|t| t.active());
                let whole = t.is_none_or(|t| t.mode() == crate::tmux::Mode::Tmux);
                if whole && !tmux.insert(g) {
                    return None;
                }
                // Someone else's session, or one on the shared server, is
                // not attached again by name: that would find the private
                // server's session of that name.
                let session = t
                    .filter(|t| t.joined().is_none() && !t.on_shared_server())
                    .and_then(Tmux::session_name)
                    .map(str::to_owned);
                (self.panes.get(&g)?, Some((session, whole)))
            }
            None => (p, None),
        };
        let bracket = |h: &str| {
            if h.contains(':') {
                format!("[{h}]")
            } else {
                h.to_owned()
            }
        };
        let kind = |alias: &str| self.settings.profile(alias).map(|p| p.kind);
        // A workspace pane still waiting for its host's login is saved as
        // what it is about to open.
        if let Some(mut spec) = self.workspace_waiting.pending(id) {
            spec.name = p.name.clone();
            return Some(spec);
        }
        let (open, dir, host) = match &from.host {
            Host::Ask(_) => (WsOpen::Prompt, None, None),
            Host::Local { .. } => (WsOpen::Local, from.local_cwd.clone(), None),
            Host::Ssh(s) => {
                let t = &s.target;
                // `alias` is the host part of what was typed: a user or
                // port typed with it is added back when the name alone
                // would resolve to another.
                let plain = Target::resolve(&t.alias, &ssh_env());
                let mut dest = if plain
                    .as_ref()
                    .is_some_and(|b| b.user == t.user && b.port == t.port)
                {
                    t.alias.clone()
                } else {
                    format!("{}@{}:{}", t.user, bracket(&t.alias), t.port)
                };
                let folder = t.sftp_folder.as_deref().filter(|f| !f.is_empty());
                if t.sftp_only && (folder.is_some() || kind(&t.alias) != Some(SessionKind::Sftp)) {
                    dest = workspaces::sftp_address(&dest, folder);
                }
                // A tmux window's own directory, as its prompt shows it.
                let dir = match session {
                    Some((_, true)) => None,
                    Some((_, false)) => p.cwd.as_deref(),
                    None => from.cwd.as_deref(),
                }
                .map(|d| String::from_utf8_lossy(d).into_owned());
                (
                    WsOpen::Connection(dest),
                    dir,
                    Some((t.alias.clone(), t.hostname.clone(), t.tag.clone())),
                )
            }
            Host::Telnet(s) => {
                let t = &s.target;
                let dest = if kind(&t.alias) == Some(SessionKind::Telnet) {
                    t.alias.clone()
                } else {
                    format!("telnet://{}:{}", bracket(&t.hostname), t.port)
                };
                (
                    WsOpen::Connection(dest),
                    None,
                    Some((t.alias.clone(), t.hostname.clone(), t.tag.clone())),
                )
            }
            Host::Winrm(s) => {
                let t = &s.target;
                // A typed address stays typed, even when a saved
                // connection shares its name.
                let dest = if t.saved && kind(&t.alias) == Some(SessionKind::WinRm) {
                    t.alias.clone()
                } else {
                    let scheme = if t.https { "winrms" } else { "winrm" };
                    let user = t
                        .user
                        .as_deref()
                        .map(|u| format!("{u}@"))
                        .unwrap_or_default();
                    format!("{scheme}://{user}{}:{}", bracket(&t.hostname), t.port)
                };
                (
                    WsOpen::Connection(dest),
                    None,
                    Some((t.alias.clone(), t.hostname.clone(), t.tag.clone())),
                )
            }
            Host::Serial {
                target, session, ..
            } => {
                let dest = session.clone().unwrap_or_else(|| target.to_string());
                let alias = session.clone().unwrap_or_else(|| target.port.clone());
                (
                    WsOpen::Connection(dest),
                    None,
                    Some((alias, target.port.clone(), None)),
                )
            }
            Host::Tmux { .. } | Host::Desktop { .. } | Host::Replay(_) | Host::Diff(_) => {
                return None;
            }
        };
        let mut spec = PaneSpec::new(open);
        spec.dir = dir.filter(|d| !d.is_empty() && d != ".");
        let tmux_window = session.is_some();
        if !matches!(session, Some((_, true))) {
            spec.name = p.name.clone();
        }
        if let Some((name, _)) = session
            && matches!(spec.open, WsOpen::Connection(_))
        {
            spec.tmux = name;
        }
        // What it ran as it opened stays, for a pane still showing what
        // the workspace opened.
        if !tmux_window
            && let Some(e) = self.workspace_extra.get(&id)
            && matches!(
                (&spec.open, &e.dest),
                (WsOpen::Connection(_), Some(_)) | (WsOpen::Local, None)
            )
        {
            spec.script.clone_from(&e.script);
            spec.command.clone_from(&e.command);
        }
        // The look is kept only where it differs from what the host (or
        // a new pane) gets anyway, so changing a host's look later still
        // reaches the workspace. A Production or Staging warning colour
        // is never overridden.
        let (font, theme) = match &host {
            Some((alias, hostname, tag)) => self.host_look(alias, hostname, tag.as_deref()),
            None => (self.default_font.clone(), self.default_theme.clone()),
        };
        if p.theme.name != theme.name
            && theme.group() != ThemeGroup::Warning
            && p.theme.group() != ThemeGroup::Warning
        {
            spec.theme = Some(p.theme.name.to_owned());
        }
        if !p.font.family.eq_ignore_ascii_case(&font.family) {
            spec.font = Some(p.font.family.clone());
        }
        if (p.font.size_pt - font.size_pt).abs() > 0.01 {
            spec.font_size = Some(p.font.size_pt);
        }
        Some(spec)
    }

    /// The window's tabs as a workspace; `None` when no pane can be
    /// saved. Also says how many panes were left out (remote desktops).
    fn workspace_now(&self) -> (Option<wsfile::Workspace>, usize) {
        let mut tmux = HashSet::new();
        let mut skipped = 0;
        let mut more_tabs = Vec::new();
        let ws = workspaces::capture(&self.ws.tabs, self.ws.active, &mut |id| {
            // A workspace's tmux session not attached yet: its saved panes
            // stand in for its first one.
            if let Some(w) = self.workspace_tmux.get(&id)
                && let Some((first, rest)) = w.plan.tabs.split_first()
            {
                more_tabs.extend(rest.iter().cloned());
                return Some(first.root.clone());
            }
            let spec = self.workspace_pane(id, &mut tmux);
            if spec.is_none()
                && matches!(
                    self.panes.get(&id).map(|p| &p.host),
                    Some(Host::Desktop { .. })
                )
            {
                skipped += 1;
            }
            spec.map(wsfile::Layout::Pane)
        });
        let ws = ws.map(|mut ws| {
            ws.tabs.extend(more_tabs);
            ws
        });
        (ws, skipped)
    }

    /// Window > Workspaces > Save layout as workspace, to `path`.
    fn save_workspace(&mut self, path: &Path) -> std::result::Result<String, String> {
        let (ws, skipped) = self.workspace_now();
        let ws = ws.ok_or_else(|| {
            "There is nothing to save: remote desktops are not kept in workspaces.".to_owned()
        })?;
        if !wsfile::fits(&ws) {
            return Err(format!(
                "A workspace holds at most {} tabs and {} panes.",
                wsfile::MAX_TABS,
                wsfile::MAX_PANES
            ));
        }
        wsfile::write(path, &ws).map_err(|e| format!("Could not save {}: {e}", path.display()))?;
        let name = path
            .file_stem()
            .map(|s| s.to_string_lossy().into_owned())
            .unwrap_or_default();
        let (tabs, panes) = (ws.tabs.len(), ws.pane_count());
        let mut text = format!(
            "Saved the workspace {name}: {tabs} tab{} with {panes} pane{}. \
             Window > Workspaces opens it again.",
            plural(tabs),
            plural(panes),
        );
        if skipped > 0 {
            text.push_str(&format!(
                " {skipped} pane{} left out: workspaces do not keep remote desktops.",
                plural(skipped)
            ));
        }
        Ok(text)
    }

    /// Keeps the window's layout for the next start, when Reopen the last
    /// layout at start is on. Nothing but connect prompts leaves nothing.
    fn save_last_layout(&self) {
        if !self.layout_owner || !self.settings.restore_layout {
            return;
        }
        let path = last_layout_path();
        // Turned off meanwhile in another FeroSSH window: its settings
        // file says so, and nothing is kept.
        let still_on = app_read(&settings_path())
            .map(|t| Settings::parse(&t).restore_layout)
            .unwrap_or(true);
        if !still_on {
            let _ = std::fs::remove_file(&path);
            return;
        }
        let ws = self.workspace_now().0.filter(|ws| {
            ws.tabs
                .iter()
                .any(|t| t.root.panes().iter().any(|p| p.open != WsOpen::Prompt))
        });
        match ws {
            // One too big for a workspace file, or one that fails to be
            // written, leaves the last one kept. FeroSSH is closing, so
            // there is no window left to say so in.
            Some(ws) => {
                if wsfile::fits(&ws) {
                    let _ = wsfile::write(&path, &ws);
                }
            }
            None => {
                let _ = std::fs::remove_file(&path);
            }
        }
    }

    /// Forgets the layout kept for the next start: FeroSSH closed with
    /// its last pane, so there is nothing to reopen.
    fn forget_last_layout(&self) {
        if self.layout_owner && self.settings.restore_layout {
            let _ = std::fs::remove_file(last_layout_path());
        }
    }

    /// Reopens the layout FeroSSH had when it last closed, when Reopen the
    /// last layout at start is on.
    fn reopen_last_layout(&mut self) -> Option<Command> {
        if !self.layout_owner || !self.settings.restore_layout {
            return None;
        }
        let path = last_layout_path();
        if !path.is_file() {
            return None;
        }
        match wsfile::read(&path) {
            Ok(ws) => self.open_workspace_checked(ws, &path),
            Err(e) => Some(Command::Notice(format!(
                "Could not reopen the last layout: {e}"
            ))),
        }
    }

    /// Opens the workspace called `name` in the workspaces folder, or the
    /// file `name` names.
    fn open_workspace_named(&mut self, name: &str) -> Option<Command> {
        let path = if name.contains(['\\', '/'])
            || name
                .rsplit_once('.')
                .is_some_and(|(_, e)| e.eq_ignore_ascii_case(wsfile::EXTENSION))
        {
            PathBuf::from(name)
        } else {
            match wsfile::existing(&workspaces_dir(), name) {
                Some(p) => p,
                None => return Some(Command::Notice(format!("There is no workspace {name}."))),
            }
        };
        match wsfile::read(&path) {
            Ok(ws) => self.open_workspace_checked(ws, &path),
            Err(e) => Some(Command::Notice(e)),
        }
    }

    /// Opens workspace `ws` (from file `path`), after asking when it runs
    /// something this PC has not allowed yet.
    fn open_workspace_checked(&mut self, ws: wsfile::Workspace, path: &Path) -> Option<Command> {
        let lines: Vec<(String, String)> = wsfile::commands(&ws)
            .into_iter()
            .map(|l| {
                let key = self.approval_key(&l);
                (l, key)
            })
            .filter(|(_, key)| !workspace_line_approved(key))
            .collect();
        if lines.is_empty() {
            self.open_workspace(&ws, true);
            return None;
        }
        let name = path
            .file_stem()
            .map(|s| s.to_string_lossy().into_owned())
            .unwrap_or_default();
        Some(Command::ConfirmWorkspace {
            name,
            ws: Box::new(ws),
            lines,
        })
    }

    /// What allowing a workspace's line (see [`wsfile::commands`])
    /// keeps: a script's line together with what the script holds now,
    /// so a script changed since asks again.
    fn approval_key(&self, line: &str) -> String {
        let Some(name) = line.strip_prefix("Script ") else {
            return line.to_owned();
        };
        match self
            .settings
            .snippets
            .iter()
            .find(|s| s.name.eq_ignore_ascii_case(name.trim()))
        {
            Some(s) => workspaces::script_key(line, &s.lines),
            None => line.to_owned(),
        }
    }

    /// Opens `ws` as new tabs; a window that only waits at the connect
    /// prompt gives its tab up to it. Panes on one SSH host log in once:
    /// the first logs in, the others wait for it and open on its
    /// connection.
    fn open_workspace(&mut self, ws: &wsfile::Workspace, run: bool) {
        let all = self.ws.all_panes();
        let idle = match all.as_slice() {
            [only] => (matches!(
                self.panes.get(only).map(|p| &p.host),
                Some(Host::Ask(t)) if t.is_empty()
            ) && !self.confirm_pending(*only))
            .then_some(*only),
            _ => None,
        };
        // A tmux session opens from its first pane; tmux shows the rest.
        let mut ws = ws.clone();
        let mut plans: HashMap<(String, String), workspaces::TmuxPlan> =
            workspaces::take_tmux(&mut ws)
                .into_iter()
                .map(|plan| ((plan.destination.clone(), plan.session.clone()), plan))
                .collect();
        let mut opened: Vec<(PaneId, PaneSpec)> = Vec::new();
        let mut focus_of_active = None;
        for (i, tab) in ws.tabs.iter().enumerate() {
            let mut panes = Vec::new();
            let ids = &mut self.ws;
            let root = workspaces::node_of(&tab.root, &mut || ids.alloc_id(), &mut panes);
            let Some(focus) = panes
                .get(tab.focus)
                .or_else(|| panes.first())
                .map(|(id, _)| *id)
            else {
                continue;
            };
            let at = self.ws.tabs.len();
            self.ws.insert_tab(at, root, focus);
            for (id, _) in &panes {
                self.add_pane(*id);
            }
            if i == ws.active || focus_of_active.is_none() {
                focus_of_active = Some(focus);
            }
            opened.extend(panes);
        }
        let Some(focus) = focus_of_active else {
            return;
        };
        if let Some(old) = idle
            && self.ws.remove_pane(old)
        {
            self.end_host(old);
            self.panes.remove(&old);
        }
        self.focus_pane(focus);
        self.focus_terminal();
        // Laid out first, so each shell starts with its pane's size.
        self.after_structure_change();
        let mut leads: HashMap<String, PaneId> = HashMap::new();
        for (id, spec) in opened {
            if let (WsOpen::Connection(dest), Some(name)) = (&spec.open, &spec.tmux) {
                let name = ferossh_tmuxcc::command::session_name(name);
                if let Some(plan) = plans.remove(&(dest.trim().to_owned(), name.clone())) {
                    let rebuild = workspaces::tmux_rebuild(&plan);
                    self.workspace_tmux.insert(
                        id,
                        WorkspaceTmux {
                            name,
                            plan,
                            rebuild,
                            key: None,
                        },
                    );
                }
            }
            let dest = match &spec.open {
                WsOpen::Connection(d) => Some(Some(d.trim().to_owned())),
                WsOpen::Local => Some(None),
                WsOpen::Prompt => None,
            };
            if let Some(dest) = dest {
                self.workspace_extra.insert(
                    id,
                    WorkspaceExtra {
                        dest,
                        script: spec.script.clone(),
                        command: spec.command.clone(),
                        pending: run && spec.runs(),
                        login: self.settings.workspace_auto_login,
                        shell: 0,
                    },
                );
            }
            self.open_workspace_pane(id, &spec, &mut leads);
            self.workspace_look(id, &spec);
            if let Some(name) = spec.name.clone() {
                self.rename_session(id, Some(name));
            }
        }
        self.update_title();
        self.refresh_chrome();
        self.request_full_redraw();
    }

    /// Opens what a workspace's pane `id` opens. An SSH host another pane
    /// of the workspace already logs in to waits for that login.
    fn open_workspace_pane(
        &mut self,
        id: PaneId,
        spec: &PaneSpec,
        leads: &mut HashMap<String, PaneId>,
    ) {
        let dest = match &spec.open {
            WsOpen::Prompt => {
                self.ask_destination(id);
                return;
            }
            WsOpen::Local => {
                self.start_shell_in(id, spec.dir.as_deref());
                return;
            }
            WsOpen::Connection(d) => d.clone(),
        };
        let kind = self.settings.profile(&dest).map(|p| p.kind);
        match kind {
            Some(SessionKind::Serial) => {
                let line = self
                    .settings
                    .profile(&dest)
                    .and_then(|p| p.serial)
                    .unwrap_or_default();
                let hostname = Target::resolve(&dest, &ssh_env()).map(|t| t.hostname);
                match hostname
                    .as_deref()
                    .and_then(serial::port_name)
                    .or_else(|| serial::port_name(&dest))
                {
                    Some(port) => self.open_serial(
                        id,
                        SerialTarget {
                            port,
                            settings: line,
                        },
                        Some(&dest),
                    ),
                    None => {
                        self.show(
                            id,
                            &format!(
                                "\x1b[0;31mThe connection {} has no COM port.\x1b[0m\r\n",
                                crate::ssh::sanitize(&dest)
                            ),
                        );
                        self.ask_destination(id);
                    }
                }
                return;
            }
            Some(
                SessionKind::Rdp | SessionKind::Vnc | SessionKind::Xvfb | SessionKind::RemoteApp,
            ) => {
                self.show(
                    id,
                    &format!(
                        "\x1b[0;90m{} is a remote desktop or app connection: open it from the \
                         Connection manager. Workspaces keep terminal panes.\x1b[0m\r\n",
                        crate::ssh::sanitize(&dest)
                    ),
                );
                self.ask_destination(id);
                return;
            }
            _ => {}
        }
        let shares = workspaces::shares_login(&dest, kind.map(|k| k == SessionKind::Ssh));
        let key = dest.to_ascii_lowercase();
        if shares
            && let Some(&lead) = leads.get(&key)
            && matches!(self.panes.get(&lead).map(|p| &p.host), Some(Host::Ssh(_)))
        {
            self.show(
                id,
                &format!(
                    "\x1b[0;90mWaiting for {} to log in in another pane; this pane then opens \
                     on the same connection.\x1b[0m\r\n",
                    crate::ssh::sanitize(&dest)
                ),
            );
            self.workspace_waiting.add(id, lead, dest, spec.clone());
            return;
        }
        self.connect_with_dir(id, &dest, spec.dir.as_deref());
        self.confirmed_look(id, spec);
        if shares && matches!(self.panes.get(&id).map(|p| &p.host), Some(Host::Ssh(_))) {
            leads.insert(key, id);
        }
    }

    /// Connects pane `id` to `dest`; an SSH shell goes to `dir` once
    /// logged in.
    fn connect_with_dir(&mut self, id: PaneId, dest: &str, dir: Option<&str>) {
        self.connect(id, dest);
        if self.confirm_pending(id) {
            // Set up once the security rule's question is answered Yes.
            self.after_confirm(
                id,
                AfterConfirm::Workspace {
                    dir: dir.map(str::to_owned),
                    spec: None,
                },
            );
            return;
        }
        if let Some(p) = self.panes.get_mut(&id)
            && let Host::Ssh(s) = &p.host
        {
            // The host a workspace's tmux session is attached on.
            if let Some(w) = self.workspace_tmux.get_mut(&id) {
                w.key = Some(sftp_key(&s.target));
            }
            if let Some(dir) = dir {
                p.start_dir = Some(dir.as_bytes().to_vec());
            }
        }
    }

    /// Workspace pane `id` waiting for a security rule's answer gets the
    /// workspace's look once the login comes, over its host's.
    fn confirmed_look(&mut self, id: PaneId, spec: &PaneSpec) {
        if let Some(PendingConnect {
            after: AfterConfirm::Workspace { spec: s, .. },
            ..
        }) = self.connect_pending.get_mut(&id)
        {
            *s = Some(Box::new(spec.clone()));
        }
    }

    /// Whether pane `id`'s logins keep their passwords as a workspace's
    /// pane: Window > Workspaces > Log in automatically is on and the
    /// pane still shows the connection the workspace opened.
    fn workspace_login(&self, id: PaneId) -> bool {
        // Also on when the workspace opened: turning it on later does not
        // reach panes already open, and turning it off reaches them all.
        self.settings.workspace_auto_login
            && self
                .workspace_extra
                .get(&id)
                .is_some_and(|e| e.login && e.dest.is_some())
    }

    /// The password source of pane `id`'s login to connection `alias`:
    /// the connection's own, except that a workspace's pane that would
    /// ask keeps the password like the Windows Credential Manager setting
    /// does (in the vault when one is open), when Log in automatically is
    /// on.
    fn login_source(&self, id: PaneId, alias: &str) -> PasswordSource {
        // A named credential's source wins over the connection's own.
        let source = self.settings.password_source(alias);
        if source == PasswordSource::Ask && self.workspace_login(id) {
            PasswordSource::Windows
        } else {
            source
        }
    }

    /// Runs what workspace pane `id` runs once its shell is ready (logged
    /// in, its login script done and in its directory; for a `local`
    /// pane, its shell started): its script, then its command. Once: a
    /// reconnect runs neither again. A pane with the Production theme asks
    /// first when Confirm scripts and agents on Production hosts is on.
    fn workspace_start(&mut self, id: PaneId, local: bool) {
        let Some(e) = self
            .workspace_extra
            .get_mut(&id)
            .filter(|e| e.pending && e.dest.is_none() == local)
        else {
            return;
        };
        e.pending = false;
        let (script, command) = (e.script.clone(), e.command.clone());
        if script.is_none() && command.is_none() {
            return;
        }
        // tmux keeps its programs running itself.
        if self.tmux.get(&id).is_some_and(Tmux::active) {
            self.show(
                id,
                "\x1b[0;90mThis pane shows tmux, so the workspace's script and command \
                 are not run here: tmux keeps its programs running.\x1b[0m\r\n",
            );
            return;
        }
        if self.settings.confirm_production
            && self
                .panes
                .get(&id)
                .is_some_and(|p| p.theme.name == "Production")
        {
            let label = self.pane_label(id);
            let shell = self.workspace_extra.get(&id).map_or(0, |e| e.shell);
            // Asked from its own timer: whatever brought the pane here
            // (output, a timer, opening the workspace) may not ask now.
            self.workspace_asks.push(Command::ConfirmWorkspaceStart {
                pane: id,
                label,
                script,
                command,
                shell,
            });
            // SAFETY: our window; replaces any earlier timer with this id.
            unsafe { SetTimer(Some(self.hwnd), TIMER_WORKSPACE_ASK, 50, None) };
            return;
        }
        self.workspace_run(id, script.as_deref(), command);
    }

    /// Workspace pane `id`'s shell ended (or is reconnecting).
    fn workspace_shell_gone(&mut self, id: PaneId) {
        if let Some(e) = self.workspace_extra.get_mut(&id) {
            e.shell += 1;
        }
    }

    /// Forgets what workspace pane `id` would run: tmux took its shell, and
    /// keeps its programs running itself.
    fn workspace_drop(&mut self, id: PaneId) {
        if let Some(e) = self.workspace_extra.get_mut(&id) {
            e.pending = false;
        }
    }

    /// Runs workspace pane `id`'s script from the scripts folder, then
    /// types its command as written once the script is over.
    fn workspace_run(&mut self, id: PaneId, script: Option<&str>, mut command: Option<String>) {
        if let Some(script) = script {
            let found = self
                .settings
                .snippets
                .iter()
                .find(|s| s.name.eq_ignore_ascii_case(script.trim()))
                .map(|s| (s.name.clone(), s.lines.clone()));
            let allowed =
                workspace_line_approved(&self.approval_key(&format!("Script {}", script.trim())));
            match found {
                Some((name, _)) if !allowed => self.show(
                    id,
                    &format!(
                        "\x1b[0;31mThe script {} changed since this workspace was allowed to \
                         run it, so it is not run. Open the workspace again to allow it.\x1b[0m\r\n",
                        crate::ssh::sanitize(&name)
                    ),
                ),
                Some((name, lines)) => {
                    // Arguments take their defaults: nobody is asked as it
                    // opens.
                    let args = login::args(&lines);
                    let vars = self.vars(id, &lines, false);
                    let steps = login::expand(
                        &lines,
                        true,
                        |n| {
                            args.iter()
                                .find(|a| a.number == n)
                                .map(|a| a.default.clone())
                                .unwrap_or_default()
                        },
                        |n| snippets_view::var(&vars, n),
                    );
                    // The command waits for this run, set before it starts:
                    // a script over at once (done, or failed) settles it
                    // before run_snippet returns.
                    let run = self.script_runs + 1;
                    let free = !self.scripts.contains_key(&id);
                    if free && let Some(c) = command.take() {
                        self.workspace_after.insert(id, (run, c));
                    }
                    if let Some(Command::Notice(text)) = self.run_snippet(&name, steps, &[id]) {
                        self.show(id, &format!("\x1b[0;31m{text}\x1b[0m\r\n"));
                    }
                    // Not started after all: the command goes on its own.
                    let started = self.scripts.get(&id).is_some_and(|r| r.run == run);
                    if !started
                        && self.workspace_after.get(&id).is_some_and(|(r, _)| *r == run)
                    {
                        command = self.workspace_after.remove(&id).map(|(_, c)| c);
                    }
                }
                None => self.show(
                    id,
                    &format!(
                        "\x1b[0;31mThe workspace runs the script {}, which is not in the \
                         scripts folder.\x1b[0m\r\n",
                        crate::ssh::sanitize(script)
                    ),
                ),
            }
        }
        let Some(command) = command else {
            return;
        };
        // A script still running in the pane (one that waits) goes first;
        // the command follows in this pane once it is over.
        match self.scripts.get(&id) {
            Some(run) => {
                self.workspace_after.insert(id, (run.run, command));
            }
            None => self.workspace_type(id, &command),
        }
    }

    /// Runs what workspace pane `id` runs after Yes on Production: unless
    /// its shell went meanwhile (reconnecting, its login script running
    /// again, or tmux in it).
    fn workspace_confirmed(
        &mut self,
        id: PaneId,
        shell: u64,
        script: Option<&str>,
        command: Option<String>,
    ) {
        let same = self
            .workspace_extra
            .get(&id)
            .is_some_and(|e| e.shell == shell);
        let ready = same
            && match self.panes.get(&id).map(|p| &p.host) {
                Some(Host::Ssh(s)) => s.state() == State::Connected,
                Some(_) => true,
                None => false,
            };
        let busy = self.scripts.get(&id).is_some_and(|r| r.login)
            || self.tmux.get(&id).is_some_and(Tmux::active);
        if !ready || busy {
            if self.panes.contains_key(&id) {
                self.show(
                    id,
                    "\x1b[0;90mThe workspace's script and command are not run: this \
                     pane's shell changed while FeroSSH asked.\x1b[0m\r\n",
                );
            }
            return;
        }
        self.workspace_run(id, script, command);
    }

    /// Types a workspace's `Command` line at pane `id` as written, then
    /// Enter.
    fn workspace_type(&mut self, id: PaneId, line: &str) {
        let mut bytes = line.as_bytes().to_vec();
        bytes.push(b'\r');
        self.input(id, bytes);
    }

    /// A workspace pane's own look, over its host's: never over a
    /// Production or Staging warning colour.
    fn workspace_look(&mut self, id: PaneId, spec: &PaneSpec) {
        let Some(p) = self.panes.get(&id) else {
            return;
        };
        if let Some(theme) = spec.theme.as_deref().and_then(Theme::by_name)
            && p.theme.group() != ThemeGroup::Warning
            && theme.group() != ThemeGroup::Warning
        {
            self.set_theme(id, theme);
        }
        let Some(p) = self.panes.get(&id) else {
            return;
        };
        if spec.font.is_some() || spec.font_size.is_some() {
            let mut font = p.font.clone();
            if let Some(family) = &spec.font {
                font.family.clone_from(family);
            }
            if let Some(size) = spec.font_size {
                font.size_pt = size.clamp(FontSpec::MIN_PT, FontSpec::MAX_PT);
            }
            self.set_font(id, font);
        }
    }

    /// The panes of a workspace that waited for pane `lead` to log in.
    /// Logged in (`ok`): they open on its connection. Failed: the first of
    /// them logs in itself, and the rest wait for that one.
    fn release_workspace_panes(&mut self, lead: PaneId, ok: bool) {
        if self.workspace_waiting.is_empty() {
            return;
        }
        let mut new_lead: Option<PaneId> = None;
        for (pane, dest, spec) in self.workspace_waiting.take(lead) {
            // The user may have typed a destination of their own meanwhile.
            let free = matches!(
                self.panes.get(&pane).map(|p| &p.host),
                Some(Host::Ask(t)) if t.is_empty()
            ) && !self.confirm_pending(pane);
            if !free {
                continue;
            }
            match new_lead {
                Some(l) if !ok => self.workspace_waiting.add(pane, l, dest, spec),
                _ => {
                    self.connect_with_dir(pane, &dest, spec.dir.as_deref());
                    // Its host's look came with the login: the workspace's
                    // goes over it again.
                    self.workspace_look(pane, &spec);
                    self.confirmed_look(pane, &spec);
                    if !ok && matches!(self.panes.get(&pane).map(|p| &p.host), Some(Host::Ssh(_))) {
                        new_lead = Some(pane);
                    }
                }
            }
        }
    }

    /// Window > Workspaces, as it opens: the saved workspaces after the
    /// first items.
    fn fill_workspaces(&mut self, menu: HMENU) {
        self.workspace_names = wsfile::list(&workspaces_dir());
        self.workspace_names.truncate(MAX_MENU_WORKSPACES);
        // SAFETY: our popup menu; it is being opened, when changing it is
        // allowed. Only the items after the fixed ones are replaced.
        unsafe {
            while GetMenuItemCount(Some(menu)) > WORKSPACE_MENU_FIXED {
                let _ = DeleteMenu(menu, WORKSPACE_MENU_FIXED as u32, MF_BYPOSITION);
            }
            if !self.workspace_names.is_empty() {
                let _ = AppendMenuW(menu, MF_SEPARATOR, 0, None);
            }
            for (id, name) in (cmd::WORKSPACE_OPEN..).zip(&self.workspace_names) {
                let label = name.replace('&', "&&");
                let _ = AppendMenuW(menu, MF_STRING, id as usize, &HSTRING::from(label));
            }
        }
    }

    /// File > Recent connections, as it opens: the recent ones, newest
    /// first, then Clear this list.
    fn fill_recent(&mut self, menu: HMENU) {
        self.pull_vault_settings();
        let recent = self.settings.recent.clone();
        // SAFETY: our popup menu; it is being opened, when changing it is
        // allowed. Everything before Clear this list is replaced.
        unsafe {
            while GetMenuItemCount(Some(menu)) > 1 {
                let _ = DeleteMenu(menu, 0, MF_BYPOSITION);
            }
            let flags = MF_BYPOSITION | MF_STRING;
            if recent.is_empty() {
                let _ = InsertMenuW(menu, 0, flags | MF_GRAYED, 0, w!("(none yet)"));
            }
            for (i, (id, dest)) in (cmd::RECENT..cmd::RECENT_END).zip(&recent).enumerate() {
                // An access key for the first nine: &1 to &9.
                let label = format!("&{} {}", i + 1, dest.replace('&', "&&"));
                let _ = InsertMenuW(menu, i as u32, flags, id as usize, &HSTRING::from(label));
            }
            let _ = InsertMenuW(
                menu,
                recent.len().max(1) as u32,
                MF_BYPOSITION | MF_SEPARATOR,
                0,
                None,
            );
            let _ = EnableMenuItem(
                menu,
                cmd::RECENT_CLEAR,
                MF_BYCOMMAND
                    | if recent.is_empty() {
                        MF_GRAYED
                    } else {
                        MF_ENABLED
                    },
            );
        }
    }

    /// Puts `destination` first in File > Recent connections.
    fn note_recent(&mut self, destination: &str) {
        if self.settings.recent.first().map(String::as_str) == Some(destination.trim()) {
            return;
        }
        self.settings.note_recent(destination);
        self.save_settings();
    }

    /// Connect to...: asks for a destination in `pane` if it is already
    /// waiting at the connect prompt, else in a new tab, so the shells
    /// already open keep running.
    fn connect_in_new_tab(&mut self, pane: PaneId) {
        let idle = matches!(
            self.panes.get(&pane).map(|p| &p.host),
            Some(Host::Ask(t)) if t.is_empty()
        ) && !self.confirm_pending(pane);
        let id = if idle { pane } else { self.new_tab_pane() };
        self.focus_terminal();
        self.ask_destination(id);
    }

    /// Open local shell: starts it in `pane` if that waits at the connect
    /// prompt or holds a local shell that ended, else in a new tab, so a
    /// running SSH, Telnet, serial or tmux session is never ended.
    fn local_shell_in_new_tab(&mut self, pane: PaneId) {
        let idle = match self.panes.get(&pane).map(|p| &p.host) {
            Some(Host::Ask(t)) => t.is_empty(),
            Some(Host::Local { exited, .. }) => *exited,
            _ => false,
        };
        // From a live local shell, in its folder.
        let dir = self.panes.get(&pane).and_then(|p| match p.host {
            Host::Local { exited: false, .. } => p.local_cwd.clone(),
            _ => None,
        });
        let id = if idle { pane } else { self.new_tab_pane() };
        // A workspace pane waiting for its SSH login is a local shell now.
        if self
            .workspace_extra
            .get(&id)
            .is_some_and(|e| e.dest.is_some())
            || self.workspace_waiting.destination(id).is_some()
        {
            self.workspace_extra.remove(&id);
            self.workspace_waiting.forget(id);
            self.workspace_tmux.remove(&id);
        }
        self.focus_terminal();
        self.start_shell_in(id, dir.as_deref());
    }

    /// Gives the keyboard back to the focused pane. Unless Settings >
    /// Keep tools open is on, the terminal covers the tool again.
    fn focus_terminal(&mut self) {
        if self.side.visible && !self.settings.tools_pinned {
            self.hide_side();
        }
        if self.side.focused {
            self.side.focused = false;
            self.refresh_chrome();
            self.request_full_redraw();
        }
        let id = self.focused_id();
        if let Some(p) = self.panes.get_mut(&id)
            && let Some(c) = p.cursor
        {
            p.grid.mark_dirty(c.y);
        }
        self.refresh(id);
    }

    /// Shows the side pane in `view`; the connection manager re-reads
    /// ssh_config, file transfer opens SFTP if it is not open.
    fn show_side(&mut self, view: SideView, focus: bool) {
        self.side.view = view;
        self.rename_return = None;
        match view {
            SideView::Sessions => {
                let env = ssh_env();
                self.side.list.set_hosts(
                    host_items(&env, &self.settings),
                    self.settings.favourites.clone(),
                );
                self.side.list.set_workspaces(workspace_items());
                self.side
                    .list
                    .set_saved_searches(self.settings.saved_searches.clone());
            }
            SideView::Files => {
                // Opening the view lists the focused pane's directory.
                self.files_pane = None;
                self.ensure_sftp(self.focused_id());
            }
            SideView::Forwards | SideView::Palette => {}
            SideView::KnownHosts => self.reload_known_hosts(),
            SideView::Inventory => self.reload_inventory(),
            SideView::Hosts => self.reload_hosts(),
            SideView::Credentials => self.reload_credentials(),
            SideView::SecurityRules => self.reload_rules(),
            SideView::Themes | SideView::ThemeRules => self.reload_themes(),
            SideView::Live => {
                let all = self.open_sessions();
                self.live_view.reset(&all);
            }
            SideView::Snippets => {
                let place = self.place(self.focused_id()).map(|p| p.0);
                self.snippets_view.set_place(place);
                if !self.snippets_view.editing()
                    && !self.snippets_view.asking()
                    && !self.snippets_view.reporting()
                {
                    self.reload_snippets();
                    self.snippets_view.reset();
                }
            }
        }
        if !self.side.visible {
            let min = scale(toolpane::MIN_SHOWN_DIP, self.dpi);
            self.side.shown = toolpane::reopen(self.side.shown, self.side.width, min);
        }
        self.side.visible = true;
        self.side.focused = focus;
        self.layout();
        self.update_menu_checks();
        self.update_quiet_timer();
    }

    /// Tools > Connection manager, Session manager, File transfer,
    /// Port forwards or Command snippets (`id`). The shortcut first moves
    /// the focus to a pane that is open but not focused, then hides it; a
    /// menu click (`from_menu`) hides it at once, since its checkmark says
    /// the pane is open.
    fn toggle_side(&mut self, id: u32, from_menu: bool) {
        let view = match id {
            cmd::FILES => SideView::Files,
            cmd::FORWARDS => SideView::Forwards,
            cmd::SNIPPETS => SideView::Snippets,
            cmd::LIVE => SideView::Live,
            cmd::KNOWN_HOSTS => SideView::KnownHosts,
            cmd::INVENTORY => SideView::Inventory,
            cmd::HOSTS => SideView::Hosts,
            cmd::CREDENTIAL_MANAGER => SideView::Credentials,
            cmd::SECURITY_RULES => SideView::SecurityRules,
            cmd::THEME_MANAGER => SideView::Themes,
            cmd::THEME_RULES => SideView::ThemeRules,
            _ => SideView::Sessions,
        };
        let open = self.side.visible && self.side.view == view;
        match side_toggle(open, self.side.focused, from_menu) {
            SideToggle::Show => {
                self.snippets_peek = view == SideView::Snippets && !self.side.visible;
                self.show_side(view, true);
            }
            SideToggle::Hide => self.hide_side(),
            SideToggle::Focus => {
                self.side.focused = true;
                self.refresh_chrome();
                self.request_full_redraw();
                self.refresh(self.focused_id());
            }
        }
        self.update_menu_checks();
    }

    fn hide_side(&mut self) {
        self.rename_return = None;
        self.snippets_peek = false;
        self.palette_return = None;
        self.side.visible = false;
        self.side.focused = false;
        self.layout();
        self.update_menu_checks();
        self.update_quiet_timer();
    }

    /// A pane for a new tab, with the default look.
    fn new_tab_pane(&mut self) -> PaneId {
        let id = self.ws.new_tab();
        self.add_pane(id);
        self.after_structure_change();
        id
    }

    fn add_pane(&mut self, id: PaneId) {
        let font = self.default_font.clone();
        let metrics = self
            .renderer
            .metrics(&font, self.dpi)
            .unwrap_or(self.chrome_metrics);
        let pane = new_pane(
            id,
            font,
            self.default_theme.clone(),
            metrics,
            self.settings.scrollback,
        );
        self.panes.insert(id, pane);
        self.apply_highlight(id, false);
    }

    /// Splits the focused pane; the new pane takes the focus.
    fn split(&mut self, side: Dir) -> Option<PaneId> {
        let id = self.ws.split(side)?;
        self.add_pane(id);
        self.after_structure_change();
        Some(id)
    }

    /// Opens a new pane like `from`: the same host as a new channel on its
    /// connection, a local shell, or the connect prompt, in the directory
    /// `from`'s shell is in where FeroSSH knows it (SSH: OSC 7 or the
    /// prompt; local: the cmd or PowerShell prompt). Telnet has no login
    /// FeroSSH can tell, so it starts where it starts.
    fn fill_like(&mut self, id: PaneId, from: PaneId) {
        enum Like {
            Ssh(Box<Target>),
            Telnet(TelnetTarget),
            Winrm(WinrmTarget),
            Local,
            Ask,
        }
        let from = self.host_pane(from);
        let (cwd, local_cwd) = self
            .panes
            .get(&from)
            .map(|p| (p.cwd.clone(), p.local_cwd.clone()))
            .unwrap_or_default();
        // A COM port opens once, so a split of a serial console asks.
        let like = match self.panes.get(&from).map(|p| &p.host) {
            Some(Host::Ssh(s)) => Like::Ssh(Box::new(s.target.clone())),
            Some(Host::Telnet(s)) => Like::Telnet(s.target.clone()),
            Some(Host::Winrm(s)) => Like::Winrm(s.target.clone()),
            Some(Host::Local { .. }) => Like::Local,
            _ => Like::Ask,
        };
        match like {
            Like::Ssh(mut target) => {
                let env = ssh_env();
                if let Err(why) = target.refresh_login(&env) {
                    self.show(id, &login_refused(&why));
                    return;
                }
                self.connect_to(id, *target, &env);
                if let Some(p) = self.panes.get_mut(&id) {
                    p.start_dir = cwd;
                }
            }
            Like::Telnet(target) => self.connect_telnet(id, target),
            Like::Winrm(target) => self.connect_winrm(id, target),
            Like::Local => self.start_shell_in(id, local_cwd.as_deref()),
            Like::Ask => self.ask_destination(id),
        }
    }

    /// After tabs or panes changed: lay out, redraw, retitle.
    fn after_structure_change(&mut self) {
        let looking = self.focused;
        if let Some(p) = self.panes.get_mut(&self.ws.focused()) {
            p.bell = false;
            // Seen only while FeroSSH is in front: a layout change in the
            // background (a tmux pane closing) leaves the badge.
            if looking {
                p.attention = false;
            }
        }
        self.layout();
        self.update_title();
        self.update_menu_checks();
    }

    /// Window > Hide pane: pane `id` leaves its tab, the others taking
    /// its space, and runs on. The session manager lists it, to show it
    /// again. A tmux pane's window stays hidden in the saved layout.
    fn hide_pane(&mut self, id: PaneId) -> Option<Command> {
        if self.locked(id) {
            return Some(Command::Notice(
                "This tmux session uses tmux's own layout, so its panes cannot be hidden. \
                 Session > tmux > One window per pane lets them hide."
                    .into(),
            ));
        }
        if !self.ws.hide(id) {
            return Some(Command::Notice(
                "The window's last pane cannot be hidden.".into(),
            ));
        }
        if self.mouse.pane == Some(id) {
            self.mouse.pane = None;
        }
        self.after_structure_change();
        self.refresh_chrome();
        None
    }

    /// Shows hidden pane `id` again where it was (in a tab of its own when
    /// the panes around it went), with the keyboard.
    fn show_hidden(&mut self, id: PaneId) {
        let before = self.focused_id();
        if !self.ws.show(id) {
            return;
        }
        if before != id {
            self.last_pane = Some(before);
        }
        let looking = self.focused;
        if let Some(p) = self.panes.get_mut(&id) {
            p.bell = false;
            if looking {
                p.attention = false;
            }
            p.grid.mark_all_dirty();
        }
        self.after_structure_change();
        self.focus_terminal();
        self.refresh_chrome();
    }

    /// Closes a pane; the last one closes the window. A tmux pane is
    /// closed in tmux, and goes when tmux says it went.
    fn close_pane(&mut self, id: PaneId) -> Option<Command> {
        if let Some(gateway) = self.panes.get(&id).and_then(Pane::gateway)
            && let Some(t) = self.tmux.get_mut(&gateway).filter(|t| t.active())
        {
            let actions = t.close(id);
            self.run_tmux(gateway, actions);
            return None;
        }
        self.reattach.remove(&id);
        self.workspace_tmux.remove(&id);
        self.workspace_extra.remove(&id);
        self.workspace_after.remove(&id);
        self.workspace_waiting.forget(id);
        self.release_workspace_panes(id, false);
        // The last pane in the tabs closing while others are hidden: the
        // one hidden last shows, so the window and their sessions stay.
        if self.ws.all_panes() == [id]
            && let Some(&last) = self.ws.hidden().last()
        {
            self.ws.show(last);
        }
        if self.ws.forget_hidden(id) {
            // A hidden pane: no tab changes.
            self.end_host(id);
            self.panes.remove(&id);
            if self.mouse.pane == Some(id) {
                self.mouse.pane = None;
            }
            self.refresh_chrome();
            self.update_menu_checks();
            return None;
        }
        match self.ws.close(id) {
            Some(Closed::Window) => return Some(Command::Destroy),
            Some(_) => {}
            None => return None,
        }
        self.end_host(id);
        self.panes.remove(&id);
        if self.mouse.pane == Some(id) {
            self.mouse.pane = None;
        }
        self.after_structure_change();
        None
    }

    /// Focuses a pane (and its tab).
    fn focus_pane(&mut self, id: PaneId) {
        let before = self.focused_id();
        let tab_before = self.ws.active;
        if !self.ws.focus(id) {
            return;
        }
        if before != id {
            if tab_before == self.ws.active {
                self.last_pane = Some(before);
            } else {
                self.last_tab_pane = Some(before);
            }
        }
        let was_side = std::mem::take(&mut self.side.focused);
        if before == id && tab_before == self.ws.active && !was_side {
            return;
        }
        // Seen only while FeroSSH is in front: a script moving focus in
        // the background leaves the badge.
        let looking = self.focused;
        if let Some(p) = self.panes.get_mut(&id) {
            p.bell = false;
            if looking {
                p.attention = false;
            }
        }
        for pid in [before, id] {
            if let Some(p) = self.panes.get_mut(&pid)
                && let Some(c) = p.cursor
            {
                p.grid.mark_dirty(c.y);
            }
        }
        if tab_before != self.ws.active {
            self.after_structure_change();
        } else {
            self.refresh(before);
            self.refresh(id);
            self.refresh_chrome();
            self.update_title();
            self.update_menu_checks();
            // The focus frame moves.
            self.request_full_redraw();
        }
    }

    fn select_tab(&mut self, i: usize) {
        if let Some(focus) = self.ws.tabs.get(i).map(|t| t.focus) {
            self.focus_pane(focus);
        }
    }

    /// The strip around the tools pane's edge where a drag starts.
    fn edge_grab(&self) -> Option<Rect> {
        let e = self.areas.side_edge?;
        let by = scale(EDGE_GRAB_DIP, self.dpi);
        Some(Rect::new(e.x - by, e.y, e.w + 2 * by, e.h))
    }

    /// Where a client point falls.
    fn spot(&self, x: i32, y: i32) -> Spot {
        let grab = scale(GRAB_DIP, self.dpi);
        if let Some(e) = self.edge_grab()
            && e.contains(x, y)
        {
            return Spot::SideEdge;
        }
        if let Some(s) = self.areas.side
            && s.contains(x, y)
        {
            let cpad = scale(CHROME_PADDING_DIP, self.dpi);
            let col = ((x - s.x - cpad).max(0) / self.chrome_metrics.width.max(1) as i32) as usize;
            let row = ((y - s.y - cpad).max(0) / self.chrome_metrics.height.max(1) as i32) as usize;
            return Spot::Side(col, row);
        }
        if let Some(s) = self.areas.strip
            && s.contains(x, y)
        {
            let cpad = scale(CHROME_PADDING_DIP, self.dpi);
            let col = ((x - s.x - cpad).max(0) / self.strip_metrics.width.max(1) as i32) as usize;
            return Spot::Strip(col);
        }
        if let Some(tab) = self.ws.tab() {
            for d in tab.root.dividers(self.areas.panes, gap(self.dpi)) {
                let hit = match d.axis {
                    Axis::Row => {
                        Rect::new(d.rect.x - grab, d.rect.y, d.rect.w + 2 * grab, d.rect.h)
                    }
                    Axis::Column => {
                        Rect::new(d.rect.x, d.rect.y - grab, d.rect.w, d.rect.h + 2 * grab)
                    }
                };
                if hit.contains(x, y) {
                    return Spot::Divider(d);
                }
            }
            for id in tab.root.panes() {
                if self.panes.get(&id).is_some_and(|p| p.rect.contains(x, y)) {
                    return Spot::Pane(id);
                }
            }
        }
        Spot::Nothing
    }

    /// The mouse cursor for a client point.
    fn cursor_at(&self, x: i32, y: i32) -> PCWSTR {
        if let Some(drag) = &self.drag {
            return match drag {
                Drag::Divider {
                    axis: Axis::Row, ..
                }
                | Drag::SideEdge => IDC_SIZEWE,
                Drag::Divider {
                    axis: Axis::Column, ..
                } => IDC_SIZENS,
                Drag::Pane { active: true, .. } | Drag::Tab { out: true, .. } => IDC_SIZEALL,
                Drag::Pane { .. } => IDC_IBEAM,
                Drag::Tab { .. } => IDC_ARROW,
            };
        }
        match self.spot(x, y) {
            Spot::SideEdge => IDC_SIZEWE,
            Spot::Divider(d) if d.axis == Axis::Row => IDC_SIZEWE,
            Spot::Divider(_) => IDC_SIZENS,
            Spot::Pane(id) if self.preview_hit(id, x, y).is_some() => IDC_HAND,
            Spot::Pane(_) => IDC_IBEAM,
            _ => IDC_ARROW,
        }
    }

    /// The viewport cell under a client-area point in pane `id`, and
    /// whether the point is in the cell's right half.
    fn cell_at(&self, id: PaneId, x: i32, y: i32) -> (usize, usize, bool) {
        let Some(p) = self.panes.get(&id) else {
            return (0, 0, false);
        };
        let (ox, oy) = p.origin(self.dpi);
        let m = &p.metrics;
        let (cw, ch) = (m.width.max(1) as i32, m.height.max(1) as i32);
        let (rx, ry) = ((x - ox).max(0), (y - oy).max(0));
        let col = ((rx / cw) as usize).min(p.term.cols().saturating_sub(1));
        let row = ((ry / ch) as usize).min(p.term.rows().saturating_sub(1));
        (col, row, rx % cw >= cw / 2)
    }

    fn capture(&self, on: bool) {
        capture(self.hwnd, on);
    }

    /// A button press or release anywhere in the client.
    fn on_button(
        &mut self,
        button: MouseButton,
        down: bool,
        (x, y): (i32, i32),
        mods: Mods,
    ) -> Option<Command> {
        self.mouse.at = (x, y);
        if !down {
            if button == MouseButton::Left
                && let Some(drag) = self.drag.take()
            {
                self.capture(false);
                return self.end_drag(drag, (x, y));
            }
            let id = self.mouse.pane.take()?;
            return self.pane_button(id, button, false, (x, y), mods);
        }
        let spot = self.spot(x, y);
        if self.side.visible
            && !self.settings.tools_pinned
            && matches!(spot, Spot::Strip(_) | Spot::Divider(_) | Spot::Nothing)
        {
            // Pin off: a click anywhere outside the tools (the tab strip,
            // a divider, a pane's margin) ends the peek, as one on a pane
            // does. The click only does that, since everything moves.
            self.hide_side();
            return None;
        }
        if button == MouseButton::Left
            && let Spot::Pane(id) = spot
            && let Some(hit) = self.preview_hit(id, x, y)
        {
            return self.preview_click(id, hit);
        }
        match spot {
            Spot::SideEdge if button == MouseButton::Left => {
                self.capture(true);
                self.drag = Some(Drag::SideEdge);
                None
            }
            Spot::Side(col, row) => {
                if !self.side.focused {
                    self.side.focused = true;
                    self.request_full_redraw();
                }
                if button == MouseButton::Right
                    && self.side.view == SideView::Sessions
                    && self.side.form.is_none()
                    && self.side.import.is_none()
                {
                    let visible = SessionList::visible(self.side.grid.rows());
                    self.side.list.select_at(row, visible);
                    self.refresh_chrome();
                    return Some(Command::SessionMenu(
                        self.side.list.selected_host(),
                        self.side.list.selected_saved_search(),
                        Vec::new(),
                    ));
                }
                if button != MouseButton::Left {
                    self.refresh_chrome();
                    return None;
                }
                // SAFETY: plain query.
                let limit = Duration::from_millis(u64::from(unsafe { GetDoubleClickTime() }));
                let now = Instant::now();
                let double = self
                    .side
                    .last_click
                    .is_some_and(|(at, r)| r == row && now - at <= limit);
                self.side.last_click = Some((now, row));
                if self.side.view == SideView::Forwards {
                    let view = self.forward_view();
                    let rows = self.side.grid.rows();
                    self.forwards_view.click(row, &view, rows);
                    self.refresh_chrome();
                    return None;
                }
                if self.side.view == SideView::Live {
                    let all = self.open_sessions();
                    let rows = self.side.grid.rows();
                    // A click ends a rename; the pane stays as it is now.
                    self.rename_return = None;
                    let action = self.live_view.click(row, double, &all, rows);
                    self.refresh_chrome();
                    return self.live_action(action);
                }
                if self.side.view == SideView::Palette {
                    let action = self.palette.click(row, double, self.side.grid.rows());
                    return self.palette_action(action);
                }
                if self.side.view == SideView::Snippets {
                    let rows = self.side.grid.rows();
                    self.snippets_view.click(row, &self.settings.snippets, rows);
                    if double && !self.snippets_view.editing() {
                        // A double-click picks a host, or runs a snippet
                        // or shows a report row's session.
                        let key = if self.snippets_view.picking() {
                            if row < snippets_view::PICK_HEAD {
                                self.refresh_chrome();
                                return None;
                            }
                            SideKey::Char(' ')
                        } else {
                            SideKey::Enter { split: false }
                        };
                        let action = self.snippets_view.key(key, &self.settings.snippets, rows);
                        return self.snippets_action(action);
                    }
                    self.refresh_chrome();
                    return None;
                }
                if let Some(form) = &mut self.side.form {
                    let action = form.click(col, row, self.side.grid.rows());
                    return self.form_action(action);
                }
                if let Some(view) = &mut self.side.import {
                    let action = view.click(col, row, self.side.grid.rows());
                    return self.import_action(action);
                }
                let visible = SessionList::visible(self.side.grid.rows());
                let action = self.side.list.click(row, double, visible);
                self.side_action(action)
            }
            Spot::Strip(col) => {
                match (button, self.strip_layout.hit(col)) {
                    (MouseButton::Left, Some(Hit::Tab(i))) => {
                        // SAFETY: plain query.
                        let limit =
                            Duration::from_millis(u64::from(unsafe { GetDoubleClickTime() }));
                        let now = Instant::now();
                        let double = self
                            .tab_click
                            .is_some_and(|(at, t)| t == i && now - at <= limit);
                        if double {
                            // A double-click renames the tab's session.
                            self.tab_click = None;
                            self.select_tab(i);
                            if let Some(focus) = self.ws.tabs.get(i).map(|t| t.focus) {
                                self.start_rename(focus);
                            }
                            return None;
                        }
                        self.tab_click = Some((now, i));
                        // The tab a drag below the strip shows: the one
                        // active before, or a neighbour.
                        let before = self.ws.active;
                        let home_tab = if before != i {
                            Some(before)
                        } else if i > 0 {
                            Some(i - 1)
                        } else {
                            (self.ws.tabs.len() > 1).then_some(1)
                        };
                        let home = home_tab.and_then(|t| self.ws.tabs.get(t)).map(|t| t.focus);
                        self.select_tab(i);
                        self.capture(true);
                        self.drag = Some(Drag::Tab {
                            index: i,
                            home,
                            out: false,
                        });
                    }
                    (MouseButton::Left, Some(Hit::Close(i))) => {
                        return Some(Command::CloseTab(i));
                    }
                    (MouseButton::Left, Some(Hit::NewTab)) => {
                        return Some(Command::Id(cmd::NEW_TAB));
                    }
                    // Middle-click closes a tab, as in browsers.
                    (MouseButton::Middle, Some(Hit::Tab(i) | Hit::Close(i))) => {
                        return Some(Command::CloseTab(i));
                    }
                    (MouseButton::Right, Some(Hit::Tab(i) | Hit::Close(i))) => {
                        self.select_tab(i);
                        return Some(Command::TabMenu(i));
                    }
                    _ => {}
                }
                None
            }
            Spot::Divider(d) if button == MouseButton::Left => {
                self.capture(true);
                self.drag = Some(Drag::Divider {
                    path: d.path,
                    axis: d.axis,
                    span: d.span,
                });
                None
            }
            Spot::Pane(id) => {
                if self.side.visible && !self.settings.tools_pinned {
                    // A peek ends: the terminal covers the tool again.
                    // The click only does that, since the panes move.
                    self.hide_side();
                    self.focus_pane(id);
                    return None;
                }
                self.focus_pane(id);
                if button == MouseButton::Left && mods.ctrl && mods.shift {
                    self.capture(true);
                    self.drag = Some(Drag::Pane {
                        id,
                        start: (x, y),
                        active: false,
                    });
                    return None;
                }
                self.mouse.pane = Some(id);
                self.pane_button(id, button, true, (x, y), mods)
            }
            _ => None,
        }
    }

    /// Finishes a drag.
    fn end_drag(&mut self, drag: Drag, (x, y): (i32, i32)) -> Option<Command> {
        if let Drag::Tab {
            index, out: true, ..
        } = drag
        {
            let joined = match self.spot(x, y) {
                Spot::Pane(target)
                    if self.ws.tab_of(target) != Some(index)
                        && !self.locked_tab(index)
                        && !self.locked(target) =>
                {
                    let r = self.panes.get(&target).map(|p| p.rect).unwrap_or_default();
                    self.ws.join_tab(index, target, layout::join_side(r, x, y))
                }
                _ => false,
            };
            if !joined && let Some(focus) = self.ws.tabs.get(index).map(|t| t.focus) {
                // Dropped elsewhere: back to the dragged tab.
                self.ws.focus(focus);
            }
            self.after_structure_change();
            self.request_full_redraw();
            return None;
        }
        if let Drag::Pane {
            id, active: true, ..
        } = drag
            && !self.locked(id)
        {
            let moved = if self.areas.strip.is_some_and(|s| s.contains(x, y)) {
                self.ws.pane_to_tab(id)
            } else if let Spot::Pane(target) = self.spot(x, y) {
                let r = self.panes.get(&target).map(|p| p.rect).unwrap_or_default();
                self.ws.move_pane(id, target, layout::drop_zone(r, x, y))
            } else {
                false
            };
            if moved {
                self.after_structure_change();
            } else {
                // Back to the pane's own tab, if the drag showed another.
                let shown = self.ws.active;
                self.ws.focus(id);
                if self.ws.active != shown {
                    self.after_structure_change();
                }
                self.request_full_redraw();
            }
        }
        None
    }

    /// The tab under client x in the strip, if any.
    fn strip_tab_at(&self, x: i32) -> Option<usize> {
        let s = self.areas.strip?;
        let cpad = scale(CHROME_PADDING_DIP, self.dpi);
        let col = ((x - s.x - cpad).max(0) / self.strip_metrics.width.max(1) as i32) as usize;
        match self.strip_layout.hit(col)? {
            Hit::Tab(i) | Hit::Close(i) => Some(i),
            Hit::NewTab => None,
        }
    }

    fn on_mouse_move(&mut self, (x, y): (i32, i32), mods: Mods) {
        self.mouse.at = (x, y);
        let hover = self.strip_tab_at(x);
        if let Some(drag) = &mut self.drag {
            match drag {
                Drag::Divider { path, axis, span } => {
                    let ratio = match axis {
                        Axis::Row => (x - span.x) as f32 / span.w.max(1) as f32,
                        Axis::Column => (y - span.y) as f32 / span.h.max(1) as f32,
                    };
                    let path = path.clone();
                    let active = self.ws.active;
                    if let Some(tab) = self.ws.tabs.get_mut(active) {
                        tab.root.set_ratio(&path, ratio);
                    }
                    self.layout();
                }
                Drag::SideEdge => {
                    let min = scale(toolpane::MIN_SHOWN_DIP, self.dpi);
                    let to = toolpane::drag(x, &self.tools_input(), min);
                    self.side.width = to.width;
                    match (self.side.visible, to.open) {
                        (true, false) => {
                            // Opened again later, it shows whole.
                            self.side.shown = 0;
                            self.hide_side();
                        }
                        (false, true) => {
                            // Uncovering from the rail: the tool shown last
                            // (not the command palette, which opens alone).
                            self.side.shown = to.shown;
                            let view = match self.side.view {
                                SideView::Palette => SideView::Sessions,
                                v => v,
                            };
                            self.show_side(view, false);
                        }
                        _ => {
                            self.side.shown = to.shown;
                            self.layout();
                        }
                    }
                    self.update_menu_checks();
                }
                Drag::Tab { index, home, out } => {
                    let Some(s) = self.areas.strip else {
                        return;
                    };
                    let in_strip = y < s.bottom();
                    if *out && in_strip {
                        // Back over the strip: another tab shows that tab
                        // to drop into; the dragged one goes back to
                        // moving it along the strip.
                        match hover {
                            Some(i) if i != *index => {
                                let focus = self.ws.tabs.get(i).map(|t| t.focus);
                                if focus.is_some() && focus != *home {
                                    *home = focus;
                                    if let Some(f) = focus {
                                        self.ws.focus(f);
                                    }
                                    self.after_structure_change();
                                }
                            }
                            _ => {
                                *out = false;
                                if let Some(f) = self.ws.tabs.get(*index).map(|t| t.focus) {
                                    self.ws.focus(f);
                                }
                                self.after_structure_change();
                            }
                        }
                        self.request_full_redraw();
                        return;
                    }
                    let below = home.is_some() && !in_strip;
                    if below != *out {
                        // Show the tab to drop into, or the dragged one again.
                        *out = below;
                        let shown = if below {
                            *home
                        } else {
                            self.ws.tabs.get(*index).map(|t| t.focus)
                        };
                        if let Some(focus) = shown {
                            self.ws.focus(focus);
                        }
                        self.after_structure_change();
                        self.request_full_redraw();
                        return;
                    }
                    if *out {
                        self.request_full_redraw();
                        return;
                    }
                    let cpad = scale(CHROME_PADDING_DIP, self.dpi);
                    let col =
                        ((x - s.x - cpad).max(0) / self.strip_metrics.width.max(1) as i32) as usize;
                    let to = self.strip_layout.slot(col);
                    if to != *index {
                        let from = *index;
                        *index = to;
                        self.ws.move_tab(from, to);
                        self.refresh_chrome();
                        self.update_menu_checks();
                    }
                }
                Drag::Pane { id, start, active } => {
                    if !*active
                        && ((x - start.0).abs() > DRAG_START_PX
                            || (y - start.1).abs() > DRAG_START_PX)
                    {
                        *active = true;
                    }
                    if *active {
                        // Over a tab in the strip: show it, to drop the
                        // pane into one of its panes.
                        let id = *id;
                        let over_strip = self.areas.strip.is_some_and(|s| s.contains(x, y));
                        if let Some(i) = hover.filter(|_| over_strip)
                            && i != self.ws.active
                            && let Some(f) = self.ws.tabs.get(i).map(|t| t.focus)
                        {
                            let f = if self.ws.tab_of(id) == Some(i) { id } else { f };
                            self.ws.focus(f);
                            self.after_structure_change();
                        }
                        self.request_full_redraw();
                    }
                }
            }
            return;
        }
        // Motion goes to the pane holding the button, or the one under the
        // mouse for hover reports.
        let id = match self.mouse.pane {
            Some(id) => id,
            None => match self.spot(x, y) {
                Spot::Pane(id) => id,
                _ => return,
            },
        };
        let (col, row, right_half) = self.cell_at(id, x, y);
        let dpi = self.dpi;
        let Some(p) = self.panes.get_mut(&id) else {
            return;
        };
        let mut reply = None;
        if p.term.mouse_reporting() && self.mouse.last_cell != Some((col, row)) {
            self.mouse.last_cell = Some((col, row));
            let event = MouseEvent::Motion(self.mouse.reporting);
            reply = p.term.mouse(event, col, row, mods);
        }
        if self.mouse.selecting && self.mouse.pane == Some(id) {
            // Dragging past the top or bottom edge scrolls the history.
            let (_, oy) = p.origin(dpi);
            let bottom = oy + p.term.rows() as i32 * p.metrics.height as i32;
            if y < oy {
                p.term.scroll_lines(1);
            } else if y >= bottom {
                p.term.scroll_lines(-1);
            }
            p.term.select_update(col, row, right_half);
            self.refresh(id);
        }
        if let Some(bytes) = reply {
            self.send(id, bytes);
        }
    }

    /// A button event inside pane `id`.
    fn pane_button(
        &mut self,
        id: PaneId,
        button: MouseButton,
        down: bool,
        (x, y): (i32, i32),
        mods: Mods,
    ) -> Option<Command> {
        let (col, row, right_half) = self.cell_at(id, x, y);
        let copy_on_select = self.settings.copy_on_select;
        let right_click_paste = self.settings.right_click_paste;
        let hwnd = self.hwnd;
        let p = self.panes.get_mut(&id)?;
        if !down {
            capture(hwnd, false);
            if self.mouse.reporting == Some(button) {
                self.mouse.reporting = None;
                if let Some(bytes) = p.term.mouse(MouseEvent::Release(button), col, row, mods) {
                    self.send(id, bytes);
                }
                return None;
            }
            if button == MouseButton::Left
                && std::mem::take(&mut self.mouse.selecting)
                && copy_on_select
                && p.term.has_selection()
            {
                return Some(Command::Id(cmd::COPY));
            }
            return None;
        }

        capture(hwnd, true);
        // Shift-click always selects, even when the host wants the mouse.
        if p.term.mouse_reporting() && !mods.shift {
            let reply = p.term.mouse(MouseEvent::Press(button), col, row, mods);
            self.mouse.reporting = Some(button);
            self.mouse.last_cell = Some((col, row));
            if let Some(bytes) = reply {
                self.send(id, bytes);
            }
            return None;
        }
        match button {
            MouseButton::Left => {
                if mods.ctrl
                    && let Some(link) = p
                        .term
                        .link_at(col, row)
                        .or_else(|| p.term.text_link_at(col, row))
                {
                    return Some(Command::OpenLink(link));
                }
                // SAFETY: plain query.
                let double = Duration::from_millis(u64::from(unsafe { GetDoubleClickTime() }));
                let now = Instant::now();
                let count = match self.mouse.last_click {
                    Some((at, cell, n)) if now - at <= double && cell == (col, row) => n % 3 + 1,
                    _ => 1,
                };
                self.mouse.last_click = Some((now, (col, row), count));
                let kind = match count {
                    2 => SelectionKind::Word,
                    3 => SelectionKind::Line,
                    _ if mods.alt => SelectionKind::Block,
                    _ => SelectionKind::Simple,
                };
                p.term.select_start(col, row, right_half, kind);
                self.mouse.selecting = true;
                self.refresh(id);
            }
            MouseButton::Right if right_click_paste => {
                return Some(Command::Id(cmd::PASTE));
            }
            _ => {}
        }
        None
    }

    fn on_wheel(&mut self, delta: i16, screen: (i32, i32), mods: Mods) -> Option<Command> {
        let mut pt = POINT {
            x: screen.0,
            y: screen.1,
        };
        // SAFETY: our window and a local point.
        let _ = unsafe { ScreenToClient(self.hwnd, &mut pt) };
        self.mouse.wheel_rest += i32::from(delta);
        let lines = self.mouse.wheel_rest / WHEEL_PER_LINE;
        if lines == 0 {
            return None;
        }
        self.mouse.wheel_rest -= lines * WHEEL_PER_LINE;
        let id = match self.spot(pt.x, pt.y) {
            Spot::Side(..) => {
                if self.side.view == SideView::Forwards {
                    let view = self.forward_view();
                    let rows = self.side.grid.rows();
                    self.forwards_view.scroll_by(lines, &view, rows);
                } else if self.side.view == SideView::Live {
                    let all = self.open_sessions();
                    let rows = self.side.grid.rows();
                    self.live_view.scroll_by(lines, &all, rows);
                } else if self.side.view == SideView::Palette {
                    self.palette.scroll_by(lines, self.side.grid.rows());
                } else if self.side.view == SideView::Snippets {
                    let rows = self.side.grid.rows();
                    self.snippets_view
                        .scroll_by(lines, &self.settings.snippets, rows);
                } else if let Some(form) = &mut self.side.form {
                    form.scroll_by(lines, self.side.grid.rows());
                } else if let Some(view) = &mut self.side.import {
                    view.scroll_by(lines, self.side.grid.rows());
                } else {
                    let visible = SessionList::visible(self.side.grid.rows());
                    self.side.list.scroll_by(lines, visible);
                }
                self.refresh_chrome();
                return None;
            }
            Spot::Pane(id) => id,
            _ => self.focused_id(),
        };
        if mods.ctrl {
            self.focus_pane(id);
            let cmd = if delta > 0 {
                cmd::ZOOM_IN
            } else {
                cmd::ZOOM_OUT
            };
            return Some(Command::Id(cmd));
        }
        let (col, row, _) = self.cell_at(id, pt.x, pt.y);
        let reply = self
            .panes
            .get_mut(&id)
            .and_then(|p| p.term.wheel(lines, col, row, mods));
        if let Some(bytes) = reply {
            self.send(id, bytes);
        }
        self.refresh(id);
        None
    }

    /// Puts the IME's composition and candidate windows at the focused
    /// pane's cursor, in its font.
    fn place_ime(&self) {
        let Some(p) = self.panes.get(&self.focused_id()) else {
            return;
        };
        let Some(cursor) = p.cursor else {
            return;
        };
        let (ox, oy) = p.origin(self.dpi);
        let m = &p.metrics;
        let x = ox + cursor.x as i32 * m.width as i32;
        let y = oy + cursor.y as i32 * m.height as i32;
        let mut font = LOGFONTW {
            lfHeight: -(m.em_px.round() as i32),
            ..Default::default()
        };
        for (dst, src) in font
            .lfFaceName
            .iter_mut()
            .take(31)
            .zip(p.font.family.encode_utf16())
        {
            *dst = src;
        }
        // SAFETY: our window's input context, released below; the structs
        // are valid locals.
        unsafe {
            let himc = ImmGetContext(self.hwnd);
            if himc.is_invalid() {
                return;
            }
            let composition = COMPOSITIONFORM {
                dwStyle: CFS_POINT,
                ptCurrentPos: POINT { x, y },
                rcArea: RECT::default(),
            };
            let _ = ImmSetCompositionWindow(himc, &composition);
            let candidate = CANDIDATEFORM {
                dwIndex: 0,
                dwStyle: CFS_CANDIDATEPOS,
                ptCurrentPos: POINT {
                    x,
                    y: y + m.height as i32,
                },
                rcArea: RECT::default(),
            };
            let _ = ImmSetCandidateWindow(himc, &candidate);
            let _ = ImmSetCompositionFontW(himc, &font);
            let _ = ImmReleaseContext(self.hwnd, himc);
        }
    }

    /// Writes the settings; a failure is shown in the focused pane.
    fn save_settings(&mut self) {
        let _ = self.try_save_settings();
    }

    /// [`Self::save_settings`], with the failure also returned, for callers
    /// that must not go on without the settings saved.
    fn try_save_settings(&mut self) -> std::result::Result<(), String> {
        // Another FeroSSH window on this PC waits while this one reads,
        // merges and writes the settings, so neither drops what the other
        // added. (A file of its own, not the vault's lock, which the vault
        // takes itself for each read and write.)
        // With a vault open, the lock is named after the vault, so an
        // installed and a portable FeroSSH using the same vault wait for
        // each other too.
        let lock_on = crate::vault::path().map_or_else(settings_path, |v| {
            let mut name = v.into_os_string();
            name.push(".settings");
            std::path::PathBuf::from(name)
        });
        let Some(_lock) = crate::vault::lock_file(&lock_on) else {
            // Saving anyway could write over what the other window is
            // merging in; this window's settings stay as they are and the
            // next save tries again.
            let e = "Could not save settings: another FeroSSH window is \
                     saving them. Try again in a moment."
                .to_owned();
            let id = self.focused_id();
            self.show(id, &format!("\r\n\x1b[0;31m{e}\x1b[0m\r\n"));
            self.refresh(id);
            return Err(e);
        };
        let rules = self.settings.security_rules.clone();
        vault_ui::sync_settings(&mut self.settings);
        // Rules the merge brought in show at once: the next focus finds
        // nothing new to take in.
        if self.settings.security_rules != rules && self.rules_native() {
            rules_panel::set_rows(self.rule_rows());
        }
        // Window colours shown by a menu preview are not saved.
        let shown = self.settings.window_colours;
        if let Some(p) = self
            .look_preview
            .as_ref()
            .filter(|p| p.colours_by.is_some())
        {
            self.settings.window_colours = p.colours;
        }
        let text = self.settings.to_text();
        self.settings.window_colours = shown;
        let written = write_app_file(&settings_path(), &text);
        match written {
            Ok(()) => {
                vault_ui::note_settings(&text);
                Ok(())
            }
            Err(e) => {
                let e = format!(
                    "Could not save settings to {}: {e}",
                    settings_path().display()
                );
                let id = self.focused_id();
                self.show(id, &format!("\r\n\x1b[0;31m{e}\x1b[0m\r\n"));
                self.refresh(id);
                Err(e)
            }
        }
    }

    /// Saves a changed remote app clipboard setting and applies it at once
    /// to every remote app running (each still within its connection's
    /// limit).
    fn apply_app_clipboard(&mut self) {
        self.save_settings();
        self.update_menu_checks();
        let running = ferostream_client::win32::sessions();
        self.app_clip_limits.retain(|id, _| running.contains(id));
        for (&id, limit) in &self.app_clip_limits {
            ferostream_client::win32::set_clipboard(
                id,
                crate::stream::app_clipboard(&self.settings, limit.as_deref()),
            );
        }
    }

    /// Runs a menu command that needs no call back into the window.
    fn command(&mut self, id: u32) -> Option<Command> {
        // A live preview ends: the chosen item's part stays (menus that
        // return their choice send no WM_COMMAND).
        self.end_look_preview(Some(id));
        let pane = self.focused_id();
        if let Some(why) = self.look_refused(pane, id) {
            return Some(Command::Notice(why));
        }
        match id {
            cmd::EXIT => return Some(Command::Exit),
            cmd::CLOSE_TAB => return Some(Command::CloseTab(self.ws.active)),
            cmd::RENAME => self.start_rename(pane),
            cmd::WORKSPACE_SAVE => return Some(Command::SaveWorkspace),
            cmd::WORKSPACE_BROWSE => return Some(Command::OpenWorkspaceFile),
            cmd::WORKSPACE_FOLDER => return Some(Command::OpenFolder(workspaces_dir())),
            cmd::WORKSPACE_AUTO_LOGIN => {
                self.settings.workspace_auto_login = !self.settings.workspace_auto_login;
                self.save_settings();
                self.update_menu_checks();
                if self.settings.workspace_auto_login {
                    return Some(Command::Notice(
                        "Panes a workspace opens now log in by themselves: a connection \
                         that asks for its password asks once, and FeroSSH keeps the \
                         password once the login works (in the vault when you use a \
                         master password, else in the Windows Credential Manager). \
                         It applies from the next workspace you open."
                            .into(),
                    ));
                }
            }
            cmd::WORKSPACE_RESTORE => {
                self.settings.restore_layout = !self.settings.restore_layout;
                self.save_settings();
                self.update_menu_checks();
                if !self.settings.restore_layout && self.layout_owner {
                    let _ = std::fs::remove_file(last_layout_path());
                }
            }
            id if (cmd::RECENT..cmd::RECENT_END).contains(&id) => {
                let dest = self
                    .settings
                    .recent
                    .get((id - cmd::RECENT) as usize)
                    .cloned()?;
                self.open_host(&dest, false);
            }
            cmd::RECENT_CLEAR => {
                self.settings.recent.clear();
                self.save_settings();
            }
            id if (cmd::WORKSPACE_OPEN..cmd::WORKSPACE_END).contains(&id) => {
                let name = self
                    .workspace_names
                    .get((id - cmd::WORKSPACE_OPEN) as usize)
                    .cloned()?;
                return self.open_workspace_named(&name);
            }
            cmd::STANDBY_STATUS => {
                let what = self.standby_what();
                return Some(Command::Notice(
                    self.standby
                        .details(&hotkey_label(self.standby_key()), &what),
                ));
            }
            cmd::STANDBY_TOGGLE => {
                if self.standby.held.is_some() {
                    self.settings.standby = false;
                    self.restore_hidden();
                    self.save_settings();
                    self.apply_standby();
                } else {
                    return Some(self.standby_on(None));
                }
            }
            cmd::STANDBY_PICK => return Some(Command::PickStandbyHotkey),
            cmd::STANDBY_OWN => {
                self.restore_hidden();
                self.settings.standby_target = None;
                self.standby.target = None;
                return Some(self.standby_on(None));
            }
            id if (cmd::STANDBY_TARGET..cmd::STANDBY_TARGET + standby::MAX_CANDIDATES as u32)
                .contains(&id) =>
            {
                let picked = self
                    .standby
                    .candidates
                    .get((id - cmd::STANDBY_TARGET) as usize)
                    .cloned()?;
                self.restore_hidden();
                self.settings.standby_target = Some(picked.exe);
                self.standby.target = Some(picked.hwnd);
                return Some(self.standby_on(None));
            }
            id if (cmd::STANDBY_PRESET..cmd::STANDBY_PRESET + STANDBY_PRESETS as u32)
                .contains(&id) =>
            {
                let key = standby_presets()
                    .get((id - cmd::STANDBY_PRESET) as usize)
                    .copied();
                return Some(self.standby_on(key));
            }
            cmd::HIDE_MENU => return Some(Command::SetMenuVisible(!self.menu_visible)),
            cmd::FULL_SCREEN => return Some(Command::FullScreen),
            cmd::KEY_BINDINGS => return Some(Command::KeyBindings),
            id if (cmd::OPEN_LINKS..cmd::OPEN_LINKS + crate::url_handler::SCHEMES.len() as u32)
                .contains(&id) =>
            {
                let scheme = crate::url_handler::SCHEMES
                    .get((id - cmd::OPEN_LINKS) as usize)
                    .copied()
                    .unwrap_or("ssh");
                let text = if crate::url_handler::registered(scheme) {
                    crate::url_handler::unregister(scheme);
                    None
                } else {
                    match crate::url_handler::register(scheme) {
                        Ok(crate::url_handler::Registered::Done) => None,
                        Ok(crate::url_handler::Registered::ChooseInSettings(other)) => {
                            Some(format!(
                                "Another program opens {scheme}:// links{}. FeroSSH is now one of \
                             the programs that can: to pick it, open Windows Settings > Apps > \
                             Default apps, search for {upper}, and choose FeroSSH.",
                                other
                                    .map(|c| format!(" ({})", crate::ssh::sanitize_line(&c)))
                                    .unwrap_or_default(),
                                upper = scheme.to_ascii_uppercase(),
                            ))
                        }
                        Err(e) => Some(e),
                    }
                };
                self.update_menu_checks();
                if let Some(text) = text {
                    return Some(Command::Message(text));
                }
            }
            cmd::FULL_SCREEN_KEY => {
                self.settings.full_screen_key = !self.settings.full_screen_key;
                self.save_settings();
                self.update_menu_checks();
            }
            cmd::CONNECTION_LOG_DELETE => {
                self.settings.connection_log_delete = !self.settings.connection_log_delete;
                self.save_settings();
                self.update_menu_checks();
                if self.inventory_native() {
                    // Delete... shows or goes.
                    self.reload_inventory();
                    self.refresh_chrome();
                }
            }
            cmd::FONT_LIGATURES => {
                self.settings.font_ligatures = !self.settings.font_ligatures;
                self.save_settings();
                self.update_menu_checks();
                self.request_full_redraw();
            }
            cmd::COPY => return Some(Command::Copy),
            cmd::PASTE => return Some(Command::Paste),
            cmd::RECORD_SNIPPET => return self.toggle_recording(),
            cmd::AUTO_RESPONSES => {
                self.settings.auto_responses = !self.settings.auto_responses;
                self.watches.clear();
                self.save_settings();
                self.update_menu_checks();
            }
            cmd::CONFIRM_PRODUCTION => {
                self.settings.confirm_production = !self.settings.confirm_production;
                self.save_settings();
                self.update_menu_checks();
            }
            cmd::TMUX_KEYS => {
                let on = !self.settings.tmux_keys;
                self.settings.tmux_keys = on;
                self.tmux_armed = None;
                self.tmux_repeat = None;
                self.save_settings();
                self.update_menu_checks();
                let gateways: Vec<PaneId> = self.tmux.keys().copied().collect();
                for g in gateways {
                    if let Some(t) = self.tmux.get_mut(&g) {
                        let actions = t.want_keys(on);
                        self.run_tmux(g, actions);
                    }
                }
                if on && !self.tmux.values().any(Tmux::active) {
                    return Some(Command::Notice(
                        "tmux keybindings work in panes of a tmux session: Session > tmux > Attach \
                         tmux starts one. Then press the tmux prefix (Ctrl+B unless tmux is set \
                         up with another) and c, %, \", n, p, o, x, d or another window or pane \
                         key; the prefix and ? lists them."
                            .into(),
                    ));
                }
            }
            cmd::SAVE_SNIPPET => {
                let text = self
                    .panes
                    .get_mut(&pane)
                    .and_then(|p| p.term.selection_text())
                    .filter(|t| !t.trim().is_empty());
                let Some(text) = text else {
                    return Some(Command::Notice(
                        "Select the text for the script in a pane first, then use Edit > Save \
                         selection as script."
                            .into(),
                    ));
                };
                self.snippets_view.new_from(&text);
                self.show_side(SideView::Snippets, true);
                self.snippets_peek = false;
                self.refresh_chrome();
            }
            cmd::REPLACE_KEY => return Some(Command::ReplaceHostKey),
            cmd::NEW_KEY => return Some(Command::NewKey),
            cmd::EXPORT
            | cmd::IMPORT_SEALED
            | cmd::VAULT_SET
            | cmd::VAULT_USE
            | cmd::VAULT_MOVE
            | cmd::VAULT_CHANGE
            | cmd::VAULT_REMOVE => return Some(Command::Vault(id)),
            cmd::COPY_ID => {
                return Some(match self.key_host(pane) {
                    Some(host) => Command::CopyKey { pane, host },
                    None => Command::Notice(NO_COPY_HOST.into()),
                });
            }
            cmd::IMPORT => return Some(Command::ImportSessions),
            cmd::IMPORT_SNIPPETS => return Some(Command::ImportSnippets),
            cmd::SNIPPET_FOLDER => return Some(Command::OpenFolder(snippets_dir())),
            cmd::WRITE_LIBRARY => return Some(Command::WriteLibrary),
            cmd::LOCAL_SHELL => self.local_shell_in_new_tab(pane),
            cmd::CONNECT => self.connect_in_new_tab(pane),
            cmd::RECONNECT => {
                let pane = self.host_pane(pane);
                if self.retries.get(&pane).is_some_and(Retry::waiting) {
                    self.retry_now(pane);
                } else {
                    self.reconnect(pane);
                }
            }
            cmd::AUTO_RECONNECT => self.toggle_auto_reconnect(),
            cmd::NEW_TAB => {
                // A tmux pane's new tab is a new tmux window.
                if let Some(gateway) = self.panes.get(&pane).and_then(Pane::gateway) {
                    let actions = self
                        .tmux
                        .get_mut(&gateway)
                        .map(|t| t.new_tab(pane))
                        .unwrap_or_default();
                    self.run_tmux(gateway, actions);
                    return None;
                }
                let id = self.new_tab_pane();
                self.fill_like(id, pane);
            }
            cmd::SPLIT_RIGHT | cmd::SPLIT_DOWN => {
                let dir = if id == cmd::SPLIT_RIGHT {
                    Dir::Right
                } else {
                    Dir::Down
                };
                if let Some(gateway) = self.panes.get(&pane).and_then(Pane::gateway) {
                    // tmux knows each pane's directory itself.
                    let actions = self
                        .tmux
                        .get_mut(&gateway)
                        .map(|t| t.split(pane, dir))
                        .unwrap_or_default();
                    self.run_tmux(gateway, actions);
                    return None;
                }
                if let Some(new) = self.split(dir) {
                    self.fill_like(new, pane);
                }
            }
            cmd::CLOSE_PANE => return self.close_pane(pane),
            cmd::PANE_TO_TAB => {
                if !self.locked(pane) && self.ws.pane_to_tab(pane) {
                    self.after_structure_change();
                }
            }
            cmd::HIDE_PANE => return self.hide_pane(pane),
            cmd::SHOW_HIDDEN => {
                if let Some(&last) = self.ws.hidden().last() {
                    self.show_hidden(last);
                }
            }
            cmd::JOIN_TAB => {
                let next = if self.ws.active == 0 {
                    1
                } else {
                    self.ws.active - 1
                };
                if !self.locked_tab(self.ws.active)
                    && !self.locked_tab(next)
                    && self.ws.join_neighbour()
                {
                    self.after_structure_change();
                }
            }
            cmd::TMUX_ATTACH => {
                let host = self.host_pane(pane);
                if host != pane {
                    // Already in tmux: offer the other sessions.
                    let actions = self
                        .tmux
                        .get_mut(&host)
                        .map(Tmux::pick_session)
                        .unwrap_or_default();
                    self.run_tmux(host, actions);
                    return None;
                }
                let name = match self.panes.get(&pane).map(|p| &p.host) {
                    Some(Host::Ssh(s)) if s.state() == State::Connected && !s.prompt_active() => {
                        self.settings
                            .profile(&s.target.alias)
                            .and_then(|p| p.tmux.clone())
                            .unwrap_or_else(|| "main".to_owned())
                    }
                    _ => return Some(Command::Notice(NOT_IN_SHELL.into())),
                };
                let _ = self.attach_tmux(pane, &name, true);
            }
            cmd::TMUX_SHARE | cmd::TMUX_JOIN => {
                let gateway = self.host_pane(pane);
                if let Err(why) = self.tmux_ready(gateway) {
                    return Some(Command::Notice(why));
                }
                return Some(if id == cmd::TMUX_SHARE {
                    Command::TmuxShare(gateway)
                } else {
                    Command::TmuxJoin(gateway)
                });
            }
            cmd::TMUX_UNSHARE => {
                let host = self.host_pane(pane);
                let actions = self
                    .tmux
                    .get_mut(&host)
                    .map(Tmux::unshare)
                    .unwrap_or_default();
                self.run_tmux(host, actions);
            }
            cmd::DESKTOP => return self.open_desktop(pane, None),
            cmd::DESKTOP_TAB => return self.open_desktop(pane, Some(Protocol::Vnc)),
            cmd::DESKTOP_TAB_RDP => return self.open_desktop(pane, Some(Protocol::Rdp)),
            cmd::VDESK => return self.open_virtual_desktop(pane, None),
            cmd::VDESK_STOP => return self.stop_virtual_desktop(pane),
            cmd::REMOTE_APP => return self.pick_remote_app(pane),
            cmd::REMOTE_APP_ATTACH => {
                return self.run_remote_app(
                    pane,
                    None,
                    None,
                    ferostream_client::transport::AttachTo::Newest,
                );
            }
            cmd::REMOTE_APP_COPY => {
                self.settings.remote_app_copy_agent = !self.settings.remote_app_copy_agent;
                self.save_settings();
                self.update_menu_checks();
            }
            cmd::REMOTE_APP_REMOVE => {
                self.settings.remote_app_remove_agent = !self.settings.remote_app_remove_agent;
                self.save_settings();
                self.update_menu_checks();
            }
            cmd::REMOTE_APP_CLIP..=cmd::REMOTE_APP_CLIP_LAST => {
                let way = crate::stream::CLIPBOARD_WAYS
                    .get((id - cmd::REMOTE_APP_CLIP) as usize)
                    .copied()
                    .unwrap_or("off");
                // Unset means off, so every choice is written down.
                self.settings.remote_app_clipboard = Some(way.to_owned());
                self.apply_app_clipboard();
            }
            cmd::DESKTOP_CLIP..=cmd::DESKTOP_CLIP_LAST => {
                let way = ferossh_config::settings::CLIPBOARD_WAYS
                    .get((id - cmd::DESKTOP_CLIP) as usize)
                    .copied()
                    .unwrap_or("off");
                // Unset means off, so every choice is written down.
                self.settings.desktop_clipboard = Some(way.to_owned());
                self.apply_desktop_clipboard();
            }
            cmd::DESKTOP_SELECTION => {
                // Read when a virtual desktop starts.
                self.settings.desktop_share_selection = !self.settings.desktop_share_selection;
                self.save_settings();
                self.update_menu_checks();
            }
            cmd::REMOTE_APP_SELECTION => {
                self.settings.remote_app_share_selection =
                    !self.settings.remote_app_share_selection;
                self.apply_app_clipboard();
            }
            cmd::TMUX_DETACH | cmd::TMUX_DETACH_OTHERS | cmd::TMUX_PICK | cmd::TMUX_LAYOUT => {
                let host = self.host_pane(pane);
                let Some(t) = self.tmux.get_mut(&host).filter(|t| t.active()) else {
                    return Some(Command::Notice(
                        "This pane is not showing a tmux session. Session > tmux > Attach tmux \
                         starts one."
                            .into(),
                    ));
                };
                let actions = match id {
                    cmd::TMUX_DETACH => t.detach(),
                    cmd::TMUX_DETACH_OTHERS => t.detach_others(None),
                    cmd::TMUX_PICK => t.pick_session(),
                    _ => {
                        let mode = match t.mode() {
                            TmuxMode::Ferossh => TmuxMode::Tmux,
                            TmuxMode::Tmux => TmuxMode::Ferossh,
                        };
                        t.set_mode(mode)
                    }
                };
                self.run_tmux(host, actions);
                self.update_menu_checks();
            }
            cmd::NEXT_TAB | cmd::PREV_TAB => {
                let mut ws = self.ws.clone();
                ws.cycle_tab(id == cmd::NEXT_TAB);
                if let Some(t) = ws.tab() {
                    let focus = t.focus;
                    self.focus_pane(focus);
                }
            }
            cmd::TAB_LEFT | cmd::TAB_RIGHT => {
                let from = self.ws.active;
                let to = if id == cmd::TAB_LEFT {
                    from.checked_sub(1)
                } else {
                    Some(from + 1).filter(|&t| t < self.ws.tabs.len())
                };
                if let Some(to) = to {
                    self.ws.move_tab(from, to);
                    self.refresh_chrome();
                }
            }
            id if (cmd::FOCUS..cmd::FOCUS + 4).contains(&id) => {
                let dir = DIRS.get((id - cmd::FOCUS) as usize).copied()?;
                let g = gap(self.dpi);
                let next = self.ws.tab().and_then(|t| {
                    layout::neighbour(&t.root.layout(self.areas.panes, g), t.focus, dir)
                });
                if let Some(next) = next {
                    self.focus_pane(next);
                }
            }
            id if (cmd::RESIZE..cmd::RESIZE + 4).contains(&id) => {
                let dir = DIRS.get((id - cmd::RESIZE) as usize).copied()?;
                let active = self.ws.active;
                let changed = self
                    .ws
                    .tabs
                    .get_mut(active)
                    .is_some_and(|t| t.root.resize(t.focus, dir, RESIZE_STEP));
                if changed {
                    self.layout();
                }
            }
            id if is_side_pane(id) => self.toggle_side(id, false),
            cmd::PALETTE => self.toggle_palette(),
            cmd::RUN_SCRIPT => return self.rerun_script(self.focused_id()),
            cmd::SIDE_RIGHT => {
                self.settings.side_pane_right = !self.settings.side_pane_right;
                self.save_settings();
                self.update_menu_checks();
                self.layout();
            }
            cmd::TOOLS_RAIL => {
                self.settings.tools_rail = !self.settings.tools_rail;
                self.save_settings();
                self.update_menu_checks();
                self.layout();
            }
            id if (cmd::WINDOW_COLOURS..cmd::WINDOW_COLOURS + WindowColours::ALL.len() as u32)
                .contains(&id) =>
            {
                if let Some(c) = WindowColours::ALL.get((id - cmd::WINDOW_COLOURS) as usize) {
                    self.settings.window_colours = *c;
                    self.save_settings();
                    self.update_menu_checks();
                    self.refresh_chrome();
                    self.request_full_redraw();
                }
            }
            cmd::TOOLS_PIN => {
                self.settings.tools_pinned = !self.settings.tools_pinned;
                // Pinning means the pane stays by choice, not a peek.
                if self.settings.tools_pinned {
                    self.snippets_peek = false;
                }
                self.save_settings();
                self.update_menu_checks();
                self.refresh_chrome();
            }
            cmd::TAB_STRIP => {
                self.settings.tab_strip = !self.settings.tab_strip;
                self.save_settings();
                self.update_menu_checks();
                self.layout();
            }
            cmd::NOTIFY => {
                self.settings.notifications = !self.settings.notifications;
                self.save_settings();
                self.update_menu_checks();
                if !self.settings.notifications {
                    for p in self.panes.values_mut() {
                        p.attention = false;
                    }
                    // The icon goes, and with it any balloon still waiting.
                    self.toasts_lost();
                    self.refresh_chrome();
                    return Some(Command::HideToast);
                }
            }
            cmd::NOTIFY_BELL => {
                self.settings.notify_bell = !self.settings.notify_bell;
                self.save_settings();
                self.update_menu_checks();
            }
            cmd::NOTIFY_QUIET => self.toggle_quiet(pane),
            cmd::AGENT_DIFF => return self.show_changes(pane),
            cmd::AGENTS_SHOW => {
                self.show_side(SideView::Live, true);
                self.live_view.set_query(crate::live::AGENTS_ONLY);
                self.refresh_chrome();
            }
            id if (cmd::AGENT_START..cmd::AGENT_END).contains(&id) => {
                let i = (id - cmd::AGENT_START) as usize;
                let command = crate::agents::commands(&self.settings.agent_commands)
                    .get(i)
                    .cloned()?;
                return self.start_agent(pane, &command);
            }
            cmd::STATUS_BAR => {
                self.settings.status_bar = !self.settings.status_bar;
                self.save_settings();
                self.update_menu_checks();
                self.layout();
                self.refresh_status();
                self.request_full_redraw();
            }
            cmd::SAVE_LOOK => return Some(Command::SaveLook),
            cmd::START_DIR => return self.start_dir_here(pane),
            cmd::UPLOAD => {
                self.ensure_sftp(pane);
                let Some(key) = self.files_target(pane) else {
                    return Some(Command::Notice(NOT_CONNECTED.into()));
                };
                let listed = self.files_visible() && self.files_key.as_deref() == Some(&key);
                let dir = self.upload_dir(pane, listed);
                return Some(Command::PickUpload { key, dir });
            }
            cmd::DOWNLOADS => return Some(Command::OpenFolder(self.download_dir())),
            cmd::ZMODEM => {
                self.settings.zmodem = !self.settings.zmodem;
                self.save_settings();
                self.update_menu_checks();
            }
            cmd::INLINE_IMAGES => {
                self.settings.inline_images = !self.settings.inline_images;
                self.save_settings();
                self.update_menu_checks();
                let on = self.settings.inline_images;
                INLINE_IMAGES.set(on);
                let ids: Vec<PaneId> = self.panes.keys().copied().collect();
                for id in ids {
                    if let Some(p) = self.panes.get_mut(&id) {
                        p.term.set_images(on);
                    }
                    // Pictures on the screen go when images are turned off.
                    self.refresh(id);
                }
            }
            cmd::UPLOAD_TYPE_PATH => {
                self.settings.upload_type_path = !self.settings.upload_type_path;
                self.save_settings();
                self.update_menu_checks();
            }
            cmd::KITTY_KEYBOARD => {
                self.settings.kitty_keyboard = !self.settings.kitty_keyboard;
                self.save_settings();
                self.update_menu_checks();
                self.apply_keys();
            }
            cmd::SHIFT_ENTER => {
                self.settings.shift_enter = if self.settings.shift_enter == ShiftEnterKey::Enter {
                    ShiftEnterKey::EscCr
                } else {
                    ShiftEnterKey::Enter
                };
                self.save_settings();
                self.update_menu_checks();
                self.apply_keys();
            }
            cmd::ANSWER_TOASTS => {
                self.settings.answer_from_notification = !self.settings.answer_from_notification;
                self.save_settings();
                self.update_menu_checks();
            }
            cmd::AGENT_AUDIT => {
                self.settings.agent_audit = !self.settings.agent_audit;
                self.save_settings();
                if self.settings.agent_audit {
                    // The agents running now are kept from here on.
                    let agents: Vec<PaneId> = self
                        .panes
                        .keys()
                        .copied()
                        .filter(|id| self.agent_of(*id).is_some())
                        .collect();
                    for id in agents {
                        self.audit_agent(id);
                    }
                }
                self.update_menu_checks();
            }
            cmd::PORT_PREVIEWS => {
                self.settings.port_previews = !self.settings.port_previews;
                self.save_settings();
                self.update_menu_checks();
                if !self.settings.port_previews {
                    self.preview_scans.clear();
                    let shown: Vec<PaneId> = self.previews.keys().copied().collect();
                    for id in shown {
                        self.drop_preview(id, false);
                    }
                }
            }
            cmd::VERIFY => {
                self.settings.verify_transfers = !self.settings.verify_transfers;
                for remote in self.sftp.values_mut() {
                    remote.verify = self.settings.verify_transfers;
                }
                self.save_settings();
                self.update_menu_checks();
                self.refresh_chrome();
            }
            cmd::FOLLOW_CD => self.toggle_follow(),
            cmd::DISCONNECT => {
                self.disconnect(pane, "[Disconnected. Press Enter to reconnect.]");
            }
            cmd::LOG_TOGGLE => {
                let p = self.panes.get_mut(&pane)?;
                let live = match &p.host {
                    Host::Ssh(s) => matches!(s.state(), State::Connecting | State::Connected),
                    Host::Telnet(s) => matches!(s.state(), State::Connecting | State::Connected),
                    Host::Winrm(s) => matches!(s.state(), State::Connecting | State::Connected),
                    Host::Tmux { .. } => true,
                    _ => false,
                };
                if p.log.enabled && p.policy.log_session && live {
                    self.show(
                        pane,
                        "\x1b[0;90mA security rule keeps this session's log on.\x1b[0m\r\n",
                    );
                    return None;
                }
                p.log.enabled = !p.log.enabled;
                // A choice made while no session is live is the user's
                // own: no rule's saved setting may undo it later.
                if !live {
                    p.log.before_rule = None;
                }
                if p.log.enabled {
                    self.start_log(pane);
                } else {
                    let path = p.log.path.clone();
                    self.stop_log(pane);
                    if let Some(path) = path {
                        let text = format!("\x1b[0;90mLog saved to {}\x1b[0m\r\n", path.display());
                        self.show(pane, &text);
                    }
                }
                self.update_menu_checks();
                self.refresh(pane);
            }
            cmd::LOG_RAW => {
                // Takes effect for the next log file.
                let p = self.panes.get_mut(&pane)?;
                p.log.raw = !p.log.raw;
                self.update_menu_checks();
            }
            cmd::LOG_TIMESTAMPS => {
                // For every plain log, the open ones too, from the next line.
                self.settings.log_timestamps = !self.settings.log_timestamps;
                let stamps = self
                    .settings
                    .log_timestamps
                    .then_some(log_line_time as Clock);
                for p in self.panes.values_mut() {
                    if let Some(w) = &mut p.log.writer {
                        w.set_timestamps(stamps);
                    }
                }
                self.save_settings();
                self.update_menu_checks();
            }
            cmd::SAVE_PANE => return Some(Command::Message(self.save_output(&[pane]))),
            cmd::SAVE_ALL => {
                let panes: Vec<PaneId> = self.ws.tabs.iter().flat_map(|t| t.root.panes()).collect();
                return Some(Command::Message(self.save_output(&panes)));
            }
            cmd::LOG_FOLDER => return Some(Command::OpenFolder(log_dir())),
            cmd::LOG_VERIFY => return Some(Command::VerifyLog),
            cmd::RECORD_CAST => self.toggle_record(pane),
            cmd::PLAY_CAST => return Some(Command::PlayCast),
            cmd::SERIAL_BREAK => {
                let pane = self.focused_id();
                match self.panes.get(&pane).map(|p| &p.host) {
                    Some(Host::Serial {
                        port: Some(port), ..
                    }) => {
                        port.send_break();
                        self.show(pane, "\x1b[0;90m[break]\x1b[0m");
                    }
                    _ => {
                        return Some(Command::Notice(
                            "Send break is for serial consoles: open a COM port first \
                             (type COM3 at the connect prompt, or make a Serial console \
                             session)."
                                .into(),
                        ));
                    }
                }
            }
            cmd::BROADCAST_TAB | cmd::BROADCAST_ALL => {
                let wanted = if id == cmd::BROADCAST_TAB {
                    broadcast::Scope::Tab
                } else {
                    broadcast::Scope::All
                };
                self.broadcast = self.broadcast.toggle(wanted);
                self.update_menu_checks();
                self.update_title();
                self.refresh_chrome();
            }
            cmd::BROADCAST_SKIP => {
                let pane = self.focused_id();
                if let Some(p) = self.panes.get_mut(&pane) {
                    p.no_broadcast = !p.no_broadcast;
                }
                self.update_menu_checks();
                self.refresh_chrome();
            }
            cmd::ZOOM_IN | cmd::ZOOM_OUT | cmd::ZOOM_RESET => {
                let font = self.panes.get(&pane)?.font.clone();
                let font = match id {
                    cmd::ZOOM_IN => font.zoomed(1),
                    cmd::ZOOM_OUT => font.zoomed(-1),
                    _ => FontSpec::new(&font.family, FontSpec::DEFAULT_PT),
                };
                self.set_font(pane, font);
            }
            cmd::TEST_PATTERN => {
                let p = self.panes.get_mut(&pane)?;
                p.term.scroll_to_bottom();
                p.term.feed(pattern::test_pattern().as_bytes());
                // The pattern asks for nothing, but commands queued
                // before (an agent question, say) must not be lost.
                let commands = self.after_feed();
                self.queued.extend(commands);
            }
            cmd::FIND => {
                self.panes.get_mut(&pane)?.term.search_open();
                self.refresh(pane);
            }
            cmd::STOP_AT => {
                self.panes.get_mut(&pane)?.term.stop_bar_open();
                self.refresh(pane);
            }
            cmd::HIGHLIGHT => self.toggle_highlight(),
            cmd::CLEAR_SCROLLBACK => {
                self.panes.get_mut(&pane)?.term.clear_scrollback();
                self.refresh(pane);
            }
            cmd::UPDATE_CHECK => {
                if ferossh_update::public_key().is_none() {
                    return Some(Command::Message(
                        "This build of FeroSSH cannot check for updates: it was built without \
                         the project's update key. Releases are listed at \
                         https://github.com/jkobierczynski/FeroSSH/releases."
                            .into(),
                    ));
                }
                self.start_update_check(true);
            }
            cmd::UPDATE_WEEKLY => {
                self.settings.update_check_weekly = !self.settings.update_check_weekly;
                self.save_settings();
                self.update_menu_checks();
            }
            cmd::ABOUT => {
                return Some(Command::Message(format!(
                    "FeroSSH {}\n\nSecure connections. Forged in Rust.\n\n\
                     https://github.com/jkobierczynski/FeroSSH\n\n\
                     Dual licensed under MIT or Apache-2.0.",
                    env!("CARGO_PKG_VERSION")
                )));
            }
            cmd::COPY_ON_SELECT => {
                self.settings.copy_on_select = !self.settings.copy_on_select;
                self.save_settings();
                self.update_menu_checks();
            }
            cmd::RIGHT_CLICK_PASTE => {
                self.settings.right_click_paste = !self.settings.right_click_paste;
                self.save_settings();
                self.update_menu_checks();
            }
            cmd::ESCAPES => {
                // Off keeps the character (`EscapeChar %` stays `%`).
                let on = !self.settings.escapes;
                self.settings.escapes = on;
                if on && self.settings.escape_char == EscapeChar::None {
                    self.settings.escape_char = EscapeChar::DEFAULT;
                }
                if !on {
                    // Drop every pane's open `ssh>` line and held escape
                    // character now, so a paste is not swallowed and a
                    // held `~` cannot come back to life if escapes are
                    // turned on again before the next key.
                    for p in self.panes.values_mut() {
                        p.escapes.cancel();
                    }
                }
                self.save_settings();
                self.update_menu_checks();
            }
            cmd::SUGGEST => {
                let on = !self.settings.command_suggestions;
                self.settings.command_suggestions = on;
                self.save_settings();
                self.update_menu_checks();
                if !on {
                    // Nothing typed from here on is read or kept.
                    self.ghost = None;
                    self.histories.clear();
                    for p in self.panes.values_mut() {
                        p.typing.reset();
                    }
                }
                self.refresh(pane);
                if on {
                    return Some(Command::Notice(
                        "Earlier commands on this host, and a few common ones, now show greyed \
                         after the cursor as you type. Right arrow, End, Ctrl+E or Ctrl+F types \
                         the rest, Ctrl+Right its next word, Ctrl+Up and Ctrl+Down show other \
                         matches, and Shift+Delete forgets the one shown (Settings > Key bindings \
                         changes these keys). Commands are kept per host, \
                         encrypted with your Windows sign-in, on this PC only; nothing typed at a \
                         password prompt is kept, nor lines that start with a space."
                            .into(),
                    ));
                }
            }
            cmd::CLEAR_HISTORY => {
                let Some(key) = self.history_key(pane) else {
                    return Some(Command::Notice(
                        "This pane has no host with a command history.".into(),
                    ));
                };
                self.histories.remove(&key);
                // A pane out of sight may hold a command Enter ran that is
                // not kept yet: it would bring the history back.
                let same: Vec<PaneId> = self
                    .panes
                    .keys()
                    .copied()
                    .filter(|p| self.history_key(*p).as_deref() == Some(key.as_str()))
                    .collect();
                for p in same {
                    if let Some(p) = self.panes.get_mut(&p) {
                        p.typing.reset();
                    }
                }
                #[cfg(windows)]
                crate::history_store::clear(&key);
                self.ghost = None;
                self.refresh(pane);
            }
            cmd::CLEAR_ALL_HISTORY => {
                return Some(Command::Confirm {
                    text: "Clear the command history of every host?".into(),
                    then: Box::new(Command::ClearAllHistory),
                });
            }
            cmd::SCROLL_PAGE_UP | cmd::SCROLL_PAGE_DOWN | cmd::SCROLL_TOP | cmd::SCROLL_BOTTOM => {
                let term = &mut self.panes.get_mut(&pane)?.term;
                match id {
                    cmd::SCROLL_PAGE_UP => term.scroll_pages(1),
                    cmd::SCROLL_PAGE_DOWN => term.scroll_pages(-1),
                    cmd::SCROLL_TOP => term.scroll_to_top(),
                    _ => term.scroll_to_bottom(),
                }
                self.refresh(pane);
            }
            id if (cmd::FONT..cmd::FONT + FONT_CHOICES.len() as u32).contains(&id) => {
                if let Some(family) = FONT_CHOICES.get((id - cmd::FONT) as usize) {
                    if !self.renderer.has_family(family)
                        && let Some(url) = font_page(family)
                    {
                        return Some(Command::FontPage { family, url });
                    }
                    let size = self.panes.get(&pane)?.font.size_pt;
                    self.set_font(pane, FontSpec::new(family, size));
                }
            }
            id if (cmd::THEME..cmd::THEME + Theme::builtin().len() as u32).contains(&id) => {
                if let Some(theme) = Theme::builtin().get((id - cmd::THEME) as usize) {
                    self.set_theme(pane, theme.clone());
                    // A tmux pane's theme is kept in the session.
                    self.sync_tmux();
                    self.refresh_chrome();
                    self.request_full_redraw();
                }
            }
            id if self.custom_at(id).is_some() => return self.use_custom_theme(pane, id),
            cmd::SAVE_THEME => return Some(Command::SaveTheme),
            cmd::THEMES_FOLDER => {
                let dir = themes_dir();
                let _ = std::fs::create_dir_all(&dir);
                return Some(Command::OpenFolder(dir));
            }
            _ => {}
        }
        None
    }

    /// Changes a pane's font; the window keeps its size and the grid gains
    /// or loses cells right away, so a shell started next (the pty-req of
    /// a new connection) gets the rows and columns that fit.
    fn set_font(&mut self, id: PaneId, font: FontSpec) {
        // An enforced theme rule's font and size stay.
        let font = match self.panes.get(&id) {
            Some(p) => p.lock.font(font),
            None => font,
        };
        let Ok(metrics) = self.renderer.metrics(&font, self.dpi) else {
            return;
        };
        if let Some(p) = self.panes.get_mut(&id) {
            p.font = font;
            p.metrics = metrics;
        }
        self.layout();
        self.update_menu_checks();
    }

    fn set_theme(&mut self, id: PaneId, theme: Theme) {
        if let Some(p) = self.panes.get_mut(&id) {
            // An enforced theme rule's theme stays.
            let theme = p.lock.theme(theme);
            p.term.set_theme(&theme);
            p.theme = theme;
        }
        self.update_menu_checks();
    }

    /// A previewed theme: drawn on the pane, while the terminal keeps
    /// answering colour queries with the committed one.
    fn show_theme(&mut self, id: PaneId, theme: Theme) {
        if let Some(p) = self.panes.get_mut(&id) {
            p.theme = p.lock.theme(theme);
        }
        self.update_menu_checks();
    }

    /// The pane's theme as picked, not as a menu preview shows it.
    fn committed_theme(&self, id: PaneId) -> Option<Theme> {
        match &self.look_preview {
            Some(p) if p.pane == id && p.theme_by.is_some() => Some(p.theme.clone()),
            _ => self.panes.get(&id).map(|p| p.theme.clone()),
        }
    }

    /// A host's font and theme (`look::for_host`), with a custom theme's
    /// own font and size where neither the connection nor a theme rule
    /// sets one.
    fn host_look(&self, alias: &str, hostname: &str, tag: Option<&str>) -> (FontSpec, Theme) {
        let (mut font, theme) = look::for_host(
            &self.settings,
            alias,
            hostname,
            tag,
            &self.default_font,
            &self.default_theme,
        );
        if let Some(c) = self.custom_named(theme.name) {
            // The connection's own font, then a theme rule's, then the
            // custom theme's.
            let (own, own_size) = look::own_font(&self.settings, alias, hostname, tag);
            let family = own
                .or_else(|| c.font.clone())
                .unwrap_or_else(|| font.family.clone());
            let size = own_size.or(c.size).unwrap_or(font.size_pt);
            if self.renderer.has_family(&family) {
                font = FontSpec::new(&family, size);
            }
        }
        (font, theme)
    }

    /// Why menu item `id` may not change pane `pane`'s look: an enforced
    /// theme rule fixes the theme (Settings > Theme, a custom theme), the
    /// font (Settings > Font) or the size (zoom).
    fn look_refused(&self, pane: PaneId, id: u32) -> Option<String> {
        let lock = &self.panes.get(&pane)?.lock;
        let theme = (cmd::THEME..cmd::THEME + Theme::builtin().len() as u32).contains(&id)
            || self.custom_at(id).is_some();
        let family = (cmd::FONT..cmd::FONT + FONT_CHOICES.len() as u32).contains(&id);
        let size = matches!(id, cmd::ZOOM_IN | cmd::ZOOM_OUT | cmd::ZOOM_RESET);
        let refused = (theme && lock.theme.is_some())
            || (family && lock.font.is_some())
            || (size && lock.size.is_some());
        refused.then(|| lock.why())
    }

    /// The custom theme behind menu id `id`, by its place in the list.
    fn custom_at(&self, id: u32) -> Option<&CustomTheme> {
        let first = cmd::THEME + Theme::builtin().len() as u32;
        let i = id.checked_sub(first)?;
        if i as usize >= custom_theme::MAX {
            return None;
        }
        self.custom_themes.get(i as usize)
    }

    /// The custom theme named `name`, if it is one.
    fn custom_named(&self, name: &str) -> Option<&CustomTheme> {
        self.custom_themes.iter().find(|c| c.theme.name == name)
    }

    /// Whether menu id `id` picks a font, a theme or window colours: the
    /// items a menu shows live while the mouse is on them.
    fn is_look_item(&self, id: u32) -> bool {
        // Fonts are not previewed: a new font size would resize the
        // remote terminal while the mouse only passes over it.
        let themes = cmd::THEME..cmd::THEME + Theme::builtin().len() as u32;
        let colours = cmd::WINDOW_COLOURS..cmd::WINDOW_COLOURS + WindowColours::ALL.len() as u32;
        themes.contains(&id) || colours.contains(&id) || self.custom_at(id).is_some()
    }

    /// `WM_MENUSELECT`: the menu item under the mouse (or keyboard) is
    /// `id`; a look item shows once it stays there a moment.
    fn menu_hover(&mut self, id: Option<u32>) {
        let id = id.filter(|id| self.is_look_item(*id));
        let Some(id) = id else {
            if let Some(p) = &mut self.look_preview {
                p.pending = None;
            }
            // SAFETY: our window's timer.
            unsafe {
                let _ = KillTimer(Some(self.hwnd), TIMER_LOOK);
            }
            return;
        };
        if self.look_preview.is_none() {
            let pane = self.focused_id();
            let Some(p) = self.panes.get(&pane) else {
                return;
            };
            self.look_preview = Some(LookPreview {
                pane,
                theme: p.theme.clone(),
                colours: self.settings.window_colours,
                pending: None,
                theme_by: None,
                colours_by: None,
                theme_shown: None,
            });
        }
        if let Some(p) = &mut self.look_preview {
            p.pending = Some(id);
        }
        // SAFETY: our window; replaces any earlier timer with this id.
        unsafe {
            SetTimer(Some(self.hwnd), TIMER_LOOK, LOOK_DELAY_MS, None);
            // A preview put back by a closing menu waits no longer.
            let _ = KillTimer(Some(self.hwnd), TIMER_LOOK_END);
        }
    }

    /// `TIMER_LOOK`: shows the item the mouse stayed on.
    fn show_look(&mut self) {
        // SAFETY: our window's timer.
        unsafe {
            let _ = KillTimer(Some(self.hwnd), TIMER_LOOK);
        }
        let Some(p) = self.look_preview.as_mut() else {
            return;
        };
        let Some(id) = p.pending.take() else {
            return;
        };
        let pane = p.pane;
        // A look changed from elsewhere meanwhile (a reconnect applying the
        // host's look) becomes what a cancelled preview goes back to.
        if let Some(now) = self.panes.get(&pane) {
            let expected_theme = p.theme_shown.as_ref().unwrap_or(&p.theme);
            if now.theme != *expected_theme {
                p.theme = now.theme.clone();
                p.theme_by = None;
                p.theme_shown = None;
            }
        }
        let committed = (p.theme.name, p.theme.group() == ThemeGroup::Warning);
        let (mut theme, mut colours) = (None, None);
        if let Some(t) = id
            .checked_sub(cmd::THEME)
            .and_then(|i| Theme::builtin().get(i as usize))
        {
            theme = Some(t.clone());
        } else if let Some(c) = id
            .checked_sub(cmd::WINDOW_COLOURS)
            .and_then(|i| WindowColours::ALL.get(i as usize))
            .filter(|_| id < cmd::FONT)
        {
            colours = Some(*c);
        } else if let Some(c) = self.custom_at(id) {
            theme = Some(c.theme.clone());
            colours = match c.window {
                Some(custom_theme::WindowSpec::Look(l)) => Some(l),
                Some(custom_theme::WindowSpec::Colours(..)) => Some(WindowColours::Theme),
                None => None,
            };
        }
        // Parts that an item shown before set, and this one does not, go
        // back: the preview shows the item under the mouse only.
        let (theme_back, colours_back) = match &self.look_preview {
            Some(p) => (
                (theme.is_none() && p.theme_by.is_some()).then(|| p.theme.clone()),
                (colours.is_none() && p.colours_by.is_some()).then_some(p.colours),
            ),
            None => (None, None),
        };
        {
            if let Some(t) = theme_back {
                self.set_theme(pane, t);
                if let Some(p) = &mut self.look_preview {
                    p.theme_by = None;
                }
            }
            if let Some(c) = colours_back {
                self.settings.window_colours = c;
                if let Some(p) = &mut self.look_preview {
                    p.colours_by = None;
                }
            }
        }
        if let Some(mut t) = theme {
            // A preview over Production or Staging, or of Production or
            // Staging, shows only colours: the pane keeps its committed
            // theme's name, which confirmations check, until a theme is
            // picked.
            if committed.1 || t.group() == ThemeGroup::Warning {
                t.name = committed.0;
            }
            self.show_theme(pane, t.clone());
            if let Some(p) = &mut self.look_preview {
                p.theme_by = Some(id);
                p.theme_shown = Some(t);
            }
        }
        if let Some(c) = colours {
            self.settings.window_colours = c;
            if let Some(p) = &mut self.look_preview {
                p.colours_by = Some(id);
            }
        }
        self.refresh_chrome();
        self.request_full_redraw();
    }

    /// Ends a live preview: puts back each part the chosen item `chosen`
    /// (none: the menu closed without a choice) does not show.
    fn end_look_preview(&mut self, chosen: Option<u32>) {
        // SAFETY: our window's timers.
        unsafe {
            let _ = KillTimer(Some(self.hwnd), TIMER_LOOK);
            let _ = KillTimer(Some(self.hwnd), TIMER_LOOK_END);
        }
        let Some(p) = self.look_preview.take() else {
            return;
        };
        // A choice applies to the focused pane: a preview on another one
        // (focus moved meanwhile) goes back.
        // A pick an enforced theme rule refuses is no choice: what the
        // preview showed goes back (window colours included).
        let chosen = chosen
            .filter(|_| self.focused_id() == p.pane)
            .filter(|id| self.look_refused(p.pane, *id).is_none());
        let back = |by: Option<u32>| by.is_some() && by != chosen;
        // Only what the preview itself shows goes back.
        let theme_now = self.panes.get(&p.pane).map(|x| &x.theme);
        let theme_back = back(p.theme_by) && theme_now == p.theme_shown.as_ref();
        let mut changed = false;
        if theme_back {
            self.set_theme(p.pane, p.theme);
            changed = true;
        }
        if back(p.colours_by) {
            self.settings.window_colours = p.colours;
            changed = true;
        }
        if changed {
            self.update_menu_checks();
            self.refresh_chrome();
            self.request_full_redraw();
        }
    }

    /// Settings > Custom themes, as it opens: the themes folder read again,
    /// a radio item per theme, and a greyed one per file that is wrong.
    fn fill_custom_themes(&mut self, menu: HMENU) {
        let broken = match load_custom_themes() {
            Ok((themes, broken)) => {
                self.custom_themes = themes;
                broken
            }
            // The themes known before stay usable.
            Err(reason) => vec![custom_theme::Broken {
                file: "themes folder".into(),
                reason,
            }],
        };
        let current = self
            .panes
            .get(&self.focused_id())
            .map(|p| p.theme.name)
            .unwrap_or_default();
        let first = cmd::THEME + Theme::builtin().len() as u32;
        // SAFETY: our popup menu, being opened, when changing it is
        // allowed. Everything before the separator above Save is replaced.
        unsafe {
            while GetMenuItemCount(Some(menu)) > 3 {
                let _ = DeleteMenu(menu, 0, MF_BYPOSITION);
            }
            let mut pos = 0;
            let mut add = |flags: MENU_ITEM_FLAGS, id: u32, label: String| {
                let _ = InsertMenuW(
                    menu,
                    pos,
                    MF_BYPOSITION | MF_STRING | flags,
                    id as usize,
                    &HSTRING::from(label),
                );
                pos += 1;
            };
            if self.custom_themes.is_empty() && broken.is_empty() {
                add(MF_GRAYED, 0, "(none yet)".into());
            }
            for (id, c) in (first..).zip(&self.custom_themes) {
                let mut label = c.theme.name.replace('&', "&&");
                if let Some(font) = &c.font {
                    let size = c.size.map(|s| format!(" {s}")).unwrap_or_default();
                    label.push_str(&format!("\t{font}{size}"));
                }
                if !c.warnings.is_empty() {
                    label.push_str(" (see file)");
                }
                add(MENU_ITEM_FLAGS(0), id, label);
            }
            for b in &broken {
                add(
                    MF_GRAYED,
                    0,
                    format!("{}: {}", b.file, b.reason).replace('&', "&&"),
                );
            }
            let checked = self
                .custom_themes
                .iter()
                .position(|c| c.theme.name == current)
                .map_or(u32::MAX, |i| first + i as u32);
            if !self.custom_themes.is_empty() {
                let last = first + self.custom_themes.len() as u32 - 1;
                let _ = CheckMenuRadioItem(menu, first, last, checked, MF_BYCOMMAND.0);
            }
        }
        // The items moved: what the owner-drawn menu recorded for each
        // place (and the command palette reads) is taken again, also
        // when this runs with the menu closed (a theme saved, the theme
        // manager's reload).
        ui_theme::own_popup(menu);
    }

    /// Picks custom theme `id` for `pane`: its colours, its font if it
    /// has one and it is installed, and its window colours if it has
    /// them.
    fn use_custom_theme(&mut self, pane: PaneId, id: u32) -> Option<Command> {
        let c = self.custom_at(id)?.clone();
        self.set_theme(pane, c.theme.clone());
        let mut missing = None;
        let now = self.panes.get(&pane).map(|p| p.font.clone());
        // A size alone keeps the pane's font family.
        let family = c
            .font
            .clone()
            .or_else(|| c.size.and(now.as_ref().map(|f| f.family.clone())));
        if let Some(family) = family {
            if self.renderer.has_family(&family) {
                let size = c
                    .size
                    .or(now.as_ref().map(|f| f.size_pt))
                    .unwrap_or(FontSpec::default().size_pt);
                self.set_font(pane, FontSpec::new(&family, size));
            } else {
                missing = Some(family);
            }
        }
        if let Some(w) = c.window {
            self.settings.window_colours = match w {
                custom_theme::WindowSpec::Look(l) => l,
                custom_theme::WindowSpec::Colours(..) => WindowColours::Theme,
            };
            self.save_settings();
        }
        self.sync_tmux();
        self.update_menu_checks();
        self.refresh_chrome();
        self.request_full_redraw();
        missing.map(|family| {
            Command::Notice(format!(
                "The theme {} uses the font {family}, which is not installed; \
                 the pane keeps its font.",
                c.theme.name
            ))
        })
    }

    /// The look of `pane` as it is now, for a theme saved from it later.
    fn look_of(&self, pane: PaneId) -> Option<SavedLook> {
        let p = self.panes.get(&pane)?;
        Some(SavedLook {
            pane,
            theme: p.theme.clone(),
            font: (p.font.family.clone(), p.font.size_pt),
        })
    }

    /// Writes theme file `path` (theme `name`, text `text`) and reads the
    /// themes folder again; an error says why it is not a custom theme now.
    fn write_theme_file(
        &mut self,
        path: &Path,
        name: &str,
        text: String,
    ) -> std::result::Result<(), String> {
        if let Some(dir) = path.parent() {
            let _ = std::fs::create_dir_all(dir);
        }
        // Written beside it first, so a failed write leaves an existing
        // theme as it was.
        let temp = path.with_extension("theme-new");
        std::fs::write(&temp, text)
            .and_then(|()| std::fs::rename(&temp, path))
            .map_err(|e| {
                let _ = std::fs::remove_file(&temp);
                format!("The theme could not be saved to {}: {e}", path.display())
            })?;
        let dir = themes_dir();
        let reason = match load_custom_themes() {
            Ok((themes, broken)) => {
                self.custom_themes = themes;
                let file = path.file_name().map(|f| f.to_string_lossy().into_owned());
                broken
                    .into_iter()
                    .find(|b| Some(&b.file) == file.as_ref())
                    .map(|b| b.reason)
            }
            Err(e) => Some(e),
        };
        // The menu (and the command palette, which reads it) matches the
        // list again.
        if let Some(menu) = custom_themes_menu(self.menu) {
            self.fill_custom_themes(menu);
        }
        // The saved file itself loaded (not another file's theme of the
        // same name, which makes this one a duplicate).
        let listed = path.parent().is_some_and(|parent| same_file(parent, &dir))
            && reason.is_none()
            && self.custom_named(name).is_some();
        if !listed {
            let why = reason.map(|r| format!(" ({r})")).unwrap_or_default();
            return Err(format!(
                "Saved {}, but it is not in Settings > Custom themes{why}. \
                 Custom themes are read from {}: copy the file there.",
                path.display(),
                dir.display()
            ));
        }
        Ok(())
    }

    /// The colour editor's `edited` colours of theme `original`, written
    /// to theme file `path` as theme `name`, with the font and window
    /// colours `original`'s own file has. Saved over its own file (same
    /// name), the panes showing it get the new colours.
    fn save_edited_colours(
        &mut self,
        original: &Theme,
        edited: &Theme,
        path: &Path,
        name: &str,
        in_place: bool,
    ) -> std::result::Result<String, String> {
        let mut own = self.custom_named(original.name).cloned();
        if in_place {
            // Saved over its file: the font and window lines as the file
            // has them now, and not over colours changed there meanwhile.
            let now = std::fs::read_to_string(path)
                .map_err(|e| e.to_string())
                .and_then(|t| custom_theme::parse(&t, name));
            match now {
                Ok(c) if crate::colour_edit::changed(original, &c.theme).is_empty() => {
                    own = Some(c);
                }
                _ => {
                    return Err(format!(
                        "{} changed since the colour editor opened, so Save leaves it as it \
                         is. Save as keeps your colours in a new theme; or cancel and open the \
                         editor again.",
                        path.display()
                    ));
                }
            }
        }
        let text = custom_theme::write(
            name,
            edited,
            own.as_ref().and_then(|c| c.font.as_deref()),
            own.as_ref().and_then(|c| c.size),
            own.as_ref().and_then(|c| c.window),
        );
        // What the file held, as this window knew it, before it changes.
        let before = self
            .custom_themes
            .iter()
            .find(|c| same_file(&c.path, path))
            .map(|c| c.theme.clone());
        self.write_theme_file(path, name, text)?;
        let saved = self
            .custom_named(name)
            .map_or_else(|| edited.clone(), |c| c.theme.clone());
        let mut shown = 0;
        let mut unsaved = String::new();
        // The theme this file held before (the edited one for Save, or the
        // one a Save as replaced): its copies take the new colours.
        if let Some(before) = before {
            // Panes with the theme as it was (not tinted by a rule, not
            // another look) change with it; so do their enforced looks.
            let ids: Vec<PaneId> = self
                .panes
                .iter()
                .filter(|(_, p)| p.theme == before)
                .map(|(id, _)| *id)
                .collect();
            for p in self.panes.values_mut() {
                if p.lock.theme.as_ref() == Some(&before) {
                    p.lock.theme = Some(saved.clone());
                }
            }
            for id in &ids {
                self.set_theme(*id, saved.clone());
            }
            // New tabs too, when it is the default theme; and the saved
            // default follows a Save as that renamed it.
            // The saved default is checked on its own: a --theme start
            // may show another default while the settings name this one.
            if self.default_theme == before {
                self.default_theme = saved.clone();
            }
            if before.name != name && self.settings.default_theme.as_deref() == Some(before.name) {
                self.settings.default_theme = Some(name.to_owned());
                if let Err(e) = self.try_save_settings() {
                    unsaved = format!(
                        " The default theme was renamed, but the settings could not be \
                         saved, so the next start uses the old default ({e})."
                    );
                }
            }
            shown = ids.len();
            if shown > 0 {
                self.sync_tmux();
                self.request_full_redraw();
            }
        }
        if self.themes_native() {
            self.reload_themes();
        }
        let panes = match shown {
            0 => String::new(),
            1 => " The pane showing it has the new colours.".to_owned(),
            n => format!(" The {n} panes showing it have the new colours."),
        };
        Ok(if in_place {
            format!(
                "Saved the colours of {name} to {}.{panes}{unsaved}",
                path.display()
            )
        } else {
            format!(
                "Saved the theme {name} to {}.{panes} It is in the Theme manager and \
                 Settings > Custom themes; Apply to this pane puts it on a pane.{unsaved}",
                path.display()
            )
        })
    }

    /// Writes a pane's look as it was when the dialog opened (colours,
    /// font, and the window colours unless they follow something) to
    /// theme file `path`, and gives the pane that theme unless its look
    /// changed meanwhile.
    fn save_theme(&mut self, look: &SavedLook, path: &Path) -> std::result::Result<String, String> {
        let pane = look.pane;
        let stem = path
            .file_stem()
            .map(|s| s.to_string_lossy().into_owned())
            .unwrap_or_default();
        let name = custom_theme::clean_name(&stem).map_err(|e| {
            format!("A theme cannot be saved as {stem}: {e}. Pick another file name.")
        })?;
        let window = match self.settings.window_colours {
            WindowColours::Theme => self.custom_named(look.theme.name).and_then(|c| c.window),
            WindowColours::System | WindowColours::Light => None,
            look => Some(custom_theme::WindowSpec::Look(look)),
        };
        let text = custom_theme::write(
            &name,
            &look.theme,
            Some(&look.font.0),
            Some(look.font.1),
            window,
        );
        self.write_theme_file(path, &name, text)?;
        let saved = path.display();
        // A warning theme (Production, Staging) stays on the pane, so its
        // confirmations keep working; the saved copy is in the menu.
        // A pane that closed, or whose look changed while the dialog was
        // open (a reconnect, maybe with a reloaded theme of the same
        // name), keeps what it has now.
        let unchanged = self.look_of(pane).is_some_and(|now| {
            now.theme == look.theme && now.font.0 == look.font.0 && now.font.1 == look.font.1
        });
        let warning = p_warning(Some(&look.theme));
        if unchanged
            && !warning
            && let Some(t) = self.custom_named(&name).map(|c| c.theme.clone())
        {
            self.set_theme(pane, t);
            self.sync_tmux();
        }
        Ok(format!(
            "Saved the theme {name}. It is in Settings > Custom themes; edit {saved} in any \
             text editor to change it (the menu reads it again each time it opens)."
        ))
    }

    /// Session > Save font and theme for this host.
    fn save_look(&mut self) -> std::result::Result<String, String> {
        let pane = self.focused_id();
        let p = self.panes.get(&pane).ok_or_else(String::new)?;
        let host = self.panes.get(&self.host_pane(pane)).map(|g| &g.host);
        let Some(Host::Ssh(s)) = host else {
            return Err(
                "Only a pane connected to an SSH host has a host to save the look for.".into(),
            );
        };
        let host = s.target.alias.clone();
        let (font, size, theme) = (p.font.family.clone(), p.font.size_pt, p.theme.name);
        let profile = self.settings.profile_mut(&host);
        profile.font = Some(font.clone());
        profile.font_size = Some(size);
        profile.theme = Some(theme.to_owned());
        self.try_save_settings()?;
        Ok(format!(
            "Saved for {host}: {font} {size} pt, {theme} theme. New panes on this host use it."
        ))
    }

    fn update_menu_checks(&mut self) {
        let p = self.panes.get(&self.focused_id());
        let font = p
            .and_then(|p| FONT_CHOICES.iter().position(|f| *f == p.font.family))
            .map_or(u32::MAX, |i| cmd::FONT + i as u32);
        let theme = p
            .and_then(|p| Theme::builtin().iter().position(|t| t.name == p.theme.name))
            .map_or(u32::MAX, |i| cmd::THEME + i as u32);
        let (log, raw) = p.map_or((false, false), |p| (p.log.enabled, p.log.raw));
        let recording = p.is_some_and(|p| p.cast.is_some());
        let last_font = cmd::FONT + FONT_CHOICES.len() as u32 - 1;
        let last_theme = cmd::THEME + Theme::builtin().len() as u32 - 1;
        let check = |on: bool| if on { MF_CHECKED } else { MF_UNCHECKED };
        let own_layout = self
            .tmux
            .get(&self.host_pane(self.focused_id()))
            .is_some_and(|t| t.active() && t.mode() == TmuxMode::Ferossh);
        let s = &self.settings;
        // SAFETY: valid menu handle; ids are ours. A missing id just leaves
        // the group unchecked.
        unsafe {
            let _ = CheckMenuRadioItem(self.menu, cmd::FONT, last_font, font, MF_BYCOMMAND.0);
            let _ = CheckMenuRadioItem(self.menu, cmd::THEME, last_theme, theme, MF_BYCOMMAND.0);
            let colours = WindowColours::ALL
                .iter()
                .position(|c| *c == s.window_colours)
                .unwrap_or(0) as u32;
            let _ = CheckMenuRadioItem(
                self.menu,
                cmd::WINDOW_COLOURS,
                cmd::WINDOW_COLOURS + WindowColours::ALL.len() as u32 - 1,
                cmd::WINDOW_COLOURS + colours,
                MF_BYCOMMAND.0,
            );
            let way = s.remote_app_clipboard.as_deref().unwrap_or("off");
            let way = crate::stream::CLIPBOARD_WAYS
                .iter()
                .position(|w| *w == way)
                .unwrap_or(0) as u32;
            let _ = CheckMenuRadioItem(
                self.menu,
                cmd::REMOTE_APP_CLIP,
                cmd::REMOTE_APP_CLIP_LAST,
                cmd::REMOTE_APP_CLIP + way,
                MF_BYCOMMAND.0,
            );
            let way = s.desktop_clipboard.as_deref().unwrap_or("off");
            let way = ferossh_config::settings::CLIPBOARD_WAYS
                .iter()
                .position(|w| *w == way)
                .unwrap_or(0) as u32;
            let _ = CheckMenuRadioItem(
                self.menu,
                cmd::DESKTOP_CLIP,
                cmd::DESKTOP_CLIP_LAST,
                cmd::DESKTOP_CLIP + way,
                MF_BYCOMMAND.0,
            );
            for (id, on) in [
                (cmd::COPY_ON_SELECT, s.copy_on_select),
                (cmd::UPDATE_WEEKLY, s.update_check_weekly),
                (
                    cmd::OPEN_LINKS,
                    crate::url_handler::SCHEMES
                        .first()
                        .is_some_and(|s| crate::url_handler::registered(s)),
                ),
                (
                    cmd::OPEN_LINKS + 1,
                    crate::url_handler::SCHEMES
                        .get(1)
                        .is_some_and(|s| crate::url_handler::registered(s)),
                ),
                (cmd::RIGHT_CLICK_PASTE, s.right_click_paste),
                (cmd::SUGGEST, s.command_suggestions),
                (cmd::LOG_TOGGLE, log),
                (cmd::LOG_RAW, raw),
                (cmd::LOG_TIMESTAMPS, s.log_timestamps),
                (cmd::RECORD_CAST, recording),
                (cmd::AUTO_RESPONSES, s.auto_responses),
                (cmd::REMOTE_APP_COPY, s.remote_app_copy_agent),
                (cmd::REMOTE_APP_REMOVE, s.remote_app_remove_agent),
                (cmd::REMOTE_APP_SELECTION, s.remote_app_share_selection),
                (cmd::DESKTOP_SELECTION, s.desktop_share_selection),
                (cmd::CONFIRM_PRODUCTION, s.confirm_production),
                (cmd::WORKSPACE_AUTO_LOGIN, s.workspace_auto_login),
                (cmd::WORKSPACE_RESTORE, s.restore_layout),
                (cmd::FULL_SCREEN, self.full_screen.is_some()),
                (cmd::FULL_SCREEN_KEY, s.full_screen_key),
                (cmd::FONT_LIGATURES, s.font_ligatures),
                (cmd::CONNECTION_LOG_DELETE, s.connection_log_delete),
                (cmd::TMUX_KEYS, s.tmux_keys),
                (cmd::RECORD_SNIPPET, self.recording.is_some()),
                (
                    cmd::SESSIONS,
                    self.side.visible && self.side.view == SideView::Sessions,
                ),
                (
                    cmd::LIVE,
                    self.side.visible && self.side.view == SideView::Live,
                ),
                (
                    cmd::FILES,
                    self.side.visible && self.side.view == SideView::Files,
                ),
                (
                    cmd::FORWARDS,
                    self.side.visible && self.side.view == SideView::Forwards,
                ),
                (
                    cmd::SNIPPETS,
                    self.side.visible && self.side.view == SideView::Snippets,
                ),
                (
                    cmd::KNOWN_HOSTS,
                    self.side.visible && self.side.view == SideView::KnownHosts,
                ),
                (
                    cmd::INVENTORY,
                    self.side.visible && self.side.view == SideView::Inventory,
                ),
                (
                    cmd::HOSTS,
                    self.side.visible && self.side.view == SideView::Hosts,
                ),
                (
                    cmd::CREDENTIAL_MANAGER,
                    self.side.visible && self.side.view == SideView::Credentials,
                ),
                (
                    cmd::SECURITY_RULES,
                    self.side.visible && self.side.view == SideView::SecurityRules,
                ),
                (
                    cmd::THEME_MANAGER,
                    self.side.visible && self.side.view == SideView::Themes,
                ),
                (
                    cmd::THEME_RULES,
                    self.side.visible && self.side.view == SideView::ThemeRules,
                ),
                (cmd::FOLLOW_CD, s.follow_directory),
                (cmd::VERIFY, s.verify_transfers),
                (cmd::ZMODEM, s.zmodem),
                (cmd::INLINE_IMAGES, s.inline_images),
                (cmd::ESCAPES, s.escapes),
                (cmd::UPLOAD_TYPE_PATH, s.upload_type_path),
                (cmd::PORT_PREVIEWS, s.port_previews),
                (cmd::KITTY_KEYBOARD, s.kitty_keyboard),
                (cmd::SHIFT_ENTER, s.shift_enter != ShiftEnterKey::Enter),
                (cmd::AGENT_AUDIT, s.agent_audit),
                (cmd::ANSWER_TOASTS, s.answer_from_notification),
                (cmd::HIGHLIGHT, s.highlight),
                (cmd::AUTO_RECONNECT, s.auto_reconnect),
                (cmd::SIDE_RIGHT, s.side_pane_right),
                (cmd::TOOLS_RAIL, s.tools_rail),
                (cmd::TOOLS_PIN, s.tools_pinned),
                (cmd::TAB_STRIP, s.tab_strip),
                (cmd::STATUS_BAR, s.status_bar),
                (cmd::NOTIFY, s.notifications),
                (cmd::NOTIFY_BELL, s.notify_bell),
                (cmd::NOTIFY_QUIET, p.is_some_and(|p| p.quiet.is_some())),
                (cmd::TMUX_LAYOUT, own_layout),
                (cmd::BROADCAST_TAB, self.broadcast == broadcast::Scope::Tab),
                (cmd::BROADCAST_ALL, self.broadcast == broadcast::Scope::All),
                (cmd::BROADCAST_SKIP, p.is_some_and(|p| p.no_broadcast)),
                (cmd::STANDBY_TOGGLE, self.standby.held.is_some()),
            ] {
                CheckMenuItem(self.menu, id, (MF_BYCOMMAND | check(on)).0);
            }
        }
        self.update_standby_menu();
        let open = crate::vault::is_open();
        let grey = |on: bool| if on { MF_ENABLED } else { MF_GRAYED };
        // SAFETY: valid menu handle; ids are ours.
        unsafe {
            for (id, on) in [
                (cmd::VAULT_SET, !open),
                (cmd::VAULT_USE, !open),
                (cmd::VAULT_MOVE, open),
                (cmd::VAULT_CHANGE, open),
                (cmd::VAULT_REMOVE, open),
            ]
            .into_iter()
            .chain(self.menu_applies())
            {
                let _ = EnableMenuItem(self.menu, id, MF_BYCOMMAND | grey(on));
            }
        }
    }

    /// Menu items greyed out while they cannot do anything for the
    /// focused pane: on when they can. The command palette leaves greyed
    /// items out; their shortcuts work as before.
    fn menu_applies(&self) -> Vec<(u32, bool)> {
        let pane = self.focused_id();
        let host = self.host_pane(pane);
        let tmux = self.tmux.get(&host).is_some_and(|t| t.active());
        let own_tmux = self
            .tmux
            .get(&host)
            .is_some_and(|t| t.active() && t.joined().is_none());
        let connection = self.pane_connection(pane);
        let vdesk = connection.is_some()
            && self
                .vdesks
                .values()
                .any(|v| Some(v.connection) == connection);
        let serial = matches!(
            self.panes.get(&pane).map(|p| &p.host),
            Some(Host::Serial { port: Some(_), .. })
        );
        let tabs = self.ws.tabs.len() > 1;
        let split = self.ws.tab().is_some_and(|t| t.root.panes().len() > 1);
        let mut out = vec![
            (cmd::TMUX_PICK, tmux),
            (cmd::TMUX_DETACH, tmux),
            (cmd::TMUX_UNSHARE, own_tmux),
            (cmd::TMUX_LAYOUT, tmux),
            (cmd::VDESK_STOP, vdesk),
            (cmd::SERIAL_BREAK, serial),
            (cmd::NEXT_TAB, tabs),
            (cmd::PREV_TAB, tabs),
            (cmd::TAB_LEFT, tabs),
            (cmd::TAB_RIGHT, tabs),
            (cmd::JOIN_TAB, tabs),
            (cmd::PANE_TO_TAB, split),
            (
                cmd::HIDE_PANE,
                self.ws.all_panes().len() > 1 && !self.locked(pane),
            ),
            (cmd::SHOW_HIDDEN, !self.ws.hidden().is_empty()),
            (cmd::NOTIFY_BELL, self.settings.notifications),
            (
                cmd::NOTIFY_QUIET,
                // A watch can always be taken off; a new one needs
                // notifications on and a shell to watch.
                self.panes.get(&pane).is_some_and(|p| {
                    p.quiet.is_some() || (self.settings.notifications && quiet_watchable(p))
                }),
            ),
        ];
        for i in 0..4 {
            out.push((cmd::FOCUS + i, split));
            out.push((cmd::RESIZE + i, split));
        }
        out
    }

    /// The hotkey the standby window uses (or would use).
    fn standby_key(&self) -> Hotkey {
        self.settings.standby_hotkey.unwrap_or(Hotkey::DEFAULT)
    }

    /// The window the standby hotkey works, for people to read.
    fn standby_what(&self) -> String {
        self.settings
            .standby_target
            .clone()
            .unwrap_or_else(|| "this window".to_owned())
    }

    /// Window > Standby window > Window to show and hide, as it opens:
    /// this FeroSSH window, then the open windows of other programs, the
    /// one in use marked.
    fn fill_standby_targets(&mut self, menu: HMENU) {
        self.standby.candidates = standby::sys::windows(self.hwnd);
        let exe = self.settings.standby_target.clone();
        let current = exe.as_deref().and_then(|e| {
            standby::find(
                &self.standby.candidates,
                e,
                self.standby.target.or(self.standby.hidden),
            )
        });
        // SAFETY: our popup menu; it is being opened, when changing it is
        // allowed. Only the window items after the first are replaced.
        unsafe {
            while GetMenuItemCount(Some(menu)) > 1 {
                let _ = DeleteMenu(menu, 1, MF_BYPOSITION);
            }
            if !self.standby.candidates.is_empty() {
                let _ = AppendMenuW(menu, MF_SEPARATOR, 0, None);
            }
            for (id, c) in (cmd::STANDBY_TARGET..).zip(&self.standby.candidates) {
                let _ = AppendMenuW(
                    menu,
                    MF_STRING,
                    id as usize,
                    &HSTRING::from(standby::menu_label(c)),
                );
            }
            let last = cmd::STANDBY_TARGET + standby::MAX_CANDIDATES as u32;
            let checked = match (&exe, current) {
                (None, _) => Some(cmd::STANDBY_OWN),
                (Some(_), Some(h)) => self
                    .standby
                    .candidates
                    .iter()
                    .position(|c| c.hwnd == h)
                    .map(|i| cmd::STANDBY_TARGET + i as u32),
                // Its program has no window open (or it is hidden).
                (Some(_), None) => None,
            };
            let _ = CheckMenuRadioItem(
                menu,
                cmd::STANDBY_OWN,
                last,
                checked.unwrap_or(u32::MAX),
                MF_BYCOMMAND.0,
            );
        }
    }

    /// Shows another program's window that the standby hotkey hid, and
    /// forgets it.
    fn restore_hidden(&mut self) {
        let hidden = self.standby.hidden.take();
        let saved = self.settings.standby_hidden.take();
        // A handle from the settings may be a reused one after a restart:
        // it is shown only while it is still a window of the picked
        // program.
        let from_file = saved.and_then(|v| isize::try_from(v).ok()).filter(|&h| {
            self.settings
                .standby_target
                .as_deref()
                .is_some_and(|exe| standby::sys::alive_with_exe(h, exe))
        });
        if let Some(h) = hidden.or(from_file) {
            standby::sys::show_async(h);
        }
        if hidden.is_some() || saved.is_some() {
            self.save_settings();
        }
    }

    /// Notes another program's window as hidden by the hotkey (`Some`) or
    /// shown again (`None`), also in the settings, so that a FeroSSH that
    /// ends without showing it shows it at its next start.
    fn note_hidden(&mut self, h: Option<isize>) {
        self.standby.hidden = h;
        let saved = h.and_then(|v| u64::try_from(v).ok());
        if self.settings.standby_hidden != saved {
            self.settings.standby_hidden = saved;
            self.save_settings();
        }
    }

    /// The window a press of the hotkey works on now.
    fn standby_target(&mut self) -> StandbyTarget {
        let Some(exe) = self.settings.standby_target.clone() else {
            return StandbyTarget::Own;
        };
        for h in [self.standby.hidden, self.standby.target]
            .into_iter()
            .flatten()
        {
            if standby::sys::alive_with_exe(h, &exe) {
                return StandbyTarget::Other(h);
            }
        }
        let found = standby::find(&standby::sys::windows(self.hwnd), &exe, None);
        self.standby.target = found;
        found.map_or(StandbyTarget::Missing(exe), StandbyTarget::Other)
    }

    /// Window > Standby window's status line and the checked hotkey.
    fn update_standby_menu(&self) {
        let key = self.standby_key();
        let status = self
            .standby
            .status(&hotkey_label(key), &self.standby_what());
        let presets = standby_presets();
        let last = cmd::STANDBY_PRESET + presets.len() as u32 - 1;
        let picked = presets
            .iter()
            .position(|p| *p == key)
            .map_or(u32::MAX, |i| cmd::STANDBY_PRESET + i as u32);
        // SAFETY: valid menu handle; ids are ours.
        unsafe {
            let _ = ModifyMenuW(
                self.menu,
                cmd::STANDBY_STATUS,
                MF_BYCOMMAND | MF_STRING,
                cmd::STANDBY_STATUS as usize,
                &HSTRING::from(status),
            );
            // A hotkey that is none of these leaves them all unchecked.
            let _ =
                CheckMenuRadioItem(self.menu, cmd::STANDBY_PRESET, last, picked, MF_BYCOMMAND.0);
        }
    }

    /// Takes or lets go of the standby hotkey to match the settings: held
    /// when Standby is on and Windows gives it, else noted as taken.
    /// Returns whether the window now holds it. `RegisterHotKey` sends no
    /// messages, so this is safe inside `with_window`.
    fn apply_standby(&mut self) -> bool {
        if self.standby.held.take().is_some() {
            // SAFETY: our window and the id it registered.
            let _ = unsafe { UnregisterHotKey(Some(self.hwnd), standby::HOTKEY_ID) };
        }
        self.standby.taken = None;
        if self.settings.standby {
            let key = self.standby_key();
            let mods = HOT_KEY_MODIFIERS(key.modifiers()) | MOD_NOREPEAT;
            // SAFETY: our window; Windows checks the key and modifiers.
            let ok = unsafe {
                RegisterHotKey(Some(self.hwnd), standby::HOTKEY_ID, mods, u32::from(key.vk))
            }
            .is_ok();
            if ok {
                self.standby.held = Some(key);
            } else {
                self.standby.taken = Some(key);
            }
        }
        self.update_menu_checks();
        self.standby.held.is_some()
    }

    /// Turns Standby on with `key` (the current one when `None`), and
    /// says how that went.
    fn standby_on(&mut self, key: Option<Hotkey>) -> Command {
        if let Some(k) = key {
            self.settings.standby_hotkey = Some(k);
        }
        self.settings.standby = true;
        self.save_settings();
        let label = hotkey_label(self.standby_key());
        let what = match &self.settings.standby_target {
            Some(exe) => format!("the window of {exe}"),
            None => "this FeroSSH window".to_owned(),
        };
        if self.apply_standby() {
            Command::Notice(format!(
                "{label} now hides {what} and brings it back.\n\nWhile hidden it has no \
                 taskbar button; only {label} brings it back, and FeroSSH shows it again when \
                 standby goes off or FeroSSH closes. Window > Standby window shows whether it \
                 is active, picks the window, and turns it off."
            ))
        } else {
            Command::Notice(self.standby.details(&label, &self.standby_what()))
        }
    }

    /// Picking a hotkey by pressing it ended: with the key pressed, or
    /// cancelled (`None`).
    fn end_capture(&mut self, key: Option<Hotkey>) -> Option<Command> {
        if self.standby.capture != Capture::Waiting {
            return None;
        }
        self.standby.capture = if key.is_some() {
            Capture::Finishing
        } else {
            Capture::Off
        };
        self.update_title();
        key.map(|k| self.standby_on(Some(k)))
    }

    fn set_focus(&mut self, focused: bool) {
        self.focused = focused;
        // Back at the pane that asked for attention: it has it (the tab
        // strip redraws below).
        let here = self.focused_id();
        if focused && let Some(p) = self.panes.get_mut(&here) {
            p.attention = false;
        }
        // The clipboard may change while away: a desktop gets it again.
        self.clip_pane = None;
        let id = self.focused_id();
        let reply = self.panes.get_mut(&id).and_then(|p| p.term.focus(focused));
        if let Some(bytes) = reply {
            self.send(id, bytes);
        }
        if !focused {
            self.mouse.selecting = false;
            self.mouse.reporting = None;
        }
        // The cursor changes shape; its row must redraw even if nothing
        // else changed.
        if let Some(p) = self.panes.get_mut(&id)
            && let Some(c) = p.cursor
        {
            p.grid.mark_dirty(c.y);
        }
        self.refresh(id);
        self.refresh_chrome();
    }

    /// The DPI changed: reload fonts at the new size.
    fn set_dpi(&mut self, dpi: u32) {
        self.dpi = dpi;
        self.renderer.clear_font_cache();
        for p in self.panes.values_mut() {
            if let Ok(metrics) = self.renderer.metrics(&p.font, dpi) {
                p.metrics = metrics;
            }
        }
        if let Ok(m) = self.renderer.metrics(&self.chrome_font, dpi) {
            self.chrome_metrics = m;
        }
        if let Ok(m) = self.renderer.metrics(&self.strip_font, dpi) {
            self.strip_metrics = m;
        }
        self.side.width = 0;
        self.full_redraw = true;
    }

    /// The window size that keeps the layout at `dpi`: the client scaled.
    fn size_for_dpi(&self, dpi: u32) -> Option<(i32, i32)> {
        // Full screen fills the monitor whatever the DPI.
        if self.dpi == 0 || self.full_screen.is_some() {
            return None;
        }
        let s = |v: i32| v * dpi as i32 / self.dpi as i32;
        Some(client_to_window(
            s(self.client.0),
            s(self.client.1),
            dpi,
            self.menu_visible,
        ))
    }

    /// Where downloads go: the setting, else the user's Downloads folder.
    fn download_dir(&self) -> PathBuf {
        self.settings
            .download_folder
            .as_ref()
            .map_or_else(|| home().join("Downloads"), PathBuf::from)
    }

    /// The file view's Local PC folder moved: downloads go there from now
    /// on, and it is remembered (`DownloadFolder`; unset for Downloads).
    fn set_download_dir(&mut self, dir: &Path) {
        let Some(text) = dir.to_str() else {
            return;
        };
        let folder = (dir != home().join("Downloads")).then(|| text.to_owned());
        if self.settings.download_folder != folder {
            self.settings.download_folder = folder;
            self.save_settings();
        }
        self.refresh_chrome();
    }

    fn files_visible(&self) -> bool {
        self.side.visible && self.side.view == SideView::Files
    }

    /// The transfer queue's key for pane `id`, if it is an SSH pane.
    fn pane_sftp_key(&self, id: PaneId) -> Option<String> {
        match &self.panes.get(&self.host_pane(id))?.host {
            Host::Ssh(s) => Some(sftp_key(&s.target)),
            _ => None,
        }
    }

    /// The queue key for pane `id` when it is logged in and its host's
    /// queue exists.
    fn files_target(&self, id: PaneId) -> Option<String> {
        let p = self.panes.get(&id)?;
        if !p.connected() {
            return None;
        }
        let key = self.pane_sftp_key(id)?;
        self.sftp.contains_key(&key).then_some(key)
    }

    /// Opens SFTP on pane `id`'s connection, if the pane is logged in and
    /// its host has no SFTP channel yet. The queue starts in the pane's
    /// directory when it reported one. Returns true when it opened the
    /// channel here (its first listing already asks for that folder).
    fn ensure_sftp(&mut self, id: PaneId) -> bool {
        let Some(p) = self.panes.get(&id) else {
            return false;
        };
        let Some(Host::Ssh(s)) = self.panes.get(&self.host_pane(id)).map(|g| &g.host) else {
            return false;
        };
        if s.state() != State::Connected || !self.workers.contains_key(&s.connection) {
            return false;
        }
        let key = sftp_key(&s.target);
        let label = s.target.label();
        let connection = s.connection;
        // The connection's Remote folder, else the shell's directory.
        let folder = self.remote_folder(id).map(String::into_bytes);
        if folder.is_some() && !self.sftp.contains_key(&key) {
            self.folder_left.remove(&key);
            self.started_in_folder.insert(key.clone(), id);
        }
        let cwd = folder.or_else(|| p.cwd.clone().filter(|_| self.settings.follow_directory));
        let (verify, parallel) = (
            self.settings.verify_transfers,
            self.settings.parallel_transfers,
        );
        let remote = self.sftp.entry(key).or_insert_with(|| {
            let mut r = Remote::new(&label);
            r.verify = verify;
            if let Some(n) = parallel {
                r.parallel = n;
            }
            r
        });
        if remote.channel().is_some() {
            return false;
        }
        if let Some(cwd) = cwd
            && remote.listing.path.is_empty()
        {
            remote.browse(&cwd);
        }
        // `self.sftp` is borrowed: the same as `new_channel`, inline.
        let channel = self.next_channel;
        self.next_channel = ((channel + 1) % FORWARD_IDS).max(1);
        remote.attach(channel, connection);
        self.sftp_routes.insert(channel, connection);
        self.flush_sftp();
        true
    }

    /// A pane logged in: transfers waiting for its host carry on, and the
    /// file view opens SFTP if it shows that host.
    fn sftp_connected(&mut self, id: PaneId) {
        let Some(key) = self.pane_sftp_key(id) else {
            return;
        };
        let shown = self.files_visible() && self.files_key.as_deref() == Some(&key);
        let waiting = self.sftp.get(&key).is_some_and(Remote::wants_connection);
        if shown || waiting {
            self.ensure_sftp(id);
        }
    }

    /// Closes SFTP channels whose connection no logged-in pane uses any
    /// more, so they do not keep it open. Their transfers wait.
    fn prune_sftp(&mut self) {
        let live: Vec<(String, ChannelId)> = self
            .panes
            .values()
            .filter_map(|p| match &p.host {
                Host::Ssh(s) if s.state() == State::Connected => {
                    Some((sftp_key(&s.target), s.connection))
                }
                _ => None,
            })
            .collect();
        let mut closed = Vec::new();
        for (key, remote) in &mut self.sftp {
            if let Some(conn) = remote.connection()
                && !live.iter().any(|(k, c)| k == key && *c == conn)
            {
                remote.close();
                closed.push(key.clone());
            }
        }
        if closed.is_empty() {
            return;
        }
        self.flush_sftp();
        self.hand_over_sftp(closed);
    }

    /// Queues `keys` lost their connection: another login to the same
    /// host (two SFTP-only tabs never share one) takes each over, so its
    /// transfers carry on without a refresh.
    fn hand_over_sftp(&mut self, keys: Vec<String>) {
        for key in keys {
            let heir = self.panes.iter().find_map(|(&id, p)| match &p.host {
                Host::Ssh(s) if s.state() == State::Connected && sftp_key(&s.target) == key => {
                    Some(id)
                }
                _ => None,
            });
            if let Some(id) = heir {
                self.ensure_sftp(id);
            }
        }
    }

    /// Sends what the queues asked for, and runs the progress timer while
    /// anything moves.
    fn flush_sftp(&mut self) {
        for remote in self.sftp.values_mut() {
            // Each to the worker of the connection its channel runs on.
            for msg in remote.take_outbox() {
                if let Some(w) = msg
                    .channel()
                    .and_then(|c| self.sftp_routes.get(&c))
                    .and_then(|c| self.workers.get(c))
                {
                    w.link.send(msg);
                }
            }
        }
        let busy = self.sftp.values().any(Remote::busy);
        if busy != self.transfer_timer {
            self.transfer_timer = busy;
            // SAFETY: our window and timer.
            unsafe {
                if busy {
                    SetTimer(Some(self.hwnd), TIMER_TRANSFER, TRANSFER_TICK_MS, None);
                } else {
                    let _ = KillTimer(Some(self.hwnd), TIMER_TRANSFER);
                }
            }
        }
    }

    fn on_transfer_timer(&mut self) -> Option<Command> {
        for remote in self.sftp.values_mut() {
            remote.poll();
        }
        let pasted = self.settle_pastes();
        self.flush_sftp();
        if self.files_visible() {
            self.refresh_chrome();
        }
        pasted
    }

    /// Points the file view at the focused pane's host when focus moved
    /// to a pane on another host, and at the focused pane's directory
    /// when focus moved to another pane (on any host).
    fn sync_files(&mut self) {
        if !self.files_visible() {
            self.files_pane = None;
            return;
        }
        let id = self.focused_id();
        let key = self.pane_sftp_key(id);
        let host_changed = key != self.files_key;
        let mut opened = false;
        if host_changed {
            self.files_key.clone_from(&key);
            opened = self.ensure_sftp(id);
        }
        if host_changed || self.files_pane != Some(id) {
            self.files_pane = Some(id);
            let ident = self.files_ident(id);
            let alias_changed = match (&key, &ident) {
                (Some(k), Some(a)) => {
                    self.files_alias_shown.insert(k.clone(), a.clone()).as_ref() != Some(a)
                }
                _ => false,
            };
            // Another connection to a host already listed, also when
            // coming back from another host: its own Remote folder, if it
            // names one. Returning to the same one keeps where it was.
            if alias_changed
                && let Some(k) = key.clone()
                && let Some(folder) = self.remote_folder(id)
                && let Some(r) = self.sftp.get_mut(&k)
            {
                // A queue that just opened empty for this pane already
                // asked for it; one that kept another's listing did not.
                if !opened || !r.listing.path.is_empty() {
                    r.notice = None;
                    r.browse(folder.as_bytes());
                }
                self.folder_left.remove(&k);
                self.started_in_folder.insert(k, id);
                // Sent now: with nothing transferring, no timer would.
                self.flush_sftp();
                return;
            }
            if !host_changed
                && alias_changed
                && let Some(k) = &key
            {
                // A connection with no Remote folder of its own follows
                // its shell.
                self.started_in_folder.remove(k);
                self.folder_left.remove(k);
            }
            if let Some(k) = &key
                && self.started_in_folder.get(k) == Some(&id)
            {
                // It stays in the connection's Remote folder; following
                // picks up from the shell's next cd. If another pane's
                // shell moved the shared listing meanwhile, list the
                // folder again.
                if self.folder_left.remove(k)
                    && let Some(folder) = self.remote_folder(id)
                    && let Some(r) = self.sftp.get_mut(k)
                {
                    r.notice = None;
                    r.browse(folder.as_bytes());
                    self.flush_sftp();
                }
                return;
            }
            self.follow_pane(id);
        }
    }

    /// The connection name of pane `id`'s SSH host.
    /// Which connection pane `id` is to File transfer: its name, and the
    /// folder of the `sftp://` address it was opened with, since two such
    /// addresses for one login differ only by folder.
    fn files_ident(&self, id: PaneId) -> Option<String> {
        match &self.panes.get(&self.host_pane(id))?.host {
            Host::Ssh(s) => Some(match &s.target.sftp_folder {
                Some(f) => format!("{} {f}", s.target.alias),
                None => s.target.alias.clone(),
            }),
            _ => None,
        }
    }

    /// The Remote folder pane `id`'s connection names for file transfer.
    fn remote_folder(&self, id: PaneId) -> Option<String> {
        match &self.panes.get(&self.host_pane(id))?.host {
            // An `sftp://` address's folder, else the connection's.
            Host::Ssh(s) => s.target.sftp_folder.clone().or_else(|| {
                self.settings
                    .profile(&s.target.alias)?
                    .remote_folder
                    .clone()
            }),
            _ => None,
        }
    }

    /// Whether pane `id` is an SFTP-only login, with no shell.
    fn sftp_only(&self, id: PaneId) -> bool {
        matches!(
            self.panes.get(&id).map(|p| &p.host),
            Some(Host::Ssh(s)) if s.target.sftp_only
        )
    }

    /// Whether pane `id` is a tunnel-only login (`ssh -N`): forwards, no
    /// shell.
    fn tunnel_only(&self, id: PaneId) -> bool {
        matches!(
            self.panes.get(&id).map(|p| &p.host),
            Some(Host::Ssh(s)) if s.target.tunnel_only && !s.target.sftp_only
        )
    }

    /// Lists pane `id`'s reported directory, when following is on.
    fn follow_pane(&mut self, id: PaneId) {
        if !self.settings.follow_directory {
            return;
        }
        let Some(cwd) = self.panes.get(&id).and_then(|p| p.cwd.clone()) else {
            return;
        };
        let Some(key) = self.pane_sftp_key(id) else {
            return;
        };
        if let Some(remote) = self.sftp.get_mut(&key)
            && remote.listing.path != cwd
        {
            remote.browse(&cwd);
            if self.started_in_folder.get(&key).is_some_and(|o| *o != id) {
                self.folder_left.insert(key);
            }
            self.flush_sftp();
        }
    }

    /// The shell reported its directory (OSC 7). Returns whether the file
    /// view changed.
    fn on_working_dir(&mut self, id: PaneId, dir: WorkingDir) -> bool {
        let Some(p) = self.panes.get_mut(&id) else {
            return false;
        };
        if !matches!(p.host, Host::Ssh(_) | Host::Tmux { .. }) {
            return false;
        }
        let host = dir.host.to_ascii_lowercase();
        let first = p.cwd_host.get_or_insert_with(|| host.clone());
        if *first != host {
            // A nested ssh on another host: its paths are not ours.
            p.cwd = None;
            return false;
        }
        let moved = p.cwd.as_ref() != Some(&dir.path);
        p.cwd = Some(dir.path);
        p.cwd_reported = true;
        if !moved {
            // The same folder again (a new prompt): nothing to follow.
            return false;
        }
        self.shell_moved(id);
        if !self.files_visible() || id != self.focused_id() {
            return false;
        }
        self.follow_pane(id);
        true
    }

    /// For shells that do not report their directory (OSC 7, which stock
    /// bash does not send): reads it from a `user@host:dir$ ` prompt at
    /// the cursor. Returns whether the file view changed.
    fn read_prompt(&mut self, id: PaneId) -> bool {
        let Some(p) = self.panes.get(&id) else {
            return false;
        };
        if p.cwd_reported || !matches!(p.host, Host::Ssh(_) | Host::Tmux { .. }) {
            return false;
        }
        let Some(dir) = p.term.prompt_line().as_deref().and_then(prompt_dir) else {
            return false;
        };
        // `~` is the home folder; before SFTP has told us where that is,
        // a path relative to where SFTP starts (the home folder) does.
        let home = self
            .pane_sftp_key(id)
            .and_then(|k| self.sftp.get(&k))
            .and_then(|r| r.home.clone());
        let path = match dir.path.strip_prefix(b"~") {
            None => dir.path,
            Some(rest) => {
                let rest = rest.strip_prefix(b"/").unwrap_or(rest);
                match (home, rest.is_empty()) {
                    (Some(home), true) => home,
                    (Some(mut home), false) => {
                        if !home.ends_with(b"/") {
                            home.push(b'/');
                        }
                        home.extend_from_slice(rest);
                        home
                    }
                    (None, true) => b".".to_vec(),
                    (None, false) => rest.to_vec(),
                }
            }
        };
        let Some(p) = self.panes.get_mut(&id) else {
            return false;
        };
        let host = dir.host.to_ascii_lowercase();
        let first = p.prompt_host.get_or_insert_with(|| host.clone());
        if *first != host {
            // A nested ssh on another host: its paths are not ours.
            let had = p.cwd.take().is_some();
            return had && id == self.focused_id() && self.files_visible();
        }
        if p.cwd.as_deref() == Some(path.as_slice()) {
            return false;
        }
        p.cwd = Some(path);
        self.shell_moved(id);
        if !self.files_visible() || id != self.focused_id() {
            return false;
        }
        self.follow_pane(id);
        true
    }

    /// Pane `id`'s shell went to another folder: from now on its file
    /// view follows the shell, even if it started in the Remote folder.
    fn shell_moved(&mut self, id: PaneId) {
        if let Some(key) = self.pane_sftp_key(id)
            && self.started_in_folder.get(&key) == Some(&id)
        {
            self.started_in_folder.remove(&key);
            self.folder_left.remove(&key);
        }
    }

    /// Notes the folder a local shell's prompt shows, for new tabs and
    /// panes opened from it.
    fn read_local_prompt(&mut self, id: PaneId) {
        let Some(p) = self.panes.get_mut(&id) else {
            return;
        };
        if !matches!(p.host, Host::Local { exited: false, .. }) {
            return;
        }
        if let Some(dir) = p
            .term
            .prompt_line()
            .as_deref()
            .and_then(same_dir::local_prompt_dir)
        {
            p.local_cwd = Some(dir);
        }
    }

    fn toggle_follow(&mut self) {
        self.settings.follow_directory = !self.settings.follow_directory;
        self.save_settings();
        self.update_menu_checks();
        self.follow_pane(self.focused_id());
        self.refresh_chrome();
    }

    /// What the file transfer pane shows.
    fn files_view(&self) -> files_panel::View {
        let remote = self.files_key.as_ref().and_then(|k| self.sftp.get(k));
        let follow = if !self.settings.follow_directory {
            Follow::Off
        } else if self
            .panes
            .get(&self.focused_id())
            .is_some_and(|p| p.cwd.is_some())
        {
            Follow::On
        } else {
            Follow::Unreported
        };
        let status = match remote {
            None => Some((NOT_CONNECTED.to_owned(), false)),
            Some(r) => r
                .notice
                .clone()
                .or_else(|| r.listing.error.clone())
                .map(|n| (n, true))
                .or_else(|| {
                    (follow == Follow::Unreported).then(|| {
                        (
                            "Follow terminal: the shell has not said which folder it is in yet."
                                .to_owned(),
                            false,
                        )
                    })
                }),
        };
        let alias = remote.and(self.files_alias());
        files_panel::View {
            host: remote.map(|r| r.label.clone()),
            key: remote.and(self.files_key.clone()),
            remote_dir: remote.map(|r| r.listing.path.clone()).unwrap_or_default(),
            remote_loading: remote.is_some_and(|r| r.listing.loading),
            remote_rows: remote
                .map(|r| files::remote_rows(&r.listing, ""))
                .unwrap_or_default(),
            status,
            queue: remote.map(files::queue_rows).unwrap_or_default(),
            question: remote.and_then(Remote::question),
            follow,
            base: self.download_dir(),
            landed: remote.map_or(0, files::landed),
            arrange: self.arrange(),
            sort: self
                .settings
                .transfer_sort
                .as_deref()
                .map(files::Sorts::parse)
                .unwrap_or_default(),
            bookmarks: self.settings.bookmarks.clone(),
            local_start: alias
                .as_deref()
                .and_then(|a| self.settings.profile(a))
                .and_then(|p| p.local_folder.as_deref())
                .map(PathBuf::from),
            alias,
        }
    }

    /// The connection name of the host the file transfer pane shows.
    fn files_alias(&self) -> Option<String> {
        self.files_key.as_ref()?;
        let id = self.files_pane?;
        match &self.panes.get(&self.host_pane(id))?.host {
            Host::Ssh(s) => Some(s.target.alias.clone()),
            _ => None,
        }
    }

    /// How the file transfer pane arranges its lists.
    fn arrange(&self) -> Arrange {
        self.settings
            .transfer_layout
            .as_deref()
            .map(Arrange::parse)
            .unwrap_or_default()
    }

    /// Carries out what the user did in the file transfer pane.
    fn files_event(&mut self, event: files_panel::Event) -> Option<Command> {
        use files_panel::{Event, JobOp};
        let key = self.files_key.clone().filter(|k| self.sftp.contains_key(k));
        let command = match event {
            // Handled before the window is borrowed: it asks first.
            Event::DropOut { .. } => None,
            Event::Browse(path) => {
                if let Some(r) = key.as_ref().and_then(|k| self.sftp.get_mut(k)) {
                    r.notice = None;
                    r.browse(&path);
                }
                None
            }
            Event::SyncBack(back) => {
                // Only for the queue and connection it left: the view may
                // have moved on, even to another connection on the queue.
                if back.applies(key.as_deref(), self.files_alias().as_deref())
                    && let Some(r) = key.as_ref().and_then(|k| self.sftp.get_mut(k))
                {
                    r.notice = None;
                    r.browse(&back.path);
                }
                None
            }
            Event::Home => {
                if let Some(r) = key.as_ref().and_then(|k| self.sftp.get_mut(k))
                    && let Some(home) = r.home.clone()
                {
                    r.notice = None;
                    r.browse(&home);
                }
                None
            }
            Event::Refresh => {
                self.ensure_sftp(self.focused_id());
                if let Some(r) = key.as_ref().and_then(|k| self.sftp.get_mut(k)) {
                    r.notice = None;
                    r.refresh();
                }
                None
            }
            Event::Download { keys, into } => {
                if let Some(r) = key.as_ref().and_then(|k| self.sftp.get_mut(k)) {
                    r.notice = None;
                    if let Err(e) = std::fs::create_dir_all(&into) {
                        r.notice = Some(format!("{}: {e}", into.display()));
                    } else {
                        for entry in files::entries_named(&r.listing, &keys) {
                            if let Err(e) = r.download(&entry, &into) {
                                r.notice = Some(e);
                            }
                        }
                    }
                }
                None
            }
            Event::DragOut {
                queue,
                dir,
                keys,
                into,
                ticket,
            } => {
                let mut guard = ticket.borrow_mut();
                let t = &mut *guard;
                // Only while the pane still waits for it.
                let waiting = t.outcome.is_none() && t.queue.is_none();
                match key.as_ref().and_then(|k| Some((k, self.sftp.get_mut(k)?))) {
                    _ if !waiting => {}
                    // Only the files the drag offered: the Remote list may
                    // have moved (Follow terminal) while it went on.
                    Some((k, r)) if queue.as_ref() != Some(k) || r.listing.path != dir => {
                        t.outcome = Some(Err(DRAG_MOVED.into()));
                    }
                    Some((_, r)) if files::entries_named(&r.listing, &keys).len() != keys.len() => {
                        t.outcome = Some(Err(DRAG_MOVED.into()));
                    }
                    // Not connected: the jobs would only wait, and nobody
                    // can reconnect while the drop waits.
                    Some((_, r)) if !r.is_ready() => t.outcome = Some(Err(DRAG_LOST.into())),
                    Some((k, r)) => {
                        r.notice = None;
                        for entry in files::entries_named(&r.listing, &keys) {
                            match r.download(&entry, &into) {
                                Ok(id) => t.jobs.push(id),
                                Err(e) => {
                                    t.outcome = Some(Err(e));
                                    break;
                                }
                            }
                        }
                        t.queue = Some(k.clone());
                        if t.jobs.is_empty() && t.outcome.is_none() {
                            t.outcome = crate::drag_out::outcome([]);
                        }
                    }
                    None => t.outcome = Some(Err(DRAG_GONE.into())),
                }
                None
            }
            Event::DragCheck { ticket, cancel } => {
                let mut guard = ticket.borrow_mut();
                let t = &mut *guard;
                let remote = t.queue.as_ref().and_then(|q| self.sftp.get_mut(q));
                match remote {
                    Some(r) if cancel => {
                        for &id in &t.jobs {
                            r.cancel(id);
                        }
                    }
                    Some(r) if t.outcome.is_none() => {
                        t.outcome = if !r.is_ready() {
                            Some(Err(DRAG_LOST.into()))
                        } else if crate::drag_out::asking_under(r.jobs(), &t.jobs) {
                            Some(Err(
                                "Two files for the drop have the same name on Windows: \
                                 the drop was cancelled."
                                    .into(),
                            ))
                        } else {
                            // Indexed once: a drop can hold thousands of files.
                            let states: std::collections::HashMap<_, _> =
                                r.jobs().iter().map(|j| (j.id, j.state)).collect();
                            match crate::drag_out::outcome(
                                t.jobs.iter().map(|id| states.get(id).copied()),
                            ) {
                                // A folder must have come down whole, not
                                // done with a note of what it missed.
                                Some(Ok(())) if !r.all_whole(&t.jobs) => {
                                    Some(Err("Part of a folder could not be downloaded \
                                              (the queue says what): the drop was cancelled."
                                        .into()))
                                }
                                other => other,
                            }
                        };
                    }
                    Some(_) => {}
                    None if t.outcome.is_none() => t.outcome = Some(Err(DRAG_GONE.into())),
                    None => {}
                }
                None
            }
            Event::Upload { paths, dir } => {
                if let Some(key) = key {
                    self.upload_files(&key, &paths, &dir);
                }
                None
            }
            Event::MakeFolder { dir, name } => {
                if let Some(r) = self.listed_in(key.as_deref(), &dir)
                    && let Err(e) = r.make_folder(&name)
                {
                    r.notice = Some(e);
                }
                None
            }
            Event::Rename { dir, from, to } => {
                if let Some(r) = self.listed_in(key.as_deref(), &dir)
                    && let Err(e) = r.rename(&from, &to)
                {
                    r.notice = Some(e);
                }
                None
            }
            Event::Chmod { dir, keys, text } => {
                if let Some(r) = self.listed_in(key.as_deref(), &dir) {
                    for entry in files::entries_named(&r.listing, &keys) {
                        let old = entry.attrs.permissions.unwrap_or(0);
                        match files::parse_mode(&text, old, entry.attrs.is_dir()) {
                            Ok(mode) if mode == old & 0o7777 => {}
                            Ok(mode) => r.chmod(&entry.name, mode),
                            Err(e) => {
                                r.notice = Some(e);
                                break;
                            }
                        }
                    }
                }
                None
            }
            Event::Edit { dir, key: name } => {
                if let Some(queue) = key.clone() {
                    self.edit_locally(&queue, &dir, &name);
                }
                None
            }
            Event::Delete(keys) => key.and_then(|key| {
                let listing = &self.sftp.get(&key)?.listing;
                let entries = files::entries_named(listing, &keys);
                let dir = listing.path.clone();
                (!entries.is_empty()).then_some(Command::ConfirmDelete { key, dir, entries })
            }),
            Event::SetLocal(dir) => {
                self.set_download_dir(&dir);
                None
            }
            Event::PickLocal => Some(Command::PickLocalFolder(self.download_dir())),
            Event::PickUpload => key.and_then(|key| {
                let dir = self.sftp.get(&key)?.listing.path.clone();
                Some(Command::PickUpload { key, dir })
            }),
            Event::OpenLocal(dir) => Some(Command::OpenFolder(dir)),
            Event::ToggleFollow => {
                self.toggle_follow();
                None
            }
            Event::Bookmarks(all) => {
                if self.settings.bookmarks != all {
                    self.settings.bookmarks = all;
                    self.save_settings();
                }
                None
            }
            Event::Sort(sort) => {
                let text = Some(sort.to_setting());
                if self.settings.transfer_sort != text {
                    self.settings.transfer_sort = text;
                    self.save_settings();
                }
                None
            }
            Event::DeleteLocal(paths) => Some(Command::ConfirmDeleteLocal(paths)),
            Event::Arrange(a) => {
                let text = Some(a.to_setting());
                if self.settings.transfer_layout != text {
                    self.settings.transfer_layout = text;
                    self.save_settings();
                }
                None
            }
            Event::Job(id, op) => {
                if let Some(r) = key.as_ref().and_then(|k| self.sftp.get_mut(k)) {
                    match op {
                        JobOp::Pause => r.pause(id),
                        JobOp::Resume => r.resume(id),
                        JobOp::Cancel => r.cancel(id),
                        JobOp::Retry => r.retry(id),
                    }
                }
                // A cancel can end a paste's last job with nothing left
                // moving to tick the timer.
                self.flush_sftp();
                self.settle_pastes()
            }
            Event::ClearFinished => {
                if let Some(r) = key.as_ref().and_then(|k| self.sftp.get_mut(k)) {
                    r.clear_finished();
                }
                None
            }
            Event::Answer(id, choice, all) => {
                // Only the question the pane shows: not one that came up
                // on another host since.
                if let Some(r) = key.as_ref().and_then(|k| self.sftp.get_mut(k))
                    && r.question().is_some_and(|q| q.0 == id)
                {
                    r.answer(id, choice, all);
                }
                None
            }
            Event::Focused => {
                if !self.side.focused {
                    self.side.focused = true;
                }
                None
            }
            Event::Leave => {
                self.focus_terminal();
                None
            }
        };
        self.flush_sftp();
        self.refresh_chrome();
        command
    }

    /// Where an upload from pane `id` goes: the listed folder when
    /// `listed`, else the shell's directory, else the home folder, else
    /// wherever the server starts SFTP.
    fn upload_dir(&self, id: PaneId, listed: bool) -> Vec<u8> {
        let remote = self.pane_sftp_key(id).and_then(|k| self.sftp.get(&k));
        if listed
            && let Some(r) = remote
            && !r.listing.path.is_empty()
        {
            return r.listing.path.clone();
        }
        if let Some(cwd) = self.panes.get(&id).and_then(|p| p.cwd.clone()) {
            return cwd;
        }
        // No shell reports a folder on an SFTP-only login: the folder File
        // transfer shows, else the one it started in.
        if self.sftp_only(id) {
            // The listing, only when this connection asked for it and it
            // has come in: another tab's for the same login lists its own
            // folder, and a queue opened in the background, a listing
            // still loading or one that failed may show another's.
            let ours = self
                .pane_sftp_key(id)
                .and_then(|k| self.files_alias_shown.get(&k))
                .is_some_and(|a| Some(a) == self.files_ident(id).as_ref());
            if ours
                && let Some(r) = remote
                && r.listing_settled()
                && !r.listing.path.is_empty()
            {
                return r.listing.path.clone();
            }
            if let Some(folder) = self.remote_folder(id) {
                return folder.into_bytes();
            }
        }
        remote
            .and_then(|r| r.home.clone())
            .unwrap_or_else(|| b".".to_vec())
    }

    /// Queue `key`'s SFTP, when it still lists folder `dir` (the folder a
    /// change in the pane was typed for); else a notice says so.
    fn listed_in(&mut self, key: Option<&str>, dir: &[u8]) -> Option<&mut Remote> {
        let r = self.sftp.get_mut(key?)?;
        r.notice = None;
        if r.listing.path != dir {
            r.notice = Some("The folder changed meanwhile: nothing was done.".into());
            return None;
        }
        Some(r)
    }

    /// File transfer's Edit locally: downloads entry `name` of remote
    /// folder `dir` into a folder of its own, to open in an editor once
    /// it is in, and to put back on each save.
    fn edit_locally(&mut self, queue: &str, dir: &[u8], name: &[u8]) {
        let Some(r) = self.listed_in(Some(queue), dir) else {
            return;
        };
        let Some(entry) = files::entries_named(&r.listing, &[name.to_vec()])
            .into_iter()
            .next()
        else {
            return;
        };
        let remote_path = ferossh_sftp::names::join(dir, name);
        let local = match crate::edit_local::edit_folder(&std::env::temp_dir().join("FeroSSH-edit"))
        {
            Ok(folder) => folder,
            Err(e) => {
                r.notice = Some(format!("Could not make a folder to edit in: {e}"));
                return;
            }
        };
        match r.download(&entry, &local) {
            Ok(job) => {
                let file = ferossh_sftp::names::local_name(name)
                    .map(|n| local.join(n))
                    .unwrap_or_else(|| local.clone());
                self.edits
                    .start(queue, &remote_path, file, job, entry.attrs.permissions);
                self.edit_timer(true);
            }
            Err(e) => r.notice = Some(e),
        }
    }

    fn edit_timer(&mut self, on: bool) {
        if on == self.edit_timer {
            return;
        }
        self.edit_timer = on;
        // SAFETY: our window and timer.
        unsafe {
            if on {
                SetTimer(
                    Some(self.hwnd),
                    TIMER_EDIT,
                    crate::edit_local::TICK.as_millis() as u32,
                    None,
                );
            } else {
                let _ = KillTimer(Some(self.hwnd), TIMER_EDIT);
            }
        }
    }

    /// Moves the local edits on; returns the files to open in an editor.
    fn on_edit_timer(&mut self) -> Vec<PathBuf> {
        use crate::edit_local::{Action, Stamp};
        let sftp = &self.sftp;
        self.edits.retain(|q| sftp.contains_key(q));
        let actions = self.edits.tick(
            |q, id| self.sftp.get(q).and_then(|r| r.job_state(id)),
            Stamp::of,
        );
        let mut open = Vec::new();
        for action in actions {
            match action {
                Action::Open(path) => open.push(path),
                Action::PutBack {
                    queue,
                    local,
                    remote,
                    mode,
                } => {
                    let Some(r) = self.sftp.get_mut(&queue) else {
                        continue;
                    };
                    let stamp = Stamp::of(&local);
                    match (r.put_back(&local, &remote, mode), stamp) {
                        (Ok(job), Some(stamp)) => self.edits.sending(&local, job, stamp),
                        (Err(e), _) => r.notice = Some(e),
                        (Ok(_), None) => {}
                    }
                }
                Action::Notice { queue, text } => {
                    if let Some(r) = self.sftp.get_mut(&queue) {
                        r.notice = Some(text);
                    }
                }
            }
        }
        let watching = !self.edits.is_empty();
        self.edit_timer(watching);
        self.flush_sftp();
        if self.files_visible() {
            self.refresh_chrome();
        }
        open
    }

    /// Uploads `paths` to `~/.cache/ferossh/paste/` on pane `id`'s host
    /// and types their paths there once they are up (UploadAndTypePath).
    /// `temp` are local copies made for this upload, removed after it;
    /// the caller removes them on an error. Folders are left out.
    fn upload_and_type(
        &mut self,
        id: PaneId,
        paths: &[PathBuf],
        temp: Vec<PathBuf>,
    ) -> std::result::Result<(), String> {
        const ON_A_PANE: &str = "Paste or drop files on a pane that is logged in to an SSH host \
            to upload them there and type their paths.";
        self.ensure_sftp(id);
        let key = self.files_target(id).ok_or(ON_A_PANE)?;
        let remote = self.sftp.get_mut(&key).ok_or(ON_A_PANE)?;
        let mut jobs = Vec::new();
        let mut left_out = Vec::new();
        for path in paths {
            match remote.upload_into_home(path, crate::paste_upload::FOLDER) {
                Ok(job) => jobs.push(job),
                Err(e) => left_out.push(e),
            }
        }
        if !jobs.is_empty() {
            let connection = self.typing_connection(id);
            self.pastes.push(PasteBatch {
                pane: id,
                connection,
                queue: key,
                results: vec![None; jobs.len()],
                jobs,
                temp,
            });
        }
        self.flush_sftp();
        if self.files_visible() {
            self.refresh_chrome();
        }
        if left_out.is_empty() {
            Ok(())
        } else {
            Err(format!(
                "Only files are uploaded and their paths typed; use File transfer for \
                 folders. Left out:\n\n{}",
                left_out.join("\n")
            ))
        }
    }

    /// Types the paths of pasted files whose uploads have all finished;
    /// shows the queue when one of them did not make it.
    fn settle_pastes(&mut self) -> Option<Command> {
        if self.pastes.is_empty() {
            return None;
        }
        let mut failures = Vec::new();
        for mut batch in std::mem::take(&mut self.pastes) {
            let remote = self.sftp.get(&batch.queue);
            // Each result is kept as its job finishes, so clearing the
            // finished transfers meanwhile loses nothing.
            for (k, &j) in batch.jobs.iter().enumerate() {
                let state = remote.and_then(|r| r.job_state(j));
                let Some(slot) = batch.results.get_mut(k) else {
                    continue;
                };
                // Retried after it failed: wait for the new outcome.
                if state.is_some_and(|s| !s.finished()) {
                    *slot = None;
                } else if slot.is_none() {
                    let landed = remote.and_then(|r| r.landed(j)).map(<[u8]>::to_vec);
                    let note = remote
                        .and_then(|r| r.jobs().iter().find(|x| x.id == j))
                        .and_then(|x| x.note.clone());
                    *slot = Some(landed.ok_or(note));
                }
            }
            if batch.results.iter().any(Option::is_none) {
                self.pastes.push(batch);
                continue;
            }
            let mut landed = Vec::new();
            let mut why = None;
            for result in batch.results.iter().flatten() {
                match result {
                    Ok(path) => landed.push(path.clone()),
                    Err(note) => {
                        why = why.or_else(|| Some(note.clone()));
                    }
                }
            }
            let missed = batch.jobs.len() - landed.len();
            if missed == 0 {
                for t in &batch.temp {
                    let _ = std::fs::remove_file(t);
                }
            } else {
                // A failed image stays for Retry in the queue; old ones no
                // transfer needs are swept on a later paste.
                let host = batch
                    .queue
                    .rsplit_once(':')
                    .map_or(batch.queue.as_str(), |(h, _)| h);
                let reason = why
                    .flatten()
                    .map(|n| format!(": {n}"))
                    .unwrap_or_else(|| ".".into());
                let text = format!(
                    "{missed} pasted file{} did not upload to {host}{reason}",
                    plural(missed)
                );
                // Kept on the queue too, in case another dialog is open.
                if let Some(r) = self.sftp.get_mut(&batch.queue) {
                    r.notice = Some(format!("Path not typed: {text}"));
                }
                failures.push(text);
            }
            if landed.is_empty() {
                continue;
            }
            let text = crate::paste_upload::typed(&landed);
            // Only into the same logged-in session: after a reconnect the
            // pane may be at a login prompt.
            let same = batch.connection.is_some()
                && self.typing_connection(batch.pane) == batch.connection;
            let paste = self
                .panes
                .get(&batch.pane)
                .filter(|_| same)
                .map(|p| p.term.paste(&text));
            match paste {
                Some(paste) => self.input(batch.pane, paste.bytes),
                None => {
                    let shown: Vec<String> = landed.iter().map(|p| names::display(p)).collect();
                    failures.push(format!(
                        "The pane's session ended before the upload finished, so these \
                         paths were not typed:\n{}",
                        shown.join("\n")
                    ));
                }
            }
        }
        if failures.is_empty() {
            return None;
        }
        Some(Command::Notice(format!(
            "{}\n\nThe paths of files that did not upload were not typed. File transfer \
             shows the transfer queue of that host, where you can retry them.",
            failures.join("\n")
        )))
    }

    /// The connection of pane `id`'s logged-in SSH session (its tmux
    /// gateway's for a tmux pane), which typed paths must still be on.
    fn typing_connection(&self, id: PaneId) -> Option<ChannelId> {
        match self.panes.get(&self.host_pane(id)).map(|p| &p.host) {
            Some(Host::Ssh(s)) if s.state() == State::Connected => Some(s.connection),
            _ => None,
        }
    }

    /// Whether files dropped at client point (`x`, `y`) go up with their
    /// paths typed: UploadAndTypePath is on and they landed on a pane.
    fn drop_types_path(&self, x: i32, y: i32) -> Option<PaneId> {
        if !self.settings.upload_type_path {
            return None;
        }
        match self.spot(x, y) {
            Spot::Pane(id) => Some(id),
            _ => None,
        }
    }

    /// Queues uploads and shows the queue.
    fn upload_files(&mut self, key: &str, paths: &[PathBuf], dir: &[u8]) {
        let Some(remote) = self.sftp.get_mut(key) else {
            return;
        };
        for path in paths {
            if let Err(e) = remote.upload(path, dir) {
                remote.notice = Some(e);
            }
        }
        self.flush_sftp();
        if !self.files_visible() {
            self.show_side(SideView::Files, false);
        }
        self.refresh_chrome();
    }

    /// Where files dropped at client point (`x`, `y`) go: the queue key,
    /// a label for the prompt, and the remote folder.
    fn drop_target(
        &mut self,
        x: i32,
        y: i32,
    ) -> std::result::Result<(String, Vec<u8>), &'static str> {
        const ON_A_PANE: &str =
            "Drop files on a pane that is logged in to an SSH host to upload them there.";
        let (id, into) = match self.spot(x, y) {
            Spot::Pane(id) => (id, None),
            Spot::Side(..) if self.files_visible() => {
                let mut pt = POINT { x, y };
                // SAFETY: a plain conversion for our own window.
                unsafe {
                    let _ = windows::Win32::Graphics::Gdi::ClientToScreen(self.hwnd, &mut pt);
                }
                match files_panel::drop_at(pt) {
                    files_panel::DropAt::Remote(folder) => (self.focused_id(), Some(folder)),
                    files_panel::DropAt::Local => {
                        return Err("Drop files on the Remote list to upload them.");
                    }
                    files_panel::DropAt::Pane => (self.focused_id(), Some(None)),
                }
            }
            _ => return Err(ON_A_PANE),
        };
        self.ensure_sftp(id);
        let key = self.files_target(id).ok_or(ON_A_PANE)?;
        let listed = into.is_some() && self.files_key.as_deref() == Some(&key);
        let dir = self.upload_dir(id, listed);
        Ok(match into.flatten() {
            Some(folder) if listed => names::join(&dir, &folder),
            _ => dir,
        })
        .map(|dir| (key, dir))
    }

    /// Transfers not yet done, failed, skipped or cancelled.
    fn unfinished_transfers(&self) -> usize {
        self.sftp
            .values()
            .flat_map(Remote::jobs)
            .filter(|j| j.parent.is_none() && !j.state.finished())
            .count()
    }

    /// SSH sessions logged in, in all tabs or in one.
    fn live_sessions(&self, tab: Option<usize>) -> usize {
        let ids = match tab {
            Some(i) => self
                .ws
                .tabs
                .get(i)
                .map(|t| t.root.panes())
                .unwrap_or_default(),
            None => {
                let mut all = self.ws.all_panes();
                all.extend(self.ws.hidden());
                all
            }
        };
        // Leaving the window only detaches tmux; closing a tab closes its
        // tmux windows.
        ids.iter()
            .filter_map(|id| self.panes.get(id))
            .filter(|p| {
                let open = p.connected()
                    || matches!(p.host, Host::Serial { port: Some(_), .. })
                    || matches!(&p.host, Host::Telnet(s) if s.state() == State::Connected)
                    || matches!(&p.host, Host::Winrm(s) if s.state() == State::Connected);
                open && (tab.is_some() || p.gateway().is_none())
            })
            .count()
    }

    fn close_tab(&mut self, i: usize) -> Option<Command> {
        let ids = self.ws.tabs.get(i).map(|t| t.root.panes())?;
        for id in ids {
            if let Some(c) = self.close_pane(id) {
                return Some(c);
            }
        }
        None
    }
}

/// What a menu item's text becomes: its shortcut after a tab (none:
/// the tab and what followed it go), or a whole new text.
enum MenuText {
    Key(Option<String>),
    Whole(String),
}

/// Sets the shortcut part of every item of `menu` and its submenus as
/// `text` says for its command id.
fn menu_key_labels(menu: HMENU, text: &dyn Fn(u32) -> MenuText) {
    use windows::Win32::UI::WindowsAndMessaging::{MENUITEMINFOW, MIIM_STRING, SetMenuItemInfoW};
    // SAFETY: a menu handle of ours.
    let count = unsafe { GetMenuItemCount(Some(menu)) };
    for pos in 0..count.max(0) {
        let at = pos as u32;
        // SAFETY: our menu and a position in it.
        let (state, sub) =
            unsafe { (GetMenuState(menu, at, MF_BYPOSITION), GetSubMenu(menu, pos)) };
        // A submenu first: its state carries its item count in the high
        // byte, which can look like the separator flag.
        if !sub.is_invalid() {
            menu_key_labels(sub, text);
            continue;
        }
        if state & MF_SEPARATOR.0 != 0 {
            continue;
        }
        // SAFETY: as above.
        let id = unsafe { GetMenuItemID(menu, pos) };
        if id == u32::MAX || !bindable(id) {
            continue;
        }
        let now = menu_text(menu, at);
        let base = now.split_once('\t').map_or(now.as_str(), |(b, _)| b);
        let new = match text(id) {
            MenuText::Key(Some(k)) => format!("{base}\t{k}"),
            MenuText::Key(None) => base.to_owned(),
            MenuText::Whole(t) => t,
        };
        if new == now {
            continue;
        }
        let mut wide_text: Vec<u16> = new.encode_utf16().chain(std::iter::once(0)).collect();
        let mii = MENUITEMINFOW {
            cbSize: std::mem::size_of::<MENUITEMINFOW>() as u32,
            fMask: MIIM_STRING,
            dwTypeData: windows::core::PWSTR(wide_text.as_mut_ptr()),
            ..Default::default()
        };
        // SAFETY: our menu; the text lives through the call, which copies it.
        unsafe {
            let _ = SetMenuItemInfoW(menu, at, true, &mii);
        }
        ui_theme::note_text(menu, at, &new);
    }
}

/// The text of the item at `pos` of `menu`, also while it is owner-drawn
/// by us: then the recorded name, which is what the menu shows (Windows
/// may report none, or an older one).
fn menu_text(menu: HMENU, pos: u32) -> String {
    if let Some(kept) = ui_theme::owned_text(menu, pos).filter(|t| !t.is_empty()) {
        return kept;
    }
    let mut buf = [0u16; 256];
    // SAFETY: our menu, a position in it and a local buffer.
    let len = unsafe { GetMenuStringW(menu, pos, Some(&mut buf), MF_BYPOSITION) };
    let len = usize::try_from(len).unwrap_or(0).min(buf.len());
    String::from_utf16_lossy(buf.get(..len).unwrap_or_default())
}

/// The command palette's actions: every item of `menu` and its submenus
/// that is not greyed out, with the menus it is in.
fn menu_entries(menu: HMENU) -> Vec<palette::Entry> {
    menu_items(menu, false)
}

/// Every item of `menu` and its submenus, with the menus it is in;
/// greyed-out ones too with `greyed`.
fn menu_items(menu: HMENU, greyed: bool) -> Vec<palette::Entry> {
    fn walk(menu: HMENU, path: &mut Vec<String>, out: &mut Vec<palette::Entry>, greyed: bool) {
        // SAFETY: a menu handle of ours.
        let count = unsafe { GetMenuItemCount(Some(menu)) };
        for pos in 0..count.max(0) {
            let at = pos as u32;
            // SAFETY: our menu and a position in it.
            let (state, sub) =
                unsafe { (GetMenuState(menu, at, MF_BYPOSITION), GetSubMenu(menu, pos)) };
            let text = menu_text(menu, at);
            // A submenu first: its state carries its item count in the
            // high byte, which can look like the separator flag.
            if !sub.is_invalid() {
                path.push(text);
                walk(sub, path, out, greyed);
                path.pop();
                continue;
            }
            if state & MF_SEPARATOR.0 != 0 {
                continue;
            }
            if !greyed && state & (MF_GRAYED.0 | MF_DISABLED.0) != 0 {
                continue;
            }
            // SAFETY: as above.
            let id = unsafe { GetMenuItemID(menu, pos) };
            let on = state & MF_CHECKED.0 != 0;
            out.push(palette::Entry::action(path, &text, id, on));
        }
    }
    let mut out = Vec::new();
    walk(menu, &mut Vec::new(), &mut out, greyed);
    out
}

/// The window shortcut for a key, as a command id (Settings > Key
/// bindings). Tab and pane keys only apply when there is more than one tab
/// or pane, so that otherwise the keys reach the terminal.
fn shortcut(keys: &Keymap, vk: VIRTUAL_KEY, m: Mods, tabs: bool, split: bool) -> Option<u32> {
    keys.lookup(keymap::chord(vk.0, m.ctrl, m.alt, m.shift), tabs, split)
}

/// Follow-up actions that call into Win32 functions which send messages to
/// the window or open dialogs, so they run after the state borrow is
/// released.
/// Whom a job handed to the signing broker is for.
#[derive(Debug, Clone, Copy)]
enum BrokerFor {
    /// The login on this channel.
    Login(ChannelId),
    /// A forwarded agent.
    Agent(crate::agent_fwd::For),
}

/// Other tmux clients keep a gateway's windows small: the question to
/// ask, kept while another dialog is open.
#[derive(Debug, Clone)]
struct CrowdedOffer {
    gateway: PaneId,
    /// The tmux session asked about, its name and its host, for the
    /// question (it may be another tab's connection).
    session: ferossh_tmuxcc::SessionId,
    name: String,
    host: String,
    have: (u16, u16),
    want: (u16, u16),
    others: u32,
}

enum Command {
    Id(u32),
    /// A Windows notification about a pane ([`crate::toast`]).
    Toast {
        /// The pane that wants the user.
        pane: PaneId,
        title: String,
        body: String,
        waiting: String,
    },
    /// The notification icon goes: the user is back.
    HideToast,
    /// Window > Workspaces > Save layout as workspace: asks for a name.
    SaveWorkspace,
    /// Window > Workspaces > Open workspace file: asks which.
    OpenWorkspaceFile,
    /// Workspace `name` runs `lines` as it opens, which this PC has not
    /// allowed yet: ask before opening it.
    ConfirmWorkspace {
        name: String,
        ws: Box<wsfile::Workspace>,
        /// Each line as shown, and what allowing it keeps.
        lines: Vec<(String, String)>,
    },
    /// The Connection manager's F2 on a workspace: its file in the editor.
    EditWorkspace(String),
    /// A workspace's pane with the Production theme is about to run its
    /// script and command: ask first.
    ConfirmWorkspaceStart {
        pane: PaneId,
        label: String,
        script: Option<String>,
        command: Option<String>,
        /// Which shell of the pane it was asked for.
        shell: u64,
    },
    /// A security rule asks before pane `pane` connects to `destination`.
    ConfirmConnect {
        pane: PaneId,
        /// The question's number, so a late answer is told apart.
        token: u64,
        destination: String,
        /// Where it goes, as resolved when asked.
        endpoint: String,
        extras: Extras,
    },
    /// A security rule requires pane `0`'s session log, which failed.
    LogRequired(PaneId),
    /// Tools > New SSH key: the window that asks what to make.
    NewKey,
    /// Settings > Key bindings: the window that changes them.
    KeyBindings,
    /// File > Import and export > Export connections, Import encrypted connections and the
    /// Master password items, by menu id.
    Vault(u32),
    /// The new key is made, or why not; `host` is what the pane it was
    /// asked from is logged in to, to offer copying it there.
    KeyMade {
        path: PathBuf,
        result: std::result::Result<String, String>,
        pane: PaneId,
        host: Option<String>,
    },
    /// Session > Copy public key to this server: picks the `.pub` file.
    CopyKey {
        pane: PaneId,
        host: String,
    },
    /// A forwarded agent asks for a signature: ask the user.
    AskAgentSign,
    /// Window > Standby window > Press a new hotkey: says what to do,
    /// then the next key pressed becomes the hotkey.
    PickStandbyHotkey,
    /// An information box.
    Message(String),
    /// Help > Check for updates found its answer; `asked` is false for
    /// the weekly check, which only speaks up about a new release.
    UpdateFound {
        outcome: crate::update::Outcome,
        asked: bool,
    },
    /// File > Exit or the close box: asks first when sessions are open.
    Exit,
    /// The last pane closed: the window goes.
    Destroy,
    SetMenuVisible(bool),
    /// Settings > Full screen and F11: in or out of full screen.
    FullScreen,
    Copy,
    Paste,
    /// The host asked to put text on the clipboard.
    ClipboardWrite(String),
    /// Ctrl+click on an OSC 8 link; the target is unchecked.
    OpenLink(String),
    /// A port-forward preview's address, forwarded here: opened in the
    /// browser without asking, as the user just clicked for it.
    OpenPreview(String),
    UpdateTitle,
    Bell,
    /// Session > Replace host key: two confirmations, then replace.
    ReplaceHostKey,
    OpenFolder(PathBuf),
    /// Settings > Font on a free font that is not installed.
    FontPage {
        family: &'static str,
        url: &'static str,
    },
    /// The tab strip's close mark: asks first when sessions are open.
    CloseTab(usize),
    /// File > Import and export > Import connections: the side pane's import page.
    ImportSessions,
    /// File > Import and export > Import scripts: the side pane's import page for snippets.
    ImportSnippets,
    /// Session > Scripts > Write built-in scripts: asks, then writes the
    /// library into the scripts folder (see config::library).
    WriteLibrary,
    /// Session > Logs and recordings > Check a log: the file picker, then the chain check.
    VerifyLog,
    /// Session > Logs and recordings > Play a recording: pick a `.cast` file.
    PlayCast,
    /// The import page's file picker.
    PickImportFile,
    SaveLook,
    /// Settings > Custom themes > Save this look as a theme.
    SaveTheme,
    /// Edit > Clear command history for all hosts, once confirmed.
    ClearAllHistory,
    /// A message box with this text.
    Notice(String),
    /// A direct Remote Desktop connection a security rule asks about
    /// first: mstsc starts after Yes.
    ConfirmRdp {
        name: String,
        addr: String,
        size: Option<(u16, u16)>,
        clipboard: bool,
    },
    /// A desktop through an SSH connection (pane `pane`'s) a security
    /// rule asks about first: the tunnel opens after Yes.
    ConfirmDesktop {
        pane: PaneId,
        desktop: PendingDesktop,
    },
    /// Ask, then delete `entries` in folder `dir` of `key`'s host (when
    /// it is still the listed one).
    ConfirmDelete {
        key: String,
        dir: Vec<u8>,
        entries: Vec<DirEntry>,
    },
    /// Asks, then moves these local files and folders to the Recycle Bin.
    ConfirmDeleteLocal(Vec<PathBuf>),
    /// The folder picker for the file view's Local PC section, starting
    /// in this folder.
    PickLocalFolder(PathBuf),
    /// The file picker, then upload into `dir` on `key`'s host.
    PickUpload {
        key: String,
        dir: Vec<u8>,
    },
    /// The file picker, for the server's `rz` in pane `pane`.
    PickZmodem {
        pane: PaneId,
        channel: ChannelId,
    },
    /// Asks whether to take the files the server's `sz` in pane `pane`
    /// (connected to `host`) sends, into `folder`.
    ConfirmZmodemReceive {
        pane: PaneId,
        channel: ChannelId,
        host: String,
        folder: PathBuf,
    },
    /// Other tmux clients keep gateway `gateway`'s windows small: offer
    /// to detach them.
    TmuxCrowded(CrowdedOffer),
    /// Session > tmux > Share this session, from gateway pane `.0`.
    TmuxShare(PaneId),
    /// Session > tmux > Join a shared session, from gateway pane `.0`.
    TmuxJoin(PaneId),
    /// A menu of tmux sessions to switch gateway `gateway`'s client to.
    TmuxPicker {
        gateway: PaneId,
        names: Vec<String>,
    },
    /// The connection manager's right-click menu, on this host if any.
    /// The connection manager's right-click menu: on this host, or on
    /// this saved search's smart folder.
    /// With two or more hosts selected, the menu acts on them all.
    SessionMenu(Option<String>, Option<String>, Vec<String>),
    /// A tab's right-click menu.
    TabMenu(usize),
    /// Ask, then remove this saved session.
    DeleteSession(String),
    /// Ask, then remove this saved workspace's file.
    DeleteWorkspace(String),
    /// The session manager's Delete: ask (when it is still open, or the
    /// last pane), then close the session's pane.
    CloseSession {
        pane: PaneId,
        label: String,
        live: bool,
        last: bool,
    },
    /// Ask this; on yes, run the command.
    Confirm {
        text: String,
        then: Box<Command>,
    },
    /// Close tab `i` without asking (it was asked already).
    CloseTabNow(usize),
    /// Ask, then remove the snippet at this index.
    DeleteSnippet(usize),
    /// The user clicked the notification of a coding agent asking a
    /// yes-or-no question: asks them for the answer.
    AnswerAgent {
        pane: PaneId,
        agent: String,
        host: String,
        production: bool,
        question: crate::agents::Question,
    },
    /// A coding agent is about to start from a pane with the Production
    /// theme: asks first.
    ConfirmAgent {
        pane: PaneId,
        command: String,
        host: String,
    },
    /// A snippet is about to go to a pane with the Production theme: asks
    /// first.
    ConfirmSnippet {
        name: String,
        steps: Vec<Step>,
        panes: Vec<PaneId>,
        /// The Production panes' hosts.
        production: Vec<String>,
    },
    /// A run on picked hosts includes hosts with the Production theme:
    /// asks first.
    ConfirmRun {
        name: String,
        hosts: Vec<Place>,
        run: Run,
        /// The Production hosts.
        production: Vec<String>,
    },
    /// Ask before a password manager command gets a login script's
    /// secret the first time (`name`; `None` is the login password).
    ConfirmSecretTool {
        pane: PaneId,
        line: String,
        name: Option<String>,
    },
    /// The file picker for the session form's key file.
    PickKey,
    /// Ask before a password manager command runs the first time.
    ConfirmPasswordTool {
        pane: PaneId,
        line: String,
    },
    /// Ask before opening VNC connection `name`, whose desktop `target`
    /// is another machine than its SSH server `via`.
    ApprovePlainVnc {
        /// What the approval is kept under in `plain_vnc_ok`.
        key: String,
        name: String,
        target: String,
        via: String,
        split: bool,
    },
    /// Ask before running a host's `ProxyCommand` for the first time.
    ApproveProxy {
        pane: PaneId,
        connection: ChannelId,
        tunnel: ChannelId,
        command: ProxyCommand,
        input: std::sync::mpsc::Receiver<Message>,
    },
}

/// Moves `paths` to the Recycle Bin (Windows warns first when one cannot
/// go there and would be deleted for good).
fn recycle(hwnd: HWND, paths: &[PathBuf]) -> std::result::Result<(), String> {
    use std::os::windows::ffi::OsStrExt;
    use windows::Win32::UI::Shell::{
        FO_DELETE, FOF_ALLOWUNDO, FOF_NO_CONNECTED_ELEMENTS, FOF_NOCONFIRMATION,
        FOF_WANTNUKEWARNING, SHFILEOPSTRUCTW, SHFileOperationW,
    };
    // Each path ends in a NUL, and the list in another. Only a full path
    // goes to the Recycle Bin (a relative one is deleted for good), and
    // `absolute` keeps a link itself rather than what it points to.
    let mut from: Vec<u16> = Vec::new();
    for p in paths {
        let full = std::path::absolute(p).map_err(|e| format!("Delete did not start ({e})."))?;
        from.extend(full.as_os_str().encode_wide().filter(|&c| c != 0));
        from.push(0);
    }
    from.push(0);
    let mut op = SHFILEOPSTRUCTW {
        hwnd,
        wFunc: FO_DELETE,
        pFrom: PCWSTR(from.as_ptr()),
        // Only what was asked about: not `page_files` with `page.html`.
        fFlags: (FOF_ALLOWUNDO.0
            | FOF_NOCONFIRMATION.0
            | FOF_WANTNUKEWARNING.0
            | FOF_NO_CONNECTED_ELEMENTS.0) as u16,
        ..Default::default()
    };
    // SAFETY: a valid, double-NUL-terminated list living through the
    // call, and our own window for any dialog it shows.
    let code = unsafe { SHFileOperationW(&mut op) };
    if code != 0 {
        Err(format!("Delete did not finish (error {code:#x})."))
    } else if op.fAnyOperationsAborted.as_bool() {
        Err("Delete was cancelled; some items may be left.".into())
    } else {
        Ok(())
    }
}

/// A modal message box; `None` if another one is already open.
fn dialog(hwnd: HWND, text: &str, style: MESSAGEBOX_STYLE) -> Option<MESSAGEBOX_RESULT> {
    if DIALOG_OPEN.get() {
        return None;
    }
    DIALOG_OPEN.set(true);
    // SAFETY: our window and valid strings. The box runs a modal loop that
    // dispatches messages back to the window; no state borrow is held.
    let result = unsafe { MessageBoxW(Some(hwnd), &HSTRING::from(text), w!("FeroSSH"), style) };
    DIALOG_OPEN.set(false);
    Some(result)
}

/// Puts the window in front, shown and restored, for a click on its
/// notification.
/// Brings the window to the front; whether it is there now.
fn bring_forward(hwnd: HWND) -> bool {
    // SAFETY: our window. Windows lets the window the user clicked a
    // notification of come forward.
    unsafe {
        if !IsWindowVisible(hwnd).as_bool() {
            let _ = ShowWindow(hwnd, SW_SHOW);
        }
        if IsIconic(hwnd).as_bool() {
            let _ = ShowWindow(hwnd, SW_RESTORE);
        }
        let _ = SetForegroundWindow(hwnd);
        GetForegroundWindow() == hwnd
    }
}

fn run_commands(hwnd: HWND, commands: Vec<Command>) {
    for command in commands {
        run_command(hwnd, command);
    }
}

/// Session > tmux > Attach tmux on a pane that is not at a logged-in shell.
const NOT_IN_SHELL: &str = "Log in to an SSH host in this pane first; Attach tmux types \
                            `tmux -CC new-session -A -s main` at its shell (the session name \
                            comes from the host's Tmux setting in ferossh.conf).";

/// The size, in pixels, a remote desktop in a pane at `rect` should have.
fn desktop_size(rect: Rect) -> (u16, u16) {
    let side = |v: i32| u16::try_from(v.clamp(200, 8192)).unwrap_or(1024);
    (side(rect.w), side(rect.h))
}

/// Session > Remote desktop > Open virtual desktop on a pane that is not logged in.
/// Where Show what changed works.
const DIFF_HOW: &str = "Show what changed works in a pane logged in to a server over SSH (or \
     a tmux pane there), in a folder of a git repository.";
/// Scrollback a diff tab keeps beyond [`crate::diff::MAX_ROWS`].
const DIFF_SPARE_ROWS: usize = 1000;

/// A colour as the diff view's red and green take it.
fn rgb(c: Rgb) -> [u8; 3] {
    [c.r, c.g, c.b]
}

const NO_COPY_HOST: &str = "Log in to an SSH host in this pane first. Copy public key to this \
                            server adds a key to ~/.ssh/authorized_keys on that host, so it \
                            can log in with the key next time.";

const NO_VDESK_HOST: &str = "Log in to an SSH host in this pane first. Open virtual desktop \
                             starts Xvfb and x11vnc on that host and shows the desktop through \
                             the connection.";

/// Where a virtual desktop's x11vnc listens, as the server sees it.
const VDESK_HOST: &str = "127.0.0.1";
const NO_APP_HOST: &str = "Log in to an SSH host in this pane first. Run remote app starts the \
                           program on that host and shows its windows here.";

/// What to tell the user when a remote app ended: nothing when its
/// program simply exited.
fn remote_app_note(what: &str, label: &str, end: &ferostream_client::win32::End) -> Option<String> {
    if let Some(id) = &end.left_running {
        return Some(format!(
            "{what} still runs on {label} (session {id}). Session > Remote apps > Reattach \
             remote app brings its windows back."
        ));
    }
    let problem = end.problem.as_deref()?;
    let mut text = format!("{what} on {label} stopped.\n\n{problem}");
    if problem.contains("ferostream-agent") && problem.contains("not found") {
        text.push_str(
            "\n\nThe host has no FeroStream agent. Turn on Session > Remote apps > Copy the \
             agent to hosts, and keep ferostream-agent next to ferossh.exe.",
        );
    }
    if problem.contains("Xvfb") {
        text.push_str(
            "\n\nThe host needs Xvfb: sudo apt install xvfb (Fedora: xorg-x11-server-Xvfb).",
        );
    }
    Some(text)
}

/// Session > Remote desktop > Open remote desktop on a pane that is not logged in.
const NO_DESKTOP_HOST: &str = "Log in to an SSH host in this pane first. Open remote desktop \
                               tunnels the host's Remote Desktop (RDP) port over that \
                               connection and opens Remote Desktop Connection on it.";

/// The message for file transfer without a logged-in pane.
const NOT_CONNECTED: &str = "Log in to an SSH host in this pane first; files go to and from \
                             the host of the focused pane.";

/// Starts Windows' Remote Desktop Connection on `addr`, from System32 so
/// nothing earlier on PATH stands in for it.
/// The keyboard layout's language id (0x409 for US English), which an
/// RDP server needs to read the scan codes the viewer sends.
#[cfg(feature = "viewer")]
fn keyboard_layout() -> u32 {
    // SAFETY: no arguments to get wrong; 0 is this thread.
    let hkl = unsafe { windows::Win32::UI::Input::KeyboardAndMouse::GetKeyboardLayout(0) };
    (hkl.0 as usize & 0xffff) as u32
}

/// Starts a VNC viewer installed on this PC on `addr` (`host:port`), and
/// names it; `None` when none was found. TigerVNC, TightVNC, RealVNC and
/// UltraVNC all take `host::port`.
fn launch_vnc_viewer(addr: &str, (to_host, from_host): (bool, bool)) -> Option<&'static str> {
    const KNOWN: [(&str, &str); 5] = [
        ("TigerVNC\\vncviewer.exe", "TigerVNC Viewer"),
        ("TightVNC\\tvnviewer.exe", "TightVNC Viewer"),
        ("RealVNC\\VNC Viewer\\vncviewer.exe", "RealVNC Viewer"),
        ("uvnc bvba\\UltraVNC\\vncviewer.exe", "UltraVNC Viewer"),
        ("UltraVNC\\vncviewer.exe", "UltraVNC Viewer"),
    ];
    let target = match addr.rsplit_once(':') {
        Some((host, port)) => format!("{host}::{port}"),
        None => addr.to_owned(),
    };
    let roots: Vec<PathBuf> = ["ProgramFiles", "ProgramFiles(x86)", "ProgramW6432"]
        .iter()
        .filter_map(std::env::var_os)
        .map(PathBuf::from)
        .chain(std::env::var_os("LOCALAPPDATA").map(|d| PathBuf::from(d).join("Programs")))
        .collect();
    let installed = KNOWN.iter().find_map(|(path, name)| {
        roots
            .iter()
            .map(|r| r.join(path))
            .find(|p| p.is_file())
            .map(|p| (p, *name))
    });
    // Then the PATH, looked up here so no current folder is searched.
    let found = installed.or_else(|| {
        let path = std::env::var_os("PATH")?;
        std::env::split_paths(&path).find_map(|dir| {
            [
                ("vncviewer.exe", "the VNC viewer"),
                ("tvnviewer.exe", "TightVNC Viewer"),
            ]
            .iter()
            .map(|(exe, name)| (dir.join(exe), *name))
            .find(|(p, _)| p.is_absolute() && p.is_file())
        })
    });
    let (exe, name) = found?;
    let mut c = std::process::Command::new(exe);
    // TigerVNC's viewer takes the clipboard's ways; for the others the
    // virtual desktop's server enforces them.
    if name == "TigerVNC Viewer" {
        c.arg(format!("-SendClipboard={}", u8::from(to_host)))
            .arg(format!("-AcceptClipboard={}", u8::from(from_host)));
    }
    c.arg(target).spawn().ok().map(|_| name)
}

/// Opens Remote Desktop Connection on `addr`, at `size` when one is set
/// (else at its own default). Its own settings share the clipboard; with
/// `clipboard` false it opens a connection file that turns that off
/// (mstsc has no switch for it on its command line).
fn launch_rdp_client(
    addr: &str,
    size: Option<(u16, u16)>,
    clipboard: bool,
) -> std::io::Result<std::process::Child> {
    let root = std::env::var_os("SystemRoot").unwrap_or_else(|| "C:\\Windows".into());
    let mstsc = PathBuf::from(root).join("System32").join("mstsc.exe");
    let mut c = std::process::Command::new(mstsc);
    if !clipboard {
        let file = app_dir().join("rdp").join("no-clipboard.rdp");
        write_app_file(&file, &rdp_file(addr, size))?;
        c.arg(file);
    }
    c.arg(format!("/v:{addr}"));
    if let Some((w, h)) = size {
        c.arg(format!("/w:{w}")).arg(format!("/h:{h}"));
    }
    c.spawn()
}

/// A Remote Desktop Connection file for `addr` without the clipboard.
fn rdp_file(addr: &str, size: Option<(u16, u16)>) -> String {
    let addr: String = addr.chars().filter(|c| !c.is_control()).collect();
    let mut text = format!("full address:s:{addr}\r\nredirectclipboard:i:0\r\n");
    if let Some((w, h)) = size {
        text.push_str(&format!(
            "screen mode id:i:1\r\ndesktopwidth:i:{w}\r\ndesktopheight:i:{h}\r\n"
        ));
    }
    text
}

/// The key of a host's transfer queue: one per user, host name and port.
fn sftp_key(t: &Target) -> String {
    format!("{}@{}:{}", t.user, t.hostname.to_ascii_lowercase(), t.port)
}

/// Who `t` reaches and how: its [`sftp_key`], the name it was opened by
/// and the hops on the way. Two connections with the same key may still
/// reach different machines through different jump hosts.
fn route_key(t: &Target) -> String {
    let jumps: Vec<String> = t.jumps.iter().map(route_key).collect();
    format!(
        "{} {} {:?} [{}] {:?} {:?}",
        sftp_key(t),
        t.alias,
        t.host_key_alias.as_deref().map(str::to_ascii_lowercase),
        jumps.join(", "),
        t.proxy_command,
        t.proxy_server
    )
}

/// Files pasted or dropped on a pane together, uploading to its host:
/// their paths are typed there, in order, once all are done.
struct PasteBatch {
    pane: PaneId,
    /// The pane's session when the paste began: paths are typed only
    /// while it is still the one logged in.
    connection: Option<ChannelId>,
    queue: String,
    jobs: Vec<ferossh_sftp::JobId>,
    /// Each job's outcome once it finished: where it landed, or the
    /// queue's note on why not.
    results: Vec<Option<std::result::Result<Vec<u8>, Option<String>>>>,
    /// Pasted images saved to a local file for the upload, removed once
    /// it succeeded.
    temp: Vec<PathBuf>,
}

/// The paths of files dropped from Explorer, and where they were dropped.
fn dropped_files(drop: HDROP) -> (Vec<PathBuf>, POINT) {
    let mut paths = Vec::new();
    let mut at = POINT::default();
    // SAFETY: `drop` is the handle WM_DROPFILES carried; each buffer is
    // sized from the length the first call reports, and DragFinish frees
    // the handle once.
    unsafe {
        let count = DragQueryFileW(drop, u32::MAX, None);
        for i in 0..count {
            let len = DragQueryFileW(drop, i, None) as usize;
            let mut buf = vec![0u16; len + 1];
            let got = DragQueryFileW(drop, i, Some(&mut buf)) as usize;
            if let Some(name) = buf.get(..got) {
                paths.push(PathBuf::from(String::from_utf16_lossy(name)));
            }
        }
        let _ = DragQueryPoint(drop, &mut at);
        DragFinish(drop);
    }
    (paths, at)
}

/// Files dropped on the window: asks, then uploads them to the host of
/// the pane they landed on.
fn drop_files(hwnd: HWND, drop: HDROP) {
    let (paths, at) = dropped_files(drop);
    upload_dropped(hwnd, &paths, at);
}

/// Local files let go at client point `at`, from Explorer or dragged out
/// of File transfer's Local list: asks, then uploads them to the host of
/// the pane they landed on.
fn upload_dropped(hwnd: HWND, paths: &[PathBuf], at: POINT) {
    if paths.is_empty() {
        return;
    }
    // UploadAndTypePath: on a pane, no question; the paths are typed.
    if let Some(id) = with_window(|w| w.drop_types_path(at.x, at.y)).flatten() {
        if !confirm_agent_files(hwnd, id, paths.len()) {
            return;
        }
        let done = with_window(|w| w.upload_and_type(id, paths, Vec::new()))
            .unwrap_or(Err("FeroSSH is busy; drop the files again.".into()));
        if let Err(why) = done {
            dialog(hwnd, &why, MB_OK | MB_ICONINFORMATION);
        }
        return;
    }
    let target = with_window(|w| w.drop_target(at.x, at.y))
        .unwrap_or(Err("FeroSSH is busy; drop the files again."));
    let (key, dir) = match target {
        Ok(t) => t,
        Err(why) => {
            dialog(hwnd, why, MB_OK | MB_ICONINFORMATION);
            return;
        }
    };
    let what = match paths {
        [one] => format!(
            "\"{}\"",
            one.file_name()
                .map(|n| n.to_string_lossy().into_owned())
                .unwrap_or_default()
        ),
        many => format!("{} items", many.len()),
    };
    let host = key.rsplit_once(':').map_or(key.as_str(), |(h, _)| h);
    let text = format!("Upload {what} to {} on {host}?", names::display(&dir));
    if dialog(hwnd, &text, MB_YESNO | MB_ICONQUESTION) == Some(IDYES) {
        with_window(|w| w.upload_files(&key, paths, &dir));
    }
}

/// Paste with no text on the clipboard, when UploadAndTypePath is on:
/// files copied in Explorer, or else an image, go up to the focused
/// pane's host and their paths are typed there.
fn paste_files(hwnd: HWND) {
    // Not while a side pane has the keyboard: it takes text only.
    if with_window(|w| w.settings.upload_type_path && !(w.side.visible && w.side.focused))
        != Some(true)
    {
        return;
    }
    let Some(id) = with_window(|w| w.focused_id()) else {
        return;
    };
    let files = clipboard::get_files(hwnd);
    let (paths, temp) = if files.is_empty() {
        let png = match clipboard::get_png(hwnd) {
            Some(png) => Ok(png),
            None => match clipboard::get_dib(hwnd) {
                Some(dib) => crate::paste_upload::png_from_dib(&dib),
                None => return,
            },
        };
        // Images an unfinished transfer still reads are never swept.
        let needed = with_window(|w| {
            w.sftp
                .values()
                .flat_map(Remote::jobs)
                .filter(|j| !j.state.finished())
                .map(|j| j.local.clone())
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
        match png.and_then(|png| save_pasted_image(&png, &needed)) {
            Ok(path) => (vec![path.clone()], vec![path]),
            Err(why) => {
                dialog(hwnd, &why, MB_OK | MB_ICONINFORMATION);
                return;
            }
        }
    } else {
        (files, Vec::new())
    };
    if !confirm_agent_files(hwnd, id, paths.len()) {
        for t in &temp {
            let _ = std::fs::remove_file(t);
        }
        return;
    }
    let done = with_window(|w| w.upload_and_type(id, &paths, temp.clone()))
        .unwrap_or(Err("FeroSSH is busy; paste again.".into()));
    if let Err(why) = done {
        // Nothing queued keeps a local copy.
        let queued = with_window(|w| w.pastes.iter().any(|b| b.temp == temp)).unwrap_or(false);
        if !queued {
            for t in &temp {
                let _ = std::fs::remove_file(t);
            }
        }
        dialog(hwnd, &why, MB_OK | MB_ICONINFORMATION);
    }
}

/// Pasted or dropped files are about to go up and have their paths typed
/// into pane `id`: when it runs a coding agent on a Production host (and
/// Confirm scripts and agents on Production hosts is on), asks first.
/// Returns whether to go on.
fn confirm_agent_files(hwnd: HWND, id: PaneId, count: usize) -> bool {
    let production = with_window(|w| w.production_agents(&[id])).unwrap_or_default();
    let Some(agent) = production.first() else {
        return true;
    };
    let text = format!(
        "Upload {count} file{} and give {} to the coding agent {agent}, which has the \
         Production theme?",
        plural(count),
        if count == 1 { "it" } else { "them" },
    );
    dialog(hwnd, &text, MB_YESNO | MB_ICONWARNING | MB_DEFBUTTON2) == Some(IDYES)
}

/// Saves a pasted image as a PNG in FeroSSH's temporary folder, under a
/// name from the local time, for uploading.
fn save_pasted_image(png: &[u8], needed: &[PathBuf]) -> std::result::Result<PathBuf, String> {
    let dir = std::env::temp_dir().join("FeroSSH-paste");
    std::fs::create_dir_all(&dir).map_err(|e| format!("{}: {e}", dir.display()))?;
    // Images whose upload failed stay for Retry; after a day they go.
    if let Ok(entries) = std::fs::read_dir(&dir) {
        let day = std::time::Duration::from_secs(24 * 60 * 60);
        for e in entries.flatten() {
            let old = e
                .metadata()
                .and_then(|m| m.modified())
                .ok()
                .and_then(|t| t.elapsed().ok())
                .is_some_and(|age| age > day);
            if old && !needed.contains(&e.path()) {
                let _ = std::fs::remove_file(e.path());
            }
        }
    }
    let name = crate::paste_upload::image_name(local_time());
    let path = dir.join(&name);
    // Two pastes in one second: the later one gets a number.
    let path = if path.exists() {
        (2..100)
            .map(|n| {
                dir.join(
                    names::numbered(&name, n)
                        .replace(' ', "-")
                        .replace(['(', ')'], ""),
                )
            })
            .find(|p| !p.exists())
            .ok_or_else(|| format!("{}: too many pasted images this second.", dir.display()))?
    } else {
        path
    };
    std::fs::write(&path, png).map_err(|e| format!("{}: {e}", path.display()))?;
    Ok(path)
}

/// File > Upload files (and ZMODEM): the system file picker, several
/// files at once.
fn pick_files(hwnd: HWND, title: PCWSTR) -> Vec<PathBuf> {
    if DIALOG_OPEN.get() {
        return Vec::new();
    }
    let mut buf = vec![0u16; 64 * 1024];
    let mut ofn = OPENFILENAMEW {
        lStructSize: std::mem::size_of::<OPENFILENAMEW>() as u32,
        hwndOwner: hwnd,
        lpstrFile: PWSTR(buf.as_mut_ptr()),
        nMaxFile: buf.len() as u32,
        lpstrTitle: title,
        Flags: OFN_ALLOWMULTISELECT
            | OFN_EXPLORER
            | OFN_FILEMUSTEXIST
            | OFN_PATHMUSTEXIST
            | OFN_NOCHANGEDIR,
        ..Default::default()
    };
    DIALOG_OPEN.set(true);
    // SAFETY: the struct is filled in as documented and `buf` outlives the
    // call; the dialog's modal loop holds no state borrow.
    let ok = unsafe { GetOpenFileNameW(&mut ofn) }.as_bool();
    DIALOG_OPEN.set(false);
    if !ok {
        return Vec::new();
    }
    // A folder, then the names, each NUL-terminated; one file comes as its
    // full path alone.
    let parts: Vec<String> = buf
        .split(|&c| c == 0)
        .take_while(|p| !p.is_empty())
        .map(String::from_utf16_lossy)
        .collect();
    match parts.as_slice() {
        [] => Vec::new(),
        [one] => vec![PathBuf::from(one)],
        [dir, names @ ..] => names.iter().map(|n| Path::new(dir).join(n)).collect(),
    }
}

/// The folder picker (the Vista-style one Explorer users know), starting
/// in `start`.
fn pick_folder(hwnd: HWND, title: PCWSTR, start: &Path) -> Option<PathBuf> {
    use windows::Win32::System::Com::{
        CLSCTX_INPROC_SERVER, COINIT_APARTMENTTHREADED, CoCreateInstance, CoInitializeEx,
        CoTaskMemFree, CoUninitialize,
    };
    use windows::Win32::UI::Shell::{
        FOS_FORCEFILESYSTEM, FOS_PATHMUSTEXIST, FOS_PICKFOLDERS, FileOpenDialog, IFileOpenDialog,
        IShellItem, SHCreateItemFromParsingName, SIGDN_FILESYSPATH,
    };
    if DIALOG_OPEN.get() {
        return None;
    }
    // SAFETY: COM on this (the UI) thread, balanced below when it took;
    // the dialog and its items are released when they drop; the path
    // string is freed with CoTaskMemFree after it is copied.
    unsafe {
        let com = CoInitializeEx(None, COINIT_APARTMENTTHREADED).is_ok();
        let picked = (|| -> Result<PathBuf> {
            let dialog: IFileOpenDialog =
                CoCreateInstance(&FileOpenDialog, None, CLSCTX_INPROC_SERVER)?;
            let options = dialog.GetOptions()?;
            dialog
                .SetOptions(options | FOS_PICKFOLDERS | FOS_FORCEFILESYSTEM | FOS_PATHMUSTEXIST)?;
            dialog.SetTitle(title)?;
            let start = HSTRING::from(start.as_os_str());
            if let Ok(folder) = SHCreateItemFromParsingName::<_, _, IShellItem>(&start, None) {
                let _ = dialog.SetFolder(&folder);
            }
            DIALOG_OPEN.set(true);
            let shown = dialog.Show(Some(hwnd));
            DIALOG_OPEN.set(false);
            shown?;
            let name = dialog.GetResult()?.GetDisplayName(SIGDN_FILESYSPATH)?;
            let path = name
                .to_string()
                .map_err(|e| windows::core::Error::new(E_FAIL, e.to_string()));
            CoTaskMemFree(Some(name.0 as *const _));
            Ok(PathBuf::from(path?))
        })();
        if com {
            CoUninitialize();
        }
        picked.ok()
    }
}

/// The session form's Browse: one key file, starting in `~/.ssh`.
fn pick_key_file(hwnd: HWND) -> Option<PathBuf> {
    pick_file(
        hwnd,
        w!("Key file for this connection"),
        &home().join(".ssh"),
    )
}

/// The open-file dialog, starting in `dir`.
fn pick_file(hwnd: HWND, title: PCWSTR, dir: &std::path::Path) -> Option<PathBuf> {
    if DIALOG_OPEN.get() {
        return None;
    }
    let mut buf = vec![0u16; 4096];
    let dir = HSTRING::from(dir.as_os_str());
    let mut ofn = OPENFILENAMEW {
        lStructSize: std::mem::size_of::<OPENFILENAMEW>() as u32,
        hwndOwner: hwnd,
        lpstrFile: PWSTR(buf.as_mut_ptr()),
        nMaxFile: buf.len() as u32,
        lpstrInitialDir: PCWSTR(dir.as_ptr()),
        lpstrTitle: title,
        Flags: OFN_EXPLORER | OFN_FILEMUSTEXIST | OFN_PATHMUSTEXIST | OFN_NOCHANGEDIR,
        ..Default::default()
    };
    DIALOG_OPEN.set(true);
    // SAFETY: the struct is filled in as documented; `buf` and `dir`
    // outlive the call; the dialog's modal loop holds no state borrow.
    let ok = unsafe { GetOpenFileNameW(&mut ofn) }.as_bool();
    DIALOG_OPEN.set(false);
    if !ok {
        return None;
    }
    let len = buf.iter().position(|&c| c == 0).unwrap_or(buf.len());
    buf.get(..len)
        .map(|name| PathBuf::from(String::from_utf16_lossy(name)))
}

/// Which file a host the session form cannot change comes from, as the
/// user knows it.
fn host_file(host: &str) -> String {
    let imported = Client::ALL.into_iter().find(|&c| {
        app_read(&imported_path(c)).is_ok_and(|t| {
            ssh_config::hosts(&t, &ssh_config::NoIncludes)
                .iter()
                .any(|h| h.name.eq_ignore_ascii_case(host))
        })
    });
    match imported {
        Some(c) => format!("the {} import", c.name()),
        None => "~/.ssh/config".to_owned(),
    }
}

/// A tab's right-click menu: rename its session, or close it.
fn tab_menu(hwnd: HWND, tab: usize) {
    const RENAME: u32 = 1;
    const CLOSE: u32 = 2;
    // SAFETY: a popup menu of our own on our window, destroyed after use.
    // TPM_RETURNCMD returns the picked id, 0 for none.
    let picked = unsafe {
        let Ok(menu) = CreatePopupMenu() else {
            return;
        };
        let _ = AppendMenuW(menu, MF_STRING, RENAME as usize, w!("Rena&me session..."));
        let _ = AppendMenuW(menu, MF_SEPARATOR, 0, None);
        let _ = AppendMenuW(menu, MF_STRING, CLOSE as usize, w!("&Close tab\tCtrl+F4"));
        let mut pt = POINT::default();
        let _ = GetCursorPos(&mut pt);
        let chosen = TrackPopupMenu(
            menu,
            TPM_RETURNCMD | TPM_NONOTIFY,
            pt.x,
            pt.y,
            None,
            hwnd,
            None,
        );
        let _ = DestroyMenu(menu);
        u32::try_from(chosen.0).unwrap_or(0)
    };
    match picked {
        RENAME => {
            with_window(|w| {
                if let Some(focus) = w.ws.tabs.get(tab).map(|t| t.focus) {
                    w.start_rename(focus);
                }
            });
        }
        CLOSE => run_command(hwnd, Command::CloseTab(tab)),
        _ => {}
    }
}

/// The connection manager's right-click menu.
/// Carries out what the user did in the connection manager's controls.
fn conn_event(hwnd: HWND, event: conn_view::Event) {
    use conn_view::Event;
    let command = match event {
        Event::Action(action) => with_window(|w| w.side_action(Some(action))).flatten(),
        Event::OpenFirst { split } => with_window(|w| {
            let host = w.side.list.first_match()?;
            w.side_action(Some(SideAction::Open { host, split }))
        })
        .flatten(),
        Event::Menu {
            host,
            search,
            marked,
        } => Some(Command::SessionMenu(host, search, marked)),
        Event::DeleteMany(names) => {
            delete_many(hwnd, names);
            None
        }
        Event::Command(id) => Some(Command::Id(id)),
        Event::Query(query) => {
            with_window(|w| {
                w.side.list.set_query(&query);
                w.refresh_chrome();
            });
            None
        }
        Event::Focused => {
            with_window(|w| {
                if !w.side.focused {
                    w.side.focused = true;
                    w.refresh_chrome();
                }
            });
            None
        }
        Event::Refresh => {
            with_window(|w| w.show_side(SideView::Sessions, true));
            None
        }
    };
    if let Some(command) = command {
        run_command(hwnd, command);
    }
}

